INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kim-yeo-appweb-lab/trend-korea-app/nextjs-performance', 'community', 'kim-yeo-appweb-lab', 'trend-korea-app', 'kim-yeo-appweb-lab/trend-korea-app', 'nextjs-performance', 0, 0, 36, '2026-03-08T01:57:15.642Z', '2026-03-08T02:13:42.436Z', 'f9f95d9fde0f9c5d1f1718b58cfdf9ba576e320fcaadb215f3df44a6ce06750f', '{"id":"kim-yeo-appweb-lab/trend-korea-app/nextjs-performance","name":"nextjs-performance","description":{"en":"nextjs-performance optimizes Next.js applications by leveraging Promise.all() for independent fetches and Suspense boundaries for slow data. Ideal for developers seeking to enhance app performance.","zh":"Next.js 性能优化是通过遵循特定的规则和最佳实践来实现的，例如使用 Promise.all() 和 Suspense","ja":"Next.js パフォーマンス最適化は、特定のルールとベストプラクティスに従うことで実現できます。Promise.all() と Suspense を使用するなど","ko":"Next.js 성능 최적화는 특정 규칙과 모범 사례를 따르는 통해 달성할 수 있습니다. Promise.all() 및 Suspense 사용 등","es":"Next.js Performance ofrece reglas críticas para mejorar el rendimiento de aplicaciones web, como el uso de Promise.all() y Suspense","fr":"Next.js Performance propose des règles critiques pour améliorer les performances des applications web, comme l''utilisation de Promise.all() et Suspense","de":"Next.js Performance bietet kritische Regeln zur Verbesserung der Leistung von Webanwendungen, wie z.B. die Verwendung von Promise.all() und Suspense","pt":"Otimize o desempenho do seu aplicativo Next.js com técnicas de carregamento lazy e Suspense. Aprenda a usar Promise.all() para carregar dados de forma eficiente.","ru":"Оптимизируйте производительность вашего приложения Next.js с помощью техник ленивой загрузки и Suspense. Узнайте, как использовать Promise.all() для эффективной загрузки данных.","ar":"احسن أداء تطبيق Next.js الخاص بك باستخدام تقنيات التحميل الكسول و Suspense. تعرف على كيفية استخدام Promise.all() لتحميل البيانات بفعالية."},"seo":{"title":{"en":"nextjs-performance: Optimization Setup Guide | AI Agent S...","zh":"Next.js 性能优化设置指南","ja":"Next.js パフォーマンス最適化セットアップガイド","ko":"Next.js 성능 최적화 설정 가이드","es":"Guía de configuración de Next.js Performance para desarro...","fr":"Guide de configuration de Next.js Performance pour les dé...","de":"Leitfaden zur Konfiguration von Next.js Performance für E...","pt":"Otimização de Desempenho Next.js: Guia de Configuração","ru":"Настройка производительности Next.js: Лучшие практики","ar":"تحسين أداء Next.js: دليل الإعداد"},"description":{"en":"Unlock faster rendering with nextjs-performance! Learn how to optimize your Next.js app with Promise.all() and Suspense boundaries","zh":"了解 Next.js 性能优化的关键规则和最佳实践，包括使用 Promise.all() 和 Suspense","ja":"Next.js パフォーマンス最適化の重要なルールとベストプラクティスを学びます。Promise.all() と Suspense を使用する方法など","ko":"Next.js 성능 최적화의 핵심 규칙과 모범 사례를 알아보세요. Promise.all() 및 Suspense 사용 등","es":"Optimice el rendimiento de su aplicación Next.js con nuestras mejores prácticas y reglas críticas para desarrolladores","fr":"Optimisez les performances de votre application Next.js avec nos meilleures pratiques et règles critiques pour les développeurs","de":"Optimieren Sie die Leistung Ihrer Next.js-Anwendung mit unseren Best Practices und kritischen Regeln für Entwickler","pt":"Aprenda a otimizar o desempenho do seu aplicativo Next.js com técnicas de carregamento lazy, Suspense e Promise.all()","ru":"Узнайте, как оптимизировать производительность вашего приложения Next.js с помощью техник ленивой загрузки, Suspense и Promise.all()","ar":"تعرف على كيفية تحسين أداء تطبيق Next.js الخاص بك باستخدام تقنيات التحميل الكسول، Suspense و Promise.all()"},"definition":{"en":"nextjs-performance is a skill that provides guidelines for optimizing Next.js applications, focusing on critical rules for waterfalls, independent fetches, and slow data handling","zh":"Next.js 性能优化是指通过优化代码和配置来提高 Next.js 应用的性能","ja":"Next.js パフォーマンス最適化は、コードと設定を最適化して Next.js アプリのパフォーマンスを向上させること","ko":"Next.js 성능 최적화는 코드와 설정을 최적화하여 Next.js 애플리케이션의 성능을 향상시키는 것","es":"Next.js Performance es un conjunto de reglas y mejores prácticas para optimizar el rendimiento de aplicaciones Next.js","fr":"Next.js Performance est un ensemble de règles et de meilleures pratiques pour optimiser les performances des applications Next.js","de":"Next.js Performance ist eine Sammlung von Regeln und Best Practices zur Optimierung der Leistung von Next.js-Anwendungen","pt":"Otimização de desempenho Next.js é uma técnica para melhorar a velocidade e eficiência de aplicativos Next.js","ru":"Оптимизация производительности Next.js - это техника для улучшения скорости и эффективности приложений Next.js","ar":"تحسين أداء Next.js هو تقنية لتحسين السرعة والفعالية لتطبيقات Next.js"},"features":{"en":["Utilizes Promise.all() for concurrent independent fetches","Employs Suspense boundaries for handling slow data","Defer await into branches where needed for optimized rendering","Provides architecture patterns in docs/agent/architecture/nextjs-critical-fixes.md","Leverages existing components in apps/frontend/components/"],"zh":["使用 Promise.all() 进行独立的数据获取","使用 Suspense 包装慢速的数据","将 await 延迟到需要的分支中","阅读文档以获取完整的模式","检查现有的组件"],"ja":["独立したデータの取得に Promise.all() を使用","Suspense を使用して遅いデータをラップ","必要な分岐で await を遅延","ドキュメントを読んで完全なパターンを取得","既存のコンポーネントを確認"],"ko":["독립적인 데이터 가져오기에 Promise.all() 사용","Suspense를 사용하여 느린 데이터를 래핑","필요한 분기에서 await를 지연","문서를 읽어 전체 패턴을 얻기","기존 구성 요소를 확인"],"es":["Uso de Promise.all() para peticiones independientes","Uso de Suspense para datos lentos","Defer await en ramas donde sea necesario","Mejora del rendimiento con Next.js","Optimización de aplicaciones web","Reglas críticas para desarrolladores"],"fr":["Utilisation de Promise.all() pour des requêtes indépendantes","Utilisation de Suspense pour des données lentes","Déférer await dans les branches où cela est nécessaire","Amélioration des performances avec Next.js","Optimisation des applications web","Règles critiques pour les développeurs"],"de":["Verwendung von Promise.all() für unabhängige Anfragen","Verwendung von Suspense für langsame Daten","Defer await in Zweigen, wo erforderlich","Leistungsverbesserung mit Next.js","Optimierung von Webanwendungen","Kritische Regeln für Entwickler"],"pt":["Uso de Promise.all() para carregar dados de forma eficiente","Técnica de carregamento lazy para reduzir o tempo de carregamento","Uso de Suspense para gerenciar o carregamento de dados","Otimização de componentes para melhorar a renderização","Uso de técnicas de caching para reduzir o tempo de carregamento"],"ru":["Использование Promise.all() для эффективной загрузки данных","Техника ленивой загрузки для уменьшения времени загрузки","Использование Suspense для управления загрузкой данных","Оптимизация компонентов для улучшения рендеринга","Использование техник кэширования для уменьшения времени загрузки"],"ar":["استخدام Promise.all() لتحميل البيانات بفعالية","تقنية التحميل الكسول لتقليل وقت التحميل","استخدام Suspense لإدارة تحميل البيانات","تحسين المكونات لتحسين العرض","استخدام تقنيات التخزين المؤقت لتقليل وقت التحميل"]},"keywords":{"en":["how to use nextjs-performance","nextjs-performance optimization techniques","nextjs-performance vs react","nextjs-performance setup guide","what is nextjs-performance","nextjs-performance install","Promise.all() in nextjs-performance","Suspense boundaries in nextjs-performance","nextjs-performance best practices"],"zh":["Next.js 性能优化","Promise.all()","Suspense","await","最优化设置","代码优化","AIエージェント","性能优化技巧"],"ja":["Next.js パフォーマンス最適化","Promise.all()","Suspense","await","最適化設定","コード最適化","AIエージェント","パフォーマンス最適化テクニック"],"ko":["Next.js 성능 최적화","Promise.all()","Suspense","await","최적화 설정","코드 최적화","AI 에이전트","성능 최적화 기술"],"es":["Next.js Performance","optimización de rendimiento","reglas críticas","Promise.all()","Suspense","desarrollo web","aplicaciones Next.js","mejores prácticas"],"fr":["Next.js Performance","optimisation des performances","règles critiques","Promise.all()","Suspense","développement web","applications Next.js","meilleures pratiques"],"de":["Next.js Performance","Leistungsoptimierung","kritische Regeln","Promise.all()","Suspense","Webentwicklung","Next.js-Anwendungen","Best Practices"],"pt":["otimização de desempenho next.js","carregamento lazy","suspense","promise.all()","desenvolvimento de aplicativos","next.js","react","javascript"],"ru":["оптимизация производительности next.js","ленивая загрузка","suspense","promise.all()","разработка приложений","next.js","react","javascript"],"ar":["تحسين أداء next.js","تحميل كسول","suspense","promise.all()","تطوير التطبيقات","next.js","react","javascript"]}},"owner":"kim-yeo-appweb-lab","repo":"trend-korea-app","repoPath":"kim-yeo-appweb-lab/trend-korea-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.642Z","topics":[],"category":"community","skillMd":{"name":"nextjs-performance","description":"|","bodyPreview":"# Next.js Performance\n\n## Before Writing Code\n\n1. Read `docs/agent/architecture/nextjs-critical-fixes.md` for full patterns\n2. Check existing components in `apps/frontend/components/`\n\n## Critical Rules\n\n### Waterfalls\n\n- Use `Promise.all()` for independent fetches\n- Wrap slow data in `<Suspense>` boundaries\n- Defer `await` into branches where needed\n\n```tsx\n// WRONG\nconst resumes = await fetchResumes();\nconst jobs = await fetchJobs();\n\n// RIGHT\nconst [resumes, jobs] = await Promise.all([fetchRe","body":"# Next.js Performance\n\n## Before Writing Code\n\n1. Read `docs/agent/architecture/nextjs-critical-fixes.md` for full patterns\n2. Check existing components in `apps/frontend/components/`\n\n## Critical Rules\n\n### Waterfalls\n\n- Use `Promise.all()` for independent fetches\n- Wrap slow data in `<Suspense>` boundaries\n- Defer `await` into branches where needed\n\n```tsx\n// WRONG\nconst resumes = await fetchResumes();\nconst jobs = await fetchJobs();\n\n// RIGHT\nconst [resumes, jobs] = await Promise.all([fetchResumes(), fetchJobs()]);\n```\n\n### Bundle Size\n\n- **NO barrel imports**: `import X from ''lucide-react''` is WRONG\n- **YES direct imports**: `import X from ''lucide-react/dist/esm/icons/x''`\n- Use `next/dynamic` for heavy components (editors, charts, PDF)\n- Defer analytics with `ssr: false`\n\n```tsx\nimport dynamic from ''next/dynamic'';\nconst HeavyEditor = dynamic(() => import(''./HeavyEditor''), { ssr: false });\n```\n\n### Server Actions\n\n- **ALWAYS** check auth INSIDE the action, not just middleware\n- Verify resource ownership before mutations\n\n### Production Build\n\n- Run `npm run build && npm run start`, NOT `npm run dev`\n- Docker must use standalone output\n\n## Pre-PR Checklist\n\n```\n[ ] No sequential awaits for independent data\n[ ] Icons imported directly (not barrel)\n[ ] Heavy components use next/dynamic\n[ ] Server Actions have auth inside\n[ ] Suspense around slow fetches\n```\n"},"lastSynced":"2026-03-08T02:13:42.436Z","agentAnalysis":{"suitability":{"en":"Ideal for Next.js Agent Developers seeking to enhance application performance through optimized data fetching and rendering.","zh":"适用于寻求通过优化数据获取和渲染来提高应用程序性能的 Next.js Agent 开发人员。","ja":"Next.js Agent 開発者が、アプリケーションのパフォーマンスを最適化されたデータ取得とレンダリングを通じて向上させようとしている場合に適しています。","ko":"Next.js 에이전트 개발자가 최적화된 데이터 가져오기와 렌더링을 통해 애플리케이션 성능을 향상시키고자 할 때 적합합니다.","es":"Ideal para desarrolladores de Agentes de Next.js que buscan mejorar el rendimiento de la aplicación a través de la obtención y representación de datos optimizados.","fr":"Idéal pour les développeurs d''agents Next.js souhaitant améliorer les performances de l''application grâce à une récupération et un rendu de données optimisés.","de":"Ideal für Next.js-Agent-Entwickler, die die Anwendungsleistung durch optimierte Datenabruf und -rendering verbessern möchten.","pt":"Ideal para desenvolvedores de Agentes do Next.js que buscam melhorar o desempenho da aplicação por meio da otimização da busca e renderização de dados.","ru":"Идеально подходит для разработчиков агентов Next.js, стремящихся улучшить производительность приложения за счет оптимизации извлечения и рендеринга данных.","ar":"مثالي لמطوري وكلاء Next.js الذين يسعون إلى تعزيز أداء التطبيق من خلال تحسين استرجاع البيانات وتحسينها."},"recommendation":{"en":"Empowers agents to leverage Promise.all() for concurrent independent fetches and Suspense boundaries for managing slow data, significantly improving overall application responsiveness and user experience with Next.js.","zh":"赋予代理以利用 Promise.all() 进行并发独立获取和 Suspense 边界来管理缓慢的数据，显著提高 Next.js 的整体应用程序响应速度和用户体验。","ja":"エージェントが Promise.all() を使用して独立したフェッチを並行して実行し、Suspense の境界を使用して遅いデータを管理することを可能にし、Next.js の全体的なアプリケーションのレスポンス速度とユーザーエクスペリエンスを大幅に改善します。","ko":"에이전트가 Promise.all()를 사용하여 독립적인 가져오기를 동시에 수행하고, Suspense 경계를 사용하여 느린 데이터를 관리하도록 허용하여, Next.js의 전체적인 애플리케이션 반응성과 사용자 경험을 크게 향상시킵니다.","es":"Permite a los agentes aprovechar Promise.all() para obtener resultados concurrentes e independientes y límites de Suspense para gestionar datos lentos, lo que mejora significativamente la respuesta general de la aplicación y la experiencia del usuario con Next.js.","fr":"Permet aux agents d''utiliser Promise.all() pour des récupérations concurrentes et indépendantes et des limites de Suspense pour gérer les données lentes, ce qui améliore considérablement la réactivité globale de l''application et l''expérience utilisateur avec Next.js.","de":"Ermächtigt Agenten, Promise.all() für konkurrierende, unabhängige Abrufe und Suspense-Grenzen für das Management langsamer Daten zu nutzen, was die gesamte Anwendungsreaktion und Benutzererfahrung mit Next.js erheblich verbessert.","pt":"Habilita os agentes a aproveitar o Promise.all() para buscas independentes concorrentes e limites de Suspense para gerenciar dados lentos, melhorando significativamente a responsividade geral do aplicativo e a experiência do usuário com o Next.js.","ru":"Позволяет агентам использовать Promise.all() для параллельных независимых запросов и границы Suspense для управления медленными данными, что значительно улучшает общую отзывчивость приложения и пользовательский опыт с Next.js.","ar":"تمكين الوكلاء من الاستفادة من Promise.all() للحصول المستقل المتزامن والحدود الطوق لادارة البيانات البطيئة، مما يحسن بشكل كبير من استجابة التطبيق الإجمالية وتجربة المستخدم مع Next.js."},"useCases":{"en":["Optimizing data fetching in Next.js applications","Implementing Suspense boundaries for slow data","Improving application performance through concurrent fetching with Promise.all()"],"zh":["在 Next.js 应用程序中优化数据获取","实现 Suspense 边界以管理缓慢的数据","通过 Promise.all() 并发获取来提高应用程序性能"],"ja":["Next.js アプリケーションのデータ取得を最適化する","遅いデータを管理するための Suspense の境界を実装する","Promise.all() を使用した並行フェッチを通じてアプリケーションのパフォーマンスを向上させる"],"ko":["Next.js 애플리케이션에서 데이터 가져오기를 최적화하는 것","느린 데이터를 관리하기 위한 Suspense 경계 구현","Promise.all()를 사용한 동시 가져오기를 통해 애플리케이션 성능 향상"],"es":["Optimización de la obtención de datos en aplicaciones Next.js","Implementación de límites de Suspense para datos lentos","Mejora del rendimiento de la aplicación a través de la obtención concurrente con Promise.all()"],"fr":["Optimisation de la récupération de données dans les applications Next.js","Mise en œuvre de limites de Suspense pour les données lentes","Amélioration des performances de l''application grâce à la récupération concurrente avec Promise.all()"],"de":["Optimierung des Datenabrufs in Next.js-Anwendungen","Implementierung von Suspense-Grenzen für langsame Daten","Verbesserung der Anwendungsleistung durch konkurrierenden Abruf mit Promise.all()"],"pt":["Otimizar a busca de dados em aplicações Next.js","Implementar limites de Suspense para dados lentos","Melhorar o desempenho da aplicação por meio da busca concorrente com Promise.all()"],"ru":["Оптимизация извлечения данных в приложениях Next.js","Реализация границ Suspense для медленных данных","Улучшение производительности приложения за счет параллельного запроса с Promise.all()"],"ar":["تحسين استرجاع البيانات في تطبيقات Next.js","تنفيذ حدود الطوق للبيانات البطيئة","تحسين أداء التطبيق من خلال الحصول المتزامن مع Promise.all()"]},"limitations":{"en":["Requires understanding of Next.js architecture and components","Limited to Next.js applications only"],"zh":["需要了解 Next.js 架构和组件","仅限 Next.js 应用程序"],"ja":["Next.js のアーキテクチャとコンポーネントの理解が必要","Next.js アプリケーションにのみ限定"],"ko":["Next.js 아키텍처 및 컴포넌트에 대한 이해가 필요","Next.js 애플리케이션에만 제한"],"es":["Requiere una comprensión de la arquitectura y componentes de Next.js","Limitado a aplicaciones Next.js solo"],"fr":["Nécessite une compréhension de l''architecture et des composants de Next.js","Limité aux applications Next.js uniquement"],"de":["Erfordert ein Verständnis der Next.js-Architektur und -Komponenten","Begrenzt auf Next.js-Anwendungen nur"],"pt":["Exige compreensão da arquitetura e componentes do Next.js","Limitado a aplicações Next.js apenas"],"ru":["Требует понимания архитектуры и компонентов Next.js","Ограничен только приложениями Next.js"],"ar":["يتطلب فهم الهندسة المعمارية ومكونات Next.js","محدود بتطبيقات Next.js فقط"]},"version":4},"contentHash":"f9f95d9fde0f9c5d1f1718b58cfdf9ba576e320fcaadb215f3df44a6ce06750f","qualityScore":36}');
