INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kim-yeo-appweb-lab/trend-korea-app/nextjs-performance', 'nextjs-performance', 'kim-yeo-appweb-lab', 'trend-korea-app', 'community', 'nextjs-performance kim-yeo-appweb-lab trend-korea-app community nextjs-performance optimizes Next.js applications by leveraging Promise.all() for independent fetches and Suspense boundaries for slow data. Ideal for developers seeking to enhance app performance. Next.js 性能优化是通过遵循特定的规则和最佳实践来实现的，例如使用 Promise.all() 和 Suspense Next.js パフォーマンス最適化は、特定のルールとベストプラクティスに従うことで実現できます。Promise.all() と Suspense を使用するなど Next.js 성능 최적화는 특정 규칙과 모범 사례를 따르는 통해 달성할 수 있습니다. Promise.all() 및 Suspense 사용 등 Next.js Performance ofrece reglas críticas para mejorar el rendimiento de aplicaciones web, como el uso de Promise.all() y Suspense Next.js Performance propose des règles critiques pour améliorer les performances des applications web, comme l''utilisation de Promise.all() et Suspense Next.js Performance bietet kritische Regeln zur Verbesserung der Leistung von Webanwendungen, wie z.B. die Verwendung von Promise.all() und Suspense Otimize o desempenho do seu aplicativo Next.js com técnicas de carregamento lazy e Suspense. Aprenda a usar Promise.all() para carregar dados de forma eficiente. Оптимизируйте производительность вашего приложения Next.js с помощью техник ленивой загрузки и Suspense. Узнайте, как использовать Promise.all() для эффективной загрузки данных. احسن أداء تطبيق Next.js الخاص بك باستخدام تقنيات التحميل الكسول و Suspense. تعرف على كيفية استخدام Promise.all() لتحميل البيانات بفعالية. how to use nextjs-performance nextjs-performance optimization techniques nextjs-performance vs react nextjs-performance setup guide what is nextjs-performance nextjs-performance install Promise.all() in nextjs-performance Suspense boundaries in nextjs-performance nextjs-performance best practices Next.js 性能优化 Promise.all() Suspense await 最优化设置 代码优化 AIエージェント 性能优化技巧 Utilizes Promise.all() for concurrent independent fetches Employs Suspense boundaries for handling slow data Defer await into branches where needed for optimized rendering Provides architecture patterns in docs/agent/architecture/nextjs-critical-fixes.md Leverages existing components in apps/frontend/components/ nextjs-performance is a skill that provides guidelines for optimizing Next.js applications, focusing on critical rules for waterfalls, independent fetches, and slow data handling');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shibuiwilliam/paper2detail/analyze-paper', 'community', 'shibuiwilliam', 'paper2detail', 'shibuiwilliam/paper2detail', 'analyze-paper', 0, 0, 36, '2026-03-08T01:57:15.642Z', '2026-03-08T02:13:42.636Z', '31a61cd2a7fc0f4dcbf5909e1430ae2b6b90d1e4e3b9270f7bf742fddc7b9589', '{"id":"shibuiwilliam/paper2detail/analyze-paper","name":"analyze-paper","description":{"en":"The analyze-paper skill generates detailed reports on arXiv papers, including chapter and section analysis. It supports long documents over 100 pages and provides a chunk export workflow for efficient processing.","zh":"analyze-paper 是一个用于分析 arXiv 论文的工具，能够处理长文档和章节分析","ja":"analyze-paper は arXiv 論文を分析するツールで、長いドキュメントと章の分析に対応しています","ko":"analyze-paper는 arXiv 논문을 분석하는 도구로, 긴 문서와 장 분석을 지원합니다","es":"Analyze-paper es una habilidad que analiza documentos de investigación y genera informes detallados sobre cada capítulo y sección, incluyendo referencias y análisis profundos","fr":"Analyze-paper est une compétence qui analyse des documents de recherche et génère des rapports détaillés sur chaque chapitre et section, y compris des références et des analyses approfondies","de":"Analyze-paper ist eine Fähigkeit, die Forschungsdokumente analysiert und detaillierte Berichte über jedes Kapitel und jede Sektion generiert, einschließlich Referenzen und tiefer Analysen","pt":"O analyze-paper é uma ferramenta de análise de artigos científicos que gera relatórios detalhados sobre cada seção de um artigo em arXiv, incluindo referências.","ru":"ИИ Агент analyze-paper - это инструмент для анализа научных статей, который генерирует подробные отчеты о каждом разделе статьи в arXiv, включая ссылки.","ar":"analyze-paper هو أداة لتحليل المقالات العلمية التي تولد تقارير مفصلة حول كل قسم من مقال في arXiv، بما في ذلك المراجع."},"seo":{"title":{"en":"analyze-paper: Advanced arXiv Analysis Setup Guide | AI A...","zh":"analyze-paper Setup Guide: arXiv 论文分析工具","ja":"analyze-paper セットアップガイド: arXiv 論文分析スキル","ko":"analyze-paper 설정 가이드: arXiv 논문 분석 도구","es":"Guía de configuración de analyze-paper: Análisis de docum...","fr":"Guide de configuration d''analyze-paper : Analyse de docum...","de":"Einrichtungsleitfaden für analyze-paper: Analyse von Fors...","pt":"Guia de Configuração do analyze-paper: Análise de Artigos...","ru":"Настройка ИИ Агента analyze-paper: Анализ Научных Статей","ar":"إعداد وتشغيل analyze-paper: تحليل المقالات العلمية"},"description":{"en":"Unlock in-depth analysis of arXiv papers with our AI agent skill. Learn how to generate detailed reports and tackle long documents over 100 pages","zh":"了解 analyze-paper 的技术细节，包括长文档处理和章节分析，提升您的 arXiv 论文分析能力","ja":"analyze-paper の技術的な詳細を学び、長いドキュメントの処理と章の分析を含む arXiv 論文分析の能力を高める","ko":"analyze-paper의 기술적인 세부 사항을 배우고, 긴 문서 처리 및 장 분석을 포함한 arXiv 논문 분석 능력을 향상시키세요","es":"Aprende a configurar y utilizar analyze-paper para analizar documentos de investigación de hasta 100 páginas o más y obtener informes detallados","fr":"Découvrez comment configurer et utiliser analyze-paper pour analyser des documents de recherche de jusqu''à 100 pages ou plus et obtenir des rapports détaillés","de":"Erfahren Sie, wie Sie analyze-paper konfigurieren und verwenden, um Forschungsdokumente von bis zu 100 Seiten oder mehr zu analysieren und detaillierte Beric...","pt":"Aprenda a configurar e utilizar o analyze-paper para análise de artigos científicos em arXiv, incluindo processamento de documentos longos","ru":"Узнайте, как настроить и использовать ИИ Агент analyze-paper для анализа научных статей в arXiv, включая обработку длинных документов","ar":"تعلم كيفية تكوين وتشغيل analyze-paper لتحليل المقالات العلمية في arXiv، بما في ذلك معالجة الوثائق الطويلة"},"definition":{"en":"analyze-paper is a skill that analyzes arXiv papers and generates detailed reports, including chapter and section analysis, with support for long documents and chunk export workflows","zh":"analyze-paper 是一个用于分析 arXiv 论文的 AI 工具","ja":"analyze-paper は arXiv 論文を分析する AI エージェントです","ko":"analyze-paper는 arXiv 논문을 분석하는 AI 도구입니다","es":"Analyze-paper es una herramienta de análisis de documentos de investigación que utiliza técnicas de procesamiento de lenguaje natural para generar informes detallados","fr":"Analyze-paper est un outil d''analyse de documents de recherche qui utilise des techniques de traitement du langage naturel pour générer des rapports détaillés","de":"Analyze-paper ist ein Tool zur Analyse von Forschungsdokumenten, das Techniken des natürlichen Sprachverarbeitung verwendet, um detaillierte Berichte zu generieren","pt":"O analyze-paper é uma ferramenta de análise de artigos científicos que utiliza técnicas de processamento de linguagem natural","ru":"ИИ Агент analyze-paper - это инструмент для анализа научных статей, который использует методы обработки естественного языка","ar":"analyze-paper هو أداة لتحليل المقالات العلمية التي تستخدم تقنيات معالجة اللغة الطبيعية"},"features":{"en":["Generates detailed reports on arXiv papers, including chapter and section analysis","Supports long documents over 100 pages using chunk export workflows","Utilizes the `uv run arxiv-helper` command for document downloads and page count verification","Processes PDF files up to 10MB in size","Employs a recommended approach based on page count, including standard and chunk export workflows","Provides output in a readable format, including page count and detailed analysis"],"zh":["支持长文档处理（100页以上）","章节分析和参照论文的深入分析","使用 Read 工具进行文档读取","支持 UV 命令行工具进行文档下载和分析"],"ja":["長いドキュメントの処理（100ページ以上）に対応","章の分析と参照論文の深い分析","Read ツールを使用したドキュメントの読み取り","UV コマンドラインツールを使用したドキュメントのダウンロードと分析"],"ko":["긴 문서 처리 지원（100페이지 이상）","장 분석 및 참조 논문의 심층 분석","Read 도구를 사용한 문서 읽기","UV 명령줄 도구를 사용한 문서 다운로드 및 분석"],"es":["Análisis de documentos de investigación de hasta 100 páginas o más","Generación de informes detallados sobre cada capítulo y sección","Inclusión de referencias y análisis profundos","Compatibilidad con documentos PDF de hasta 10MB","Uso de técnicas de procesamiento de lenguaje natural"],"fr":["Analyse de documents de recherche de jusqu''à 100 pages ou plus","Génération de rapports détaillés sur chaque chapitre et section","Inclusion de références et d''analyses approfondies","Compatibilité avec des documents PDF de jusqu''à 10MB","Utilisation de techniques de traitement du langage naturel"],"de":["Analyse von Forschungsdokumenten von bis zu 100 Seiten oder mehr","Generierung von detaillierten Berichten über jedes Kapitel und jede Sektion","Einbeziehung von Referenzen und tiefer Analysen","Kompatibilität mit PDF-Dokumenten von bis zu 10MB","Verwendung von Techniken des natürlichen Sprachverarbeitung"],"pt":["Análise de artigos científicos em arXiv","Processamento de documentos longos (mais de 100 páginas)","Geração de relatórios detalhados sobre cada seção do artigo","Inclusão de referências e links para artigos relacionados","Utilização da ferramenta de linha de comando (CLI) para download e análise de artigos"],"ru":["Анализ научных статей в arXiv","Обработка длинных документов (более 100 страниц)","Генерация подробных отчетов о каждом разделе статьи","Включение ссылок и ссылок на связанные статьи","Использование командной строки (CLI) для загрузки и анализа статей"],"ar":["تحليل المقالات العلمية في arXiv","معالجة الوثائق الطويلة (أكثر من 100 صفحة)","توليد تقارير مفصلة حول كل قسم من المقال","إدراج المراجع والروابط للمقالات المرتبطة","استخدام سطر الأوامر (CLI) لتنزيل وتحليل المقالات"]},"keywords":{"en":["how to use analyze-paper","what is analyze-paper","analyze-paper alternative","analyze-paper vs other AI agents","analyze-paper install","analyze-paper setup guide","arXiv paper analysis","long document analysis","chunk export workflow"],"zh":["analyze-paper","arXiv 论文分析","长文档处理","章节分析","AI 工具","Read 工具","UV 命令行工具"],"ja":["analyze-paper","arXiv 論文分析","長いドキュメントの処理","章の分析","AI エージェント","Read ツール","UV コマンドラインツール"],"ko":["analyze-paper","arXiv 논문 분석","긴 문서 처리","장 분석","AI 도구","Read 도구","UV 명령줄 도구"],"es":["análisis de documentos de investigación","herramientas de análisis de texto","procesamiento de lenguaje natural","informes detallados","documentos PDF","investigación científica","analyze-paper","IA para la investigación","herramientas de IA para la investigación"],"fr":["analyse de documents de recherche","outils d''analyse de texte","traitement du langage naturel","rapports détaillés","documents PDF","recherche scientifique","analyze-paper","IA pour la recherche","outils d''IA pour la recherche"],"de":["Analyse von Forschungsdokumenten","Tools zur Textanalyse","natürliche Sprachverarbeitung","detaillierte Berichte","PDF-Dokumente","wissenschaftliche Forschung","analyze-paper","KI für die Forschung","KI-Tools für die Forschung"],"pt":["análise de artigos científicos","arXiv","processamento de linguagem natural","ferramenta de análise de textos","CLI","download de artigos","análise de documentos longos"],"ru":["анализ научных статей","arXiv","обработка естественного языка","инструмент для анализа текстов","CLI","загрузка статей","обработка длинных документов"],"ar":["تحليل المقالات العلمية","arXiv","معالجة اللغة الطبيعية","أداة لتحليل النصوص","CLI","تنزيل المقالات","معالجة الوثائق الطويلة"]}},"owner":"shibuiwilliam","repo":"paper2detail","repoPath":"shibuiwilliam/paper2detail","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.642Z","topics":[],"category":"community","skillMd":{"name":"analyze-paper","description":"Analyzes arXiv papers and generates detailed reports. Use when the user provides an arXiv URL or asks to analyze an academic paper.","bodyPreview":"# arXiv 論文分析スキル（詳細版）\n\narXiv 論文を分析して、各章・セクションの詳細な解説と参照論文の深い分析を含むレポートを生成します。\n\n**100ページ以上の長いドキュメントにも対応しています。**\n\n---\n\n## 長いドキュメントの処理（100ページ以上）\n\n**重要**: 100ページ以上の論文や 10MB 以上の PDF は `Read` ツールで直接読み取れません。\n必ず以下の**チャンクエクスポートワークフロー**を使用してください。\n\n### ドキュメント長の確認\n\n論文をダウンロードして、まずページ数を確認してください：\n\n```bash\nuv run arxiv-helper <arxiv_url> --download\n```\n\n出力に `Pages: XXX` と表示されます。100ページ以上または 10MB 以上の場合は、次のセクションの手順に従ってください。\n\n### 長いドキュメントの分析戦略\n\n| ページ数 | 分類 | 推奨アプローチ |\n|---------|------|---------------|\n| 1-30 | 標準 | 通","body":"# arXiv 論文分析スキル（詳細版）\n\narXiv 論文を分析して、各章・セクションの詳細な解説と参照論文の深い分析を含むレポートを生成します。\n\n**100ページ以上の長いドキュメントにも対応しています。**\n\n---\n\n## 長いドキュメントの処理（100ページ以上）\n\n**重要**: 100ページ以上の論文や 10MB 以上の PDF は `Read` ツールで直接読み取れません。\n必ず以下の**チャンクエクスポートワークフロー**を使用してください。\n\n### ドキュメント長の確認\n\n論文をダウンロードして、まずページ数を確認してください：\n\n```bash\nuv run arxiv-helper <arxiv_url> --download\n```\n\n出力に `Pages: XXX` と表示されます。100ページ以上または 10MB 以上の場合は、次のセクションの手順に従ってください。\n\n### 長いドキュメントの分析戦略\n\n| ページ数 | 分類 | 推奨アプローチ |\n|---------|------|---------------|\n| 1-30 | 標準 | 通常の分析フロー（Read で PDF を直接読む） |\n| 31-50 | やや長い | セクション単位で読む |\n| 51-100 | 長い | チャンク分割、重要部分を優先 |\n| 100+ | 非常に長い | **チャンクエクスポート必須（下記参照）** |\n\n---\n\n## 【必須】100ページ以上の論文のワークフロー\n\n### ステップ 1: チャンクをテキストファイルにエクスポート\n\n**このステップが最も重要です。** 以下のコマンドでPDFをテキストファイルに分割します：\n\n```bash\nuv run pdf-chunker <arxiv_url_or_id> --export-dir chunks/<arxiv_id>\n```\n\n例：\n```bash\nuv run pdf-chunker 2512.13564 --export-dir chunks/2512.13564\n```\n\nこのコマンドにより以下が生成されます：\n- `chunks/<arxiv_id>/<arxiv_id>_chunks_info.md` - チャンク情報サマリー\n- `chunks/<arxiv_id>/<arxiv_id>_chunk01_*.txt` - チャンク1のテキスト\n- `chunks/<arxiv_id>/<arxiv_id>_chunk02_*.txt` - チャンク2のテキスト\n- ...\n\n### ステップ 2: チャンク情報を確認\n\nまず情報ファイルを読んで、チャンク構成を確認します：\n\n```\nRead(file_path=\"chunks/<arxiv_id>/<arxiv_id>_chunks_info.md\")\n```\n\nこのファイルには以下が含まれます：\n- PDF の基本情報（ページ数、サイズ等）\n- チャンク一覧（ページ範囲、タイトル）\n- 各チャンクファイルのパス\n\n### ステップ 3: チャンクを順番に読んで分析\n\n各チャンクファイルを `Read` ツールで読み取り、分析を進めます：\n\n```\n# チャンク1を読む\nRead(file_path=\"chunks/<arxiv_id>/<arxiv_id>_chunk01_Introduction.txt\")\n\n# チャンク2を読む\nRead(file_path=\"chunks/<arxiv_id>/<arxiv_id>_chunk02_*.txt\")\n```\n\n**分析の優先順位**（時間が限られる場合）:\n\n1. **最優先**: Introduction/Abstract を含むチャンク、Conclusion を含むチャンク\n2. **高優先**: Method/Approach を含むチャンク、Results を含むチャンク\n3. **中優先**: Related Work, Background を含むチャンク\n4. **低優先**: Appendix, 詳細な証明を含むチャンク\n\n### ステップ 4: チャンク分析のテンプレート\n\n各チャンクを読んだ後、以下の形式で分析結果を記録します：\n\n**チャンク分析のテンプレート**:\n\n```markdown\n## チャンク [N] 分析結果（p.XX-YY）\n\n### セクション: [セクション名]\n\n#### 要約\n[このチャンクの主要な内容を 3-5 文で要約]\n\n#### キーポイント\n- [ポイント1]\n- [ポイント2]\n- [ポイント3]\n\n#### 重要な図表\n- Figure X: [説明]\n- Table Y: [説明]\n\n#### 参照される論文\n- [論文1の情報]\n\n#### 次のチャンクへの接続\n[このチャンクから次のチャンクにつながる内容]\n```\n\n### ステップ 5: 結果の統合とレポート生成\n\n全チャンクの分析が完了したら、結果を統合してレポートを生成します：\n\n1. 各チャンクのサマリーを結合\n2. 重複する情報を整理\n3. 論理的な流れを確認\n4. 最終レポートを `reports/{arxiv_id}_report.md` として生成\n\n### 長いドキュメント分析のベストプラクティス\n\n#### Do''s（やるべきこと）\n\n- ✅ 最初に全体構造を把握する\n- ✅ チャンク計画を立ててから分析を開始する\n- ✅ 重要なセクションを優先的に分析する\n- ✅ 各チャンクの分析結果を記録する\n- ✅ 中間結果を定期的に保存する\n- ✅ セクション間の関連性を意識する\n\n#### Don''ts（避けるべきこと）\n\n- ❌ 100ページ以上の PDF を一度に全て読み込もうとする\n- ❌ チャンク計画なしに分析を開始する\n- ❌ 詳細な分析なしに全体を流し読みする\n- ❌ 中間結果を記録せずに進める\n- ❌ 参照論文を全て調査しようとする（5-10本に絞る）\n\n### サーベイ論文（100ページ以上）の特別な注意点\n\nサーベイ論文は特に長くなりやすいため、以下に注意：\n\n1. **分類体系（Taxonomy）を最初に把握**\n   - 多くのサーベイは分類軸を持つ\n   - 分類軸を理解してから各カテゴリを分析\n\n2. **各カテゴリの代表的手法に集中**\n   - 全ての手法を詳細に分析する必要はない\n   - 各カテゴリから 2-3 の代表的手法を選択\n\n3. **比較表を優先的に抽出**\n   - サーベイの価値は比較分析にある\n   - 比較表は完全に転記する\n\n4. **セクション間の重複に注意**\n   - サーベイは同じ手法が複数箇所で言及される\n   - 重複を整理して記述する\n\n---\n\n## 【最重要】レポート執筆の文体規則\n\n### 文体: ですます調（敬体）・丁寧語で統一【必須】\n\n**レポート全体を必ず「ですます調（敬体）」と「丁寧語」で統一してください。**\n\nこれは最も重要なルールです。読者に丁寧に説明する姿勢で、すべての文を敬体で記述します。\n\n#### ですます調の基本パターン\n\n| パターン | 例文 |\n|---------|------|\n| 〜です | 「本論文の目的は効率化です。」 |\n| 〜ます | 「提案手法はメモリを自動管理します。」 |\n| 〜ています | 「著者らは新しいアプローチを提案しています。」 |\n| 〜されています | 「実験により有効性が確認されています。」 |\n| 〜でしょう | 「この手法は広く応用できるでしょう。」 |\n| 〜ください | 「以下の点に注意してください。」 |\n\n#### 良い例（ですます調・丁寧語）✓\n\n- 「本論文では、LLMエージェントの効率化手法を提案しています。」\n- 「この手法の特徴は、メモリ管理を自動化する点にあります。」\n- 「実験結果から、提案手法が従来手法を15%上回ることが示されています。」\n- 「以下では、各コンポーネントについて詳しく説明します。」\n- 「この結果は非常に重要な意味を持っています。」\n\n#### 悪い例（である調は使用禁止）✗\n\n以下のような「である調（常体）」は使用しないでください：\n\n- ~~「本論文では、LLMエージェントの効率化手法を提案している。」~~\n- ~~「この手法の特徴は、メモリ管理を自動化する点にある。」~~\n- ~~「実験結果から、提案手法が従来手法を15%上回ることが示された。」~~\n- ~~「以下では、各コンポーネントについて説明する。」~~\n- ~~「この結果は重要な意味を持つ。」~~\n\n#### 注意すべき表現\n\n| 使用禁止（である調） | 使用すべき（ですます調） |\n|-------------------|---------------------|\n| 〜である | 〜です |\n| 〜している | 〜しています |\n| 〜された | 〜されました |\n| 〜と考えられる | 〜と考えられます |\n| 〜が必要だ | 〜が必要です |\n| 〜すべきだ | 〜すべきです |\n| 〜ではない | 〜ではありません |\n| 〜できる | 〜できます |\n| 〜だろう | 〜でしょう |\n\n### 詳細で自己完結した説明\n\nレポートは**論文を読まなくても内容が理解できる**レベルの詳細さで記述します。\n\n#### 原則\n\n1. **専門用語は必ず説明する**\n   - 初出の専門用語には定義や説明を付ける\n   - 略語は初出時にフルスペルと意味を記載する\n\n2. **背景知識を補足する**\n   - 読者が前提知識を持っていないと仮定する\n   - 必要な背景情報は省略せずに記述する\n\n3. **論理の流れを明確にする**\n   - 「なぜなら」「したがって」「具体的には」等の接続表現を使用する\n   - 各段落の関係性を明示する\n\n4. **具体例を豊富に含める**\n   - 抽象的な説明には具体例を添える\n   - 数値や事例を用いて理解を助ける\n\n#### 詳細な説明の例\n\n**悪い例**（説明不足）:\n```\nMemGPTは階層的メモリを使用します。\n```\n\n**良い例**（詳細で自己完結）:\n```\nMemGPTは、コンピュータのOSにおけるメモリ管理の仕組みをLLMに適用した手法です。\n具体的には、LLMのコンテキストウィンドウを「メインメモリ」、外部データベースを\n「仮想メモリ（外部ストレージ）」として扱います。LLMは必要に応じてこれらの\nメモリ間でデータを移動させる関数（core_memory_append、archival_memory_search等）\nを自律的に呼び出すことで、コンテキスト長の制限を実質的に撤廃しています。\nこの仕組みにより、長期間にわたる対話でも重要な情報を保持し続けることが可能になります。\n```\n\n---\n\n## 論文タイプの判定\n\n**最初に論文タイプを判定**し、適切な分析アプローチを選択してください。\n\n### 1. サーベイ論文 (Survey/Review)\n\n以下の特徴がある場合はサーベイ論文として分析します：\n- タイトルに \"Survey\", \"Review\", \"Overview\", \"Systematic Review\" 等が含まれる\n- 複数の既存手法を比較・分類している\n- 新しい手法の提案ではなく、分野の整理が目的\n\n**分析方針**: 紹介されている各手法・論文の説明を中心に、分類体系や比較軸を詳述します。\n\n### 2. 研究論文 (Research Paper)\n\n以下の特徴がある場合は研究論文として分析します：\n- 新しい手法・理論・発見を提案している\n- 実験による主張の検証がある\n\n**分析方針**: 主張・ロジック・手法・実験・結果を正確に追跡します。\n\n---\n\n## 読解の姿勢\n\n- **まず全体を通読**してから詳細分析に入ります\n- **論文の構造と流れ**を把握します\n- **著者の主張と根拠の関係**を理解します\n- **数値・引用は原文に忠実**に抽出します\n- **解釈を加えすぎない**ようにします（論文が言っていないことを書かない）\n\n---\n\n## ワークフロー\n\n### 1. URL/ID の解析とドキュメント情報の取得\n\n```bash\nuv run arxiv-helper <url_or_id> --download\n```\n\nこのコマンドにより arXiv ID、PDF URL、メタデータが表示され、PDF がダウンロードされます。\n\n### 2. ドキュメント長の確認と戦略決定\n\nPDF をダウンロードしたら、まずページ数を確認します：\n\n```python\nfrom src.pdf_chunker import get_pdf_info\n\ninfo = get_pdf_info(\"reports/<arxiv_id>.pdf\")\nprint(f\"ページ数: {info.page_count}\")\nprint(f\"長いドキュメント: {info.is_long_document}\")\nprint(f\"非常に長いドキュメント: {info.is_very_long_document}\")\n```\n\n**分岐**:\n- **50ページ未満**: 通常のワークフロー（下記ステップ3へ）\n- **50-100ページ**: セクション単位の分析を推奨\n- **100ページ以上**: **上記「長いドキュメントの処理」セクション**に従う\n\n### 3. PDF の読み取り\n\n#### 標準的なドキュメント（50ページ未満、10MB未満）\n\n- `Read` ツールで直接 PDF を読み取ります\n- **必ず論文全体を通読**してから詳細分析に入ります\n- 論文のタイプ（サーベイ vs 研究論文）を判定します\n\n#### 長いドキュメント（50ページ以上 または 10MB以上）\n\n**重要**: 大きな PDF は `Read` ツールで直接読み取れません。以下のワークフローを使用してください。\n\n1. **チャンクをテキストファイルにエクスポート**:\n   ```bash\n   uv run pdf-chunker <arxiv_id> --export-dir chunks/<arxiv_id>\n   ```\n\n2. **チャンク情報を確認**:\n   ```\n   Read(file_path=\"chunks/<arxiv_id>/<arxiv_id>_chunks_info.md\")\n   ```\n\n3. **各チャンクを順番に読み取り**:\n   ```\n   Read(file_path=\"chunks/<arxiv_id>/<arxiv_id>_chunk01_*.txt\")\n   Read(file_path=\"chunks/<arxiv_id>/<arxiv_id>_chunk02_*.txt\")\n   ...\n   ```\n\n詳細は上記「【必須】100ページ以上の論文のワークフロー」セクションを参照してください。\n\n### 4. 論文タイプに応じた詳細分析\n\n以下の A または B のセクションに従って分析を進めます。\n\n---\n\n## A. サーベイ論文の分析方法\n\nサーベイ論文では、**紹介されている手法・論文の正確な説明**が最も重要です。\n\n### A.1 サーベイの構造把握\n\n以下の項目を特定します：\n- **対象分野**: このサーベイが扱う研究領域は何か\n- **分類軸（Taxonomy）**: どのような基準で手法を分類しているか\n- **各カテゴリ**: それぞれのカテゴリにはどのような手法が含まれるか\n- **比較表**: 手法間の比較表があれば抽出します\n\n### A.2 各カテゴリ・手法の詳細記述\n\nサーベイで紹介されている**各手法について**、以下の形式で詳細に記述します：\n\n```markdown\n### [手法名]\n\n**提案論文**: [著者名], [年], [会議/ジャーナル名]\n\n#### 概要\n\n[この手法が何を目的として、どのようなアプローチを取るのかを3-5文で説明します。\n専門用語は必ず説明を付け、読者が予備知識なしに理解できるようにします。]\n\n#### 技術的詳細\n\nこの手法の核心となる技術的なポイントを説明します。\n\n**主要なアイデア**:\n[手法の着想や基本的な考え方を説明します。なぜこのアプローチを取るのか、\nその動機も含めて記述します。]\n\n**アーキテクチャ/アルゴリズムの特徴**:\n[具体的な処理の流れ、構成要素、重要なステップを説明します。\n図がある場合は「Figure X に示すように」と言及します。]\n\n**重要な数式**:\n[手法の理解に必要な数式があれば、その意味と各変数の定義を含めて記載します。]\n\n$$[数式]$$\n\nここで、$[変数]$ は [変数の意味] を表しています。\n\n#### 利点\n\nこの手法には以下の強みがあります：\n- [利点1の詳細な説明]\n- [利点2の詳細な説明]\n\n#### 限界\n\n一方で、以下の課題が残されています：\n- [限界1の詳細な説明と、それが問題となる理由]\n- [限界2の詳細な説明]\n\n#### サーベイでの位置づけ\n\n本サーベイでは、この手法を[カテゴリ名]に分類しています。\n[サーベイ著者がこの手法をどのように評価しているか、\n他の手法との比較でどのような特徴があるとされているかを記述します。]\n```\n\n### A.3 比較分析の抽出\n\n- **比較表**があれば完全に転記し、各項目の意味を説明します\n- **各手法の違い**を明確に説明します\n- **トレードオフ**を特定し、どのような状況でどの手法が適しているかを記述します\n- **性能比較**があれば数値を正確に引用し、その意味を解説します\n\n### A.4 サーベイの結論・展望\n\n- サーベイが示す**分野の現状**を要約します\n- **未解決の課題**を列挙し、それぞれがなぜ難しいのかを説明します\n- **今後の研究方向**として示唆されている内容を記述します\n\n---\n\n## B. 研究論文の分析方法\n\n研究論文では、**主張・ロジック・実験・結果の正確な追跡**が最も重要です。\n\n### B.1 主張の特定\n\n以下を明確に抽出します：\n- **主要な主張（Main Claim）**: この論文が最も伝えたいことは何か\n- **その主張を支える論拠**: なぜその主張が正しいと言えるのか\n- **主張の新規性**: 既存研究と比較して何が新しいのか\n\n### B.2 ロジックの追跡\n\n論文の論理展開を以下のように追跡します：\n\n```\n1. 問題提起: [既存の何が問題なのかを具体的に説明します]\n      ↓ なぜなら\n2. 問題の原因: [その問題が生じる根本原因を分析します]\n      ↓ したがって\n3. 提案の着想: [どのようなアイデアで解決しようとしているかを説明します]\n      ↓ 具体的には\n4. 手法の詳細: [提案手法の技術的詳細を記述します]\n      ↓ 検証するために\n5. 実験設計: [どのような実験で主張を検証するかを説明します]\n      ↓ 結果として\n6. 実験結果: [実験で何が示されたかを数値とともに記述します]\n      ↓ これは\n7. 結論: [主張が正しいことがどのように確認されたかを述べます]\n```\n\n### B.3 各セクションの詳細分析\n\n#### Abstract の分析\n\nAbstract から以下の情報を抽出します：\n\n- **主要な主張**: 論文の核心を1文で表現します\n- **キーポイント**: 重要なポイントを箇条書きで列挙します\n- **数値的成果**: 具体的な改善率や達成した性能を正確に引用します\n\n**記述例**:\n```markdown\n### 概要\n\n本論文では、[研究テーマ]に取り組んでいます。著者らは[問題]を解決するために\n[提案手法]を提案しています。\n\n#### キーポイント\n\n- [キーポイント1の詳細な説明]\n- [キーポイント2の詳細な説明]\n- [キーポイント3の詳細な説明]\n\n#### 主要な数値結果\n\n実験の結果、以下の成果が報告されています：\n- [指標1]: [数値]（従来手法と比較して[X]%の改善）\n- [指標2]: [数値]（ベンチマーク[Y]における最高性能）\n```\n\n#### Introduction の詳細分析\n\nIntroduction から以下の情報を抽出し、詳細に記述します：\n\n**問題の背景・文脈**:\nこの研究が取り組む問題がなぜ重要なのかを説明します。関連する応用分野や\n社会的意義についても言及します。\n\n**既存手法の課題**:\nこれまでにどのようなアプローチが試みられてきたか、そしてそれらの\n具体的な限界は何かを説明します。\n\n**研究ギャップ**:\n既存研究では何が解決されていないのか、どのような課題が残されているのかを\n明確にします。\n\n**本研究の着想**:\n著者らがどのようなアイデアで問題を解決しようとしているのかを説明します。\nその着想がどこから来ているのか（他分野からの応用、既存手法の組み合わせ等）\nも含めて記述します。\n\n**貢献のリスト**:\n論文が主張する貢献を原文から抽出し、それぞれの意義を説明します。\n\n**重要な引用文**:\n論文の核心を表す重要な文を原文で引用し、日本語で解説を加えます。\n\n```markdown\n> \"Our method achieves state-of-the-art performance while reducing computational cost by 50%.\"\n\nこの文は、提案手法が最先端の性能を達成しながら、同時に計算コストを半減させている\nことを主張しています。これは性能と効率のトレードオフを解決した点で重要な貢献です。\n```\n\n#### Related Work / Background の詳細分析\n\n関連研究を**カテゴリ別に分類**して記述します：\n\n```markdown\n### 関連研究\n\n#### [カテゴリ1の名前]\n\nこのカテゴリには、[カテゴリの特徴や共通点]を持つ手法が含まれます。\n\n**代表的な手法**:\n\n- **[手法1の名前]** ([著者], [年]): [手法の概要を2-3文で説明します。\n  何を目的として、どのようなアプローチを取り、どのような結果を得たかを記述します。]\n\n- **[手法2の名前]** ([著者], [年]): [同様に説明します]\n\n**本研究との関係**:\n本研究は、これらの手法と比較して[どのように異なるか/どのように発展させているか]\nという点で差別化されています。具体的には、[具体的な違いの説明]という特徴があります。\n```\n\n#### Method / Approach の詳細分析\n\n**このセクションは最も詳細に分析します。**\n\n以下の項目すべてについて、読者が実装できるレベルの詳細さで記述します：\n\n**手法の動機**:\nなぜこのアプローチを選んだのかを説明します。他のアプローチではなく\nこのアプローチを選んだ理由、期待される利点を記述します。\n\n**全体アーキテクチャ**:\n```markdown\nFigure [X] に、提案手法の全体アーキテクチャを示します。システムは以下の\n[N]個の主要コンポーネントから構成されています：\n\n| コンポーネント | 役割 | 入力 | 出力 |\n|---------------|------|------|------|\n| [コンポーネント1] | [このコンポーネントが担う役割の説明] | [入力データの形式と内容] | [出力データの形式と内容] |\n| [コンポーネント2] | [役割の説明] | [入力] | [出力] |\n```\n\n**各コンポーネントの詳細**:\n```markdown\n#### [コンポーネント1の名前]\n\nこのコンポーネントは[役割]を担当しています。\n\n**処理の流れ**:\n1. まず、入力として[入力の説明]を受け取ります\n2. 次に、[処理1の説明]を行います\n3. その後、[処理2の説明]を実行します\n4. 最後に、[出力の説明]を生成します\n\n**重要な数式**:\nこのコンポーネントの中核となる処理は、以下の数式で表されます：\n\n$$[数式]$$\n\nここで：\n- $[変数1]$: [変数1の意味と次元]\n- $[変数2]$: [変数2の意味と次元]\n- $[変数3]$: [変数3の意味と典型的な値の範囲]\n\nこの数式の意味は、[数式が何を計算しているのか、なぜこの形式なのかの説明]です。\n```\n\n**アルゴリズム**:\n```markdown\n#### アルゴリズムの詳細\n\n論文の Algorithm [X] に示されている処理の流れを以下に説明します：\n\n```\n入力: [入力の説明]\n出力: [出力の説明]\n\n1. [ステップ1の処理内容]\n2. [ステップ2の処理内容]\n3. for each [要素] in [集合]:\n4.     [ループ内の処理]\n5. end for\n6. return [戻り値]\n```\n\n**各ステップの解説**:\n- ステップ1では、[このステップが何をしているのか、なぜ必要なのかの説明]\n- ステップ2では、[同様の説明]\n- ステップ3-5のループでは、[ループの目的と処理内容の説明]\n```\n\n**理論的根拠**:\n定理や証明がある場合は以下のように記述します：\n\n```markdown\n#### 理論的保証\n\n本手法には以下の理論的保証があります。\n\n**定理 [X]**: [定理の statement を記載]\n\nこの定理は、[定理が意味すること、なぜ重要かの説明]を示しています。\n\n**証明の概要**:\n証明は以下の流れで行われています：\n1. まず、[証明の第一段階の説明]\n2. 次に、[第二段階の説明]\n3. 最後に、[結論の導出]\n```\n\n**実装の詳細**:\n```markdown\n#### 実装の詳細\n\n**使用フレームワーク**: [PyTorch/TensorFlow/JAX 等]\n\n**重要なハイパーパラメータ**:\n\n| パラメータ | 値 | 説明 |\n|-----------|-----|------|\n| [パラメータ1] | [値] | [このパラメータが何を制御するか、なぜこの値を選んだかの説明] |\n| [パラメータ2] | [値] | [説明] |\n\n**計算リソース**:\n- GPU: [使用したGPUの種類と数]\n- 学習時間: [かかった時間]\n- 推論時間: [1サンプルあたりの時間]\n```\n\n#### Experiments の詳細分析\n\n**実験の目的**:\nこの実験セクションで検証しようとしている仮説や主張を明確にします。\n\n**データセット**:\n```markdown\n#### 使用データセット\n\n| データセット | サイズ | 特徴 | 用途 |\n|-------------|-------|------|------|\n| [データセット1] | [サンプル数、特徴量数等] | [データの特徴、ドメイン] | [学習/検証/テスト] |\n\n**[データセット1]の詳細**:\n[データセット1]は[作成元/目的]のために構築されたデータセットです。\n[データの形式、含まれる情報、データセットの特徴]を含んでいます。\n本研究では、[データセットをどのように使用したか、前処理の内容]を行っています。\n```\n\n**評価指標**:\n```markdown\n#### 評価指標\n\n本研究では以下の評価指標を使用しています：\n\n**[指標1の名前]**:\n$$[数式]$$\n\nこの指標は[何を測定するのか]を表しています。値が[高い/低い]ほど\n[良い/悪い]ことを意味します。この指標を選んだ理由は、[選択理由の説明]です。\n```\n\n**ベースライン手法**:\n```markdown\n#### ベースライン手法\n\n比較対象として以下の手法を使用しています：\n\n| 手法 | 概要 | 実装 |\n|------|------|------|\n| [手法1] | [手法の概要と特徴を2-3文で説明] | [著者公開実装/再実装] |\n```\n\n#### Results の詳細分析\n\n**主要結果の完全な転記と解説**:\n```markdown\n#### 主要な実験結果\n\nTable [X] に主要な実験結果を示します。\n\n| 手法 | [指標1] | [指標2] | [指標3] |\n|------|---------|---------|---------|\n| [ベースライン1] | [値] | [値] | [値] |\n| [ベースライン2] | [値] | [値] | [値] |\n| **提案手法** | **[値]** | **[値]** | **[値]** |\n\n**結果の解説**:\nこの結果から、以下のことが読み取れます：\n\n1. 提案手法は[指標1]において、最も性能の高いベースラインである[手法名]と\n   比較して[X]%の改善を達成しています。これは[改善の意義の説明]を示しています。\n\n2. [指標2]については、[結果の解釈と意味]という傾向が見られます。\n\n3. 特筆すべき点として、[特に重要な発見や洞察]が挙げられます。\n```\n\n**アブレーション研究**:\n```markdown\n#### アブレーション研究\n\n提案手法の各コンポーネントの貢献を検証するため、以下のアブレーション実験を\n行っています：\n\n| 条件 | [指標] | 変化 |\n|------|--------|------|\n| 完全な提案手法 | [値] | (基準) |\n| [コンポーネント1]を除去 | [値] | [X]%低下 |\n| [コンポーネント2]を除去 | [値] | [Y]%低下 |\n\n**考察**:\n- [コンポーネント1]の除去により[X]%の性能低下が見られることから、\n  [このコンポーネントの重要性/役割]が確認されます。\n- [コンポーネント2]については、[結果の解釈]であることがわかります。\n```\n\n**定性的分析**:\n```markdown\n#### 定性的分析\n\n**成功例**:\nFigure [X] に提案手法の成功例を示します。[成功例の具体的な説明、\nなぜ成功したかの分析]\n\n**失敗例**:\n一方、Figure [Y] に示すケースでは、提案手法は期待通りの結果を\n得られていません。この失敗の原因として、[失敗の原因分析、\nどのような入力で失敗しやすいか]が考えられます。\n```\n\n#### Conclusion の詳細分析\n\n```markdown\n### 結論\n\n#### 主要な貢献\n\n本論文の主要な貢献は以下の通りです：\n\n1. **[貢献1のタイトル]**: [貢献1の詳細な説明。何を達成し、なぜそれが重要か]\n\n2. **[貢献2のタイトル]**: [貢献2の詳細な説明]\n\n3. **[貢献3のタイトル]**: [貢献3の詳細な説明]\n\n#### 限界と課題\n\n著者らは以下の限界を認めています：\n\n- **[限界1]**: [限界の詳細な説明と、それが実用上どのような問題を引き起こすか]\n- **[限界2]**: [限界の説明]\n\n#### 今後の研究方向\n\n本研究を発展させる方向として、以下が示唆されています：\n\n- **[方向1]**: [具体的な研究の方向性と期待される成果]\n- **[方向2]**: [方向性の説明]\n```\n\n---\n\n### 4. 参照論文の詳細調査\n\nReferences セクションから**重要な論文を 5-10 本**特定します。\n\n**重要な論文の選定基準**:\n- 本文で詳しく議論されている\n- ベースラインとして使用されている\n- 提案手法の基盤となっている\n- 比較対象として重要\n\n各論文について `WebSearch` で調査し、以下の形式で詳細に記述します：\n\n```markdown\n### [論文番号]. [論文タイトル]\n\n| 項目 | 内容 |\n|------|------|\n| **著者** | [著者名] |\n| **年** | [年] |\n| **発表先** | [会議/ジャーナル名] |\n| **URL** | [arXiv/公式URL] |\n\n#### 概要\n\n[この論文が何を目的として、どのような手法を提案し、どのような結果を得たかを\n3-5文で説明します。専門用語は必ず説明を付けてください。]\n\n#### 主要な貢献\n\nこの論文の主要な貢献は以下の通りです：\n- **[貢献1]**: [貢献の詳細な説明]\n- **[貢献2]**: [貢献の詳細な説明]\n\n#### 手法の概要\n\n[技術的な手法の説明を、読者が理解できるレベルの詳細さで記述します。\n重要な概念やアルゴリズムの流れを説明してください。]\n\n#### 本論文での引用箇所・方法\n\n分析対象の論文では、この参照論文を以下のように引用しています：\n- セクション[X.X]で[ベースライン/基盤手法/比較対象]として使用\n- 「[原文引用]」と言及されています\n\n#### この論文の限界\n\nこの参照論文には以下の限界があり、分析対象の論文はそれを以下のように解決しています：\n- **[限界]**: [限界の説明]\n- **解決方法**: [分析対象論文がどのように解決しているか]\n\n#### 本論文との関係\n\n[基盤手法/ベースライン/関連アプローチ/評価手法] として位置づけられています。\n[より詳細な関係性の説明]\n```\n\n**参照論文のカテゴリ分類**:\n以下のカテゴリに分類して整理します：\n- **基盤となる手法**: 提案手法が依拠している先行研究\n- **比較対象（ベースライン）**: 実験で比較している手法\n- **関連するアプローチ**: 類似の問題を扱う別のアプローチ\n- **評価手法・ベンチマーク**: 評価に使用したベンチマーク論文\n- **応用分野**: 応用先に関する論文\n\n---\n\n### 5. レポート生成\n\n`reports/{arxiv_id}_report.md` として保存します。\n\n---\n\n## 詳細分析のポイント\n\n### 論文からの引用\n\n- **重要な主張**は原文を引用し、日本語で詳しく解説します\n  ```markdown\n  > \"Our method achieves state-of-the-art performance on X benchmark while\n  > reducing computational cost by 50%.\"\n\n  この文は、提案手法がXベンチマークにおいて最先端の性能を達成しながら、\n  同時に計算コストを50%削減したことを主張しています。従来は性能と効率は\n  トレードオフの関係にあると考えられていましたが、本研究はその両立に\n  成功したという点で重要な貢献をしています。\n  ```\n- **数値結果は正確に**引用します（四捨五入しない）\n- **図表の説明**を含めます（「Figure 1 に示すように...」）\n\n### 精度と完全性\n\n- **論文が言っていること**だけを書きます\n- **推測や解釈**は明示的に区別します（「推測ですが」「おそらく」等）\n- **わからないこと**は「論文に記載なし」と明記します\n- **数式**はできる限り正確に転記し、各変数の意味を説明します\n\n### サーベイ論文特有の注意点\n\n- 紹介されている**各手法を公平に**説明します\n- **分類体系（Taxonomy）を正確に**再現します\n- **比較表を完全に**転記し、各項目の意味を解説します\n- サーベイ著者の**評価・意見**と**事実**を区別します\n\n### 研究論文特有の注意点\n\n- **主張の強さ**を正確に伝えます（\"demonstrates\" vs \"suggests\" の違い等）\n- **実験の限界**を見逃さないようにします\n- **再現に必要な情報**が記載されているか確認します\n\n---\n\n## Python API の活用\n\n### 基本的な使用方法\n\n```python\nfrom src.paper_analyzer import PaperAnalyzer, AnalysisConfig\nfrom pathlib import Path\n\n# 分析を実行します\nconfig = AnalysisConfig(output_dir=Path(\"reports\"))\nanalyzer = PaperAnalyzer(config)\npaper = analyzer.load_from_url(\"https://arxiv.org/abs/2401.12345\")\n\n# ドキュメント情報を確認（長いドキュメントの場合に重要）\nif analyzer.is_long_document:\n    print(analyzer.get_analysis_guidance())\n\n# 論文タイプを設定します\nanalyzer.set_section(\"paper_type\", \"survey\")  # or \"research\"\n\n# サーベイ論文の場合: 分類体系を設定します\nanalyzer.set_section(\"taxonomy_overview\", \"本サーベイは3つの軸で分類しています...\")\nanalyzer.set_section(\"taxonomy_categories\", [\n    \"カテゴリ1: 説明\",\n    \"カテゴリ2: 説明\",\n])\n\n# 紹介されている手法を追加します\nanalyzer.add_surveyed_method(\n    name=\"MethodName\",\n    paper_ref=\"Author et al., 2023\",\n    summary=\"手法の概要\",\n    technical_details=\"技術的詳細\",\n    advantages=[\"利点1\", \"利点2\"],\n    limitations=[\"限界1\"],\n    category=\"カテゴリ1\",\n)\n\n# 研究論文の場合: 主張とロジックを設定します\nanalyzer.set_section(\"main_claim\", \"本論文の主要な主張\")\nanalyzer.set_section(\"claim_evidence\", \"主張を支える根拠\")\nanalyzer.set_section(\"novelty\", \"新規性のポイント\")\n\n# レポートを生成します\nreport_path = analyzer.generate_report()\n```\n\n### 長いドキュメント用 API\n\n```python\nfrom src.paper_analyzer import PaperAnalyzer, AnalysisConfig, ChunkingStrategy\nfrom src.pdf_chunker import PDFChunker, get_pdf_info\nfrom pathlib import Path\n\n# 長いドキュメント用の設定\nconfig = AnalysisConfig(\n    output_dir=Path(\"reports\"),\n    long_document_threshold=50,      # 50ページ以上で「長い」と判定\n    very_long_document_threshold=100, # 100ページ以上で「非常に長い」と判定\n    chunking_strategy=ChunkingStrategy.SMART,\n    target_chunk_size=20,             # 目標チャンクサイズ\n)\n\nanalyzer = PaperAnalyzer(config)\npaper = analyzer.load_from_url(\"https://arxiv.org/abs/XXXX.XXXXX\")\n\n# ドキュメント情報を取得\ndoc_info = analyzer.document_info\nprint(f\"ページ数: {doc_info.page_count}\")\nprint(f\"推奨戦略: {doc_info.recommended_strategy.value}\")\nprint(f\"チャンク数: {doc_info.estimated_chunks}\")\n\n# チャンク情報を確認\nfor chunk in doc_info.chunk_info:\n    print(f\"Chunk {chunk[''id'']}: p.{chunk[''start'']}-{chunk[''end'']}\")\n\n# チャンクごとに分析して結果を追加\nanalyzer.add_chunk_result(\n    chunk_id=1,\n    start_page=1,\n    end_page=20,\n    title=\"Introduction\",\n    content_summary=\"本論文は...\",\n    key_points=[\"ポイント1\", \"ポイント2\"],\n)\n\n# 進捗を確認\nprint(analyzer.get_progress_summary())\n\n# 残りのチャンクを確認\nremaining = analyzer.get_remaining_chunks()\nprint(f\"残りチャンク: {len(remaining)}\")\n```\n\n### PDF チャンカーの直接使用\n\n```python\nfrom src.pdf_chunker import get_pdf_info, export_chunks_to_files\n\n# PDF 情報を取得\ninfo = get_pdf_info(\"downloads/2401.12345.pdf\")\nprint(f\"ページ数: {info.page_count}\")\nprint(f\"目次あり: {info.has_toc}\")\nprint(f\"セクション数: {len(info.sections)}\")\nprint(f\"長いドキュメント: {info.is_long_document}\")\nprint(f\"非常に長いドキュメント: {info.is_very_long_document}\")\n\n# 長いドキュメントの場合、チャンクをファイルにエクスポート\nif info.is_long_document:\n    result = export_chunks_to_files(\n        \"downloads/2401.12345.pdf\",\n        output_dir=\"chunks/2401.12345\",\n        arxiv_id=\"2401.12345\",\n        strategy=\"smart\",\n        target_pages=20,\n    )\n    print(f\"Exported {result.total_chunks} chunks to {result.output_dir}\")\n\n    # 各チャンクファイルを Read ツールで読み取り可能\n    for chunk_file in result.chunk_files:\n        print(f\"  - {chunk_file}\")\n```\n\nCLI からチャンクをエクスポート:\n```bash\nuv run pdf-chunker downloads/2401.12345.pdf --export-dir chunks/2401.12345\n```\n\n---\n\n## レポートセクション構成\n\n| セクション | サーベイ論文 | 研究論文 |\n|------------|-------------|----------|\n| 概要 | サーベイの範囲と目的 | 主要な主張とキーポイント |\n| 背景 | 分野の概要と課題 | 問題設定と研究ギャップ |\n| 本論 | 分類体系と各手法の説明 | 提案手法の詳細 |\n| 比較/実験 | 手法の比較分析 | 実験設定と結果 |\n| 参照論文 | サーベイ内の重要論文 | 引用された重要論文 |\n| 結論 | 分野の現状と展望 | 貢献と限界 |\n\n---\n\n## 注意事項\n\n- **【最重要】すべての記述は「ですます調（敬体）」と「丁寧語」で統一してください**\n- 論文の内容を**正確に**反映します（解釈を加えすぎない）\n- 数値や主張は**原文に忠実**に引用します\n- 長い論文は処理に時間がかかることがあります\n- 参照論文は重要度の高い 5-10 本に絞って**詳細に**調査します\n- 数式や図表の詳細な再現には限界があります\n- 旧形式の arXiv ID はファイル名で `/` を `_` に置換します\n\n---\n\n## 最終チェックリスト\n\nレポート完成前に以下を確認してください：\n\n- [ ] **文体**: すべての文が「ですます調（敬体）」で書かれていますか？\n- [ ] **丁寧語**: 「である」「だ」「している」などの常体が混在していませんか？\n- [ ] **一貫性**: レポート全体で文体が統一されていますか？\n"},"lastSynced":"2026-03-08T02:13:42.636Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing in-depth analysis of arXiv papers with detailed chapter and section breakdowns.","zh":"非常适合需要对arXiv论文进行深入分析的研究代理，包括详细的章节和部分细分。","ja":"arXiv論文の詳細な章とセクションのブレークダウンを必要とする研究エージェントに最適です。","ko":"arXiv 논문의详细한 章과 섹션의 분해를 필요로 하는 연구 에이전트에게 적합합니다.","es":"Perfecto para agentes de investigación que necesitan un análisis en profundidad de los documentos de arXiv con desgloses detallados de capítulos y secciones.","fr":"Parfait pour les agents de recherche nécessitant une analyse approfondie des documents arXiv avec des décompositions détaillées de chapitres et de sections.","de":"Perfekt für Forschungsagenten, die eine detaillierte Analyse von arXiv-Papern mit detaillierter Kapitel- und Abschnittszerlegung benötigen.","pt":"Perfeito para Agentes de Pesquisa que necessitam de análise aprofundada de artigos do arXiv com quebra de capítulo e seção detalhada.","ru":"Идеально для исследовательских агентов, которым требуется детальный анализ статей arXiv с подробным разбором глав и разделов.","ar":"مثالي للوكلاء البحثيين الذين يحتاجون إلى تحليل متعمق لأوراق arXiv مع كسر فصل ومقسم تفصيلي."},"recommendation":{"en":"Empowers agents to generate comprehensive reports on long documents, including those over 100 pages, using a chunk export workflow for efficient processing, and supports PDF analysis up to 10MB.","zh":"赋予代理生成长文档的综合报告的能力，包括超过100页的文档，使用chunk导出工作流进行高效处理，并支持最多10MB的PDF分析。","ja":"エージェントが長いドキュメント、100ページを超えるものを含む、効率的な処理のためのチャンクエクスポートワークフローを使用して、包括的なレポートを生成する能力を提供し、最大10MBのPDF分析をサポートします。","ko":"에이전트가 장문 문서에 대한 포괄적인 보고서를 생성할 수 있는 능력을 부여합니다. 100 페이지 이상의 문서를 포함하여 효율적인 처리를 위한 청크 내보내기 워크플로우를 사용하고 최대 10MB의 PDF 분석을 지원합니다.","es":"Permite a los agentes generar informes completos sobre documentos largos, incluidos aquellos de más de 100 páginas, utilizando un flujo de trabajo de exportación de fragmentos para un procesamiento eficiente, y admite el análisis de PDF de hasta 10MB.","fr":"Permet aux agents de générer des rapports complets sur de longs documents, y compris ceux de plus de 100 pages, en utilisant un workflow d''exportation de fragments pour un traitement efficace, et prend en charge l''analyse de PDF jusqu''à 10Mo.","de":"Ermächtigt Agenten, umfassende Berichte über lange Dokumente zu erstellen, einschließlich solcher mit mehr als 100 Seiten, unter Verwendung eines Chunk-Export-Workflows für ein effizientes Verarbeiten und unterstützt die Analyse von PDF-Dateien bis zu 10MB.","pt":"Habilita os agentes a gerar relatórios abrangentes sobre documentos longos, incluindo aqueles com mais de 100 páginas, usando um fluxo de trabalho de exportação de pedaços para processamento eficiente e suporta análise de PDF de até 10MB.","ru":"Наделяет агентов возможностью генерировать комплексные отчеты о длинных документах, включая те, которые превышают 100 страниц, используя рабочий процесс экспорта фрагментов для эффективной обработки, и поддерживает анализ PDF до 10МБ.","ar":"يمكن الوكلاء من生成 تقارير شاملة حول المستندات الطويلة، بما في ذلك تلك التي تزيد عن 100 صفحة، باستخدام تدفق عمل لتصدير قطع للобработة الفعالة، ودعم تحليل PDF يصل إلى 10MB."},"useCases":{"en":["Analyzing lengthy academic papers","Generating detailed chapter and section summaries","Exporting chunks of large documents for efficient review"],"zh":["分析冗长的学术论文","生成详细的章节和部分摘要","导出大型文档的块以便于审查"],"ja":["長い学術論文の分析","詳細な章とセクションのサマリーの生成","効率的なレビューのための大規模ドキュメントのチャンクのエクスポート"],"ko":["길い 학술 논문의 분석","詳細한 장과 절의 요약 생성","효율적인 검토를 위한 대형 문서의 청크 내보내기"],"es":["Análisis de artículos académicos extensos","Generación de resúmenes detallados de capítulos y secciones","Exportación de fragmentos de documentos grandes para una revisión eficiente"],"fr":["Analyse de documents universitaires longs","Génération de résumés détaillés de chapitres et de sections","Exportation de fragments de grands documents pour une revue efficace"],"de":["Analyse umfangreicher akademischer Artikel","Erstellung detaillierter Kapitel- und Abschnittszusammenfassungen","Export von Fragmenten großer Dokumente für eine effiziente Überprüfung"],"pt":["Analisar artigos acadêmicos longos","Gerar resumos detalhados de capítulo e seção","Exportar pedaços de documentos grandes para revisão eficiente"],"ru":["Анализ длинных академических статей","Генерирование подробных резюме глав и разделов","Экспорт фрагментов крупных документов для эффективного обзора"],"ar":["تحليل الأوراق الأكاديمية الطويلة","توليد ملخصات مفصلة للفصل والقسم","تصدير قطع من المستندات الكبيرة لمراجعة فعالة"]},"limitations":{"en":["Requires chunk export workflow for documents over 100 pages or 10MB","Limited to arXiv papers and PDF format"],"zh":["需要chunk导出工作流来处理超过100页或10MB的文档","仅限arXiv论文和PDF格式"],"ja":["100ページを超える文書や10MBを超える文書の処理にはチャンクエクスポートワークフローが必要","arXiv論文とPDF形式のみに対応"],"ko":["100 페이지 이상 또는 10MB 이상의 문서를 처리하기 위해 청크 내보내기 워크플로우가 필요","arXiv 논문 및 PDF 형식만 해당"],"es":["Requiere un flujo de trabajo de exportación de fragmentos para documentos de más de 100 páginas o 10MB","Limitado a documentos de arXiv y formato PDF"],"fr":["Nécessite un workflow d''exportation de fragments pour les documents de plus de 100 pages ou 10Mo","Limité aux documents arXiv et au format PDF"],"de":["Benötigt einen Chunk-Export-Workflow für Dokumente über 100 Seiten oder 10MB","Begrenzt auf arXiv-Dokumente und PDF-Format"],"pt":["Exige fluxo de trabalho de exportação de pedaços para documentos com mais de 100 páginas ou 10MB","Limitado a artigos do arXiv e formato PDF"],"ru":["Требует рабочего процесса экспорта фрагментов для документов более 100 страниц или 10МБ","Ограничен статьями arXiv и форматом PDF"],"ar":["يتطلب تدفق عمل لتصدير قطع للمستندات التي تزيد عن 100 صفحة أو 10MB","محدود بأوراق arXiv وتنسيق PDF"]},"version":4},"contentHash":"31a61cd2a7fc0f4dcbf5909e1430ae2b6b90d1e4e3b9270f7bf742fddc7b9589","qualityScore":36}');
