INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shibuiwilliam/paper2detail/analyze-paper', 'analyze-paper', 'shibuiwilliam', 'paper2detail', 'community', 'analyze-paper shibuiwilliam paper2detail community The analyze-paper skill generates detailed reports on arXiv papers, including chapter and section analysis. It supports long documents over 100 pages and provides a chunk export workflow for efficient processing. analyze-paper 是一个用于分析 arXiv 论文的工具，能够处理长文档和章节分析 analyze-paper は arXiv 論文を分析するツールで、長いドキュメントと章の分析に対応しています analyze-paper는 arXiv 논문을 분석하는 도구로, 긴 문서와 장 분석을 지원합니다 Analyze-paper es una habilidad que analiza documentos de investigación y genera informes detallados sobre cada capítulo y sección, incluyendo referencias y análisis profundos Analyze-paper est une compétence qui analyse des documents de recherche et génère des rapports détaillés sur chaque chapitre et section, y compris des références et des analyses approfondies Analyze-paper ist eine Fähigkeit, die Forschungsdokumente analysiert und detaillierte Berichte über jedes Kapitel und jede Sektion generiert, einschließlich Referenzen und tiefer Analysen O analyze-paper é uma ferramenta de análise de artigos científicos que gera relatórios detalhados sobre cada seção de um artigo em arXiv, incluindo referências. ИИ Агент analyze-paper - это инструмент для анализа научных статей, который генерирует подробные отчеты о каждом разделе статьи в arXiv, включая ссылки. analyze-paper هو أداة لتحليل المقالات العلمية التي تولد تقارير مفصلة حول كل قسم من مقال في arXiv، بما في ذلك المراجع. how to use analyze-paper what is analyze-paper analyze-paper alternative analyze-paper vs other AI agents analyze-paper install analyze-paper setup guide arXiv paper analysis long document analysis chunk export workflow analyze-paper arXiv 论文分析 长文档处理 章节分析 AI 工具 Read 工具 UV 命令行工具 Generates detailed reports on arXiv papers, including chapter and section analysis Supports long documents over 100 pages using chunk export workflows Utilizes the `uv run arxiv-helper` command for document downloads and page count verification Processes PDF files up to 10MB in size Employs a recommended approach based on page count, including standard and chunk export workflows Provides output in a readable format, including page count and detailed analysis analyze-paper is a skill that analyzes arXiv papers and generates detailed reports, including chapter and section analysis, with support for long documents and chunk export workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leopechnicki/AI-Assistant/sag', 'community', 'leopechnicki', 'AI-Assistant', 'leopechnicki/AI-Assistant', 'sag', 0, 0, 36, '2026-03-08T01:57:15.645Z', '2026-03-08T02:13:45.715Z', 'bcb60cc493272d56164bee8da1e3769073ed306ca108e61e8b77f0f805f77e6b', '{"id":"leopechnicki/AI-Assistant/sag","name":"sag","description":{"en":"The sag skill utilizes ElevenLabs TTS for local playback, allowing developers to generate high-quality audio. It supports various models, including eleven_v3, eleven_multilingual_v2, and eleven_flash_v2_5.","zh":"Sag AI助手是一个使用ElevenLabs TTS实现本地播放的工具，支持多种语音和发音规则","ja":"Sag AIエージェントはElevenLabs TTSを使用してローカル再生を実現するツールです。複数のボイスと発音ルールをサポート","ko":"Sag AI 에이전트는 ElevenLabs TTS를 사용하여 로컬 재생을 구현하는 도구입니다. 여러 가지 음성과 발음 규칙을 지원","es":"sag es una herramienta de asistente de AI para ElevenLabs TTS con reproducción local. Utiliza la clave de API de ElevenLabs para una configuración rápida.","fr":"sag est un outil d''assistant AI pour ElevenLabs TTS avec lecture locale. Il utilise la clé d''API d''ElevenLabs pour une configuration rapide.","de":"sag ist ein AI-Assistenten-Tool für ElevenLabs TTS mit lokaler Wiedergabe. Es verwendet den ElevenLabs-API-Schlüssel für eine schnelle Konfiguration.","pt":"O sag é um assistente de IA que usa o ElevenLabs TTS com reprodução local. Ele suporta modelos de voz como eleven_v3, eleven_multilingual_v2 e eleven_flash_v2_5.","ru":"Sag - это помощник ИИ, использующий ElevenLabs TTS с локальным воспроизведением. Он поддерживает голосовые модели, такие как eleven_v3, eleven_multilingual_v2 и eleven_flash_v2_5.","ar":"sag هو مساعد ذكاء اصطناعي يستخدم ElevenLabs TTS مع تشغيل المحلي. وهو يدعم نماذج الصوت مثل eleven_v3 و eleven_multilingual_v2 و eleven_flash_v2_5."},"seo":{"title":{"en":"sag: ElevenLabs TTS Setup Guide | AI Agent Skill","zh":"Sag AI助手设置指南 - ElevenLabs TTS集成","ja":"Sag AIエージェントの設定方法 - ElevenLabs TTSを活用","ko":"Sag AI 에이전트 설정 가이드 - ElevenLabs TTS 통합","es":"Guía de configuración de sag para ElevenLabs TTS","fr":"Configurer sag pour ElevenLabs TTS : Guide pratique","de":"sag-Setup-Anleitung für ElevenLabs TTS","pt":"Guia de Configuração do sag: ElevenLabs TTS com Reproduçã...","ru":"Настройка sag: ElevenLabs TTS с локальным воспроизведением","ar":"دليل إعداد sag: ElevenLabs TTS مع تشغيل محلي"},"description":{"en":"Discover how to use sag for local playback with ElevenLabs TTS. Get started with our quick start guide and explore model notes, pronunciation rules, and more.","zh":"了解Sag AI助手的功能和设置方法，利用ElevenLabs TTS实现本地播放，快速开始使用","ja":"Sag AIエージェントの機能と設定方法を紹介します。ElevenLabs TTSを使用してローカル再生を実現する方法を知る","ko":"Sag AI 에이전트의 기능과 설정 방법을 알아보세요. ElevenLabs TTS를 사용하여 로컬 재생을 구현하는 방법을 빠르게 시작","es":"Aprende a utilizar sag con ElevenLabs TTS para reproducción local con nuestra guía paso a paso","fr":"Découvrez comment configurer sag pour utiliser ElevenLabs TTS avec une reproduction locale avec notre guide étape par étape","de":"Erfahren Sie, wie Sie sag mit ElevenLabs TTS für lokale Wiedergabe mit unserer Schritt-für-Schritt-Anleitung verwenden","pt":"Aprenda a usar o sag com o ElevenLabs TTS e reprodução local. Veja como configurar e usar a API com chaves de API e modelos de voz.","ru":"Узнайте, как использовать sag с ElevenLabs TTS и локальным воспроизведением. Просмотрите, как настроить и использовать API с ключами API и голосовыми моделями.","ar":"تعرف على كيفية استخدام sag مع ElevenLabs TTS وتشغيل المحلي. استعرض كيفية ضبط واستخدام API مع مفاتيح API ونماذج الصوت."},"definition":{"en":"sag is a command-line interface for ElevenLabs TTS, enabling local playback and customization of text-to-speech output.","zh":"Sag AI助手是一种使用ElevenLabs TTS技术的AI工具","ja":"Sag AIエージェントはElevenLabs TTS技術を使用するAIエージェントの一種","ko":"Sag AI 에이전트는 ElevenLabs TTS 기술을 사용하는 AI 에이전트의 일종","es":"sag es un agente de AI para ElevenLabs TTS que permite la reproducción local de audio","fr":"sag est un agent AI pour ElevenLabs TTS qui permet la lecture locale de l''audio","de":"sag ist ein AI-Agent für ElevenLabs TTS, der die lokale Wiedergabe von Audio ermöglicht","pt":"O sag é um assistente de IA que fornece reprodução local de áudio com o ElevenLabs TTS.","ru":"Sag - это помощник ИИ, обеспечивающий локальное воспроизведение аудио с помощью ElevenLabs TTS.","ar":"sag هو مساعد ذكاء اصطناعي يقدم تشغيل صوت محلي مع ElevenLabs TTS."},"features":{"en":["Utilizes ElevenLabs TTS for local playback","Supports multiple models, including eleven_v3, eleven_multilingual_v2, and eleven_flash_v2_5","Allows for pronunciation and delivery rule customization","Provides quick start commands, such as `sag \"Hello there\"` and `sag speak -v \"Roger\" \"Hello\"`","Offers model-specific tips with `sag prompting` command","Requires API key, supporting both `ELEVENLABS_API_KEY` and `SAG_API_KEY`"],"zh":["支持ElevenLabs TTS本地播放","多种语音选择（eleven_v3、eleven_multilingual_v2、eleven_flash_v2_5）","自定义发音规则","支持CLI命令行操作","快速开始使用示例代码"],"ja":["ElevenLabs TTSローカル再生をサポート","複数のボイスを選択可能（eleven_v3、eleven_multilingual_v2、eleven_flash_v2_5）","発音ルールをカスタマイズ","CLIコマンドライン操作をサポート","クイックスタート用のサンプルコードを提供"],"ko":["ElevenLabs TTS 로컬 재생을 지원","여러 가지 음성을 선택할 수 있음（eleven_v3、eleven_multilingual_v2、eleven_flash_v2_5）","발음 규칙을 사용자 정의","CLI 명령행操作을 지원","빠르게 시작하는 예제 코드를 제공"],"es":["Reproducción local de audio con ElevenLabs TTS","Compatibilidad con la clave de API de ElevenLabs","Modelos de voz preestablecidos como eleven_v3 y eleven_multilingual_v2","Reglas de pronunciación y entrega personalizables","Soporte para respellar y ajustar el caso de las palabras"],"fr":["Lecture locale de l''audio avec ElevenLabs TTS","Compatibilité avec la clé d''API d''ElevenLabs","Modèles de voix prédéfinis tels que eleven_v3 et eleven_multilingual_v2","Règles de prononciation et de livraison personnalisables","Prise en charge de la respellation et de l''ajustement du cas des mots"],"de":["Lokale Wiedergabe von Audio mit ElevenLabs TTS","Unterstützung für den ElevenLabs-API-Schlüssel","Vordefinierte Sprachmodelle wie eleven_v3 und eleven_multilingual_v2","Anpassbare Ausspracheregeln und Lieferbedingungen","Unterstützung für die Neuschreibung und Anpassung des Wortfalls"],"pt":["Suporte a modelos de voz como eleven_v3, eleven_multilingual_v2 e eleven_flash_v2_5","Reprodução local de áudio com o ElevenLabs TTS","Uso de chaves de API como ELEVENLABS_API_KEY e SAG_API_KEY","Comandos CLI para executar ações como ''sag speak'' e ''sag voices''","Dicas de modelagem específicas para cada modelo de voz","Regras de pronúncia e entrega para melhorar a qualidade do áudio"],"ru":["Поддержка голосовых моделей, таких как eleven_v3, eleven_multilingual_v2 и eleven_flash_v2_5","Локальное воспроизведение аудио с помощью ElevenLabs TTS","Использование ключей API, таких как ELEVENLABS_API_KEY и SAG_API_KEY","Команды CLI для выполнения действий, таких как ''sag speak'' и ''sag voices''","Советы по моделированию для каждого голосового модели","Правила произношения и доставки для улучшения качества аудио"],"ar":["دعم نماذج الصوت مثل eleven_v3 و eleven_multilingual_v2 و eleven_flash_v2_5","تشغيل صوت محلي مع ElevenLabs TTS","استخدام مفاتيح API مثل ELEVENLABS_API_KEY و SAG_API_KEY","أوامر CLI لتنفيذ إجراءات مثل ''sag speak'' و ''sag voices''","نصائح نمذجة محددة لكل نموذج صوت","قواعد النطق والتسليم لتحسين جودة الصوت"]},"keywords":{"en":["how to use sag","sag alternative","sag setup guide","ElevenLabs TTS integration","sag vs Google TTS","sag install","what is sag","sag api key","sag models"],"zh":["Sag AI助手","ElevenLabs TTS","本地播放","AI工具","语音合成","发音规则","CLI命令行"],"ja":["Sag AIエージェント","ElevenLabs TTS","ローカル再生","AIエージェント","音声合成","発音ルール","CLIコマンドライン"],"ko":["Sag AI 에이전트","ElevenLabs TTS","로컬 재생","AI 에이전트","음성합성","발음 규칙","CLI 명령행"],"es":["sag","ElevenLabs TTS","reproducción local","clave de API","modelos de voz","reglas de pronunciación","agentes de AI","herramientas de AI","desarrollo de audio"],"fr":["sag","ElevenLabs TTS","lecture locale","clé d''API","modèles de voix","règles de prononciation","agents AI","outils AI","développement audio"],"de":["sag","ElevenLabs TTS","lokale Wiedergabe","API-Schlüssel","Sprachmodelle","Ausspracheregeln","AI-Agenten","AI-Tools","Audio-Entwicklung"],"pt":["sag","ElevenLabs TTS","reprodução local","modelos de voz","chaves de API","CLI","assistente de IA","áudio","pronúncia","entrega"],"ru":["sag","ElevenLabs TTS","локальное воспроизведение","голосовые модели","ключи API","CLI","помощник ИИ","аудио","произношение","доставка"],"ar":["sag","ElevenLabs TTS","تشغيل المحلي","نماذج الصوت","مفاتيح API","CLI","مساعد ذكاء اصطناعي","صوت","نطق","تسليم"]}},"owner":"leopechnicki","repo":"AI-Assistant","repoPath":"leopechnicki/AI-Assistant","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.645Z","topics":[],"category":"community","skillMd":{"name":"sag","description":"ElevenLabs text-to-speech with mac-style say UX.","bodyPreview":"# sag\n\nUse `sag` for ElevenLabs TTS with local playback.\n\nAPI key (required)\n\n- `ELEVENLABS_API_KEY` (preferred)\n- `SAG_API_KEY` also supported by the CLI\n\nQuick start\n\n- `sag \"Hello there\"`\n- `sag speak -v \"Roger\" \"Hello\"`\n- `sag voices`\n- `sag prompting` (model-specific tips)\n\nModel notes\n\n- Default: `eleven_v3` (expressive)\n- Stable: `eleven_multilingual_v2`\n- Fast: `eleven_flash_v2_5`\n\nPronunciation + delivery rules\n\n- First fix: respell (e.g. \"key-note\"), add hyphens, adjust casing.\n- Numbe","body":"# sag\n\nUse `sag` for ElevenLabs TTS with local playback.\n\nAPI key (required)\n\n- `ELEVENLABS_API_KEY` (preferred)\n- `SAG_API_KEY` also supported by the CLI\n\nQuick start\n\n- `sag \"Hello there\"`\n- `sag speak -v \"Roger\" \"Hello\"`\n- `sag voices`\n- `sag prompting` (model-specific tips)\n\nModel notes\n\n- Default: `eleven_v3` (expressive)\n- Stable: `eleven_multilingual_v2`\n- Fast: `eleven_flash_v2_5`\n\nPronunciation + delivery rules\n\n- First fix: respell (e.g. \"key-note\"), add hyphens, adjust casing.\n- Numbers/units/URLs: `--normalize auto` (or `off` if it harms names).\n- Language bias: `--lang en|de|fr|...` to guide normalization.\n- v3: SSML `<break>` not supported; use `[pause]`, `[short pause]`, `[long pause]`.\n- v2/v2.5: SSML `<break time=\"1.5s\" />` supported; `<phoneme>` not exposed in `sag`.\n\nv3 audio tags (put at the entrance of a line)\n\n- `[whispers]`, `[shouts]`, `[sings]`\n- `[laughs]`, `[starts laughing]`, `[sighs]`, `[exhales]`\n- `[sarcastic]`, `[curious]`, `[excited]`, `[crying]`, `[mischievously]`\n- Example: `sag \"[whispers] keep this quiet. [short pause] ok?\"`\n\nVoice defaults\n\n- `ELEVENLABS_VOICE_ID` or `SAG_VOICE_ID`\n\nConfirm voice + speaker before long output.\n\n## Chat voice responses\n\nWhen Peter asks for a \"voice\" reply (e.g., \"crazy scientist voice\", \"explain in voice\"), generate audio and send it:\n\n```bash\n# Generate audio file\nsag -v Clawd -o /tmp/voice-reply.mp3 \"Your message here\"\n\n# Then include in reply:\n# MEDIA:/tmp/voice-reply.mp3\n```\n\nVoice character tips:\n\n- Crazy scientist: Use `[excited]` tags, dramatic pauses `[short pause]`, vary intensity\n- Calm: Use `[whispers]` or slower pacing\n- Dramatic: Use `[sings]` or `[shouts]` sparingly\n\nDefault voice for Clawd: `lj2rcrvANS3gaWWnczSX` (or just `-v Clawd`)\n"},"lastSynced":"2026-03-08T02:13:45.715Z","agentAnalysis":{"suitability":{"en":"Perfect for Voice Assistants and Chatbots needing high-quality text-to-speech capabilities with local playback using ElevenLabs TTS.","zh":"非常适合需要高质量文本转语音能力并使用ElevenLabs TTS进行本地播放的语音助手和聊天机器人","ja":"ElevenLabs TTSを使用してローカル再生する高品質のテキストツースピーチ機能を必要とするボイスアシスタントやチャットボットに最適","ko":"ElevenLabs TTS를 사용하여 로컬 재생하는 고품질의 텍스트 음성 변환 기능이 필요한 보이스 어시스턴트와 채팅봇에 적합","es":"Perfecto para asistentes de voz y chatbots que necesitan capacidades de texto a voz de alta calidad con reproducción local utilizando ElevenLabs TTS.","fr":"Parfait pour les assistants vocaux et les chatbots qui ont besoin de capacités de texte à parole de haute qualité avec une lecture locale à l''aide d''ElevenLabs TTS.","de":"Perfekt für Sprachassistenten und Chatbots, die hochwertige Text-to-Speech-Fähigkeiten mit lokaler Wiedergabe unter Verwendung von ElevenLabs TTS benötigen.","pt":"Perfeito para Assistente de Voz e Chatbots que precisam de capacidades de texto-para-fala de alta qualidade com reprodução local usando ElevenLabs TTS.","ru":"Идеально для голосовых помощников и чат-ботов, требующих высококачественных возможностей текст-в-речь с локальным воспроизведением, используя ElevenLabs TTS.","ar":"مثالي لنظام المساعد الصوتي و Chatbots الذين يحتاجون إلى قدرات النص إلى الكلام عالية الجودة مع تشغيل محلي باستخدام ElevenLabs TTS."},"recommendation":{"en":"Empowers agents to generate high-quality audio using ElevenLabs models such as eleven_v3, eleven_multilingual_v2, and eleven_flash_v2_5, supporting features like pronunciation and delivery rules with API key authentication via ELEVENLABS_API_KEY or SAG_API_KEY.","zh":"通过ELEVENLABS_API_KEY或SAG_API_KEY的API密钥认证，赋予代理生成高质量音频的能力，支持诸如发音和送货规则等功能，使用ElevenLabs的模型，如eleven_v3、eleven_multilingual_v2和eleven_flash_v2_5","ja":"ELEVENLABS_API_KEYまたはSAG_API_KEYによるAPIキー認証を通じて、エージェントに高品質のオーディオを生成する能力を付与する。発音や配信ルールなどの機能をサポートし、ElevenLabsのモデル（eleven_v3、eleven_multilingual_v2、eleven_flash_v2_5）を使用","ko":"ELEVENLABS_API_KEY 또는 SAG_API_KEY를 통한 API 키 인증을 통해 에이전트가 고품질의 오디오를 생성할 수 있는 능력을 부여한다. 발음 및 배달 규칙 등의 기능을 지원하며 ElevenLabs의 모델(eleven_v3, eleven_multilingual_v2, eleven_flash_v2_5)을 사용","es":"Permite a los agentes generar audio de alta calidad utilizando modelos de ElevenLabs como eleven_v3, eleven_multilingual_v2 y eleven_flash_v2_5, que admiten características como reglas de pronunciación y entrega con autenticación de clave de API a través de ELEVENLABS_API_KEY o SAG_API_KEY.","fr":"Permet aux agents de générer un audio de haute qualité en utilisant des modèles ElevenLabs tels que eleven_v3, eleven_multilingual_v2 et eleven_flash_v2_5, prenant en charge des fonctionnalités comme les règles de prononciation et de livraison avec une authentification par clé d''API via ELEVENLABS_API_KEY ou SAG_API_KEY.","de":"Ermöglicht es Agents, hochwertiges Audio unter Verwendung von ElevenLabs-Modellen wie eleven_v3, eleven_multilingual_v2 und eleven_flash_v2_5 zu generieren, die Funktionen wie Ausspracheregeln und Lieferregeln mit API-Schlüsselauthentifizierung über ELEVENLABS_API_KEY oder SAG_API_KEY unterstützen.","pt":"Permite que os agentes gerem áudio de alta qualidade usando modelos ElevenLabs, como eleven_v3, eleven_multilingual_v2 e eleven_flash_v2_5, com suporte a recursos como regras de pronúncia e entrega com autenticação de chave de API via ELEVENLABS_API_KEY ou SAG_API_KEY.","ru":"Позволяет агентам генерировать высококачественный аудио, используя модели ElevenLabs, такие как eleven_v3, eleven_multilingual_v2 и eleven_flash_v2_5, с поддержкой функций, таких как правила произношения и доставки с аутентификацией по ключу API через ELEVENLABS_API_KEY или SAG_API_KEY.","ar":"تمكن الوكلاء من توليد صوت عالي الجودة باستخدام نماذج ElevenLabs مثل eleven_v3 و eleven_multilingual_v2 و eleven_flash_v2_5، مع دعم لميزات مثل قواعد النطق وتسليم مع مصادقة مفتاح واجهة برمجة التطبيقات عبر ELEVENLABS_API_KEY أو SAG_API_KEY."},"useCases":{"en":["Generating voice responses for chatbots","Creating audio content with local playback","Testing text-to-speech models for pronunciation and delivery"],"zh":["为聊天机器人生成语音响应","创建带有本地播放的音频内容","测试文本转语音模型的发音和送货"],"ja":["チャットボットの音声応答を生成する","ローカル再生を含むオーディオコンテンツを作成する","テキストツースピーチモデルを発音や配信ルールでテストする"],"ko":["채팅봇을 위한 음성 응답 생성","로컬 재생을 포함하는 오디오 콘텐츠 생성","텍스트 음성 변환 모델의 발음 및 배달 규칙 테스트"],"es":["Generar respuestas de voz para chatbots","Crear contenido de audio con reproducción local","Probar modelos de texto a voz para la pronunciación y la entrega"],"fr":["Générer des réponses vocales pour les chatbots","Créer du contenu audio avec une lecture locale","Tester les modèles de texte à parole pour la prononciation et la livraison"],"de":["Erzeugen von Sprachantworten für Chatbots","Erstellen von Audioinhalten mit lokaler Wiedergabe","Testen von Text-to-Speech-Modellen für Aussprache und Lieferung"],"pt":["Gerar respostas de voz para chatbots","Criar conteúdo de áudio com reprodução local","Testar modelos de texto-para-fala para pronúncia e entrega"],"ru":["Генерировать голосовые ответы для чат-ботов","Создавать аудиоконтент с локальным воспроизведением","Тестировать модели текст-в-речь для произношения и доставки"],"ar":["توليد استجابات صوتية لأنظمة الدردشة","إنشاء محتوى صوتي مع تشغيل محلي","اختبار نماذج النص إلى الكلام للنطق والتسليم"]},"limitations":{"en":["Requires ElevenLabs API key (ELEVENLABS_API_KEY or SAG_API_KEY)","Limited to ElevenLabs TTS models"],"zh":["需要ElevenLabs API密钥（ELEVENLABS_API_KEY或SAG_API_KEY）","仅限ElevenLabs TTS模型"],"ja":["ElevenLabs APIキー（ELEVENLABS_API_KEYまたはSAG_API_KEY）が必要","ElevenLabs TTSモデルに限定"],"ko":["ElevenLabs API 키(ELEVENLABS_API_KEY 또는 SAG_API_KEY)가 필요","ElevenLabs TTS 모델만 지원"],"es":["Requiere una clave de API de ElevenLabs (ELEVENLABS_API_KEY o SAG_API_KEY)","Limitado a los modelos de TTS de ElevenLabs"],"fr":["Nécessite une clé d''API ElevenLabs (ELEVENLABS_API_KEY ou SAG_API_KEY)","Limité aux modèles de TTS ElevenLabs"],"de":["Benötigt einen ElevenLabs-API-Schlüssel (ELEVENLABS_API_KEY oder SAG_API_KEY)","Begrenzt auf ElevenLabs-TTS-Modelle"],"pt":["Exige chave de API do ElevenLabs (ELEVENLABS_API_KEY ou SAG_API_KEY)","Limitado a modelos de TTS do ElevenLabs"],"ru":["Требует ключа API ElevenLabs (ELEVENLABS_API_KEY или SAG_API_KEY)","Ограничен моделями TTS от ElevenLabs"],"ar":["يتطلب مفتاح واجهة برمجة التطبيقات من ElevenLabs (ELEVENLABS_API_KEY أو SAG_API_KEY)","محدود بنماذج TTS من ElevenLabs"]},"version":4},"contentHash":"bcb60cc493272d56164bee8da1e3769073ed306ca108e61e8b77f0f805f77e6b","qualityScore":36}');
