INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zolkers/better-claude/do', 'do', 'zolkers', 'better-claude', 'community', 'do zolkers better-claude community The do skill automates workflow management, handling planning, execution, review, and git. It creates a plan, executes it step by step, and runs mandatory code reviews. Do 技术是一种自动化工作流技能，能够创建计划、执行计划、运行强制代码检查和 Git 管理 Do 技術は、計画の作成、計画の実行、強制コードチェックの実行、Git 管理などを自動化するワークフロースキル Do 기술은 계획 생성,计划 실행, 강제 코드 검사 실행 및 Git 관리 등을 자동화하는 워크플로우 스킬 El skill ''do'' automatiza la creación de planes, ejecución y revisión en flujos de trabajo de Claude Le skill ''do'' automatise la création de plans, l''exécution et la révision dans les workflows Claude Das Skill ''do'' automatisiert die Erstellung von Plänen, Ausführung und Überprüfung in Claude-Workflows O ''do'' é um fluxo de trabalho principal que automatiza planejamento, execução, revisão e git em um comando. ИИ Агенты: ''do'' - это основной workflow, который автоматизирует планирование, выполнение, проверку и git в одном команде العامل ''do'' هو تدفق عمل رئيسي يautomatiza التخطيط والتنفيذ والمراجعة و git في أمر واحد how to use do do setup guide do alternative do vs other workflow tools do install what is do do workflow automation do git management do code review AI 工具 Do 技术 自动化工作流 计划创建 计划执行 强制代码检查 Git 管理 开发者工具 Automatically creates a plan if none exists or resumes an existing plan Executes the plan step by step Runs mandatory code reviews Manages git workflow Handles planning, execution, and review in a single command do is a workflow automation skill that handles planning, execution, review, and git management, streamlining the development process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('radutopala/ticket/tk', 'community', 'radutopala', 'ticket', 'radutopala/ticket', 'tk', 0, 0, 36, '2026-03-08T01:57:15.648Z', '2026-03-08T02:13:49.814Z', '413ece83edcb25e512d858da0e09e0e3ea43f7d898ccc0e9a751cd8ffa003038', '{"id":"radutopala/ticket/tk","name":"tk","description":{"en":"tk is a minimal CLI ticket management system designed for AI agents, streamlining workflow with markdown files in .tickets/. It benefits developers and AI agents by providing a simple command-line interface for tracking tickets.","zh":"tk是一个Minimal CLI票据管理系统，用于AI代理的票据跟踪","ja":"tkは、AIエージェントのチケット追跡用に設計された最小限のCLIチケット管理システムです","ko":"tk는 AI 에이전트의 티켓 추적을 위한 최소한의 CLI 티켓 관리 시스템입니다","es":"tk es un sistema de gestión de tickets de línea de comandos minimalista diseñado para agentes de inteligencia artificial. Permite crear, ver y gestionar tickets de forma eficiente","fr":"tk est un système de gestion de tickets en ligne de commande minimaliste conçu pour les agents d''intelligence artificielle. Il permet de créer, de visualiser et de gérer des tickets de manière efficace","de":"tk ist ein minimales CLI-Ticketsystem, das für KI-Agents entwickelt wurde. Es ermöglicht die effiziente Erstellung, Anzeige und Verwaltung von Tickets","pt":"O tk é um sistema de gerenciamento de tickets CLI minimalista que permite aos agentes de IA gerenciar tarefas de forma eficiente","ru":"Tk - это минимальная система управления тикетами CLI, которая позволяет ИИ Агентам эффективно управлять задачами","ar":"tk هو نظام إدارة التذاكر CLI الأصغر الذي يسمح للوكلاء الذكاء الاصطناعي بإدارة المهام بفعالية"},"seo":{"title":{"en":"tk: Minimal CLI Ticket Management Setup Guide | AI Agent ...","zh":"tk.Setup Guide: Minimal CLI Ticket Management for AI Agents","ja":"tk Setup Guide: AIエージェント用の最小限のCLIチケット管理","ko":"tk 설정 가이드: AI 에이전트를 위한 최소한의 CLI 티켓 관리","es":"Guía de configuración de tk: Sistema de gestión de ticket...","fr":"Guide de configuration de tk : Système de gestion de tick...","de":"Einrichtungsleitfaden für tk: Minimales CLI-Ticketsystem ...","pt":"Guia de Configuração do tk: Sistema de Gerenciamento de T...","ru":"Руководство по настройке tk: Минимальная система управлен...","ar":"دليل إعداد tk: نظام إدارة التذاكر CLI الأصغر للوكلاء الذك..."},"description":{"en":"Discover how tk simplifies ticket tracking with markdown files. Learn to install and use tk for efficient workflow management.","zh":"使用tk实现高效的CLI票据管理，包括创建、查看和关闭票据等功能","ja":"tkを使用して効率的なCLIチケット管理を実現します。チケットの作成、表示、クローズなど","ko":"tk를 사용하여 효율적인 CLI 티켓 관리를 구현합니다. 티켓 생성, 보기, 종료 등","es":"Aprende a configurar y utilizar tk, un sistema de gestión de tickets de línea de comandos diseñado para agentes de inteligencia artificial, para mejorar tu p...","fr":"Découvrez comment configurer et utiliser tk, un système de gestion de tickets en ligne de commande conçu pour les agents d''intelligence artificielle, pour am...","de":"Erfahren Sie, wie Sie tk, ein minimales CLI-Ticketsystem für KI-Agents, konfigurieren und nutzen können, um Ihre Produktivität zu steigern","pt":"Aprenda a usar o tk, um sistema de gerenciamento de tickets CLI minimalista projetado para agentes de IA, e melhore sua produtividade","ru":"Узнайте, как использовать tk, минимальную систему управления тикетами CLI, предназначенную для ИИ Агентов, и повысьте свою производительность","ar":"تعلم كيفية استخدام tk، نظام إدارة التذاكر CLI الأصغر المصمم للوكلاء الذكاء الاصطناعي، وتحسين إنتاجيتك"},"definition":{"en":"tk is a minimal command-line interface ticket management system designed to track tickets as markdown files in .tickets/.","zh":"tk是一种命令行界面票据管理工具，用于AI代理管理票据","ja":"tkは、AIエージェントがチケットを管理するためのコマンドラインインターフェースチケット管理ツールです","ko":"tk는 AI 에이전트가 티켓을 관리하기 위한 명령줄 인터페이스 티켓 관리 도구입니다","es":"tk es un sistema de gestión de tickets de línea de comandos que utiliza archivos markdown para almacenar tickets en el directorio .tickets/","fr":"tk est un système de gestion de tickets en ligne de commande qui utilise des fichiers markdown pour stocker des tickets dans le répertoire .tickets/","de":"tk ist ein CLI-Ticketsystem, das Markdown-Dateien verwendet, um Tickets im Verzeichnis .tickets/ zu speichern","pt":"O tk é um sistema de gerenciamento de tickets que utiliza arquivos markdown em `.tickets/` para armazenar informações","ru":"Tk - это система управления тикетами, которая использует файлы markdown в `.tickets/` для хранения информации","ar":"tk هو نظام إدارة التذاكر الذي يستخدم ملفات markdown في `.tickets/` لتخزين المعلومات"},"features":{"en":["Creates tickets using `tk create \"title\"` command","Claims tickets with `tk start <id>` for efficient workflow","Displays ticket details using `tk show <id>`","Supports marking tickets as complete with `tk close <id>`","Stores tickets as markdown files in .tickets/ directory"],"zh":["创建票据","查看票据详情","关闭票据","使用CLI命令行界面","支持Markdown文件格式","提供tk ready、tk start、tk show等核心命令"],"ja":["チケットの作成","チケットの詳細表示","チケットのクローズ","CLIコマンドラインインターフェースを使用","Markdownファイル形式をサポート","tk ready、tk start、tk showなどのコアコマンドを提供"],"ko":["티켓 생성","티켓 세부 정보 보기","티켓 종료","CLI 명령줄 인터페이스 사용","Markdown 파일 형식 지원","tk ready, tk start, tk show 등의 핵심 명령 제공"],"es":["Crear tickets utilizando el comando `tk create \"title\"`","Ver detalles de un ticket con `tk show <id>`","Claimar un ticket con `tk start <id>`","Marcar un ticket como completo con `tk close <id>`","Utilizar comandos CLI para gestionar tickets de forma eficiente"],"fr":["Créer des tickets à l''aide de la commande `tk create \"title\"`","Afficher les détails d''un ticket avec `tk show <id>`","Réclamer un ticket avec `tk start <id>`","Marquer un ticket comme complet avec `tk close <id>`","Utiliser des commandes CLI pour gérer des tickets de manière efficace"],"de":["Tickets mit dem Befehl `tk create \"title\"` erstellen","Ticket-Details mit `tk show <id>` anzeigen","Ein Ticket mit `tk start <id>` claimen","Ein Ticket als abgeschlossen markieren mit `tk close <id>`","CLI-Befehle verwenden, um Tickets effizient zu verwalten"],"pt":["Criação de tickets com `tk create \"title\"`","Visualização de detalhes de tickets com `tk show <id>`","Início de trabalho em tickets com `tk start <id>`","Fechamento de tickets com `tk close <id>`","Utilização de arquivos markdown em `.tickets/` para armazenar informações"],"ru":["Создание тикетов с `tk create \"title\"`","Просмотр деталей тикетов с `tk show <id>`","Начало работы над тикетами с `tk start <id>`","Закрытие тикетов с `tk close <id>`","Использование файлов markdown в `.tickets/` для хранения информации"],"ar":["إنشاء تذاكر مع `tk create \"title\"`","عرض تفاصيل التذاكر مع `tk show <id>`","بدء العمل على التذاكر مع `tk start <id>`","إغلاق التذاكر مع `tk close <id>`","استخدام ملفات markdown في `.tickets/` لتخزين المعلومات"]},"keywords":{"en":["how to use tk","tk setup guide","tk alternative","tk vs ticket management systems","tk install","what is tk","tk cli commands","tk markdown files","tk workflow management"],"zh":["tk","CLI票据管理","AI代理","命令行界面","Markdown文件","tk ready","tk start","tk show","票据管理工具"],"ja":["tk","CLIチケット管理","AIエージェント","コマンドラインインターフェース","Markdownファイル","tk ready","tk start","tk show","チケット管理ツール"],"ko":["tk","CLI 티켓 관리","AI 에이전트","명령줄 인터페이스","Markdown 파일","tk ready","tk start","tk show","티켓 관리 도구"],"es":["tk","sistema de gestión de tickets","agentes de inteligencia artificial","CLI","markdown","gestión de tickets","productividad","herramientas de desarrollo","desarrollo de software"],"fr":["tk","système de gestion de tickets","agents d''intelligence artificielle","CLI","markdown","gestion de tickets","productivité","outils de développement","développement de logiciels"],"de":["tk","Ticketsystem","KI-Agents","CLI","markdown","Ticketverwaltung","Produktivität","Entwicklungstools","Softwareentwicklung"],"pt":["tk","sistema de gerenciamento de tickets","CLI","agentes de IA","gerenciamento de tarefas","arquivos markdown","produtividade","ferramentas de desenvolvimento"],"ru":["tk","система управления тикетами","CLI","ИИ Агенты","управление задачами","файлы markdown","производительность","инструменты разработки"],"ar":["tk","نظام إدارة التذاكر","CLI","الوكلاء الذكاء الاصطناعي","إدارة المهام","ملفات markdown","الإنتاجية","أدوات التطوير"]}},"owner":"radutopala","repo":"ticket","repoPath":"radutopala/ticket","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.648Z","topics":[],"category":"community","skillMd":{"name":"tk","description":"Git-backed ticket management for AI agents","bodyPreview":"# tk - Ticket Management\n\nA minimal CLI for tracking tickets as markdown files in `.tickets/`.\n\n## Workflow\n\n```bash\ntk ready              # 1. Find available work\ntk start <id>         # 2. Claim a ticket\ntk show <id>          # 3. Read details\n# ... do the work\ntk close <id>         # 4. Mark complete\n```\n\n## Core Commands\n\n| Command | Description |\n|---------|-------------|\n| `tk create \"title\"` | Create ticket (returns ID) |\n| `tk show <id>` | View ticket details |\n| `tk start <id>` | Claim","body":"# tk - Ticket Management\n\nA minimal CLI for tracking tickets as markdown files in `.tickets/`.\n\n## Workflow\n\n```bash\ntk ready              # 1. Find available work\ntk start <id>         # 2. Claim a ticket\ntk show <id>          # 3. Read details\n# ... do the work\ntk close <id>         # 4. Mark complete\n```\n\n## Core Commands\n\n| Command | Description |\n|---------|-------------|\n| `tk create \"title\"` | Create ticket (returns ID) |\n| `tk show <id>` | View ticket details |\n| `tk start <id>` | Claim ticket (set to in_progress) |\n| `tk close <id>` | Complete ticket |\n| `tk reopen <id>` | Revert to open |\n| `tk edit <id>` | Open in $EDITOR |\n\n## Listing & Filtering\n\n```bash\ntk list                      # All tickets\ntk list --status open        # By status (open|in_progress|closed)\ntk list -a alice             # By assignee\ntk list -T urgent            # By tag\ntk ready                     # Open tickets with resolved deps\ntk blocked                   # Tickets with unresolved deps\ntk closed                    # Recently closed\n```\n\n## Create Options\n\n```bash\ntk create \"Fix login bug\" \\\n  -d \"Description text\" \\\n  -t bug \\                   # Type: bug|feature|task|epic|chore\n  -p 1 \\                     # Priority: 0-4 (0=highest)\n  -a alice \\                 # Assignee\n  --parent <epic-id> \\       # Parent ticket\n  --tags ui,urgent           # Tags\n```\n\n## Dependencies\n\n```bash\ntk dep add <id> <depends-on>   # Add dependency\ntk dep remove <id> <dep-id>    # Remove dependency\ntk dep tree                    # Show dependency tree\ntk dep check                   # Check for cycles\n```\n\n## Notes & Links\n\n```bash\ntk add-note <id> \"Progress update\"   # Add timestamped note\ntk link <id1> <id2>                  # Link related tickets\ntk unlink <id1> <id2>                # Remove link\n```\n\n## Export\n\n```bash\ntk query                    # JSON output\ntk query ''.[] | .title''     # With jq filter\n```\n\n## Tips\n\n- Partial ID matching: `tk show a1b` matches `tic-a1b2c3`\n- Tickets stored in `.tickets/` as markdown with YAML frontmatter\n- Git-friendly: commit tickets with your code\n"},"lastSynced":"2026-03-08T02:13:49.814Z","agentAnalysis":{"suitability":{"en":"Ideal for CLI-focused AI Agents seeking streamlined ticket management through markdown files.","zh":"适合专注于CLI的AI代理，通过markdown文件实现流线型的票据管理。","ja":"CLIに焦点を当てたAIエージェントが、Markdownファイルを介してストリーミングしたチケット管理を実現するのに適しています。","ko":"CLI에 중점을 둔 AI 에이전트가 마크다운 파일을 통해 스트리밍된 티켓 관리를 구현하는 데 적합합니다.","es":"Ideal para agentes de IA centrados en CLI que buscan una gestión de tickets simplificada a través de archivos markdown.","fr":"Idéal pour les agents IA axés sur CLI recherchant une gestion de tickets simplifiée via des fichiers markdown.","de":"Ideal für CLI-fokussierte KI-Agents, die eine vereinfachte Ticketverwaltung über Markdown-Dateien suchen.","pt":"Ideal para Agentes de IA com foco em CLI que buscam gerenciamento de tickets simplificado por meio de arquivos markdown.","ru":"Идеально для AI-агентов с фокусом на CLI, ищущих упрощенное управление тикетами через markdown-файлы.","ar":"مثالية لعميل إKeyType AI ذي التركيز على CLI الذي يسعى إلى إدارة تذاكر مبسطة من خلال ملفات markdown."},"recommendation":{"en":"Empowers agents to manage tickets efficiently using a minimal CLI, supporting commands like `tk create`, `tk show`, and `tk close`, all while leveraging markdown files in `.tickets/` for seamless workflow integration.","zh":"赋予代理高效管理票据的能力，使用最小的CLI，支持诸如`tk create`、`tk show`和`tk close`命令，同时利用`.tickets/`中的markdown文件实现无缝的工作流集成。","ja":"`tk create`、`tk show`、`tk close`などのコマンドをサポートする最小のCLIを使用して、エージェントがチケットを効率的に管理できるようにし、`.tickets/`内のMarkdownファイルを使用してワークフローのシームレスな統合を実現します。","ko":"`tk create`, `tk show`, `tk close` 등과 같은 명령을 지원하는 최소한의 CLI를 사용하여 에이전트가 티켓을 효율적으로 관리할 수 있도록 하며, `.tickets/` 내의 마크다운 파일을 사용하여 워크플로우의 무결한 통합을 구현합니다.","es":"Empodera a los agentes para gestionar tickets de forma eficiente utilizando un CLI mínimo, que admite comandos como `tk create`, `tk show` y `tk close`, todo mientras aprovecha los archivos markdown en `.tickets/` para una integración de flujo de trabajo sin problemas.","fr":"Autonomise les agents pour gérer les tickets de manière efficace en utilisant un CLI minimal, prenant en charge des commandes comme `tk create`, `tk show` et `tk close`, le tout en exploitant les fichiers markdown dans `.tickets/` pour une intégration du flux de travail sans heurts.","de":"Ermächtigt die Agents, Tickets effizient zu verwalten, indem sie ein minimales CLI verwenden, das Befehle wie `tk create`, `tk show` und `tk close` unterstützt, und dabei die Markdown-Dateien in `.tickets/` für eine nahtlose Workflow-Integration nutzt.","pt":"Habilita os agentes a gerenciar tickets de forma eficiente usando uma CLI mínima, que suporta comandos como `tk create`, `tk show` e `tk close`, ao mesmo tempo em que aproveita os arquivos markdown em `.tickets/` para integração de fluxo de trabalho sem interrupções.","ru":"Наделяет агентов возможностью эффективно управлять тикетами, используя минимальную CLI, поддерживающую команды типа `tk create`, `tk show` и `tk close`, одновременно используя markdown-файлы в `.tickets/` для бесшовной интеграции рабочего процесса.","ar":"تمكّن الوكيل من إدارة التذاكر بفعالية باستخدام واجهة سطر الأوامر CLI المُختَصرة، ودعم أوامر مثل `tk create` و `tk show` و `tk close`، مع الاستفادة من ملفات markdown في `.tickets/` لتكامل سلس للعملية."},"useCases":{"en":["Automating ticket creation with `tk create`","Streamlining workflow with `tk start` and `tk close` commands","Retrieving ticket details using `tk show`"],"zh":["使用`tk create`自动创建票据","使用`tk start`和`tk close`命令简化工作流","使用`tk show`检索票据详情"],"ja":["`tk create`を使用してチケットを作成を自動化する","`tk start`および`tk close`コマンドを使用してワークフローをストリーミングする","`tk show`を使用してチケットの詳細を取得する"],"ko":["`tk create`를 사용하여 티켓 생성을 자동화하는 것","`tk start` 및 `tk close` 명령을 사용하여 워크플ロー 스트리밍","`tk show`를 사용하여 티켓 세부 정보를 검색하는 것"],"es":["Automatizar la creación de tickets con `tk create`","Simplificar el flujo de trabajo con los comandos `tk start` y `tk close`","Recuperar detalles de tickets usando `tk show`"],"fr":["Automatiser la création de tickets avec `tk create`","Rationaliser le flux de travail avec les commandes `tk start` et `tk close`","Récupérer les détails des tickets en utilisant `tk show`"],"de":["Automatisieren der Ticketerstellung mit `tk create`","Optimieren des Workflows mit den Befehlen `tk start` und `tk close`","Abrufen von Ticketdetails mit `tk show`"],"pt":["Automatizar a criação de tickets com `tk create`","Otimizar o fluxo de trabalho com os comandos `tk start` e `tk close`","Recuperar detalhes do ticket usando `tk show`"],"ru":["Автоматизировать создание тикетов с помощью `tk create`","Оптимизировать рабочий процесс с помощью команд `tk start` и `tk close`","Получать подробную информацию о тикете, используя `tk show`"],"ar":["تأليف تذاكر آليًا باستخدام `tk create`","جعل سير العمل أكثر كفاءة باستخدام أوامر `tk start` و `tk close`","استرجاع تفاصيل التذكرة باستخدام `tk show`"]},"limitations":{"en":["Requires CLI access","Limited to markdown file format in `.tickets/` directory"],"zh":["需要CLI访问","仅限于`.tickets/`目录中的markdown文件格式"],"ja":["CLIアクセスが必要",".tickets/`ディレクトリ内のMarkdownファイル形式に限定される"],"ko":["CLI 액세스가 필요함",".tickets/` 디렉토리 내의 마크다운 파일 형식으로 제한됨"],"es":["Requiere acceso a CLI","Limitado al formato de archivo markdown en el directorio `.tickets/`"],"fr":["Nécessite un accès à CLI","Limité au format de fichier markdown dans le répertoire `.tickets/`"],"de":["Benötigt CLI-Zugriff","Begrenzt auf Markdown-Dateiformat im Verzeichnis `.tickets/`"],"pt":["Exige acesso à CLI","Limitado ao formato de arquivo markdown no diretório `.tickets/`"],"ru":["Требует доступа к CLI","Ограничен форматом markdown-файлов в директории `.tickets/`"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر CLI","محدود بتنسيق ملفات markdown في الدليل `.tickets/`"]},"version":4},"contentHash":"413ece83edcb25e512d858da0e09e0e3ea43f7d898ccc0e9a751cd8ffa003038","qualityScore":36}');
