INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pluginagentmarketplace/custom-plugin-javascript/functions', 'functions', 'pluginagentmarketplace', 'custom-plugin-javascript', 'community', 'functions pluginagentmarketplace custom-plugin-javascript community The functions skill is a JavaScript development plugin that enables developers to utilize various function styles and scope rules, streamlining their coding process. It benefits developers working with JavaScript. 函数开发插件提供了多种函数样式，包括声明、表达式和箭头函数，并遵循特定的作用域规则 関数開発プラグインは、関数の宣言、関数式、矢印関数などの機能を提供し、スコープルールに従います 함수 개발 플러그인은 함수 선언, 함수 표현식, 화살표 함수 등을 제공하며, 특정한 범위 규칙을 따릅니다 El plugin de desarrollo de JavaScript permite crear funciones con diferentes estilos y reglas de alcance. Aprende a utilizarlas. Le plugin de développement JavaScript permet de créer des fonctions avec différents styles et règles de portée. Découvrez comment les utiliser. Das JavaScript-Entwicklungstool ermöglicht die Erstellung von Funktionen mit verschiedenen Stilen und Gültigkeitsbereichsregeln. Erfahren Sie, wie Sie sie nutzen können. Funções em JavaScript são blocos de código reutilizáveis que executam uma tarefa específica. Este guia cobre estilos de função, incluindo declarações, expressões e setas. Функции в JavaScript являются повторно используемыми блоками кода, которые выполняют конкретную задачу. Это руководство охватывает стили функций, включая объявления, выражения и стрелки для ИИ Агентов. الدوال في الجافا سكريبت هي كتل من الكود يمكن إعادة استخدامها التي تقوم بمهمة محددة. هذا الدليل يغطي أنماط الدوال، بما في ذلك الإعلانات والتعبيرات والسهام للآي إيه آي. how to use functions in JavaScript what is functions in JavaScript functions alternative plugins functions vs JavaScript libraries functions install guide functions setup for AI agents 函数开发插件 JavaScript函数 函数样式 作用域规则 全局作用域 函数作用域 async/await 单参数函数 Supports declaration functions with hoisting Utilizes expression functions that are not hoisted Employs arrow functions with lexical this binding Allows for single parameter functions Enables asynchronous functions with async/await syntax Functions is a JavaScript development plugin that provides support for declaration, expression, and arrow functions, along with global and function scope rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GigaFyde/project-orchestrator/project-orchestrator:changelog', 'community', 'GigaFyde', 'project-orchestrator', 'GigaFyde/project-orchestrator', 'project-orchestrator:changelog', 0, 0, 36, '2026-03-08T01:57:15.659Z', '2026-03-08T02:14:02.885Z', 'db8d7e581731199c2c0b34e8fb13a3df170cce0f3d044aa74beae695bde6d713', '{"id":"GigaFyde/project-orchestrator/project-orchestrator:changelog","name":"project-orchestrator:changelog","description":{"en":"The project-orchestrator:changelog skill automates the creation of standardized changelog entries for AI agent projects, benefiting developers by simplifying change tracking.","zh":"project-orchestrator:changelog 是一个全生命周期的项目编排插件，用于记录标准化的变更日志","ja":"project-orchestrator:changelog は、プロジェクトの変更履歴を標準化するフルライフサイクルのプロジェクトオーケストレーションプラグインです","ko":"project-orchestrator:changelog는 프로젝트의 변경 이력을 표준화하는 풀 라이프사이클 프로젝트 오케스트레이션 플러그인입니다","es":"Project-orchestrator:changelog es un plugin de orquestación de proyectos que ayuda a gestionar cambios en tus proyectos de desarrollo","fr":"Project-orchestrator:changelog est un plugin d''orchestration de projets qui aide à gérer les modifications dans vos projets de développement","de":"Project-orchestrator:changelog ist ein Plugin für die Projektorchestrierung, das hilft, Änderungen in Ihren Entwicklungsprojekten zu verwalten","pt":"O project-orchestrator:changelog é um plugin de orquestração de projeto de ciclo de vida completo para Claude Code, que ajuda a escrever entradas de changelog padrão","ru":"Project-orchestrator:changelog - это плагин для полного цикла проектной оркестрации для Claude Code, giúpающий писать стандартизированные записи изменений","ar":"مشروع project-orchestrator:changelog هو مكون إضافي لorchestration المشروع للحياة الكاملة من أجل Claude Code، الذي يساعد في كتابة إدخالات سجل التغييرات الموحدة"},"seo":{"title":{"en":"project-orchestrator:changelog: Automated Changelog Manag...","zh":"project-orchestrator:changelog 配置指南","ja":"project-orchestrator:changelog を使用したプロジェクトオーケストレーションのベストプ...","ko":"project-orchestrator:changelog 프로젝트 오케스트레이션 플러그인 설정 가이드","es":"Guía de Configuración de project-orchestrator:changelog p...","fr":"Guide de Configuration de project-orchestrator:changelog ...","de":"Konfigurationsleitfaden für project-orchestrator:changelo...","pt":"Guia de Configuração do project-orchestrator:changelog pa...","ru":"Настройка project-orchestrator:changelog: лучшие практики...","ar":"إعداد مشروع project-orchestrator:changelog: دليل أفضل الم..."},"description":{"en":"Streamline your project''s changelog with project-orchestrator:changelog. Learn how to automate changelog entries and improve your development workflow today!","zh":"了解 project-orchestrator:changelog 的功能和配置方法，实现标准化的变更日志记录","ja":"project-orchestrator:changelog を使用してプロジェクトの変更履歴を標準化して管理する方法を紹介します","ko":"project-orchestrator:changelog 플러그인을 사용하여 프로젝트의 변경 이력을 표준화하고 관리하는 방법을 알아보세요","es":"Aprende a configurar project-orchestrator:changelog para gestionar cambios en tus proyectos de desarrollo con Agentes de IA","fr":"Découvrez comment configurer project-orchestrator:changelog pour gérer les modifications dans vos projets de développement avec des Outils d''IA","de":"Erfahren Sie, wie Sie project-orchestrator:changelog konfigurieren, um Änderungen in Ihren Entwicklungsprojekten mit KI-Tools zu verwalten","pt":"Aprenda a configurar o project-orchestrator:changelog para melhorar a gestão de projetos e escrever entradas de changelog padrão","ru":"Узнайте, как настроить project-orchestrator:changelog, чтобы улучшить управление проектами и писать стандартизированные записи изменений","ar":"تعلم كيفية إعداد مشروع project-orchestrator:changelog لتحسين إدارة المشاريع وكتابة إدخالات سجل التغييرات الموحدة"},"definition":{"en":"project-orchestrator:changelog is a full-lifecycle project orchestration plugin for generating and managing changelog entries in Claude Code projects.","zh":"project-orchestrator:changelog 是一个用于记录项目变更日志的插件","ja":"project-orchestrator:changelog は、プロジェクトの変更履歴を記録するためのプラグインです","ko":"project-orchestrator:changelog는 프로젝트의 변경 이력을 기록하는 플러그인입니다","es":"Project-orchestrator:changelog es un plugin que permite escribir entradas de registro de cambios estandarizadas después de completar cambios en un proyecto","fr":"Project-orchestrator:changelog est un plugin qui permet d''écrire des entrées de journal des modifications standardisées après avoir apporté des modifications à un projet","de":"Project-orchestrator:changelog ist ein Plugin, das es ermöglicht, standardisierte Änderungsprotokolleinträge nach Abschluss von Änderungen in einem Projekt zu schreiben","pt":"O project-orchestrator:changelog é um plugin que ajuda a gerenciar projetos e escrever entradas de changelog padrão","ru":"Project-orchestrator:changelog - это плагин, который помогает управлять проектами и писать стандартизированные записи изменений","ar":"مشروع project-orchestrator:changelog هو مكون إضافي يساعد في إدارة المشاريع وكتابة إدخالات سجل التغييرات الموحدة"},"features":{"en":["Automatically generates changelog entries after completing changes","Checks for .project-orchestrator/project.yml configuration files","Supports changelog file paths via config.services[name].changelog","Triggers after bug fixes, new features, refactors, API changes, and configuration changes","Skips changelog entries for typo fixes and other minor changes"],"zh":["支持标准化的变更日志记录","自动检测 `.project-orchestrator/project.yml` 配置文件","支持在服务目录或项目根目录中查找 `CHANGELOG.md` 文件","在 Bug 修复、新功能、重构、API 更改和配置更改后触发","跳过 typo 修复和其他非关键更改"],"ja":["標準化された変更履歴の記録をサポート","`.project-orchestrator/project.yml` 構成ファイルを自動で検出","サービスディレクトリまたはプロジェクトルートディレクトリ内で `CHANGELOG.md` ファイルを検索","バグ修正、 新機能、リファクタリング、API 変更、構成変更後にトリガー","タイポの修正やその他の非重要な変更をスキップ"],"ko":["표준화된 변경 이력 기록을 지원","`.project-orchestrator/project.yml` 구성 파일을 자동으로 감지","서비스 디렉토리 또는 프로젝트 루트 디렉토리 내에서 `CHANGELOG.md` 파일을 검색","버그 수정, 새로운 기능, 리팩토링, API 변경, 구성 변경 후에 트리거","타입 오류 수정 및 기타 비중요한 변경을 건너뛰기"],"es":["Escribe entradas de registro de cambios estandarizadas después de completar cambios","Carga de configuración desde `.project-orchestrator/project.yml`","Compatibilidad con `CHANGELOG.md` en el directorio del servicio o raíz del proyecto","Dispara después de completar correcciones de errores, nuevas características, refactorizaciones y cambios de API","Omite correcciones de errores tipográficos y otros cambios menores"],"fr":["Écrit des entrées de journal des modifications standardisées après avoir apporté des modifications","Chargement de la configuration depuis `.project-orchestrator/project.yml`","Compatibilité avec `CHANGELOG.md` dans le répertoire du service ou à la racine du projet","Déclenche après avoir terminé les corrections de bogues, les nouvelles fonctionnalités, les refactorisations et les modifications d''API","Ignore les corrections de bogues typographiques et d''autres modifications mineures"],"de":["Schreibt standardisierte Änderungsprotokolleinträge nach Abschluss von Änderungen","Lädt Konfiguration aus `.project-orchestrator/project.yml`","Kompatibilität mit `CHANGELOG.md` im Service-Verzeichnis oder Projektstamm","Wird ausgelöst nach Abschluss von Fehlern, neuen Funktionen, Refactorings und API-Änderungen","Ignoriert Tippfehlerkorrekturen und andere unwesentliche Änderungen"],"pt":["Carregamento de configuração a partir de `.project-orchestrator/project.yml`","Suporte a escrita de entradas de changelog padrão após a conclusão de alterações","Gatilho para após a conclusão de correções de bugs, novas funcionalidades, refatorações que afetam o comportamento, alterações de API e alterações de configuração","Suporte a skip para correções de erros de digitação","Integração com Claude Code"],"ru":["Загрузка конфигурации из `.project-orchestrator/project.yml`","Поддержка написания стандартизированных записей изменений после завершения изменений","Триггер после завершения исправления ошибок, новых функций, рефакторинга, влияющего на поведение, изменений API и изменений конфигурации","Поддержка пропуска для исправления опечаток","Интеграция с Claude Code"],"ar":["تحميل التكوين من `.project-orchestrator/project.yml`","دعم كتابة إدخالات سجل التغييرات الموحدة بعد إكمال التغييرات","التحفيز بعد إكمال исправة الأخطاء، والميزات الجديدة، وإعادة هيكلة السلوك، وتغييرات واجهة برمجة التطبيقات، وتغييرات التكوين","دعم تجاوز لتصحيح أخطاء الكتابة","التكامل مع Claude Code"]},"keywords":{"en":["how to use project-orchestrator:changelog","project-orchestrator:changelog setup guide","automated changelog management","Claude Code project orchestration","project-orchestrator:changelog alternative","project-orchestrator:changelog vs manual changelog"],"zh":["project-orchestrator:changelog","AI工具","项目编排","变更日志","标准化","配置文件","CHANGELOG.md","Bug 修复","新功能","重构"],"ja":["project-orchestrator:changelog","AIエージェント","プロジェクトオーケストレーション","変更履歴","標準化","構成ファイル","CHANGELOG.md","バグ修正","新機能","リファクタリング"],"ko":["project-orchestrator:changelog","AI 에이전트","프로젝트 오케스트레이션","변경 이력","표준화","구성 파일","CHANGELOG.md","버그 수정","새로운 기능","리팩토링"],"es":["project-orchestrator:changelog","Agentes de IA para desarrollo","gestión de cambios en proyectos","registro de cambios estandarizado","configuración de proyecto","CHANGELOG.md","desarrollo de software","herramientas de desarrollo","integración de proyecto"],"fr":["project-orchestrator:changelog","Outils d''IA pour le développement","gestion des modifications dans les projets","journal des modifications standardisé","configuration de projet","CHANGELOG.md","développement de logiciels","outils de développement","intégration de projet"],"de":["project-orchestrator:changelog","KI-Tools für die Entwicklung","Änderungsmanagement in Projekten","standardisierter Änderungsprotokoll","Projekt-Konfiguration","CHANGELOG.md","Software-Entwicklung","Entwicklungs-Tools","Projekt-Integration"],"pt":["project-orchestrator:changelog","orquestração de projeto","changelog","gestão de projetos","Claude Code","plugin de orquestração","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["project-orchestrator:changelog","проектная оркестрация","изменения","управление проектами","Claude Code","плагин для оркестрации","разработка программного обеспечения","инструменты для разработчиков ИИ Агентов"],"ar":["project-orchestrator:changelog","أوركسترا المشروع","سجل التغييرات","إدارة المشاريع","Claude Code","مكون إضافي للأوركسترا","تطوير البرمجيات","أدوات تطوير أدوات الذكاء الاصطناعي"]}},"owner":"GigaFyde","repo":"project-orchestrator","repoPath":"GigaFyde/project-orchestrator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.659Z","topics":[],"category":"community","skillMd":{"name":"project-orchestrator:changelog","description":"Use when completing changes to any service - ensures standardized changelog entries with correct format, location, and content.","bodyPreview":"# Changelog\n\n## Overview\n\nWrite standardized changelog entries after completing changes. Focus on WHY not WHAT.\n\n## Config Loading\n\n1. Check if `.project-orchestrator/project.yml` exists\n2. If yes: use `config.services[name].changelog` for the correct file path\n3. If no: look for `CHANGELOG.md` in the service directory or project root\n\n## When to Trigger\n\nAfter completing:\n- Bug fixes\n- New features\n- Refactors affecting behavior\n- API changes\n- Configuration changes\n\n**Skip for:** typo fixes, c","body":"# Changelog\n\n## Overview\n\nWrite standardized changelog entries after completing changes. Focus on WHY not WHAT.\n\n## Config Loading\n\n1. Check if `.project-orchestrator/project.yml` exists\n2. If yes: use `config.services[name].changelog` for the correct file path\n3. If no: look for `CHANGELOG.md` in the service directory or project root\n\n## When to Trigger\n\nAfter completing:\n- Bug fixes\n- New features\n- Refactors affecting behavior\n- API changes\n- Configuration changes\n\n**Skip for:** typo fixes, comment-only changes, test-only changes\n\n## Format\n\n```markdown\n### YYYY-MM-DD - Brief Title\n\n**Summary:** One-line description.\n\n**What prompted the change:**\n- Motivation or problem\n\n**Problem solved:**\n- What this enables\n```\n\n## Location\n\nWrite to the affected service''s changelog path from `config.services[name].changelog`.\n\nIf no changelog path is configured:\n- Check if `{service_path}/CHANGELOG.md` exists\n- If not, check if `CHANGELOG.md` exists at project root\n- If neither exists, ask the user where to write the entry\n\n**Multiple services?** Write entry to EACH affected service''s changelog.\n\n## Checklist\n\n- [ ] Date format: YYYY-MM-DD (not \"Jan 17\")\n- [ ] Title: Brief, describes outcome (not implementation)\n- [ ] Summary: One line, WHY not WHAT\n- [ ] Prompted: What problem existed\n- [ ] Solved: What''s now possible\n- [ ] 10-20 lines max\n- [ ] Written to correct service changelog\n\n## Red Flags\n\n| Bad | Good |\n|-----|------|\n| \"Updated code\" | \"Fix bookmark sync failing silently\" |\n| \"Fixed bug\" | \"Prevent duplicate records on import\" |\n| Lists files changed | Explains behavior change |\n| 50+ lines | 10-20 lines |\n| Entry in root README | Entry in service CHANGELOG.md |\n\n## Example\n\n```markdown\n### 2026-01-17 - Fix SSE reconnection dropping notifications\n\n**Summary:** SSE connections now preserve undelivered notifications during reconnect.\n\n**What prompted the change:**\n- Users reported missing notifications after connection drops\n\n**Problem solved:**\n- Notifications queue during disconnect and deliver on reconnect\n```\n"},"lastSynced":"2026-03-08T02:14:02.885Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated changelog management and standardized change tracking.","zh":"适用于需要自动变更日志管理和标准化变更跟踪的开发代理。","ja":"自動化された変更ログ管理と標準化された変更追跡を必要とする開発エージェントに適しています。","ko":"자동화된 변경 로그 관리 및 표준화된 변경 추적이 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una gestión de registros de cambios automatizada y un seguimiento de cambios estandarizado.","fr":"Idéal pour les agents de développement nécessitant une gestion automatique du journal des modifications et un suivi des modifications standardisé.","de":"Ideal für Entwicklungsmittel, die eine automatisierte Änderungsprotokollverwaltung und eine standardisierte Änderungsnachverfolgung erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem gerenciamento automatizado de registro de alterações e rastreamento de alterações padronizado.","ru":"Идеально подходит для агентов разработки, требующих автоматизированного управления журналом изменений и стандартизированного отслеживания изменений.","ar":"مثالي لعمليات التطوير التي تتطلب إدارة سجل التعديلات آليًا وتعقب التغييرات بشكل معياري."},"recommendation":{"en":"Empowers agents to generate standardized changelog entries in Markdown format, utilizing `.project-orchestrator/project.yml` for configuration and creating `CHANGELOG.md` files, thus simplifying change tracking and focusing on the rationale behind changes.","zh":"赋予代理生成标准化的变更日志条目，以Markdown格式呈现，利用`.project-orchestrator/project.yml`进行配置，并创建`CHANGELOG.md`文件，从而简化变更跟踪，并关注变更背后的理由。","ja":"エージェントが標準化された変更ログエントリをMarkdown形式で生成できるようにし、`.project-orchestrator/project.yml`を使用して構成し、`CHANGELOG.md`ファイルを作成して変更の追跡を簡素化し、変更の背后的理由に焦点を当てます。","ko":"에이전트가 표준화된 변경 로그 항목을 Markdown 형식으로 생성할 수 있도록 하며, `.project-orchestrator/project.yml`을 사용하여 구성하고, `CHANGELOG.md` 파일을 생성하여 변경 추적을 단순화하며, 변경의背后的 이유에 집중합니다.","es":"Habilita a los agentes a generar entradas de registros de cambios estandarizadas en formato Markdown, utilizando `.project-orchestrator/project.yml` para la configuración y creando archivos `CHANGELOG.md`, simplificando así el seguimiento de cambios y centrándose en la justificación detrás de los cambios.","fr":"Permet aux agents de générer des entrées de journal des modifications standardisées au format Markdown, en utilisant `.project-orchestrator/project.yml` pour la configuration et en créant des fichiers `CHANGELOG.md`, simplifiant ainsi le suivi des modifications et en se concentrant sur la justification derrière les modifications.","de":"Ermächtigt Agenten zur Erstellung standardisierter Änderungsprotokolleinträge im Markdown-Format, unter Verwendung von `.project-orchestrator/project.yml` für die Konfiguration und Erstellung von `CHANGELOG.md`-Dateien, wodurch die Änderungsnachverfolgung vereinfacht und der Fokus auf die Begründung hinter den Änderungen gelegt wird.","pt":"Habilita os agentes a gerar entradas de registro de alterações padronizadas no formato Markdown, utilizando `.project-orchestrator/project.yml` para configuração e criando arquivos `CHANGELOG.md`, simplificando assim o rastreamento de alterações e focando na justificativa por trás das alterações.","ru":"Наделяет агентов возможностью генерировать стандартизированные записи журнала изменений в формате Markdown, используя `.project-orchestrator/project.yml` для конфигурации и создания файлов `CHANGELOG.md`, тем самым упрощая отслеживание изменений и сосредотачиваясь на обосновании изменений.","ar":"تمكين الوكلاء من توليد إدخالات سجل التعديلات المعيارية بتنسيق Markdown، باستخدام `.project-orchestrator/project.yml` للتهيئة وإنشاء ملفات `CHANGELOG.md`، وبالتالي تبسيط تعقب التغييرات وتركيز على المبررات وراء التغييرات."},"useCases":{"en":["Automating changelog updates after bug fixes","Generating changelog entries for new features and API changes","Standardizing refactor and configuration change documentation"],"zh":["自动更新变更日志后修复错误","为新功能和API更改生成变更日志条目","标准化重构和配置更改文档"],"ja":["バグ修正後の変更ログを自動更新する","新機能とAPIの変更に対する変更ログエントリを生成する","リファクタリングと構成の変更のドキュメントを標準化する"],"ko":["버그 수정 후 변경 로그를 자동으로 업데이트합니다","새로운 기능 및 API 변경에 대한 변경 로그 항목을 생성합니다","리팩토링 및 구성 변경 문서를 표준화합니다"],"es":["Automatización de actualizaciones de registros de cambios después de correcciones de errores","Generación de entradas de registros de cambios para nuevas características y cambios de API","Estandarización de la documentación de refactorización y cambios de configuración"],"fr":["Automatisation des mises à jour du journal des modifications après correction des bogues","Génération d''entrées de journal des modifications pour les nouvelles fonctionnalités et les modifications de l''API","Standardisation de la documentation de refactorisation et des modifications de configuration"],"de":["Automatisierung von Änderungsprotokoll-Updates nach Fehlerbehebungen","Erstellung von Änderungsprotokolleinträgen für neue Funktionen und API-Änderungen","Standardisierung der Dokumentation von Refactoring und Konfigurationsänderungen"],"pt":["Automatizar atualizações de registro de alterações após correções de bugs","Gerar entradas de registro de alterações para novos recursos e alterações de API","Padronizar documentação de alterações de refatoração e configuração"],"ru":["Автоматизировать обновления журнала изменений после исправления ошибок","Генерировать записи журнала изменений для новых функций и изменений API","Стандартизировать документацию изменений рефакторинга и конфигурации"],"ar":["توفير تحديثات سجل التعديلات آليًا بعد إصلاح العيوب","توليد إدخالات سجل التعديلات لالميزات الجديدة والتغييرات في واجهة برمجة التطبيقات","تقييس توثيق تعديلات إعادة الهيكلة والتكوين"]},"limitations":{"en":["Requires `.project-orchestrator/project.yml` or `CHANGELOG.md` file presence","Limited to Markdown format for changelog entries"],"zh":["需要`.project-orchestrator/project.yml`或`CHANGELOG.md`文件存在","仅限Markdown格式的变更日志条目"],"ja":["`.project-orchestrator/project.yml`または`CHANGELOG.md`ファイルの存在が必要","変更ログエントリはMarkdown形式のみ"],"ko":["`.project-orchestrator/project.yml` 또는 `CHANGELOG.md` 파일의 존재가 필요합니다","변경 로그 항목은 Markdown 형식만 해당"],"es":["Requiere la presencia del archivo `.project-orchestrator/project.yml` o `CHANGELOG.md`","Limitado al formato Markdown para las entradas de registros de cambios"],"fr":["Nécessite la présence du fichier `.project-orchestrator/project.yml` ou `CHANGELOG.md`","Limité au format Markdown pour les entrées de journal des modifications"],"de":["Erfordert die Anwesenheit der Datei `.project-orchestrator/project.yml` oder `CHANGELOG.md`","Begrenzt auf das Markdown-Format für Änderungsprotokolleinträge"],"pt":["Exige a presença do arquivo `.project-orchestrator/project.yml` ou `CHANGELOG.md`","Limitado ao formato Markdown para entradas de registro de alterações"],"ru":["Требует присутствия файла `.project-orchestrator/project.yml` или `CHANGELOG.md`","Ограничен форматом Markdown для записей журнала изменений"],"ar":["يتطلب وجود ملف `.project-orchestrator/project.yml` أو `CHANGELOG.md`","محدود بتنسيق Markdown لإدخالات سجل التعديلات"]},"version":4},"contentHash":"db8d7e581731199c2c0b34e8fb13a3df170cce0f3d044aa74beae695bde6d713","qualityScore":36}');
