INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GigaFyde/project-orchestrator/project-orchestrator:changelog', 'project-orchestrator:changelog', 'GigaFyde', 'project-orchestrator', 'community', 'project-orchestrator:changelog GigaFyde project-orchestrator community The project-orchestrator:changelog skill automates the creation of standardized changelog entries for AI agent projects, benefiting developers by simplifying change tracking. project-orchestrator:changelog 是一个全生命周期的项目编排插件，用于记录标准化的变更日志 project-orchestrator:changelog は、プロジェクトの変更履歴を標準化するフルライフサイクルのプロジェクトオーケストレーションプラグインです project-orchestrator:changelog는 프로젝트의 변경 이력을 표준화하는 풀 라이프사이클 프로젝트 오케스트레이션 플러그인입니다 Project-orchestrator:changelog es un plugin de orquestación de proyectos que ayuda a gestionar cambios en tus proyectos de desarrollo Project-orchestrator:changelog est un plugin d''orchestration de projets qui aide à gérer les modifications dans vos projets de développement Project-orchestrator:changelog ist ein Plugin für die Projektorchestrierung, das hilft, Änderungen in Ihren Entwicklungsprojekten zu verwalten O project-orchestrator:changelog é um plugin de orquestração de projeto de ciclo de vida completo para Claude Code, que ajuda a escrever entradas de changelog padrão Project-orchestrator:changelog - это плагин для полного цикла проектной оркестрации для Claude Code, giúpающий писать стандартизированные записи изменений مشروع project-orchestrator:changelog هو مكون إضافي لorchestration المشروع للحياة الكاملة من أجل Claude Code، الذي يساعد في كتابة إدخالات سجل التغييرات الموحدة how to use project-orchestrator:changelog project-orchestrator:changelog setup guide automated changelog management Claude Code project orchestration project-orchestrator:changelog alternative project-orchestrator:changelog vs manual changelog project-orchestrator:changelog AI工具 项目编排 变更日志 标准化 配置文件 CHANGELOG.md Bug 修复 新功能 重构 Automatically generates changelog entries after completing changes Checks for .project-orchestrator/project.yml configuration files Supports changelog file paths via config.services[name].changelog Triggers after bug fixes, new features, refactors, API changes, and configuration changes Skips changelog entries for typo fixes and other minor changes project-orchestrator:changelog is a full-lifecycle project orchestration plugin for generating and managing changelog entries in Claude Code projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('steveclarke/kiso/contributing', 'community', 'steveclarke', 'kiso', 'steveclarke/kiso', 'contributing', 0, 0, 36, '2026-03-08T00:00:12Z', '2026-03-08T02:14:10.370Z', '1ba8ac3122d2e887612f42f1cd742e3c97c182faaa1ffd0bb1608ebf890c25ff', '{"id":"steveclarke/kiso/contributing","name":"contributing","description":{"en":"The contributing skill provides guidelines for developing Rails UI components with ERB partials, Tailwind CSS, and progressive Stimulus. It benefits developers working with the Kiso component library.","zh":"Kiso组件库的contributing指南，涵盖组件创建、审查和设计系统规则等","ja":"Kisoコンポーネントライブラリのコントリビューティングガイド。コンポーネントの作成、レビュー、デザインシステムのルールなど","ko":"Kiso 컴포넌트 라이브러리의 기고 가이드. 컴포넌트 생성, 검토, 디자인 시스템 규칙 등","es":"Contribuir a bibliotecas de componentes inspiradas en shadcn/ui con ERB, Tailwind CSS y Stimulus","fr":"Contribuer aux bibliothèques de composants inspirées de shadcn/ui avec ERB, Tailwind CSS et Stimulus","de":"Mitarbeit an Komponentenbibliotheken, die von shadcn/ui inspiriert sind, mit ERB, Tailwind CSS und Stimulus","pt":"A biblioteca de componentes UI Kiso oferece diretrizes de desenvolvimento e recursos de código aberto para contribuir com componentes inspirados em shadcn/ui","ru":"Библиотека компонентов Kiso предоставляет руководства по разработке и открытые ресурсы для внесения вклада в компоненты, вдохновленные shadcn/ui для ИИ Агентов","ar":"مكتبة مكونات Kiso توفر إرشادات لتنمية الوكلاء الذكية وموارد الكود المفتوح للمساهمة في مكونات مستوحاة من shadcn/ui"},"seo":{"title":{"en":"Contributing: Setup Guide for Kiso Component Library | AI...","zh":" Contributing指南：Kiso组件库开发最佳实践","ja":"コントリビューティングセットアップガイド：Kisoコンポーネントライブラリ","ko":"기고 개발 가이드: Kiso 컴포넌트 라이브러리","es":"Guía de configuración para contribuir a bibliotecas de co...","fr":"Guide de démarrage pour contribuer aux bibliothèques de c...","de":"Einrichtungsleitfaden für die Mitarbeit an Komponentenbib...","pt":"Guia de Contribuição para Desenvolvedores de Componentes UI","ru":"Руководство по внесению вклада в библиотеку компонентов K...","ar":"دليل المساهمة في مكتبة مكونات Kiso للوكلاء الذكية"},"description":{"en":"Unlock efficient component development with contributing. Discover how to build, review, and design components with ERB partials, Tailwind CSS, and Stimulus....","zh":"了解如何为Kiso组件库做出贡献，包括组件创建、审查和设计系统规则","ja":"Kisoコンポーネントライブラリに貢献する方法を学びましょう。コンポーネントの作成、レビュー、デザインシステムのルールなど","ko":"Kiso 컴포넌트 라이브러리에 기고하는 방법에 대해 알아보세요. 컴포넌트 생성, 검토, 디자인 시스템 규칙 등","es":"Aprende a contribuir a bibliotecas de componentes con ERB, Tailwind CSS y Stimulus","fr":"Découvrez comment contribuer aux bibliothèques de composants avec ERB, Tailwind CSS et Stimulus","de":"Erfahren Sie, wie Sie an Komponentenbibliotheken mit ERB, Tailwind CSS und Stimulus mitwirken können","pt":"Aprenda a contribuir para a biblioteca de componentes UI Kiso com nossas diretrizes de desenvolvimento e recursos de código aberto","ru":"Узнайте, как внести свой вклад в библиотеку компонентов Kiso с нашими руководствами по разработке и открытым ресурсам для ИИ Агентов","ar":"تعلم كيف تساهم في مكتبة مكونات Kiso باستخدام إرشاداتنا لتنمية الوكلاء الذكية وموارد الكود المفتوح"},"definition":{"en":"Contributing is a set of guidelines and rules for building, reviewing, and designing UI components for the Kiso library using ERB partials, Tailwind CSS, and Stimulus.","zh":"Contributing是指为Kiso组件库开发和维护过程中提供代码、文档或其他形式的贡献","ja":"コントリビューティングとは、Kisoコンポーネントライブラリの開発とメンテナンスプロセスにコード、ドキュメント、その他の形式で貢献すること","ko":"기고는 Kiso 컴포넌트 라이브러리의 개발 및 유지 보수 과정에서 코드, 문서 또는 기타 형식의 기고를 제공하는 것","es":"Contribuir es el proceso de desarrollar y mejorar bibliotecas de componentes","fr":"Contribuer est le processus de développement et d''amélioration des bibliothèques de composants","de":"Mitarbeit ist der Prozess der Entwicklung und Verbesserung von Komponentenbibliotheken","pt":"Contribuição de componentes UI é o processo de desenvolver e compartilhar componentes reutilizáveis inspirados em shadcn/ui","ru":"Внесение вклада в компоненты UI - это процесс разработки и обмена повторно используемыми компонентами, вдохновленными shadcn/ui для ИИ Агентов","ar":"مساهمة مكونات الواجهة هو عملية تطوير ومشاركة مكونات قابلة لإعادة الاستخدام مستوحاة من shadcn/ui"},"features":{"en":["Provides a full workflow for building components with `project/component-creation.md`","Includes a 12-point checklist for reviewing components with `project/component-review.md`","Enforces design system rules with compound variants, tokens, and spatial system in `project/design-system.md`","Supports architecture patterns with component strategy in `project/component-strategy.md`","Utilizes ERB partials for templating","Leverages Tailwind CSS for styling"],"zh":["ERB部分和Tailwind CSS支持","进步的Stimulus","组件创建和审查工作流","设计系统规则和令牌","空间系统和组合变体"],"ja":["ERBパーシャルとTailwind CSSのサポート","進歩的なStimulus","コンポーネントの作成とレビューのワークフロー","デザインシステムのルールとトークン","空間システムとコンパウンドバリアント"],"ko":["ERB 부분과 Tailwind CSS 지원","진보된 Stimulus","컴포넌트 생성 및 검토 워크플로","디자인 시스템 규칙 및 토큰","공간 시스템 및 컴파운드 변형"],"es":["ERB partials para la creación de componentes","Integración con Tailwind CSS para el diseño","Uso de Stimulus para la interactividad","Guía de creación de componentes con checklist","Revisión de componentes con lista de verificación de 12 puntos","Reglas de diseño de sistema para la coherencia"],"fr":["Partiels ERB pour la création de composants","Intégration avec Tailwind CSS pour la conception","Utilisation de Stimulus pour l''interactivité","Guide de création de composants avec checklist","Révision de composants avec liste de vérification de 12 points","Règles de conception de système pour la cohérence"],"de":["ERB-Partials für die Komponenten-Erstellung","Integration mit Tailwind CSS für das Design","Verwendung von Stimulus für die Interaktivität","Leitfaden für die Komponenten-Erstellung mit Checklist","Überprüfung von Komponenten mit 12-Punkte-Checkliste","Design-System-Regeln für die Konsistenz"],"pt":["Componentes UI inspirados em shadcn/ui","ERB parciais para desenvolvimento de componentes","Tailwind CSS para estilização de componentes","Stimulus progressivo para interação de componentes"],"ru":["Компоненты UI, вдохновленные shadcn/ui для ИИ Агентов","ERB частичные для разработки компонентов","Tailwind CSS для стилизации компонентов","Прогрессивный Stimulus для взаимодействия компонентов"],"ar":["مكونات الواجهة المستوحاة من shadcn/ui","أجزاء ERB لتنمية المكونات","Tailwind CSS لتصميم المكونات","استيمولوس تقدمي لتفاعل المكونات"]},"keywords":{"en":["how to use contributing","what is contributing","contributing setup guide","Kiso component library alternative","contributing vs shadcn/ui","install contributing","contributing for Rails developers","Stimulus component development","ERB partials tutorial","Tailwind CSS component styling"],"zh":["Kiso组件库","contributing指南","组件创建","审查流程","设计系统规则","Tailwind CSS","Stimulus","ERB部分","AIエージェント","组件库开发"],"ja":["Kisoコンポーネントライブラリ","コントリビューティングガイド","コンポーネントの作成","レビューのワークフロー","デザインシステムのルール","Tailwind CSS","Stimulus","ERBパーシャル","AIエージェント","コンポーネントライブラリの開発"],"ko":["Kiso 컴포넌트 라이브러리","기고 가이드","컴포넌트 생성","검토 워크플로","디자인 시스템 규칙","Tailwind CSS","Stimulus","ERB 부분","AI 에이전트","컴포넌트 라이브러리 개발"],"es":["contribuir a bibliotecas de componentes","ERB partials","Tailwind CSS","Stimulus","desarrollo de componentes","creación de componentes","revisión de componentes","reglas de diseño de sistema","Herramientas de desarrollo de software","Agentes de IA para desarrollo"],"fr":["contribuer aux bibliothèques de composants","partiels ERB","Tailwind CSS","Stimulus","développement de composants","création de composants","révision de composants","règles de conception de système","Outils de développement de logiciels","Agents IA pour le développement"],"de":["Mitarbeit an Komponentenbibliotheken","ERB-Partials","Tailwind CSS","Stimulus","Komponenten-Entwicklung","Komponenten-Erstellung","Überprüfung von Komponenten","Design-System-Regeln","Software-Entwicklungstools","KI-Agents für die Entwicklung"],"pt":["contribuição de componentes UI","desenvolvimento de componentes","shadcn/ui","ERB parciais","Tailwind CSS","Stimulus progressivo","biblioteca de componentes Kiso"],"ru":["внесение вклада в компоненты UI","разработка компонентов","shadcn/ui для ИИ Агентов","ERB частичные","Tailwind CSS","прогрессивный Stimulus","библиотека компонентов Kiso"],"ar":["مساهمة مكونات الواجهة","تنمية المكونات","مكونات shadcn/ui","أجزاء ERB","Tailwind CSS","استيمولوس تقدمي","مكتبة مكونات Kiso"]}},"owner":"steveclarke","repo":"kiso","repoPath":"steveclarke/kiso","stars":0,"forks":0,"updatedAt":"2026-03-08T00:00:12Z","topics":[],"category":"community","skillMd":{"name":"contributing","description":"Kiso component conventions and development workflow. Points to the right docs for building, reviewing, and shipping components.","bodyPreview":"# Kiso Development\n\nGuidelines for contributing to the Kiso component library.\n\n## Where to find what\n\n| Topic | File |\n|-------|------|\n| **Building a component** | `project/component-creation.md` — full workflow, templates, checklist |\n| **Reviewing a component** | `project/component-review.md` — 12-point checklist, common mistakes |\n| **Design system rules** | `project/design-system.md` — compound variants, tokens, spatial system |\n| **Architecture patterns** | `project/component-strategy.md`","body":"# Kiso Development\n\nGuidelines for contributing to the Kiso component library.\n\n## Where to find what\n\n| Topic | File |\n|-------|------|\n| **Building a component** | `project/component-creation.md` — full workflow, templates, checklist |\n| **Reviewing a component** | `project/component-review.md` — 12-point checklist, common mistakes |\n| **Design system rules** | `project/design-system.md` — compound variants, tokens, spatial system |\n| **Architecture patterns** | `project/component-strategy.md` — ClassVariants, override system |\n| **Per-slot `ui:` overrides** | `project/decisions/004-per-slot-ui-prop.md` — ADR for `ui:` prop |\n| **Testing strategy** | `project/testing-strategy.md` — tier system, E2E requirements |\n| **Docs page template** | `project/component-doc-template.md` — structure and guidelines |\n| **All conventions** | `CLAUDE.md` — framework mindset, naming, code rules |\n\n## Project structure\n\n```\nlib/kiso/themes/              Ruby theme modules (ClassVariants definitions)\napp/views/kiso/components/    ERB partials (rendered via kui() helper)\napp/assets/tailwind/kiso/     engine.css — shipped with gem (fonts + all color tokens)\napp/helpers/kiso/             kui(), kiso_prepare_options() helpers\napp/javascript/controllers/kiso/  Stimulus controllers (namespaced kiso--)\napp/javascript/kiso/utils/    Shared JS utilities (positioning, highlight, focusable)\ntest/components/previews/kiso/  Lookbook previews + templates\nskills/kiso/                  AI skill (update when adding components)\nproject/                      Architecture docs, design system, decisions\ndocs/                         Bridgetown docs site (published documentation)\nlookbook/                     Lookbook dev app (bin/dev → port 4001)\n```\n\n## CSS architecture\n\n**`app/assets/tailwind/kiso/engine.css`** is what the gem ships. It contains\nGeist fonts, all default color tokens (`@theme`), dark mode overrides\n(`.dark {}`), and `@source` directives for Kiso''s views, helpers, and theme\nmodules. **Never put color tokens in the Lookbook''s `application.css`** — they\nbelong in `engine.css` so host apps get them too.\n\nThe `tailwindcss:engines` Rake task (from `tailwindcss-rails` v4) automatically\ndetects any Rails engine with `app/assets/tailwind/{engine_name}/engine.css`\nand generates `app/assets/builds/tailwind/{engine_name}.css`. Kiso''s engine\nname is `kiso`, so the directory must be `app/assets/tailwind/kiso/`.\n\n**Lookbook setup:** `lookbook/app/assets/tailwind/application.css` imports the\nauto-generated engine file and adds Lookbook-specific source paths:\n\n```css\n@import \"tailwindcss\";\n@import \"../builds/tailwind/kiso.css\";\n\n@source \"../../views\";\n@source \"../../../../test/components/previews\";\n```\n\n## Pull request workflow\n\n**Always include `Closes #N` in the PR body** so GitHub auto-closes the issue\non merge. This is the most commonly missed step.\n\n```bash\n# Create branch\ngit checkout -b feat/{name}-component\n\n# Stage specific files (never git add -A)\ngit add lib/kiso/themes/{name}.rb app/views/kiso/components/...\n\n# Commit\ngit commit -m \"feat: ComponentName component (#N)\"\n\n# Push and create PR\ngit push -u origin feat/{name}-component\ngh pr create --title \"feat: ComponentName component\" --body \"$(cat <<''EOF''\n## Summary\n- [what was built]\n\nCloses #N\n\n## Test plan\n- [x] All Lookbook previews render (200)\n- [x] standardrb passes\n- [x] rake test passes\n- [ ] Visual review in Lookbook\nEOF\n)\"\n```\n\n## Commands\n\n```bash\nbin/dev                         # All services via Overmind (Lookbook :4001 + docs :4000)\nbin/dev -- -l web,css           # Lookbook + Tailwind only (no docs)\nbin/worktree start              # Start on worktree-assigned port\nbin/worktree port               # Show port for current worktree\novermind restart web            # Restart Lookbook server\nbundle exec rake test           # Run Ruby tests\nnpm run test:unit               # Run JS unit tests (Vitest)\nnpm run test:e2e                # Run Playwright E2E tests (needs bin/dev)\nnpm run test:e2e:ui             # Open Playwright GUI\nbundle exec standardrb --fix    # Lint & auto-format Ruby\nnpm run lint                    # Lint JS (oxlint)\nnpm run fmt                     # Format JS (oxfmt)\n```\n\n## Worktree workflow\n\nSee `.claude/skills/worktree/SKILL.md` for the full worktree lifecycle\n(create, start Lookbook, commit, push, PR, cleanup). Key command:\n`bin/worktree start` — starts Lookbook on a deterministic port (4101-4600).\n"},"lastSynced":"2026-03-08T02:14:10.370Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents working with Rails UI components and Kiso component library, needing guidelines for contributing with ERB partials and Tailwind CSS.","zh":"适合使用 Rails UI 组件和 Kiso 组件库的前端代理，需要指南来为 ERB 部分和 Tailwind CSS 做出贡献。","ja":"Rails UI コンポーネントと Kiso コンポーネント ライブラリを使用するフロントエンド エージェントに最適であり、ERB パーシャルと Tailwind CSS に貢献するためのガイドラインが必要です。","ko":"Rails UI 컴포넌트와 Kiso 컴포넌트 라이브러리를 사용하는 프론트엔드 에이전트에게 적합하며, ERB 부분과 Tailwind CSS에 기여하기 위한 가이드라인이 필요합니다.","es":"Ideal para agentes de frontend que trabajan con componentes de interfaz de usuario de Rails y la biblioteca de componentes Kiso, que necesitan pautas para contribuir con particiones ERB y Tailwind CSS.","fr":"Idéal pour les agents de frontend travaillant avec des composants d''interface utilisateur Rails et la bibliothèque de composants Kiso, ayant besoin de lignes directrices pour contribuer avec des parties ERB et Tailwind CSS.","de":"Ideal für Frontend-Agenten, die mit Rails-Benutzeroberflächenkomponenten und der Kiso-Komponentenbibliothek arbeiten und Richtlinien für die Mitarbeit an ERB-Partials und Tailwind CSS benötigen.","pt":"Ideal para Agentes Frontend que trabalham com componentes de interface do usuário Rails e biblioteca de componentes Kiso, necessitando de diretrizes para contribuir com partições ERB e Tailwind CSS.","ru":"Идеально для Фронтенд-агентов, работающих с компонентами пользовательского интерфейса Rails и библиотекой компонентов Kiso, нуждающихся в рекомендациях для внесения вклада в части ERB и Tailwind CSS.","ar":"مثالي للوكلاء الأماميين الذين يعملون مع مكونات واجهة المستخدم من Rail و مكتبة المكونات Kiso، و الذين يحتاجون إلى إرشادات للمساهمة في أجزاء ERB و Tailwind CSS."},"recommendation":{"en":"Empowers agents to develop and review Rails UI components using Stimulus, following design system rules and architecture patterns, with access to comprehensive checklists and templates for component creation and review, utilizing ERB partials, Tailwind CSS, and design system tokens.","zh":"赋予代理开发和审查使用 Stimulus 的 Rails UI 组件的能力，遵循设计系统规则和架构模式，并提供全面检查清单和模板用于组件创建和审查，利用 ERB 部分、Tailwind CSS 和设计系统令牌。","ja":"Stimulus を使用する Rails UI コンポーネントの開発とレビューをエージェントに可能にすることで、デザイン システム ルールとアーキテクチャ パターンに従い、コンポーネントの作成とレビューのための包括的なチェックリストとテンプレートにアクセスし、ERB パーシャル、Tailwind CSS、デザイン システム トークンを利用します。","ko":"Stimulus를 사용하는 Rails UI 컴포넌트를 개발하고 검토할 수 있는 에이전트의 능력을 부여하여, 디자인 시스템 규칙과 아키텍처 패턴을 따르며, 컴포넌트 생성과 검토를 위한 포괄적인 체크리스트와 템플릿에 접근하고, ERB 부분, Tailwind CSS, 디자인 시스템 토큰을 활용합니다.","es":"Habilita a los agentes a desarrollar y revisar componentes de interfaz de usuario de Rails utilizando Stimulus, siguiendo reglas de sistema de diseño y patrones de arquitectura, con acceso a listas de verificación y plantillas completas para la creación y revisión de componentes, utilizando particiones ERB, Tailwind CSS y tokens de sistema de diseño.","fr":"Habilite les agents à développer et à examiner des composants d''interface utilisateur Rails en utilisant Stimulus, en suivant les règles du système de conception et les modèles d''architecture, avec un accès à des listes de vérification et des modèles complets pour la création et l''examen de composants, en utilisant des parties ERB, Tailwind CSS et des jetons de système de conception.","de":"Ermächtigt Agenten, Rails-Benutzeroberflächenkomponenten mit Stimulus zu entwickeln und zu überprüfen, indem sie Regeln des Designsystems und Architekturmuster befolgen, mit Zugriff auf umfassende Prüflisten und Vorlagen für die Erstellung und Überprüfung von Komponenten, unter Verwendung von ERB-Partials, Tailwind CSS und Designsystem-Tokens.","pt":"Permite que os agentes desenvolvam e revisem componentes de interface do usuário Rails usando Stimulus, seguindo regras do sistema de design e padrões de arquitetura, com acesso a listas de verificação abrangentes e modelos para criação e revisão de componentes, utilizando partições ERB, Tailwind CSS e tokens do sistema de design.","ru":"Наделяет агентов возможностью разрабатывать и проверять компоненты пользовательского интерфейса Rails с помощью Stimulus, следуя правилам системы дизайна и шаблонам архитектуры, с доступом к всесторонним чек-листам и шаблонам для создания и проверки компонентов, используя части ERB, Tailwind CSS и токены системы дизайна.","ar":"يمنح الوكلاء القدرة على تطوير ومراجعة مكونات واجهة المستخدم من Rail باستخدام Stimulus، متبعين قواعد نظام التصميم وأنماط الهندسة المعمارية، مع الوصول إلى قوائم مراجعة شاملة ونماذج لإنشاء ومراجعة المكونات، باستخدام أجزاء ERB و Tailwind CSS ورموز نظام التصميم."},"useCases":{"en":["Building new components with ERB partials and Tailwind CSS","Reviewing existing components against a 12-point checklist","Applying design system rules for compound variants and spatial systems"],"zh":["使用 ERB 部分和 Tailwind CSS 构建新的组件","使用 12 点检查清单审查现有的组件","应用设计系统规则用于复合变体和空间系统"],"ja":["ERB パーシャルと Tailwind CSS を使用して新しいコンポーネントを構築する","12 点のチェックリストを使用して既存のコンポーネントをレビューする","複合バリアントと空間システムのデザイン システム ルールを適用する"],"ko":["ERB 부분과 Tailwind CSS를 사용하여 새로운 컴포넌트를 구축한다","12점 체크리스트를 사용하여 기존 컴포넌트를 검토한다","합성 변형과 공간 시스템을 위한 디자인 시스템 규칙을 적용한다"],"es":["Creación de nuevos componentes con particiones ERB y Tailwind CSS","Revisión de componentes existentes frente a una lista de verificación de 12 puntos","Aplicación de reglas de sistema de diseño para variantes compuestas y sistemas espaciales"],"fr":["Création de nouveaux composants avec des parties ERB et Tailwind CSS","Examen de composants existants par rapport à une liste de vérification de 12 points","Application des règles du système de conception pour les variantes composées et les systèmes spatiaux"],"de":["Erstellung neuer Komponenten mit ERB-Partials und Tailwind CSS","Überprüfung bestehender Komponenten anhand einer 12-Punkte-Prüfliste","Anwendung von Designsystemregeln für Zusammensetzungen und räumliche Systeme"],"pt":["Construir novos componentes com partições ERB e Tailwind CSS","Revisar componentes existentes contra uma lista de verificação de 12 pontos","Aplicar regras do sistema de design para variantes compostas e sistemas espaciais"],"ru":["Создание новых компонентов с помощью частей ERB и Tailwind CSS","Проверка существующих компонентов на соответствие 12-балльной проверке","Применение правил системы дизайна для составных вариантов и пространственных систем"],"ar":["بناء مكونات جديدة باستخدام أجزاء ERB و Tailwind CSS","مراجعة المكونات الموجودة مقابل قائمة مراجعة من 12 نقطة","تطبيق قواعد نظام التصميم للتفاريع المركبة والأنظمة المكانية"]},"limitations":{"en":["Requires familiarity with Rails UI components and Kiso component library","Specific to ERB partials and Tailwind CSS","Dependent on Stimulus for progressive enhancement"],"zh":["需要熟悉 Rails UI 组件和 Kiso 组件库","特定于 ERB 部分和 Tailwind CSS","依赖于 Stimulus 进行渐进增强"],"ja":["Rails UI コンポーネントと Kiso コンポーネント ライブラリの知識が必要","ERB パーシャルと Tailwind CSS に特有","Stimulus による進化的向上に依存する"],"ko":["Rails UI 컴포넌트와 Kiso 컴포넌트 라이브러리에 대한 지식이 필요하다","ERB 부분과 Tailwind CSS에 특정하다","Stimulus에 의한 점진적 향상을 의존한다"],"es":["Requiere familiaridad con componentes de interfaz de usuario de Rails y la biblioteca de componentes Kiso","Específico para particiones ERB y Tailwind CSS","Dependiente de Stimulus para la mejora progresiva"],"fr":["Nécessite une familiarité avec les composants d''interface utilisateur Rails et la bibliothèque de composants Kiso","Spécifique aux parties ERB et Tailwind CSS","Dépendant de Stimulus pour l''amélioration progressive"],"de":["Benötigt Vertrautheit mit Rails-Benutzeroberflächenkomponenten und der Kiso-Komponentenbibliothek","Spezifisch für ERB-Partials und Tailwind CSS","Abhängig von Stimulus für die schrittweise Verbesserung"],"pt":["Exige familiaridade com componentes de interface do usuário Rails e biblioteca de componentes Kiso","Específico para partições ERB e Tailwind CSS","Dependente de Stimulus para melhoria progressiva"],"ru":["Требует знакомства с компонентами пользовательского интерфейса Rails и библиотекой компонентов Kiso","Конкретно для частей ERB и Tailwind CSS","Зависит от Stimulus для постепенного улучшения"],"ar":["يتطلب إلمامًا بمكونات واجهة المستخدم من Rail و مكتبة المكونات Kiso","محدد لأجزاء ERB و Tailwind CSS","يعتمد على Stimulus للتحسين التدريجي"]},"version":4},"contentHash":"1ba8ac3122d2e887612f42f1cd742e3c97c182faaa1ffd0bb1608ebf890c25ff","qualityScore":36}');
