INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('steveclarke/kiso/contributing', 'contributing', 'steveclarke', 'kiso', 'community', 'contributing steveclarke kiso community The contributing skill provides guidelines for developing Rails UI components with ERB partials, Tailwind CSS, and progressive Stimulus. It benefits developers working with the Kiso component library. Kiso组件库的contributing指南，涵盖组件创建、审查和设计系统规则等 Kisoコンポーネントライブラリのコントリビューティングガイド。コンポーネントの作成、レビュー、デザインシステムのルールなど Kiso 컴포넌트 라이브러리의 기고 가이드. 컴포넌트 생성, 검토, 디자인 시스템 규칙 등 Contribuir a bibliotecas de componentes inspiradas en shadcn/ui con ERB, Tailwind CSS y Stimulus Contribuer aux bibliothèques de composants inspirées de shadcn/ui avec ERB, Tailwind CSS et Stimulus Mitarbeit an Komponentenbibliotheken, die von shadcn/ui inspiriert sind, mit ERB, Tailwind CSS und Stimulus A biblioteca de componentes UI Kiso oferece diretrizes de desenvolvimento e recursos de código aberto para contribuir com componentes inspirados em shadcn/ui Библиотека компонентов Kiso предоставляет руководства по разработке и открытые ресурсы для внесения вклада в компоненты, вдохновленные shadcn/ui для ИИ Агентов مكتبة مكونات Kiso توفر إرشادات لتنمية الوكلاء الذكية وموارد الكود المفتوح للمساهمة في مكونات مستوحاة من shadcn/ui how to use contributing what is contributing contributing setup guide Kiso component library alternative contributing vs shadcn/ui install contributing contributing for Rails developers Stimulus component development ERB partials tutorial Tailwind CSS component styling Kiso组件库 contributing指南 组件创建 审查流程 设计系统规则 Tailwind CSS Stimulus ERB部分 AIエージェント 组件库开发 Provides a full workflow for building components with `project/component-creation.md` Includes a 12-point checklist for reviewing components with `project/component-review.md` Enforces design system rules with compound variants, tokens, and spatial system in `project/design-system.md` Supports architecture patterns with component strategy in `project/component-strategy.md` Utilizes ERB partials for templating Leverages Tailwind CSS for styling Contributing is a set of guidelines and rules for building, reviewing, and designing UI components for the Kiso library using ERB partials, Tailwind CSS, and Stimulus.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('poisontr33s/chthonic-archive/skill-polisher', 'community', 'poisontr33s', 'chthonic-archive', 'poisontr33s/chthonic-archive', 'skill-polisher', 0, 0, 36, '2026-03-07T17:27:12Z', '2026-03-08T02:14:13.400Z', 'ced48430eb6fceece6b6c57e039dac3988eb14fa5961921cd26145360717098c', '{"id":"poisontr33s/chthonic-archive/skill-polisher","name":"skill-polisher","description":{"en":"The skill-polisher audits Codex skills for structural integrity and standardization using existing tooling. It supports Claude-flavored and cross-flavored compatibility.","zh":"Skill Polisher 是一个用于优化 Rust/Vulkan 代码的工具，确保结构完整性和标准化","ja":"Skill Polisher は Rust/Vulkan AIエージェント開発を効率化するツールです","ko":"Skill Polisher 는 Rust/Vulkan 코드를 최적화하는 도구입니다","es":"El skill-polisher es una herramienta para auditar y estandarizar habilidades en Codex y Claude, compatible con tecnologías como Rust y Vulkan","fr":"Le skill-polisher est un outil pour auditer et standardiser les compétences dans Codex et Claude, compatible avec des technologies comme Rust et Vulkan","de":"Der skill-polisher ist ein Tool zur Überprüfung und Standardisierung von Fähigkeiten in Codex und Claude, kompatibel mit Technologien wie Rust und Vulkan","pt":"O Skill Polisher é uma ferramenta de auditoria de código que valida a integridade estrutural e a padronização dos skills","ru":"ИИ Агент Skill Polisher является инструментом для аудита кода, который проверяет целостность и стандарты кода","ar":"Skill Polisher هو أداة مراجعة شفرة تتحقق من سلامة البنية وتوحيد مهارات الترميز"},"seo":{"title":{"en":"skill-polisher: Vulkan-Powered Isometric RPG Engine Setup...","zh":"Skill Polisher 工具安装指南 - Rust/Vulkan 避免重复代码","ja":"Skill Polisher セットアップガイド - Rust/Vulkan AIエージェント開発","ko":"Skill Polisher 설정 가이드 - Rust/Vulkan 코드 최적화","es":"Guía de configuración de skill-polisher para motores de R...","fr":"Guide d''installation de skill-polisher pour les moteurs d...","de":"Einrichtungsleitfaden für skill-polisher in isometrischen...","pt":"Guia de Configuração do Skill Polisher para Desenvolvedores","ru":"Настройка ИИ Агента Skill Polisher для Разработчиков","ar":"دليل إعداد Skill Polisher لمنصة التطبيقات الإبداعية"},"description":{"en":"Discover how to harness the power of Rust and Vulkan with skill-polisher. Learn to audit Codex skills for structural integrity and standardization - get star...","zh":"使用 Skill Polisher 工具来优化您的 Rust/Vulkan 代码，确保结构完整性和标准化","ja":"Rust/Vulkan AIエージェント開発を効率化する Skill Polisher ツールの使い方","ko":"코드 최적화를 위한 Skill Polisher 설정 방법과 Rust/Vulkan 개발 가이드","es":"Aprende a utilizar skill-polisher para auditar y estandarizar habilidades en Codex y Claude con tecnologías como Rust y Vulkan","fr":"Découvrez comment utiliser skill-polisher pour auditer et standardiser les compétences dans Codex et Claude avec des technologies comme Rust et Vulkan","de":"Erfahren Sie, wie Sie skill-polisher verwenden, um Fähigkeiten in Codex und Claude mit Technologien wie Rust und Vulkan zu überprüfen und zu standardisieren","pt":"Aprenda a utilizar o Skill Polisher para melhorar a integridade estrutural e a padronização dos skills de código","ru":"Узнайте, как использовать ИИ Агент Skill Polisher для проверки и улучшения кода","ar":"اكتشف كيفية استخدام Skill Polisher لتحسين بنية وتوحيد مهارات الترميز"},"definition":{"en":"skill-polisher is a Rust/Vulkan Isometric RPG Engine tool that validates Codex skills for standardization and integrity.","zh":"Skill Polisher 是一个用于检查和优化 Rust/Vulkan 代码的工具","ja":"Skill Polisher は Rust/Vulkan AIエージェントのコードを効率化するツール","ko":"Skill Polisher 는 Rust/Vulkan 코드를 검사하고 최적화하는 도구","es":"El skill-polisher es una herramienta de auditoría y estandarización para habilidades en entornos de desarrollo como Codex y Claude","fr":"Le skill-polisher est un outil d''audit et de standardisation pour les compétences dans les environnements de développement tels que Codex et Claude","de":"Der skill-polisher ist ein Tool zur Überprüfung und Standardisierung von Fähigkeiten in Entwicklungsumgebungen wie Codex und Claude","pt":"O Skill Polisher é uma ferramenta de auditoria de código que valida a integridade estrutural dos skills","ru":"ИИ Агент Skill Polisher - это инструмент для аудита кода, который проверяет целостность кода","ar":"Skill Polisher هو أداة مراجعة شفرة لتحقق من سلامة البنية"},"features":{"en":["Audits Codex skills for structural integrity using existing tooling","Validates Claude frontmatter and tooling rules by default","Supports cross-flavored compatibility via shared auditor","Targets single or whole sets of Codex skills in .codex/skills","Targets single Claude skills in .claude/skills/<skill-name>"],"zh":["支持 Rust/Vulkan 代码检查","确保代码结构完整性和标准化","支持单个技能和整个技能集的检查","兼容 Claude 和 Cross-Flavor 审核"],"ja":["Rust/Vulkan コードのチェックをサポート","コードの構造的完全性と標準化を確保","単一のスキルとスキルセットの両方のチェックをサポート","Claude と Cross-Flavor オーディットと互換性がある"],"ko":["Rust/Vulkan 코드 검사를 지원","코드 구조의 완전성과 표준화를 보장","개별 스킬과 스킬 세트 모두를 검사","Claude 및 Cross-Flavor 감사를 지원"],"es":["Compatibilidad con tecnologías como Rust y Vulkan","Auditoría y estandarización de habilidades en Codex y Claude","Soporte para auditorías cruzadas de sabores","Validación de reglas de frontmatter y herramientas de Claude","Compatibilidad con auditorías de habilidades individuales y conjuntas"],"fr":["Compatibilité avec des technologies comme Rust et Vulkan","Audit et standardisation des compétences dans Codex et Claude","Prise en charge des audits de saveur croisés","Validation des règles de frontmatter et des outils de Claude","Compatibilité avec les audits de compétences individuelles et collectives"],"de":["Kompatibilität mit Technologien wie Rust und Vulkan","Überprüfung und Standardisierung von Fähigkeiten in Codex und Claude","Unterstützung für Kreuzaudits von Geschmacksrichtungen","Validierung von Frontmatter-Regeln und Claude-Tools","Kompatibilität mit Einzel- und Gruppenfähigkeitsaudits"],"pt":["Validação de integridade estrutural dos skills","Padronização de código utilizando regras de frontmatter","Compatibilidade com skills de código Claude","Suporte à auditoria de skills individuais ou em conjunto","Utilização de auditor compartilhado para skills de código cruzados"],"ru":["Проверка целостности кода","Стандартизация кода с помощью правил frontmatter","Совместимость с кодом Claude","Поддержка аудита отдельных или всех навыков","Использование общего аудитора для навыков кода разных типов"],"ar":["التحقق من سلامة البنية","توحيد شفرة الترميز باستخدام قواعد الترميز الأمامي","التوافق مع مهارات الترميز كلود","دعم مراجعة مهارات الترميز الفردية أو الجماعية","استخدام مراجع مشترك لمراجعة مهارات الترميز المتقاطعة"]},"keywords":{"en":["how to use skill-polisher","what is skill-polisher","skill-polisher alternative","skill-polisher vs Vulkan","skill-polisher install","Rust isometric RPG engine","Vulkan game development","Codex skill standardization"],"zh":["Rust/Vulkan 代码优化","Skill Polisher 工具","AIエージェント开发","代码检查","结构完整性","标准化","Claude","Cross-Flavor"],"ja":["Rust/Vulkan AIエージェント開発","Skill Polisher ツール","コードの効率化","構造的完全性","標準化","Claude","Cross-Flavor オーディット"],"ko":["Rust/Vulkan 코드 최적화","Skill Polisher 도구","AI 에이전트 개발","코드 검사","구조 완전성","표준화","Claude","Cross-Flavor 감사"],"es":["skill-polisher","Rust","Vulkan","motor de RPG isométrico","auditoría de habilidades","estandarización de habilidades","Codex","Claude","herramientas de desarrollo","agentes de IA"],"fr":["skill-polisher","Rust","Vulkan","moteur de RPG isométrique","audit de compétences","standardisation de compétences","Codex","Claude","outils de développement","agents d''IA"],"de":["skill-polisher","Rust","Vulkan","isometrischer RPG-Motor","Fähigkeitsaudit","Fähigkeitsstandardisierung","Codex","Claude","Entwicklungstools","KI-Agenten"],"pt":["Skill Polisher","auditoria de código","integridade estrutural","padronização de código","desenvolvimento de skills","ferramentas de desenvolvimento","tecnologias de código","desenvolvedores de código"],"ru":["ИИ Агент Skill Polisher","аудит кода","целостность кода","стандартизация кода","разработка навыков","инструменты разработки","технологии кода","разработчики кода","ИИ Агенты"],"ar":["Skill Polisher","أداة مراجعة الشفرة","سلامة البنية","توحيد شفرة الترميز","تطوير مهارات الترميز","أدوات التطوير","تكنولوجيا الترميز","مطورو الترميز","أدوات الذكاء الاصطناعي"]}},"owner":"poisontr33s","repo":"chthonic-archive","repoPath":"poisontr33s/chthonic-archive","stars":0,"forks":0,"updatedAt":"2026-03-07T17:27:12Z","topics":[],"category":"community","skillMd":{"name":"skill-polisher","description":"Meta-skill for Claude Code to validate and polish Codex skills under `.codex/skills/` by running the skill-polisher and reviewing structural integrity. Use when auditing Codex skills, enforcing standardization, or running integrity sweeps across the Codex skill set.","bodyPreview":"# Skill Polisher (Claude Code)\n\nAudit Codex skills for structural integrity and standardization by using the existing Codex `skill-polisher` tooling.\n\n## Flavor Contract\n- **Claude-flavored** by default: validates Claude frontmatter/tooling rules.\n- **Cross-flavored compatible** via shared auditor (see Cross-Flavor Audit).\n\n## Target scope\n- Codex skills:\n  - Single skill: `.codex/skills/<skill-name>`\n  - Whole set: `.codex/skills`\n- Claude skills:\n  - Single skill: `.claude/skills/<skill-name>`","body":"# Skill Polisher (Claude Code)\n\nAudit Codex skills for structural integrity and standardization by using the existing Codex `skill-polisher` tooling.\n\n## Flavor Contract\n- **Claude-flavored** by default: validates Claude frontmatter/tooling rules.\n- **Cross-flavored compatible** via shared auditor (see Cross-Flavor Audit).\n\n## Target scope\n- Codex skills:\n  - Single skill: `.codex/skills/<skill-name>`\n  - Whole set: `.codex/skills`\n- Claude skills:\n  - Single skill: `.claude/skills/<skill-name>`\n  - Whole set: `.claude/skills`\n\n## Execution\n### Codex skills (preferred)\nUse the Codex polisher for deterministic audits:\n\n```powershell\nuv run .codex/skills/skill-polisher/scripts/polish_skill.py .codex/skills --all\n```\n\nFor a single skill:\n\n```powershell\nuv run .codex/skills/skill-polisher/scripts/polish_skill.py .codex/skills/<skill-name>\n```\n\n### Claude skills (manual audit)\nClaude skills do not share the Codex polisher; use a lightweight audit:\n\n```powershell\nGet-ChildItem .claude/skills -Directory\nGet-Content .claude/skills/<skill-name>/SKILL.md\n```\n\nChecks to confirm:\n- `SKILL.md` present\n- Frontmatter includes `name` and `description`\n- Any `allowed-tools` entries match Claude tool names (`Read`, `Write`, `Glob`, `Grep`, `Bash` as needed)\n\n## Cross-Flavor Audit (shared)\nUse the shared auditor when you want consistent reporting:\n\n```powershell\nuv run scripts/skill_audit.py --flavor codex --root .codex/skills\nuv run scripts/skill_audit.py --flavor claude --root .claude/skills\n```\n\n## Hook (Claude-side)\nRun the Claude cross-compatible audit via the helper script:\n\n```powershell\n.\\scripts\\run_claude_skill_polisher.ps1 -Root .claude/skills\n```\n\n## Claude-Local Audit (Claude-centric outputs)\nWrite JSON outputs into `claude/mailbox`:\n\n```powershell\n.\\scripts\\run_claude_local_audit.ps1 -Root .claude/skills\n```\n\n## Hook (Claude-side cross-polish)\nRun both Codex and Claude audits in one pass:\n\n```powershell\n.\\scripts\\run_claude_cross_polish.ps1 -CodexRoot .codex/skills -ClaudeRoot .claude/skills\n```\n\n## Bridge (Codex tooling)\nInvoke Codex polisher from Claude:\n\n```powershell\n.\\scripts\\run_codex_polisher.ps1 -Root .codex/skills\n```\n\n## Reporting\nSummarize:\n- TASTE + score\n- Issues (if any)\n- Files changed (if any)\n\n## Notes\n- This skill audits **Codex and Claude skills**; do not modify either unless explicitly requested.\n- If you need to add `@POLISHED` seals, do so after a clean run and record the timestamp.\n\n## Cross-Flavor Compatibility\n- Codex flavor: requires `agents/openai.yaml` and `assets/` with SVG icons.\n- Claude flavor: requires `SKILL.md` with valid frontmatter (`name`, `description`), optional `allowed-tools`.\n- For shared audits use: `python scripts/skill_audit.py --flavor codex --root .codex/skills` and `python scripts/skill_audit.py --flavor claude --root .claude/skills`.\n\n\n\n"},"lastSynced":"2026-03-08T02:14:13.400Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced Codex skill standardization and structural integrity validation.","zh":"适用于需要高级Codex技能标准化和结构完整性验证的AI代理。","ja":"高度なCodexスキル標準化と構造的完全性の検証が必要なAIエージェントに適しています。","ko":"고급 Codex 스킬 표준화 및 구조적 무결성 검증이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan una estandarización avanzada de habilidades de Codex y validación de integridad estructural.","fr":"Parfait pour les agents IA ayant besoin d''une standardisation avancée des compétences Codex et de validation de l''intégrité structurelle.","de":"Perfekt für KI-Agents, die eine erweiterte Standardisierung von Codex-Fähigkeiten und eine Validierung der strukturellen Integrität benötigen.","pt":"Perfeito para Agentes de IA que necessitam de padronização avançada de habilidades do Codex e validação de integridade estrutural.","ru":"Идеально подходит для агентов ИИ, которым требуются продвинутые стандарты навыков Codex и проверка структурной целостности.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى معايير مهارات متقدمة من Codex وتحقق من الصحة الهيكلية."},"recommendation":{"en":"Empowers agents to validate Codex skills using existing tooling, ensuring Claude-flavored and cross-flavored compatibility via shared auditor, and supports standardization of skills in `.codex/skills` and `.claude/skills` directories.","zh":"赋予代理验证Codex技能的能力，利用现有的工具，确保Claude风格和跨风格兼容性通过共享审计员，并支持在`.codex/skills`和`.claude/skills`目录中标准化技能。","ja":"エージェントにCodexスキルを検証する能力を与え、共有監査人を介して既存のツールを使用してClaudeスタイルとクロススタイルの互換性を確保し、`.codex/skills`および`.claude/skills`ディレクトリのスキルの標準化をサポートします。","ko":"에이전트가 Codex 스킬을 검증할 수 있는 능력을 부여하여 기존 도구를 사용하고 공유 감사를 통해 Claude 스타일 및 크로스 스타일 호환성을 보장하며 `.codex/skills` 및 `.claude/skills` 디렉토리에서 스킬을 표준화하는 것을 지원합니다.","es":"Habilita a los agentes a validar habilidades de Codex utilizando herramientas existentes, garantizando la compatibilidad con Claude y cross-flavored a través de un auditor compartido, y admite la estandarización de habilidades en los directorios `.codex/skills` y `.claude/skills`.","fr":"Permet aux agents de valider les compétences Codex en utilisant les outils existants, en garantissant la compatibilité avec Claude et cross-flavored via un auditeur partagé, et prend en charge la standardisation des compétences dans les répertoires `.codex/skills` et `.claude/skills`.","de":"Ermöglicht es Agenten, Codex-Fähigkeiten mit bestehenden Tools zu validieren, wodurch die Kompatibilität mit Claude und cross-flavored über einen gemeinsamen Auditor gewährleistet wird, und unterstützt die Standardisierung von Fähigkeiten in den Verzeichnissen `.codex/skills` und `.claude/skills`.","pt":"Habilita os agentes a validar habilidades do Codex usando ferramentas existentes, garantindo compatibilidade com Claude e cross-flavored via auditor compartilhado, e suporta a padronização de habilidades nos diretórios `.codex/skills` e `.claude/skills`.","ru":"Позволяет агентам проверять навыки Codex с помощью существующих инструментов, обеспечивая совместимость с Claude и cross-flavored через общий аудитор, и поддерживает стандартизацию навыков в директориях `.codex/skills` и `.claude/skills`.","ar":"تمكين العميل من التحقق من مهارات Codex باستخدام أدوات موجودة، وضمان التوافق مع Claude و cross-flavored عبر مدقق مشترك، ودعم معايير المهارات في الدلائل `.codex/skills` و `.claude/skills`."},"useCases":{"en":["Auditing Codex skills for structural integrity","Validating Claude frontmatter and tooling rules","Standardizing skills across `.codex/skills` and `.claude/skills` directories"],"zh":["审计Codex技能以验证结构完整性","验证Claude前置内容和工具规则","在`.codex/skills`和`.claude/skills`目录中标准化技能"],"ja":["構造的完全性の検証のためのCodexスキルの監査","Claudeヘッダーコンテンツとツールルールの検証","`.codex/skills`および`.claude/skills`ディレクトリのスキルの標準化"],"ko":["구조적 무결성의 검증을 위한 Codex 스킬 감사","Claude 헤더 콘텐츠 및 도구 규칙의 검증",".codex/skills 및 .claude/skills 디렉토리의 스킬 표준화"],"es":["Auditoría de habilidades de Codex para integridad estructural","Validación de frontmatter y reglas de herramientas de Claude","Estandarización de habilidades en los directorios `.codex/skills` y `.claude/skills`"],"fr":["Audit des compétences Codex pour l''intégrité structurelle","Validation du frontmatter et des règles d''outils de Claude","Standardisation des compétences dans les répertoires `.codex/skills` et `.claude/skills`"],"de":["Auditorische Überprüfung von Codex-Fähigkeiten für strukturelle Integrität","Validierung von Claude-Frontmatter und Tool-Regeln","Standardisierung von Fähigkeiten in den Verzeichnissen `.codex/skills` und `.claude/skills`"],"pt":["Auditoria de habilidades do Codex para integridade estrutural","Validação de frontmatter e regras de ferramentas do Claude","Padronização de habilidades nos diretórios `.codex/skills` e `.claude/skills`"],"ru":["Проверка навыков Codex на структурную целостность","Проверка frontmatter и правил инструментов Claude","Стандартизация навыков в директориях `.codex/skills` и `.claude/skills`"],"ar":["مراجعة مهارات Codex لتحقق من الصحة الهيكلية","تحقق من frontmatter و قواعد أدوات Claude","معايير المهارات في الدلائل `.codex/skills` و `.claude/skills`"]},"limitations":{"en":["Requires existing Codex `skill-polisher` tooling","Limited to Codex and Claude skills","Claude-flavored by default, cross-flavored compatibility via shared auditor"],"zh":["需要现有的Codex `skill-polisher`工具","仅限于Codex和Claude技能","默认为Claude风格，通过共享审计员实现跨风格兼容性"],"ja":["既存のCodex `skill-polisher`ツールが必要","CodexとClaudeのスキルに限定","デフォルトはClaudeスタイル、共有監査人を介してクロススタイルの互換性"],"ko":["기존의 Codex `skill-polisher` 도구가 필요","Codex 및 Claude 스킬에만 한정","기본적으로 Claude 스타일이며, 공유 감사를 통해 크로스 스타일 호환성을 제공"],"es":["Requiere herramientas de `skill-polisher` de Codex existentes","Limitado a habilidades de Codex y Claude","Con sabor a Claude de forma predeterminada, compatibilidad cross-flavored a través de un auditor compartido"],"fr":["Nécessite des outils `skill-polisher` de Codex existants","Limité aux compétences Codex et Claude","A saveur de Claude par défaut, compatibilité cross-flavored via un auditeur partagé"],"de":["Benötigt bestehende Codex-`skill-polisher`-Tools","Begrenzt auf Codex- und Claude-Fähigkeiten","Mit Claude-Geschmack standardmäßig, cross-flavored-Kompatibilität über einen gemeinsamen Auditor"],"pt":["Requer ferramentas existentes de `skill-polisher` do Codex","Limitado a habilidades do Codex e Claude","Com sabor Claude por padrão, compatibilidade cross-flavored via auditor compartilhado"],"ru":["Требует существующих инструментов `skill-polisher` от Codex","Ограничен навыками Codex и Claude","Имеет вкус Claude по умолчанию, совместимость cross-flavored через общий аудитор"],"ar":["يتطلب أدوات موجودة من `skill-polisher` من Codex","محدود بالمهارات من Codex و Claude","ذو نكهة Claude افتراضيًا، ومتوافق مع cross-flavored عبر مدقق مشترك"]},"version":4},"contentHash":"ced48430eb6fceece6b6c57e039dac3988eb14fa5961921cd26145360717098c","qualityScore":36}');
