INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('poisontr33s/chthonic-archive/skill-polisher', 'skill-polisher', 'poisontr33s', 'chthonic-archive', 'community', 'skill-polisher poisontr33s chthonic-archive community The skill-polisher audits Codex skills for structural integrity and standardization using existing tooling. It supports Claude-flavored and cross-flavored compatibility. Skill Polisher 是一个用于优化 Rust/Vulkan 代码的工具，确保结构完整性和标准化 Skill Polisher は Rust/Vulkan AIエージェント開発を効率化するツールです Skill Polisher 는 Rust/Vulkan 코드를 최적화하는 도구입니다 El skill-polisher es una herramienta para auditar y estandarizar habilidades en Codex y Claude, compatible con tecnologías como Rust y Vulkan Le skill-polisher est un outil pour auditer et standardiser les compétences dans Codex et Claude, compatible avec des technologies comme Rust et Vulkan Der skill-polisher ist ein Tool zur Überprüfung und Standardisierung von Fähigkeiten in Codex und Claude, kompatibel mit Technologien wie Rust und Vulkan O Skill Polisher é uma ferramenta de auditoria de código que valida a integridade estrutural e a padronização dos skills ИИ Агент Skill Polisher является инструментом для аудита кода, который проверяет целостность и стандарты кода Skill Polisher هو أداة مراجعة شفرة تتحقق من سلامة البنية وتوحيد مهارات الترميز how to use skill-polisher what is skill-polisher skill-polisher alternative skill-polisher vs Vulkan skill-polisher install Rust isometric RPG engine Vulkan game development Codex skill standardization Rust/Vulkan 代码优化 Skill Polisher 工具 AIエージェント开发 代码检查 结构完整性 标准化 Claude Cross-Flavor Audits Codex skills for structural integrity using existing tooling Validates Claude frontmatter and tooling rules by default Supports cross-flavored compatibility via shared auditor Targets single or whole sets of Codex skills in .codex/skills Targets single Claude skills in .claude/skills/<skill-name> skill-polisher is a Rust/Vulkan Isometric RPG Engine tool that validates Codex skills for standardization and integrity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edrickleong/obsidian-beautiful-mermaid/obsidian-cli', 'community', 'edrickleong', 'obsidian-beautiful-mermaid', 'edrickleong/obsidian-beautiful-mermaid', 'obsidian-cli', 0, 0, 36, '2026-03-05T14:48:08Z', '2026-03-08T02:15:56.472Z', 'b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358', '{"id":"edrickleong/obsidian-beautiful-mermaid/obsidian-cli","name":"obsidian-cli","description":{"en":"The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command-line interface. It provides a range of commands for creating and managing notes.","zh":"Obsidian CLI 是一个用于与 Obsidian 实例交互的命令行工具。它提供了创建和管理笔记的功能","ja":"Obsidian CLI は、Obsidian インスタンスと対話するためのコマンドラインツールです。ノートの作成や管理が可能です","ko":"Obsidian CLI는 Obsidian 인스턴스와 상호작용하는 명령행 도구입니다. 노트 생성 및 관리 기능을 제공합니다","es":"El comando obsidian-cli permite interactuar con instancias de Obsidian. Utiliza parámetros y banderas para personalizar tu experiencia.","fr":"La commande obsidian-cli permet d''interagir avec des instances Obsidian. Utilisez des paramètres et des indicateurs pour personnaliser votre expérience.","de":"Der Befehl obsidian-cli ermöglicht die Interaktion mit Obsidian-Instanzen. Verwenden Sie Parameter und Flags, um Ihre Erfahrung anzupassen.","pt":"O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias em execução. Veja a documentação para mais informações.","ru":"Obsidian-CLI - это инструмент командной строки для взаимодействия с запущенными экземплярами. См. документацию для более подробной информации.","ar":"Obsidian-CLI هو أداة سطر أوامر للتفاعل مع مثيلات التشغيل. راجع الوثائق لمزيد من المعلومات."},"seo":{"title":{"en":"obsidian-cli: Command-Line Interface Setup Guide | AI Age...","zh":"Obsidian CLI 设置指南 - 命令行工具","ja":"Obsidian CLI ベストプラクティス - AIエージェントの使い方","ko":"Obsidian CLI 