INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edrickleong/obsidian-beautiful-mermaid/obsidian-cli', 'obsidian-cli', 'edrickleong', 'obsidian-beautiful-mermaid', 'community', 'obsidian-cli edrickleong obsidian-beautiful-mermaid community The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command-line interface. It provides a range of commands for creating and managing notes. Obsidian CLI 是一个用于与 Obsidian 实例交互的命令行工具。它提供了创建和管理笔记的功能 Obsidian CLI は、Obsidian インスタンスと対話するためのコマンドラインツールです。ノートの作成や管理が可能です Obsidian CLI는 Obsidian 인스턴스와 상호작용하는 명령행 도구입니다. 노트 생성 및 관리 기능을 제공합니다 El comando obsidian-cli permite interactuar con instancias de Obsidian. Utiliza parámetros y banderas para personalizar tu experiencia. La commande obsidian-cli permet d''interagir avec des instances Obsidian. Utilisez des paramètres et des indicateurs pour personnaliser votre expérience. Der Befehl obsidian-cli ermöglicht die Interaktion mit Obsidian-Instanzen. Verwenden Sie Parameter und Flags, um Ihre Erfahrung anzupassen. O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias em execução. Veja a documentação para mais informações. Obsidian-CLI - это инструмент командной строки для взаимодействия с запущенными экземплярами. См. документацию для более подробной информации. Obsidian-CLI هو أداة سطر أوامر للتفاعل مع مثيلات التشغيل. راجع الوثائق لمزيد من المعلومات. how to use obsidian-cli obsidian-cli setup guide obsidian-cli alternative obsidian-cli vs other note-taking tools obsidian-cli install what is obsidian-cli obsidian-cli command reference obsidian-cli documentation Obsidian CLI 命令行工具 笔记管理 Obsidian 实例 命令行参数 标志设置 silent模式 overwrite模式 Runs `obsidian help` to display all available commands Supports parameters with values using the `=` syntax Allows quoting values with spaces for commands like `obsidian create` Includes boolean flags like `silent` and `overwrit` for customization Provides full documentation at https://help.obsidian.md/cli obsidian-cli is a command-line interface for interacting with a running Obsidian instance, providing a range of commands for note creation and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Jack5316/Obsidian/obsidian-cli', 'community', 'Jack5316', 'Obsidian', 'Jack5316/Obsidian', 'obsidian-cli', 0, 0, 36, '2026-03-05T02:19:06Z', '2026-03-08T02:15:59.876Z', 'b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358', '{"id":"Jack5316/Obsidian/obsidian-cli","name":"obsidian-cli","description":{"en":"The obsidian-cli skill syncs Obsidian Vault via Git and Working Copy, allowing developers to interact with a running Obsidian instance. It requires Obsidian to be open and uses specific commands and parameters.","zh":"Obsidian CLI 是一个命令行工具，用于与运行中的 Obsidian 实例交互，支持 Git 和 Working Copy 同步","ja":"Obsidian CLI は、実行中の Obsidian インスタンスとやり取りするためのコマンドラインツールで、Git と Working Copy の同期をサポートします","ko":"Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하는 명령줄 도구로 Git 및 Working Copy 동기화를 지원합니다","es":"obsidian-cli es una herramienta de línea de comandos para interactuar con una instancia de Obsidian en ejecución. Requiere que Obsidian esté abierto.","fr":"obsidian-cli est un outil de ligne de commande pour interagir avec une instance Obsidian en cours d''exécution. Requiert que Obsidian soit ouvert.","de":"obsidian-cli ist ein Kommandozeilen-Tool zur Interaktion mit einer laufenden Obsidian-Instanz. Erfordert, dass Obsidian geöffnet ist.","pt":"O Obsidian-CLI é uma ferramenta de linha de comando para interagir com o Obsidian. Permite sincronizar com Git e Working Copy.","ru":"Obsidian-CLI - это инструмент командной строки для взаимодействия с Obsidian. Позволяет синхронизироваться с Git и Working Copy.","ar":"أداة Obsidian-CLI هي أداة سطر أوامر للتفاعل مع Obsidian. تسمح بدمج البيانات مع Git و Working Copy."},"seo":{"title":{"en":"obsidian-cli: Sync Obsidian Vault via Git and Working Cop...","zh":"Obsidian CLI 设置指南：Git 和 Working Copy 同步","ja":"Obsidian CLI 導入ガイド：Git と Working Copy を同期する","ko":"Obsidian CLI 설정 가이드: Git 및 Working Copy 동기화","es":"Guía de configuración de obsidian-cli para sincronización...","fr":"Guide de mise en route d''obsidian-cli pour la synchronisa...","de":"Einrichtungsanleitung für obsidian-cli zur Synchronisieru...","pt":"Guia de Configuração do Obsidian-CLI: Sincronize com Git","ru":"ИИ Агент Obsidian-CLI: Настройка и Синхронизация с Git","ar":"إعداد أداة Obsidian-CLI: مزامنة مع Git"},"description":{"en":"Discover how to sync your Obsidian Vault with Git and Working Copy using the obsidian-cli. Learn the commands and parameters to get started today!","zh":"使用 Obsidian CLI 实现 Obsidian Vault 的 Git 和 Working Copy 同步，提高开发效率","ja":"Obsidian CLI を使用して Obsidian Vault を Git と Working Copy に同期し、開発効率を向上させる","ko":"Obsidian CLI를 사용하여 Obsidian Vault를 Git 및 Working Copy와 동기화하여 개발 효율성을 높입니다","es":"Aprende a usar obsidian-cli para sincronizar tu bóveda de Obsidian con Git y Working Copy. Descubre cómo interactuar con la instancia de Obsidian mediante la...","fr":"Découvrez comment utiliser obsidian-cli pour synchroniser votre coffre Obsidian avec Git et Working Copy. Apprenez à interagir avec l''instance Obsidian via l...","de":"Erfahren Sie, wie Sie obsidian-cli verwenden, um Ihr Obsidian-Vault mit Git und Working Copy zu synchronisieren. Entdecken Sie, wie Sie mit der Obsidian-Inst...","pt":"Aprenda a configurar o Obsidian-CLI para sincronizar com Git e Working Copy. Descubra os comandos e parâmetros disponíveis.","ru":"Узнайте, как настроить Obsidian-CLI для синхронизации с Git и Working Copy. Ознакомьтесь с доступными командами и параметрами.","ar":"تعرف على كيفية إعداد أداة Obsidian-CLI لتنظيم البيانات مع Git و Working Copy. استكشف الأوامر والparameters المتاحة."},"definition":{"en":"obsidian-cli is a command-line interface that interacts with a running Obsidian instance, allowing for synchronization with Git and Working Copy.","zh":"Obsidian CLI 是一个用于与 Obsidian 交互的命令行工具","ja":"Obsidian CLI は、Obsidian とやり取りするためのコマンドラインツールです","ko":"Obsidian CLI는 Obsidian과 상호 작용하는 명령줄 도구입니다","es":"obsidian-cli es una herramienta de línea de comandos para sincronizar tu bóveda de Obsidian con Git y Working Copy","fr":"obsidian-cli est un outil de ligne de commande pour synchroniser votre coffre Obsidian avec Git et Working Copy","de":"obsidian-cli ist ein Kommandozeilen-Tool zur Synchronisierung Ihres Obsidian-Vaults mit Git und Working Copy","pt":"O que é Obsidian-CLI? É uma ferramenta de linha de comando para gerenciar o Obsidian via Git.","ru":"Что такое Obsidian-CLI? Это инструмент командной строки для управления Obsidian через Git.","ar":"ما هي أداة Obsidian-CLI؟ هي أداة سطر أوامر لإدارة Obsidian من خلال Git."},"features":{"en":["Runs `obsidian help` to see all available commands","Supports parameters with values using `=` and quoted values with spaces","Uses flags as boolean switches with no value, such as `silent` and `overwrite`","Creates new notes using the `create` command with `name` and `content` parameters","Requires Obsidian to be open for interaction"],"zh":["支持 Git 同步","支持 Working Copy 同步","命令行工具","与 Obsidian 实例交互","支持参数和标志"],"ja":["Git 同期をサポート","Working Copy 同期をサポート","コマンドラインツール","Obsidian インスタンスとやり取り","パラメータとフラグをサポート"],"ko":["Git 동기화를 지원","Working Copy 동기화를 지원","명령줄 도구","Obsidian 인스턴스와 상호 작용","매개 변수 및 플래그를 지원"],"es":["Sincronización de la bóveda de Obsidian con Git","Integración con Working Copy","Línea de comandos para interactuar con la instancia de Obsidian","Compatibilidad con parámetros y flags","Documentación en línea disponible"],"fr":["Synchronisation du coffre Obsidian avec Git","Intégration avec Working Copy","Ligne de commande pour interagir avec l''instance Obsidian","Compatibilité avec les paramètres et les flags","Documentation en ligne disponible"],"de":["Synchronisierung des Obsidian-Vaults mit Git","Integration mit Working Copy","Kommandozeile zur Interaktion mit der Obsidian-Instanz","Kompatibilität mit Parametern und Flags","Online-Dokumentation verfügbar"],"pt":["Sincronização com Git","Integração com Working Copy","Comandos personalizados com parâmetros","Suporte a flags booleanas","Documentação completa em https://help.obsidian.md/cli"],"ru":["Синхронизация с Git","Интеграция с Working Copy","Пользовательские команды с параметрами","Поддержка булевых флагов","Полная документация на https://help.obsidian.md/cli"],"ar":["مزامنة مع Git","دمج مع Working Copy","أوامر مخصصة مع parameters","دعم الرايات المنطقية","وثائق شاملة على https://help.obsidian.md/cli"]},"keywords":{"en":["how to use obsidian-cli","obsidian-cli setup guide","obsidian-cli vs Working Copy","obsidian-cli install","what is obsidian-cli","obsidian-cli alternative","obsidian-cli git sync","obsidian-cli command reference","obsidian-cli parameters","obsidian-cli flags"],"zh":["Obsidian CLI","Git 同步","Working Copy 同步","命令行工具","Obsidian","开发工具","AIエージェント","代码同步"],"ja":["Obsidian CLI","Git 同期","Working Copy 同期","コマンドラインツール","Obsidian","開発ツール","AIエージェント","コード同期"],"ko":["Obsidian CLI","Git 동기화","Working Copy 동기화","명령줄 도구","Obsidian","개발 도구","AI 에이전트","코드 동기화"],"es":["obsidian-cli","sincronización de Obsidian","Git","Working Copy","línea de comandos","parámetros","flags","documentación en línea","herramientas de desarrollo"],"fr":["obsidian-cli","synchronisation d''Obsidian","Git","Working Copy","ligne de commande","paramètres","flags","documentation en ligne","outils de développement"],"de":["obsidian-cli","Synchronisierung von Obsidian","Git","Working Copy","Kommandozeile","Parameter","Flags","Online-Dokumentation","Entwickler-Tools"],"pt":["Obsidian-CLI","Sincronização com Git","Working Copy","Comandos personalizados","Ferramentas de linha de comando","Gerenciamento de notas","Integração com Git","Documentação Obsidian-CLI"],"ru":["Obsidian-CLI","Синхронизация с Git","Working Copy","Пользовательские команды","ИИ Агенты","Инструменты командной строки","Управление заметками","Интеграция с Git","Документация Obsidian-CLI"],"ar":["أداة Obsidian-CLI","مزامنة مع Git","Working Copy","أوامر مخصصة","أدوات سطر أوامر","إدارة الملاحظات","دمج مع Git","وثائق أداة Obsidian-CLI","أدوات إدارة البيانات"]}},"owner":"Jack5316","repo":"Obsidian","repoPath":"Jack5316/Obsidian","stars":0,"forks":0,"updatedAt":"2026-03-05T02:19:06Z","topics":[],"category":"community","skillMd":{"name":"obsidian-cli","description":"Interact with Obsidian vaults using the Obsidian CLI to read, create, search, and manage notes, tasks, properties, and more. Also supports plugin and theme development with commands to reload plugins, run JavaScript, capture errors, take screenshots, and inspect the DOM. Use when the user asks to interact with their Obsidian vault, manage notes, search vault content, perform vault operations from the command line, or develop and debug Obsidian plugins and themes.","bodyPreview":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrit","body":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrite\n```\n\nFor multiline content use `\\n` for newline and `\\t` for tab.\n\n## File targeting\n\nMany commands accept `file` or `path` to target a file. Without either, the active file is used.\n\n- `file=<name>` — resolves like a wikilink (name only, no path or extension needed)\n- `path=<path>` — exact path from vault root, e.g. `folder/note.md`\n\n## Vault targeting\n\nCommands target the most recently focused vault by default. Use `vault=<name>` as the first parameter to target a specific vault:\n\n```bash\nobsidian vault=\"My Vault\" search query=\"test\"\n```\n\n## Common patterns\n\n```bash\nobsidian read file=\"My Note\"\nobsidian create name=\"New Note\" content=\"# Hello\" template=\"Template\" silent\nobsidian append file=\"My Note\" content=\"New line\"\nobsidian search query=\"search term\" limit=10\nobsidian daily:read\nobsidian daily:append content=\"- [ ] New task\"\nobsidian property:set name=\"status\" value=\"done\" file=\"My Note\"\nobsidian tasks daily todo\nobsidian tags sort=count counts\nobsidian backlinks file=\"My Note\"\n```\n\nUse `--copy` on any command to copy output to clipboard. Use `silent` to prevent files from opening. Use `total` on list commands to get a count.\n\n## Plugin development\n\n### Develop/test cycle\n\nAfter making code changes to a plugin or theme, follow this workflow:\n\n1. **Reload** the plugin to pick up changes:\n   ```bash\n   obsidian plugin:reload id=my-plugin\n   ```\n2. **Check for errors** — if errors appear, fix and repeat from step 1:\n   ```bash\n   obsidian dev:errors\n   ```\n3. **Verify visually** with a screenshot or DOM inspection:\n   ```bash\n   obsidian dev:screenshot path=screenshot.png\n   obsidian dev:dom selector=\".workspace-leaf\" text\n   ```\n4. **Check console output** for warnings or unexpected logs:\n   ```bash\n   obsidian dev:console level=error\n   ```\n\n### Additional developer commands\n\nRun JavaScript in the app context:\n\n```bash\nobsidian eval code=\"app.vault.getFiles().length\"\n```\n\nInspect CSS values:\n\n```bash\nobsidian dev:css selector=\".workspace-leaf\" prop=background-color\n```\n\nToggle mobile emulation:\n\n```bash\nobsidian dev:mobile on\n```\n\nRun `obsidian help` to see additional developer commands including CDP and debugger controls.\n"},"lastSynced":"2026-03-08T02:15:59.876Z","agentAnalysis":{"suitability":{"en":"Perfect for Knowledge Management Agents needing seamless interaction with Obsidian Vaults via Git and Working Copy","zh":"适合需要与Obsidian Vaults通过Git和Working Copy进行无缝交互的知识管理代理","ja":"Obsidian VaultsとGitおよびWorking Copyを介してシームレスに相互作用する必要があるナレッジマネジメントエージェントに最適","ko":"Git 및 Working Copy를 통해 Obsidian Vaults와 무결점으로 상호 작용하는 지식 관리 에이전트에 적합","es":"Perfecto para agentes de Gestión del Conocimiento que necesitan una interacción sin problemas con Obsidian Vaults a través de Git y Working Copy","fr":"Parfait pour les agents de gestion des connaissances ayant besoin d''une interaction sans problème avec les coffres Obsidian via Git et Working Copy","de":"Perfekt für Wissensmanagement-Agenten, die eine nahtlose Interaktion mit Obsidian Vaults über Git und Working Copy benötigen","pt":"Perfeito para Agentes de Gerenciamento de Conhecimento que necessitam de interação sem problemas com Vaults do Obsidian via Git e Working Copy","ru":"Идеально подходит для агентов управления знаниями, которым требуется бесперебойное взаимодействие с хранилищами Obsidian через Git и Working Copy","ar":"مثالي لعمليات وكيل إدارة المعرفة التي تحتاج إلى تفاعل بدون مشاكل مع خزائن Obsidian عبر Git و Working Copy"},"recommendation":{"en":"Empowers agents to create, manage, and sync Obsidian notes using specific commands and parameters, leveraging Git version control and Working Copy integration for robust content management, and utilizing parameters and flags for customized interactions","zh":"赋予代理创建、管理和同步Obsidian笔记的能力，使用特定命令和参数，利用Git版本控制和Working Copy集成实现强大的内容管理，并利用参数和标志实现自定义交互","ja":"エージェントが特定のコマンドとパラメータを使用してObsidianノートを作成、管理、同期する機能を提供し、Gitのバージョン管理とWorking Copyの統合を利用して強力なコンテンツ管理を実現し、パラメータとフラグを使用してカスタマイズされた相互作用を実現する","ko":"에이전트가 특정 명령과 매개 변수를 사용하여 Obsidian 노트를 생성, 관리 및 동기화 할 수 있는 기능을 제공하며, Git 버전 관리 및 Working Copy 통합을 활용하여 강력한 콘텐츠 관리를 가능하게 하며, 매개 변수 및 플래그를 사용하여 사용자 지정 상호 작용을 구현합니다.","es":"Habilita a los agentes a crear, gestionar y sincronizar notas de Obsidian utilizando comandos y parámetros específicos, aprovechando el control de versiones Git y la integración de Working Copy para una gestión de contenido robusta, y utilizando parámetros y flags para interacciones personalizadas","fr":"Permet aux agents de créer, de gérer et de synchroniser des notes Obsidian en utilisant des commandes et des paramètres spécifiques, en exploitant le contrôle de version Git et l''intégration de Working Copy pour une gestion de contenu robuste, et en utilisant des paramètres et des flags pour des interactions personnalisées","de":"Ermächtigt Agenten, Obsidian-Notizen zu erstellen, zu verwalten und zu synchronisieren, indem sie spezifische Befehle und Parameter verwenden, die Git-Versionierung und die Working Copy-Integration für eine robuste Inhaltsverwaltung nutzen und Parameter und Flags für benutzerdefinierte Interaktionen verwenden","pt":"Habilita os agentes a criar, gerenciar e sincronizar notas do Obsidian usando comandos e parâmetros específicos, aproveitando o controle de versão do Git e a integração do Working Copy para gerenciamento de conteúdo robusto, e utilizando parâmetros e flags para interações personalizadas","ru":"Предоставляет агентам возможность создавать, управлять и синхронизировать заметки Obsidian с помощью определенных команд и параметров, используя контроль версий Git и интеграцию Working Copy для надежного управления контентом, и используя параметры и флаги для настраиваемого взаимодействия","ar":"يسمح للوكيل بإنشاء وإدارة وتنسيق ملاحظات Obsidian باستخدام أوامر ومعاملات محددة، مستفيداً من التحكم في الإصدارات بواسطة Git ودمج Working Copy لإدارة المحتوى القوي، واستخدام المعاملات والمراتب للتفاعلات المخصصة"},"useCases":{"en":["Syncing Obsidian Vaults via Git for collaborative knowledge management","Automating note creation with custom content and metadata","Debugging Obsidian instance interactions using the `obsidian help` command"],"zh":["通过Git进行协作知识管理的Obsidian Vaults同步","使用自定义内容和元数据自动创建笔记","使用`obsidian help`命令调试Obsidian实例交互"],"ja":["コラボレーションナレッジマネジメントのためのGitを介したObsidian Vaultsの同期","カスタムコンテンツとメタデータを使用したノートの自動作成","`obsidian help`コマンドを使用したObsidianインスタンスの相互作用のデバッグ"],"ko":["Git를 통한 협력 지식 관리를 위한 Obsidian Vaults 동기화","사용자 지정 콘텐츠 및 메타데이터로 자동 노트 생성","`obsidian help` 명령어를 사용한 Obsidian 인스턴스 상호 작용 디버깅"],"es":["Sincronización de Obsidian Vaults a través de Git para la gestión colaborativa del conocimiento","Automatización de la creación de notas con contenido y metadatos personalizados","Depuración de interacciones de instancias de Obsidian utilizando el comando `obsidian help`"],"fr":["Synchronisation des coffres Obsidian via Git pour la gestion collaborative des connaissances","Automatisation de la création de notes avec un contenu et des métadonnées personnalisés","Débogage des interactions d''instances Obsidian en utilisant la commande `obsidian help`"],"de":["Synchronisierung von Obsidian Vaults über Git für die kollaborative Wissensverwaltung","Automatisierung der Notizenerstellung mit benutzerdefiniertem Inhalt und Metadaten","Fehlerbehebung von Obsidian-Instanz-Interaktionen mit dem Befehl `obsidian help`"],"pt":["Sincronização de Vaults do Obsidian via Git para gerenciamento colaborativo de conhecimento","Criação automática de notas com conteúdo e metadados personalizados","Depuração de interações de instâncias do Obsidian usando o comando `obsidian help`"],"ru":["Синхронизация хранилищ Obsidian через Git для совместного управления знаниями","Автоматическое создание заметок с пользовательским содержимым и метаданными","Отладка взаимодействий экземпляров Obsidian с помощью команды `obsidian help`"],"ar":["تنسيق خزائن Obsidian عبر Git لإدارة المعرفة التعاونية","إنشاء تلقائي للملاحظات بمحتوى ومetadata مخصص","تصحيح أخطاء تفاعلات实例 Obsidian باستخدام الأمر `obsidian help`"]},"limitations":{"en":["Requires Obsidian to be open and running","Specific command and parameter syntax must be followed"],"zh":["需要Obsidian打开并运行","必须遵循特定命令和参数的语法"],"ja":["Obsidianが開かれ、実行されている必要がある","特定のコマンドとパラメータの構文に従う必要がある"],"ko":["Obsidian을 열고 실행해야 함","특정 명령과 매개 변수의 구문을 따라야 함"],"es":["Requiere que Obsidian esté abierto y en ejecución","La sintaxis de comandos y parámetros específicos debe seguirse"],"fr":["Nécessite que Obsidian soit ouvert et en cours d''exécution","La syntaxe de commandes et de paramètres spécifiques doit être suivie"],"de":["Erfordert, dass Obsidian geöffnet und ausgeführt wird","Die Syntax spezifischer Befehle und Parameter muss befolgt werden"],"pt":["Requer que o Obsidian esteja aberto e em execução","A sintaxe de comandos e parâmetros específicos deve ser seguida"],"ru":["Требует, чтобы Obsidian был открыт и запущен","Должна быть соблюдена конкретная синтаксис команд и параметров"],"ar":["يتطلب أن يكون Obsidian مفتوحاً ويعمل","يجب اتباع بنية أوامر ومعاملات محددة"]},"version":4},"contentHash":"b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358","qualityScore":36}');
