INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jack5316/Obsidian/obsidian-cli', 'obsidian-cli', 'Jack5316', 'Obsidian', 'community', 'obsidian-cli Jack5316 Obsidian community The obsidian-cli skill syncs Obsidian Vault via Git and Working Copy, allowing developers to interact with a running Obsidian instance. It requires Obsidian to be open and uses specific commands and parameters. Obsidian CLI 是一个命令行工具，用于与运行中的 Obsidian 实例交互，支持 Git 和 Working Copy 同步 Obsidian CLI は、実行中の Obsidian インスタンスとやり取りするためのコマンドラインツールで、Git と Working Copy の同期をサポートします Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하는 명령줄 도구로 Git 및 Working Copy 동기화를 지원합니다 obsidian-cli es una herramienta de línea de comandos para interactuar con una instancia de Obsidian en ejecución. Requiere que Obsidian esté abierto. obsidian-cli est un outil de ligne de commande pour interagir avec une instance Obsidian en cours d''exécution. Requiert que Obsidian soit ouvert. obsidian-cli ist ein Kommandozeilen-Tool zur Interaktion mit einer laufenden Obsidian-Instanz. Erfordert, dass Obsidian geöffnet ist. O Obsidian-CLI é uma ferramenta de linha de comando para interagir com o Obsidian. Permite sincronizar com Git e Working Copy. Obsidian-CLI - это инструмент командной строки для взаимодействия с Obsidian. Позволяет синхронизироваться с Git и Working Copy. أداة Obsidian-CLI هي أداة سطر أوامر للتفاعل مع Obsidian. تسمح بدمج البيانات مع Git و Working Copy. how to use obsidian-cli obsidian-cli setup guide obsidian-cli vs Working Copy obsidian-cli install what is obsidian-cli obsidian-cli alternative obsidian-cli git sync obsidian-cli command reference obsidian-cli parameters obsidian-cli flags Obsidian CLI Git 同步 Working Copy 同步 命令行工具 Obsidian 开发工具 AIエージェント 代码同步 Runs `obsidian help` to see all available commands Supports parameters with values using `=` and quoted values with spaces Uses flags as boolean switches with no value, such as `silent` and `overwrite` Creates new notes using the `create` command with `name` and `content` parameters Requires Obsidian to be open for interaction obsidian-cli is a command-line interface that interacts with a running Obsidian instance, allowing for synchronization with Git and Working Copy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jyje/cluster/git-commit-helper', 'community', 'jyje', 'cluster', 'jyje/cluster', 'git-commit-helper', 0, 0, 36, '2026-03-07T12:46:33.609Z', '2026-03-07T12:59:29.754Z', '6a9b6a96e875bb80cafe588bf47afdee619d37cea30f85d0983373fe4d8328db', '{"id":"jyje/cluster/git-commit-helper","name":"git-commit-helper","description":{"en":"The git-commit-helper skill assists developers in creating informative git commit messages by analyzing changes and determining affected domains. It benefits developers working with git repositories.","zh":"Git Commit Helper是一个帮助您优化代码提交的AI工具，通过分析更改、确定域和选择合适的提交类型","ja":"Git Commit Helperは、コードの変更を分析し、ドメインを決定し、適切なコミットタイプを選択することで、コードのコミットプロセスを最適化するAIエージェントです","ko":"Git Commit Helper는 코드 제출 프로세스를 최적화하는 AI 에이전트로, 변경 사항을 분석하고 도메인을 결정하고 적절한 커밋 유형을 선택합니다","es":"El git-commit-helper es una herramienta que te ayuda a mejorar tus commites de Git. Analiza cambios y determina dominios para commites efectivos.","fr":"Le git-commit-helper est un outil qui vous aide à améliorer vos commits Git. Il analyse les modifications et détermine les domaines pour des commits efficaces.","de":"Der git-commit-helper ist ein Tool, das Ihnen hilft, Ihre Git-Commits zu verbessern. Es analysiert Änderungen und bestimmt Domänen für effektive Commits.","pt":"O git-commit-helper é uma ferramenta que ajuda a analisar alterações e criar mensagens de commit personalizadas","ru":"ИИ Агент git-commit-helper помогает анализировать изменения и создавать индивидуальные сообщения о фиксации","ar":"مساعد التزام الجيت هو أداة تساعد في تحليل التغييرات وإنشاء رسائل التزام مخصصة"},"seo":{"title":{"en":"git-commit-helper: Git Commit Message Setup Guide | AI Ag...","zh":"Git Commit Helper setup guide - AI工具","ja":"Git Commit Helperの設定方法 - AIエージェント","ko":"Git Commit Helper 설정 가이드 - AI 에이전트","es":"Guía de configuración de git-commit-helper para desarroll...","fr":"Guide d''installation de git-commit-helper pour les dévelo...","de":"Einrichtungsanleitung für git-commit-helper-Entwickler","pt":"Guia de Configuração do git-commit-helper: Melhores Práticas","ru":"Настройка ИИ Агента git-commit-helper: Руководство","ar":"إعداد مساعد التزام الجيت: دليل المستخدم"},"description":{"en":"Discover how to automate git commit messages with git-commit-helper. Learn to analyze changes, determine domains, and select types with gitmoji. Get started ...","zh":"了解Git Commit Helper的功能和设置方法，优化您的代码提交流程 - AI工具","ja":"Git Commit Helperの機能と設定方法を学び、コードのコミットプロセスを最適化する - AIエージェント","ko":"Git Commit Helper의 기능과 설정 방법을 알아보고 코드 제출 프로세스를 최적화하세요 - AI 에이전트","es":"Mejora tus flujos de trabajo de Git con git-commit-helper. Aprende a analizar cambios y determinar dominios para commites efectivos.","fr":"Améliorez vos flux de travail Git avec git-commit-helper. Découvrez comment analyser les modifications et déterminer les domaines pour des commits efficaces.","de":"Verbessern Sie Ihre Git-Arbeitsabläufe mit git-commit-helper. Erfahren Sie, wie Sie Änderungen analysieren und Domänen bestimmen, um effektive Commits durchz...","pt":"Aprenda a configurar e utilizar o git-commit-helper para melhorar a eficiência do seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить и использовать ИИ Агент git-commit-helper для оптимизации вашего рабочего процесса разработки","ar":"تعرف على كيفية إعداد وتشغيل مساعد التزام الجيت لتحسين كفاءة سير عمل التطوير الخاص بك"},"definition":{"en":"git-commit-helper is a skill that automates the process of creating git commit messages by reviewing staged and unstaged changes, identifying primary components, and selecting appropriate types with corresponding gitmoji.","zh":"Git Commit Helper是一种AI工具，帮助开发者优化代码提交流程","ja":"Git Commit Helperは、開発者がコードのコミットプロセスを最適化するのに役立つAIエージェントです","ko":"Git Commit Helper는 개발자가 코드 제출 프로세스를 최적화하는 데 도움이 되는 AI 에이전트입니다","es":"El git-commit-helper es una herramienta de asistencia para commits de Git que analiza cambios y determina dominios.","fr":"Le git-commit-helper est un outil d''assistance pour les commits Git qui analyse les modifications et détermine les domaines.","de":"Der git-commit-helper ist ein Assistenztool für Git-Commits, das Änderungen analysiert und Domänen bestimmt.","pt":"O que é git-commit-helper? É uma ferramenta que auxilia na criação de mensagens de commit personalizadas","ru":"Что такое ИИ Агент git-commit-helper? Это инструмент, помогающий создавать индивидуальные сообщения о фиксации","ar":"ما هو مساعد التزام الجيت؟ هو أداة تساعد في إنشاء رسائل التزام مخصصة"},"features":{"en":["Analyzes staged and unstaged changes to understand the scope of work","Determines the primary component or domain affected using lowercase and kebab-case","Selects the appropriate type and its corresponding gitmoji for commit messages","Supports git commit message generation based on analyzed changes","Utilizes a table to map types to their corresponding gitmoji","Searches git log to ensure consistent commit messaging"],"zh":["分析更改和确定域","选择合适的提交类型和Gitmoji","支持kebab-case和lowercase命名约定","集成git命令行工具"],"ja":["変更を分析し、ドメインを決定する","適切なコミットタイプとGitmojiを選択する","kebab-caseとlowercase命名規約をサポートする","gitコマンドラインツールと統合する"],"ko":["변경 사항을 분석하고 도메인을 결정합니다","적절한 커밋 유형과 Gitmoji를 선택합니다","kebab-case와 lowercase 명명 규칙을 지원합니다","git 명령行 도구와 통합합니다"],"es":["Análisis de cambios para entender el alcance y propósito del trabajo","Determinación de dominios para commites efectivos","Selección de tipo y gitmoji adecuados","Búsqueda de git log para encontrar información relevante"],"fr":["Analyse des modifications pour comprendre la portée et l''objectif du travail","Détermination des domaines pour des commits efficaces","Sélection du type et du gitmoji appropriés","Recherche de git log pour trouver des informations pertinentes"],"de":["Analyse von Änderungen, um den Umfang und Zweck der Arbeit zu verstehen","Bestimmung von Domänen für effektive Commits","Auswahl des geeigneten Typs und Gitmojis","Suche nach Git-Log, um relevante Informationen zu finden"],"pt":["Análise de alterações para entender o escopo e propósito do trabalho","Determinação do domínio primário afetado","Seleção do tipo e gitmoji apropriados","Suporte à busca de commit"],"ru":["Анализ изменений для понимания объема и цели работы","Определение основного домена, на который влияет работа","Выбор подходящего типа и гитмоджи","Поддержка поиска фиксации"],"ar":["تحليل التغييرات لفهم نطاق وغرض العمل","تحديد المجال الرئيسي المتأثر","اختيار النوع والشعار المناسبين","دعم البحث عن التزام"]},"keywords":{"en":["how to use git-commit-helper","git-commit-helper setup guide","git-commit-helper alternative","git-commit-helper vs git hooks","git-commit-helper install","what is git-commit-helper","git-commit-helper for AI agents","automating git commit messages","gitmoji for commit messages"],"zh":["Git Commit Helper","AI工具","代码提交","git命令行工具","kebab-case","lowercase","Gitmoji"],"ja":["Git Commit Helper","AIエージェント","コードコミット","gitコマンドラインツール","kebab-case","lowercase","Gitmoji"],"ko":["Git Commit Helper","AI 에이전트","코드 제출","git 명령行 도구","kebab-case","lowercase","Gitmoji"],"es":["git-commit-helper","herramientas de Git","commits de Git","análisis de cambios","determinación de dominios","gitmoji","búsqueda de git log","desarrollo de software","herramientas de desarrollo"],"fr":["git-commit-helper","outils Git","commits Git","analyse des modifications","détermination des domaines","gitmoji","recherche de git log","développement de logiciels","outils de développement"],"de":["git-commit-helper","Git-Tools","Git-Commits","Analyse von Änderungen","Bestimmung von Domänen","Gitmoji","Suche nach Git-Log","Software-Entwicklung","Entwicklungstools"],"pt":["git-commit-helper","ferramenta de commit","análise de alterações","mensagem de commit personalizada","desenvolvimento de software","fluxo de trabalho de desenvolvimento"],"ru":["ИИ Агент git-commit-helper","инструмент фиксации","анализ изменений","индивидуальное сообщение о фиксации","разработка программного обеспечения","рабочий процесс разработки"],"ar":["مساعد التزام الجيت","أداة التزام","تحليل التغييرات","رسالة التزام مخصصة","تطوير البرمجيات","سير عمل التطوير"]}},"owner":"jyje","repo":"cluster","repoPath":"jyje/cluster","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.609Z","topics":[],"category":"community","skillMd":{"name":"git-commit-helper","description":"Generate descriptive commit messages by analyzing git diffs following the projects specific policy. Use when the user asks for help writing commit messages or reviewing staged changes.","bodyPreview":"# Git Commit Helper\n\nYou are an expert software engineer managing git commits. Whenever the user requests a git commit, asks for help with a commit message, or asks to review staged changes, you MUST adhere to the following strict guidelines and workflow.\n\n## 1. Commit Message Format\nAll commit messages must strictly follow this format:\n```\n<gitmoji> <type>(<domain>): <title>\n\n<description>\n```\n\n### Formatting Rules:\n- **Gitmoji**: Must use one of the exactly specified emojis (see mapping below)","body":"# Git Commit Helper\n\nYou are an expert software engineer managing git commits. Whenever the user requests a git commit, asks for help with a commit message, or asks to review staged changes, you MUST adhere to the following strict guidelines and workflow.\n\n## 1. Commit Message Format\nAll commit messages must strictly follow this format:\n```\n<gitmoji> <type>(<domain>): <title>\n\n<description>\n```\n\n### Formatting Rules:\n- **Gitmoji**: Must use one of the exactly specified emojis (see mapping below).\n- **Type**: Must be lowercase, chosen from the mapping below.\n- **Domain**: Must be enclosed in parentheses `()`. Identify the primary component or domain affected (e.g., `(nfs)`, `(open-webui)`). Use lowercase and kebab-case. \n- **Title**: A concise summary of the change in imperative mood. Must start with a lowercase letter directly after the colon and space.\n- **Description**: (Optional) Use this to explain \"why\" the change was made or provide further context.\n\n---\n\n## 2. Gitmoji & Type Mapping\nOnly use the following approved types and emojis:\n\n| Gitmoji | Type       | Description |\n| :------ | :--------- | :---------- |\n| 🔧      | `chore`    | Routine maintenance or minor corrections |\n| 🛠️      | `fix`      | Intentional functional configuration changes |\n| ✨      | `feat`     | New features |\n| ✏️      | `typo`     | Fix a typo |\n| 🐛      | `bug`      | Fix a bug |\n| ⬆️      | `dep`      | Upgrade dependencies |\n| 🔐      | `security` | Add or update secrets |\n| 🗑️      | `remove`   | Deprecate or clean up code |\n| ♻️      | `refactor` | Refactor code |\n| 📄      | `docs`     | Add or update documentation |\n| 📝      | `article`  | Add or update articles (content/workload, not project code) |\n| 🎨      | `style`    | Improve structure / format |\n| ⚡      | `perf`     | Improve performance |\n| ✅      | `test`     | Add, update, or pass tests |\n| 🔨      | `build`    | Add or update development scripts |\n\n---\n\n## 3. Workflow Requirements\n1. **Analyze changes**: Review staged and unstaged changes to understand the scope and purpose of the work.\n2. **Review history**: Search the most recent 10 commits in the `git log` to help determine the appropriate `Type` and `Domain`. After identifying a potential `Domain`, search up to 10 recent commits specifically for that domain to ensure consistency and gain context for writing the commit message.\n3. **Propose message**: Present the drafted commit message to the user in a markdown code block.\n4. **Wait for confirmation**: Ask the user if they want to proceed with the proposed commit message. Do not proceed with committing or pushing until explicit approval is given.\n5. **Commit & Push**:\n   - Only execute `git commit` after explicit user approval. Do NOT auto-commit.\n   - After committing, ask the user if they want to push to the remote repository.\n   - Only execute `git push` after receiving explicit user approval. Do NOT auto-push.\n\n---\n\n## 4. Strict Constraints\n- **Agent Autonomy**: You MUST NOT arbitrarily execute commit or push commands before the user approves. All execution must wait for explicit user consent.\n- **Language**: The commit message and any detailed explanations of changes MUST be in English only. Do NOT use Korean.\n- **Privacy & Security**: NEVER include local paths, sensitive environment variables, or other local/sensitive information in the commit messages or detailed descriptions.\n\n---\n\n## 5. Examples\n\n### Feature addition\n```\n✨ feat(n8n): add n8n application\n\nAdd n8n workflow automation application to the cluster.\n```\n\n### Intentional functional configuration change\n```\n🛠️ fix(nfs): rollback health probes and chart rename to fix distroless image compatibility\n\nRevert recent changes including health উজ্জchanges including health probes and chart renaming because the\ndistroless image lacks ''sh'' and other shell utilities required for probes.\n```\n\n### Routine maintenance\n```\n🔧 chore(helm): remove deprecated Helm chart versions and clean up configuration files\n\nRemove old chart versions and clean up unused configuration files for homer applications.\n```\n\n### Bug fix\n```\n🐛 bug(open-webui): resolve inconsistencies in git commit policy rule\n\nFix three bugs in the git commit policy rule:\n1. Translate Korean text to English to match the ''Always English'' policy\n2. Clarify gitmoji mapping conflicts\n3. Add missing types to the Type list\n```\n\n### Dependency update\n```\n⬆️ dep(open-webui): update chart to 10.2.1 from 8.10.0\n\nUpgrade open-webui Helm chart to latest version.\n```\n\n### Refactoring\n```\n♻️ refactor(nfs): rename custom Helm chart with -jyje suffix and add health probes\n\nRename Helm chart directory and add health probe configurations.\n```\n\n### Security\n```\n🔐 security(open-webui): add CORS_ALLOW_ORIGIN environment variable for enhanced security\n\nConfigure CORS settings to restrict allowed origins.\n```\n\n### Typo fix\n```\n✏️ typo(docs): fix typo in gitmoji standard reference\n\nCorrect \"gitmodi\" to \"gitmoji\" in documentation.\n```\n\n### Article (content/workload)\n```\n📝 article(blog): add new post about kubernetes best practices\n\nAdd a new blog post discussing kubernetes deployment strategies and best practices.\n```\n"},"lastSynced":"2026-03-07T12:59:29.754Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing standardized git commit message generation and repository management.","zh":"非常适合需要标准化git提交消息生成和仓库管理的开发代理。","ja":"開発エージェントが標準化されたgitコミットメッセージ生成とリポジトリ管理を必要とする場合に最適です。","ko":"표준화된 git 커밋 메시지 생성 및 저장소 관리가 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan generación de mensajes de confirmación de git estandarizados y gestión de repositorios.","fr":"Parfait pour les Agents de Développement qui ont besoin d''une génération de messages de validation git standardisés et de gestion de référentiels.","de":"Perfekt für Entwicklungssagenten, die eine standardisierte Erstellung von git-Commit-Mitteilungen und Repository-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de geração de mensagens de commit do git padronizadas e gerenciamento de repositório.","ru":"Идеально для Агентов Разработки, которым необходима стандартизированная генерация сообщений о фиксации git и управление репозиторием.","ar":"مثالي لعميل التطوير الذي يحتاج إلى توليد رسائل الالتزام المعيارية لجيت وإدارة المستودع."},"recommendation":{"en":"Empowers agents to generate informative git commit messages using a strict format with gitmoji, type, domain, and description, streamlining repository maintenance and collaboration through protocols like git and file formats like .gitignore.","zh":"赋予代理生成使用严格格式的信息丰富的git提交消息，包括gitmoji、类型、域和描述，通过像git这样的协议和.gitignore这样的文件格式来简化仓库维护和协作。","ja":"gitmoji、タイプ、ドメイン、説明を使用した厳格な形式の情報の豊富なgitコミットメッセージをエージェントが生成できるようにし、gitや.gitignoreなどのファイル形式などのプロトコルを通じてリポジトリのメンテナンスとコラボレーションを簡素化します。","ko":"에이전트가 gitmoji, 유형, 도메인 및 설명을 사용하여 엄격한 형식의 정보가 풍부한 git 커밋 메시지를 생성할 수 있도록 하여 git 및 .gitignore와 같은 파일 형식과 같은 프로토콜을 통해 저장소 유지 관리 및 협력을 간소화합니다.","es":"Habilita a los agentes a generar mensajes de confirmación de git informativos utilizando un formato estricto con gitmoji, tipo, dominio y descripción, simplificando el mantenimiento del repositorio y la colaboración a través de protocolos como git y formatos de archivo como .gitignore.","fr":"Permet aux agents de générer des messages de validation git informatifs en utilisant un format strict avec gitmoji, type, domaine et description, simplifiant la maintenance du référentiel et la collaboration via des protocoles comme git et des formats de fichiers comme .gitignore.","de":"Ermächtigt Agenten, informative git-Commit-Mitteilungen mit einem strengen Format mit gitmoji, Typ, Domäne und Beschreibung zu erstellen, wodurch die Wartung des Repositorys und die Zusammenarbeit durch Protokolle wie git und Dateiformate wie .gitignore erleichtert werden.","pt":"Habilita os agentes a gerar mensagens de commit do git informativas usando um formato estrito com gitmoji, tipo, domínio e descrição, simplificando a manutenção do repositório e a colaboração por meio de protocolos como git e formatos de arquivo como .gitignore.","ru":"Наделяет агентов возможностью генерировать информативные сообщения о фиксации git, используя строгий формат с gitmoji, типом, доменом и описанием, упрощая обслуживание репозитория и сотрудничество через протоколы, такие как git, и форматы файлов, такие как .gitignore.","ar":"يمنح الوكلاء القدرة على توليد رسائل الالتزام المعيارية لجيت باستخدام تنسيق صارم مع جت موجي، ونوع، ونطاق، ووصف، مبسطًا صيانة المستودع والتعاون من خلال بروتوكولات مثل جيت وتنسيقات الملفات مثل .gitignore."},"useCases":{"en":["Automating commit message creation","Reviewing staged changes for affected domains","Generating commit messages with standardized gitmoji"],"zh":["自动创建提交消息","审查受影响域的暂存更改","使用标准化的gitmoji生成提交消息"],"ja":["コミットメッセージの自動生成","影響を受けるドメインのステージングされた変更の確認","標準化されたgitmojiを使用したコミットメッセージの生成"],"ko":["커밋 메시지 자동 생성","영향받는 도메인의 스테이징된 변경 사항 검토","표준화된 gitmoji를 사용한 커밋 메시지 생성"],"es":["Automatización de la creación de mensajes de confirmación","Revisión de los cambios en espera para los dominios afectados","Generación de mensajes de confirmación con gitmoji estandarizados"],"fr":["Automatisation de la création de messages de validation","Révision des modifications en attente pour les domaines affectés","Génération de messages de validation avec des gitmoji standardisés"],"de":["Automatisierung der Erstellung von Commit-Mitteilungen","Überprüfung der gestaffelten Änderungen für betroffene Domänen","Erstellung von Commit-Mitteilungen mit standardisierten gitmoji"],"pt":["Automatizar a criação de mensagens de commit","Revisar alterações em estágio para domínios afetados","Gerar mensagens de commit com gitmoji padronizado"],"ru":["Автоматизировать создание сообщений о фиксации","Просматривать отложенные изменения для затронутых доменов","Генерировать сообщения о фиксации с стандартизированным gitmoji"],"ar":["آليّة إنشاء رسائل الالتزام","استعراض التغييرات المُرحّلة للمجالات المُتأثرة","توليد رسائل الالتزام باستخدام جت موجي معياري"]},"limitations":{"en":["Requires adherence to a specific commit message format","Limited to git repositories","Must use one of the exactly specified gitmoji"],"zh":["需要遵循特定的提交消息格式","仅限于git仓库","必须使用指定的gitmoji"],"ja":["特定のコミットメッセージ形式への従属が必要","gitリポジトリのみに限定","指定されたgitmojiの使用が必須"],"ko":["특정 커밋 메시지 형식에 대한 준수 필요","git 저장소에만 제한","지정된 gitmoji의 사용이 필수"],"es":["Requiere la adhesión a un formato de mensaje de confirmación específico","Limitado a repositorios git","Debe utilizar uno de los gitmoji exactamente especificados"],"fr":["Requiert l''adhésion à un format de message de validation spécifique","Limité aux référentiels git","Doit utiliser l''un des gitmoji exactement spécifiés"],"de":["Erfordert die Einhaltung eines bestimmten Commit-Mitteilungsformats","Begrenzt auf git-Repositorys","Muss genau eines der angegebenen gitmoji verwenden"],"pt":["Exige aderência a um formato de mensagem de commit específico","Limitado a repositórios git","Deve usar um dos gitmoji especificados exatamente"],"ru":["Требует соблюдения конкретного формата сообщения о фиксации","Ограничен репозиториями git","Должен использовать один из точных gitmoji"],"ar":["يتطلب اتباع تنسيق رسالة الالتزام المحدد","محدود بالمستودعات جيت","يجب استخدام واحد من جت موجي المحددة بدقة"]},"version":4},"contentHash":"6a9b6a96e875bb80cafe588bf47afdee619d37cea30f85d0983373fe4d8328db","qualityScore":36}');
