INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jyje/cluster/git-commit-helper', 'git-commit-helper', 'jyje', 'cluster', 'community', 'git-commit-helper jyje cluster community The git-commit-helper skill assists developers in creating informative git commit messages by analyzing changes and determining affected domains. It benefits developers working with git repositories. Git Commit Helper是一个帮助您优化代码提交的AI工具，通过分析更改、确定域和选择合适的提交类型 Git Commit Helperは、コードの変更を分析し、ドメインを決定し、適切なコミットタイプを選択することで、コードのコミットプロセスを最適化するAIエージェントです Git Commit Helper는 코드 제출 프로세스를 최적화하는 AI 에이전트로, 변경 사항을 분석하고 도메인을 결정하고 적절한 커밋 유형을 선택합니다 El git-commit-helper es una herramienta que te ayuda a mejorar tus commites de Git. Analiza cambios y determina dominios para commites efectivos. Le git-commit-helper est un outil qui vous aide à améliorer vos commits Git. Il analyse les modifications et détermine les domaines pour des commits efficaces. Der git-commit-helper ist ein Tool, das Ihnen hilft, Ihre Git-Commits zu verbessern. Es analysiert Änderungen und bestimmt Domänen für effektive Commits. O git-commit-helper é uma ferramenta que ajuda a analisar alterações e criar mensagens de commit personalizadas ИИ Агент git-commit-helper помогает анализировать изменения и создавать индивидуальные сообщения о фиксации مساعد التزام الجيت هو أداة تساعد في تحليل التغييرات وإنشاء رسائل التزام مخصصة how to use git-commit-helper git-commit-helper setup guide git-commit-helper alternative git-commit-helper vs git hooks git-commit-helper install what is git-commit-helper git-commit-helper for AI agents automating git commit messages gitmoji for commit messages Git Commit Helper AI工具 代码提交 git命令行工具 kebab-case lowercase Gitmoji Analyzes staged and unstaged changes to understand the scope of work Determines the primary component or domain affected using lowercase and kebab-case Selects the appropriate type and its corresponding gitmoji for commit messages Supports git commit message generation based on analyzed changes Utilizes a table to map types to their corresponding gitmoji Searches git log to ensure consistent commit messaging git-commit-helper is a skill that automates the process of creating git commit messages by reviewing staged and unstaged changes, identifying primary components, and selecting appropriate types with corresponding gitmoji.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LeastBit/Claude_skills_zh-CN/pdf', 'community', 'LeastBit', 'Claude_skills_zh-CN', 'LeastBit/Claude_skills_zh-CN', 'pdf', 0, 0, 36, '2026-03-06T12:59:22.129Z', '2026-03-06T13:13:03.023Z', 'f3b58911fee0703d516c6c91b2246bc71dcb0f35dd9e7c7fa47815868d337f3a', '{"id":"LeastBit/Claude_skills_zh-CN/pdf","name":"pdf","description":{"en":"The PDF skill enables developers to perform basic PDF operations using Python libraries. It benefits developers working with PDF files.","zh":"本指南涵盖使用 Python 库和命令行工具进行的基本 PDF 处理操作","ja":"このガイドでは、Python ライブラリとコマンドラインツールを使用して基本的な PDF 処理操作を実行する方法について説明します","ko":"이 가이드는 Python 라이브러리와 명령줄 도구를 사용하여 기본적인 PDF 처리 작업을 수행하는 방법에 대해 설명합니다","es":"Procesamiento de PDF con Python. Guía para mergear, extraer texto y realizar operaciones básicas con pypdf","fr":"Traitement de PDF avec Python. Guide pour merger, extraire du texte et effectuer des opérations de base avec pypdf","de":"PDF-Verarbeitung mit Python. Anleitung zum Zusammenführen, Extrahieren von Text und Durchführen von grundlegenden Operationen mit pypdf","pt":"Este guia aborda operações básicas de processamento de PDF com Python. Aprenda a ler, escrever e manipular arquivos PDF com a biblioteca pypdf.","ru":"Это руководство охватывает основные операции обработки PDF с помощью Python. Узнайте, как читать, записывать и манипулировать файлами PDF с помощью библиотеки pypdf.","ar":"يهدف هذا الدليل إلى عمليات أساسية لمعالجة ملفات PDF باستخدام Python. تعلم كيف تقرأ وتكتب وتحول ملفات PDF باستخدام مكتبة pypdf."},"seo":{"title":{"en":"PDF: Python Library Setup Guide | AI Agent Skill","zh":"PDF 处理指南：Python 库和命令行工具","ja":"PDF 処理ガイド：Python ライブラリとコマンドラインツール","ko":"PDF 처리 가이드: Python 라이브러리와 명령줄 도구","es":"Guía de configuración de PDF con Python","fr":"Guide de mise en route de PDF avec Python","de":"PDF-Setup-Anleitung mit Python","pt":"Guia de Configuração de PDF com Python","ru":"Руководство по настройке PDF с помощью Python и ИИ Агентов","ar":"دليل إعداد ملفات PDF باستخدام Python وأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock PDF processing capabilities with Python libraries like pypdf. Learn how to merge, extract text, and more with our expert guide.","zh":"使用 Python 库和命令行工具进行 PDF 处理操作，包括合并、提取文本和填写表单","ja":"Python ライブラリとコマンドラインツールを使用して PDF 処理操作を実行します。マージ、テキスト抽出、フォーム入力を含みます","ko":"Python 라이브러리와 명령줄 도구를 사용하여 PDF 처리 작업을 수행합니다. 합치기, 텍스트 추출, 양식填写 포함","es":"Aprende a procesar PDF con Python y herramientas de línea de comandos. Descubre cómo mergear, extraer texto y más","fr":"Apprenez à traiter les PDF avec Python et les outils de ligne de commande. Découvrez comment merger, extraire du texte et plus","de":"Erfahren Sie, wie Sie PDF mit Python und Befehlszeilen-Tools verarbeiten. Entdecken Sie, wie Sie zusammenführen, Text extrahieren und mehr","pt":"Aprenda a processar e manipular arquivos PDF com Python e bibliotecas como pypdf. Veja exemplos de código e dicas para começar.","ru":"Узнайте, как обрабатывать и манипулировать файлами PDF с помощью Python и библиотеки pypdf. Посмотрите примеры кода и советы для начала.","ar":"تعرف على كيفية معالجة وتحويل ملفات PDF باستخدام Python ومكتبات مثل pypdf. شاهد أمثلة من الكود والنصائح للبدء."},"definition":{"en":"pdf is a file format processed using libraries like pypdf, allowing for operations such as merging and text extraction.","zh":"PDF 处理是指使用软件和工具对 PDF 文档进行操作和处理","ja":"PDF 処理とは、ソフトウェアとツールを使用して PDF ドキュメントを操作および処理すること","ko":"PDF 처리는 PDF 문서를 처리하고操作하는 소프트웨어 및 도구를 사용하는 것을 의미합니다","es":"El procesamiento de PDF es la capacidad de leer, escribir y manipular archivos PDF utilizando bibliotecas como pypdf","fr":"Le traitement de PDF est la capacité de lire, d''écrire et de manipuler des fichiers PDF à l''aide de bibliothèques comme pypdf","de":"Die PDF-Verarbeitung ist die Fähigkeit, PDF-Dateien zu lesen, zu schreiben und mit Bibliotheken wie pypdf zu manipulieren","pt":"O processamento de PDF refere-se à manipulação de arquivos PDF usando bibliotecas como pypdf para realizar operações como leitura e escrita.","ru":"Обработка PDF означает манипулирование файлами PDF с помощью библиотек, таких как pypdf, для выполнения операций, таких как чтение и запись.","ar":"معالجة ملفات PDF تعني التعامل مع ملفات PDF باستخدام مكتبات مثل pypdf لتنفيذ عمليات مثل القراءة والكتابة."},"features":{"en":["Merges PDF files using pypdf''s PdfWriter and PdfReader","Extracts text from PDF pages with page.extract_text()","Supports basic PDF operations like reading and writing","Uses Python libraries for efficient PDF processing","Enables filling of PDF forms with related libraries"],"zh":["使用 pypdf 库进行 PDF 合并","提取 PDF 文本","使用命令行工具进行 PDF 处理","填写 PDF 表单","使用 Python 脚本进行 PDF 自动化"],"ja":["pypdf ライブラリを使用した PDF マージ","PDF テキストの抽出","コマンドラインツールを使用した PDF 処理","PDF フォームの入力","Python スクリプトを使用した PDF 自動化"],"ko":["pypdf 라이브러리를 사용한 PDF 합치기","PDF 텍스트 추출","명령줄 도구를 사용한 PDF 처리","PDF 양식填写","Python 스크립트를 사용한 PDF 자동화"],"es":["Mergear PDF con pypdf","Extraer texto de PDF con Python","Realizar operaciones básicas con pypdf","Utilizar la biblioteca pypdf para leer y escribir PDF","Procesar PDF con herramientas de línea de comandos"],"fr":["Merger des PDF avec pypdf","Extraire du texte de PDF avec Python","Effectuer des opérations de base avec pypdf","Utiliser la bibliothèque pypdf pour lire et écrire des PDF","Traiter des PDF avec des outils de ligne de commande"],"de":["PDF zusammenführen mit pypdf","Text aus PDF extrahieren mit Python","Grundlegende Operationen mit pypdf durchführen","Die Bibliothek pypdf zum Lesen und Schreiben von PDF verwenden","PDF mit Befehlszeilen-Tools verarbeiten"],"pt":["Leitura de arquivos PDF com pypdf","Escrita de arquivos PDF com pypdf","Extração de texto de arquivos PDF","Merge de arquivos PDF","Uso de Python para automação de tarefas de PDF"],"ru":["Чтение файлов PDF с помощью pypdf","Запись файлов PDF с помощью pypdf","Извлечение текста из файлов PDF","Объединение файлов PDF","Использование Python для автоматизации задач PDF"],"ar":["قراءة ملفات PDF باستخدام pypdf","كتابة ملفات PDF باستخدام pypdf","استخراج النص من ملفات PDF","دمج ملفات PDF","استخدام Python لتحسين مهام ملفات PDF"]},"keywords":{"en":["how to use pypdf","pdf processing with python","pdf vs docx","install pypdf library","pdf setup guide for developers","what is pdf file format"],"zh":["PDF 处理","Python PDF 库","命令行 PDF 工具","PDF 合并","PDF 文本提取","PDF 表单填写","pypdf","PDF 自动化"],"ja":["PDF 処理","Python PDF ライブラリ","コマンドライン PDF ツール","PDF マージ","PDF テキスト抽出","PDF フォーム入力","pypdf","PDF 自動化"],"ko":["PDF 처리","Python PDF 라이브러리","명령줄 PDF 도구","PDF 합치기","PDF 텍스트 추출","PDF 양식填写","pypdf","PDF 자동화"],"es":["procesamiento de pdf","python pdf","pypdf","mergear pdf","extraer texto de pdf","herramientas de línea de comandos para pdf","bibliotecas de python para pdf","pdf con python"],"fr":["traitement de pdf","python pdf","pypdf","merger des pdf","extraire du texte de pdf","outils de ligne de commande pour pdf","bibliothèques python pour pdf","pdf avec python"],"de":["pdf-verarbeitung","python pdf","pypdf","pdf zusammenführen","text aus pdf extrahieren","befehlszeilen-tools für pdf","python-bibliotheken für pdf","pdf mit python"],"pt":["processamento de pdf","pypdf","python pdf","leitura de pdf","escrita de pdf","extração de texto de pdf","merge de pdf","automação de tarefas de pdf"],"ru":["обработка pdf","pypdf","python pdf","чтение pdf","запись pdf","извлечение текста из pdf","объединение pdf","автоматизация задач pdf","ИИ Агенты для PDF"],"ar":["معالجة ملفات pdf","pypdf","python pdf","قراءة ملفات pdf","كتابة ملفات pdf","استخراج النص من ملفات pdf","دمج ملفات pdf","تحسين مهام ملفات pdf","أدوات الذكاء الاصطناعي لملفات PDF"]}},"owner":"LeastBit","repo":"Claude_skills_zh-CN","repoPath":"LeastBit/Claude_skills_zh-CN","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.129Z","topics":[],"category":"community","skillMd":{"name":"pdf","description":"全面的 PDF 操作工具包，用于提取文本和表格、创建新 PDF、合并/拆分文档以及处理表单。当 Claude 需要填写 PDF 表单或以编程方式大规模处理、生成或分析 PDF 文档时使用。","bodyPreview":"# PDF 处理指南\n\n## 概述\n\n本指南涵盖使用 Python 库和命令行工具进行的基本 PDF 处理操作。有关高级功能、JavaScript 库和详细示例，请参阅 reference.md。如果需要填写 PDF 表单，请阅读 forms.md 并按照其说明操作。\n\n## 快速开始\n\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# 读取 PDF\nreader = PdfReader(\"document.pdf\")\nprint(f\"页数: {len(reader.pages)}\")\n\n# 提取文本\ntext = \"\"\nfor page in reader.pages:\n    text += page.extract_text()\n```\n\n## Python 库\n\n### pypdf - 基本操作\n\n#### 合并 PDF\n```python\nfrom pypdf import PdfWriter, PdfReader\n\nwriter = PdfWriter()\nfor pdf_file in [\"doc1.pdf\", \"do","body":"# PDF 处理指南\n\n## 概述\n\n本指南涵盖使用 Python 库和命令行工具进行的基本 PDF 处理操作。有关高级功能、JavaScript 库和详细示例，请参阅 reference.md。如果需要填写 PDF 表单，请阅读 forms.md 并按照其说明操作。\n\n## 快速开始\n\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# 读取 PDF\nreader = PdfReader(\"document.pdf\")\nprint(f\"页数: {len(reader.pages)}\")\n\n# 提取文本\ntext = \"\"\nfor page in reader.pages:\n    text += page.extract_text()\n```\n\n## Python 库\n\n### pypdf - 基本操作\n\n#### 合并 PDF\n```python\nfrom pypdf import PdfWriter, PdfReader\n\nwriter = PdfWriter()\nfor pdf_file in [\"doc1.pdf\", \"doc2.pdf\", \"doc3.pdf\"]:\n    reader = PdfReader(pdf_file)\n    for page in reader.pages:\n        writer.add_page(page)\n\nwith open(\"merged.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n#### 拆分 PDF\n```python\nreader = PdfReader(\"input.pdf\")\nfor i, page in enumerate(reader.pages):\n    writer = PdfWriter()\n    writer.add_page(page)\n    with open(f\"page_{i+1}.pdf\", \"wb\") as output:\n        writer.write(output)\n```\n\n#### 提取元数据\n```python\nreader = PdfReader(\"document.pdf\")\nmeta = reader.metadata\nprint(f\"标题: {meta.title}\")\nprint(f\"作者: {meta.author}\")\nprint(f\"主题: {meta.subject}\")\nprint(f\"创建者: {meta.creator}\")\n```\n\n#### 旋转页面\n```python\nreader = PdfReader(\"input.pdf\")\nwriter = PdfWriter()\n\npage = reader.pages[0]\npage.rotate(90)  # 顺时针旋转90度\nwriter.add_page(page)\n\nwith open(\"rotated.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n### pdfplumber - 文本和表格提取\n\n#### 提取带布局的文本\n```python\nimport pdfplumber\n\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    for page in pdf.pages:\n        text = page.extract_text()\n        print(text)\n```\n\n#### 提取表格\n```python\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    for i, page in enumerate(pdf.pages):\n        tables = page.extract_tables()\n        for j, table in enumerate(tables):\n            print(f\"第 {i+1} 页的表格 {j+1}:\")\n            for row in table:\n                print(row)\n```\n\n#### 高级表格提取\n```python\nimport pandas as pd\n\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    all_tables = []\n    for page in pdf.pages:\n        tables = page.extract_tables()\n        for table in tables:\n            if table:  # 检查表格是否为空\n                df = pd.DataFrame(table[1:], columns=table[0])\n                all_tables.append(df)\n\n# 合并所有表格\nif all_tables:\n    combined_df = pd.concat(all_tables, ignore_index=True)\n    combined_df.to_excel(\"extracted_tables.xlsx\", index=False)\n```\n\n### reportlab - 创建 PDF\n\n#### 基本 PDF 创建\n```python\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.pdfgen import canvas\n\nc = canvas.Canvas(\"hello.pdf\", pagesize=letter)\nwidth, height = letter\n\n# 添加文本\nc.drawString(100, height - 100, \"Hello World!\")\nc.drawString(100, height - 120, \"这是用 reportlab 创建的 PDF\")\n\n# 添加线条\nc.line(100, height - 140, 400, height - 140)\n\n# 保存\nc.save()\n```\n\n#### 创建多页 PDF\n```python\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak\nfrom reportlab.lib.styles import getSampleStyleSheet\n\ndoc = SimpleDocTemplate(\"report.pdf\", pagesize=letter)\nstyles = getSampleStyleSheet()\nstory = []\n\n# 添加内容\ntitle = Paragraph(\"报告标题\", styles[''Title''])\nstory.append(title)\nstory.append(Spacer(1, 12))\n\nbody = Paragraph(\"这是报告的正文内容。\" * 20, styles[''Normal''])\nstory.append(body)\nstory.append(PageBreak())\n\n# 第2页\nstory.append(Paragraph(\"第2页\", styles[''Heading1'']))\nstory.append(Paragraph(\"第2页的内容\", styles[''Normal'']))\n\n# 构建 PDF\ndoc.build(story)\n```\n\n## 命令行工具\n\n### pdftotext (poppler-utils)\n```bash\n# 提取文本\npdftotext input.pdf output.txt\n\n# 提取文本并保留布局\npdftotext -layout input.pdf output.txt\n\n# 提取指定页面\npdftotext -f 1 -l 5 input.pdf output.txt  # 第1-5页\n```\n\n### qpdf\n```bash\n# 合并 PDF\nqpdf --empty --pages file1.pdf file2.pdf -- merged.pdf\n\n# 拆分页面\nqpdf input.pdf --pages . 1-5 -- pages1-5.pdf\nqpdf input.pdf --pages . 6-10 -- pages6-10.pdf\n\n# 旋转页面\nqpdf input.pdf output.pdf --rotate=+90:1  # 将第1页旋转90度\n\n# 移除密码\nqpdf --password=mypassword --decrypt encrypted.pdf decrypted.pdf\n```\n\n### pdftk（如果可用）\n```bash\n# 合并\npdftk file1.pdf file2.pdf cat output merged.pdf\n\n# 拆分\npdftk input.pdf burst\n\n# 旋转\npdftk input.pdf rotate 1east output rotated.pdf\n```\n\n## 常见任务\n\n### 从扫描的 PDF 提取文本\n```python\n# 需要安装: pip install pytesseract pdf2image\nimport pytesseract\nfrom pdf2image import convert_from_path\n\n# 将 PDF 转换为图像\nimages = convert_from_path(''scanned.pdf'')\n\n# 对每一页进行 OCR 识别\ntext = \"\"\nfor i, image in enumerate(images):\n    text += f\"第 {i+1} 页:\\n\"\n    text += pytesseract.image_to_string(image)\n    text += \"\\n\\n\"\n\nprint(text)\n```\n\n### 添加水印\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# 创建水印（或加载现有的）\nwatermark = PdfReader(\"watermark.pdf\").pages[0]\n\n# 应用到所有页面\nreader = PdfReader(\"document.pdf\")\nwriter = PdfWriter()\n\nfor page in reader.pages:\n    page.merge_page(watermark)\n    writer.add_page(page)\n\nwith open(\"watermarked.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n### 提取图像\n```bash\n# 使用 pdfimages (poppler-utils)\npdfimages -j input.pdf output_prefix\n\n# 这会将所有图像提取为 output_prefix-000.jpg、output_prefix-001.jpg 等\n```\n\n### 密码保护\n```python\nfrom pypdf import PdfReader, PdfWriter\n\nreader = PdfReader(\"input.pdf\")\nwriter = PdfWriter()\n\nfor page in reader.pages:\n    writer.add_page(page)\n\n# 添加密码\nwriter.encrypt(\"userpassword\", \"ownerpassword\")\n\nwith open(\"encrypted.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n## 快速参考\n\n| 任务 | 最佳工具 | 命令/代码 |\n|------|-----------|--------------|\n| 合并 PDF | pypdf | `writer.add_page(page)` |\n| 拆分 PDF | pypdf | 每页一个文件 |\n| 提取文本 | pdfplumber | `page.extract_text()` |\n| 提取表格 | pdfplumber | `page.extract_tables()` |\n| 创建 PDF | reportlab | Canvas 或 Platypus |\n| 命令行合并 | qpdf | `qpdf --empty --pages ...` |\n| OCR 扫描 PDF | pytesseract | 先转换为图像 |\n| 填写 PDF 表单 | pdf-lib 或 pypdf（参见 forms.md） | 参见 forms.md |\n\n## 后续步骤\n\n- 有关 pypdfium2 的高级用法，请参阅 reference.md\n- 有关 JavaScript 库（pdf-lib），请参阅 reference.md\n- 如果需要填写 PDF 表单，请按照 forms.md 中的说明操作\n- 有关故障排除指南，请参阅 reference.md\n"},"lastSynced":"2026-03-06T13:13:03.023Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing advanced PDF processing capabilities.","zh":"适合需要高级PDF处理能力的文档分析代理。","ja":"高度なPDF処理能力を必要とする文書分析エージェントに適しています。","ko":"고급 PDF 처리 기능이 필요한 문서 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades de procesamiento de PDF avanzadas.","fr":"Parfait pour les agents d''analyse de documents nécessitant des capacités de traitement de PDF avancées.","de":"Perfekt für Dokumentenanalyse-Agents, die erweiterte PDF-Verarbeitungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de capacidades avançadas de processamento de PDF.","ru":"Идеально подходит для агентов анализа документов, которым необходимы расширенные возможности обработки PDF.","ar":"مثالي لعمليات وكيل تحليل المستندات التي تحتاج إلى إمكانيات متقدمة لمعالجة PDF."},"recommendation":{"en":"Empowers agents to perform basic PDF operations such as reading, writing, and merging PDF files using Python libraries like pypdf, enabling efficient document processing and analysis.","zh":"使代理能够使用Python库（如pypdf）执行基本的PDF操作，例如读取、写入和合并PDF文件，从而实现高效的文档处理和分析。","ja":"エージェントがPythonライブラリ（例：pypdf）を使用して基本的なPDF操作（PDFファイルの読み取り、書き込み、結合など）を実行できるようにし、効率的な文書処理と分析を可能にします。","ko":"에이전트가 Python 라이브러리(pypdf 등)를 사용하여 기본적인 PDF 연산(예: PDF 파일 읽기, 쓰기, 병합)을 수행할 수 있도록 하여 효율적인 문서 처리 및 분석을 가능하게 합니다.","es":"Habilita a los agentes a realizar operaciones de PDF básicas como leer, escribir y fusionar archivos de PDF utilizando bibliotecas de Python como pypdf, lo que permite un procesamiento y análisis de documentos eficientes.","fr":"Permet aux agents d''effectuer des opérations de base de PDF telles que la lecture, l''écriture et la fusion de fichiers de PDF à l''aide de bibliothèques Python comme pypdf, permettant ainsi un traitement et une analyse de documents efficaces.","de":"Ermöglicht es Agenten, grundlegende PDF-Operationen wie Lesen, Schreiben und Zusammenfügen von PDF-Dateien mithilfe von Python-Bibliotheken wie pypdf durchzuführen, was einen effizienten Dokumentenprozess und -analyse ermöglicht.","pt":"Habilita os agentes a realizar operações PDF básicas, como leitura, escrita e mesclagem de arquivos PDF usando bibliotecas Python como pypdf, permitindo processamento e análise de documentos eficientes.","ru":"Наделяет агентов возможностью выполнять базовые операции с PDF, такие как чтение, запись и слияние файлов PDF, используя библиотеки Python, такие как pypdf, что обеспечивает эффективную обработку и анализ документов.","ar":"تمكين الوكلاء من أداء عمليات PDF الأساسية مثل قراءة وكتابة ودمج ملفات PDF باستخدام مكتبات Python مثل pypdf، مما يسمح بمعالجة وافية وفعالة للوثائق."},"useCases":{"en":["Extracting text from PDF documents","Merging multiple PDF files into a single document","Automating PDF form filling"],"zh":["从PDF文档中提取文本","合并多个PDF文件到单个文档","自动化PDF表单填充"],"ja":["PDF文書からテキストを抽出する","複数のPDFファイルを1つの文書に結合する","PDFフォームの自動入力を実行する"],"ko":["PDF 문서에서 텍스트 추출","여러 개의 PDF 파일을 하나의 문서로 병합","PDF 양식 자동 채우기"],"es":["Extraer texto de documentos de PDF","Combinar varios archivos de PDF en un solo documento","Automatizar el llenado de formularios de PDF"],"fr":["Extraire du texte de documents de PDF","Combiner plusieurs fichiers de PDF en un seul document","Automatiser le remplissage de formulaires de PDF"],"de":["Text aus PDF-Dokumenten extrahieren","Mehrere PDF-Dateien zu einem einzigen Dokument zusammenfügen","Automatisierung des Ausfüllens von PDF-Formularen"],"pt":["Extração de texto de documentos PDF","Mesclagem de vários arquivos PDF em um único documento","Automação de preenchimento de formulários PDF"],"ru":["Извлечение текста из документов PDF","Объединение нескольких файлов PDF в один документ","Автоматизация заполнения форм PDF"],"ar":["استخراج النص من مستندات PDF","دمج ملفات PDF متعددة في مستند واحد","أتمتة ملء استمارات PDF"]},"limitations":{"en":["Requires Python environment","Limited to basic PDF operations","Dependent on pypdf library"],"zh":["需要Python环境","仅限基本PDF操作","依赖于pypdf库"],"ja":["Python環境が必要","基本的なPDF操作のみ","pypdfライブラリに依存"],"ko":["Python 환경 필요","기본 PDF 연산만 가능","pypdf 라이브러리에 의존"],"es":["Requiere entorno de Python","Limitado a operaciones de PDF básicas","Dependiente de la biblioteca pypdf"],"fr":["Nécessite un environnement Python","Limité aux opérations de base de PDF","Dépendant de la bibliothèque pypdf"],"de":["Benötigt Python-Umgebung","Begrenzt auf grundlegende PDF-Operationen","Abhängig von der pypdf-Bibliothek"],"pt":["Requer ambiente Python","Limitado a operações PDF básicas","Dependente da biblioteca pypdf"],"ru":["Требуется среда Python","Ограничен базовыми операциями с PDF","Зависит от библиотеки pypdf"],"ar":["يتطلب بيئة Python","محدود بالعمليات الأساسية لملفات PDF","يعتمد على مكتبة pypdf"]},"version":4},"contentHash":"f3b58911fee0703d516c6c91b2246bc71dcb0f35dd9e7c7fa47815868d337f3a","qualityScore":36}');
