INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-gemini/gemini-cli/pr-creator', 'pr-creator', 'google-gemini', 'gemini-cli', 'community', 'pr-creator google-gemini gemini-cli community pr-creator是一个开源的AI智能工具，直接将Gemini集成到您的终端，提供更高效的开发体验 pr-creatorはオープンソースのAIエージェントで、Geminiをターミナルに直接導入し、開発者に更なる効率的な開発体験を提供する pr-creator는 오픈소스의 AI 에이전트로서 Gemini를 터미널에 직접 통합하여 개발자에게 더욱 효율적인 개발 경험을 제공한다 Pr-creator es un agente AI de código abierto que trae la potencia de Gemini directamente a tu terminal, mejorando tu flujo de trabajo Pr-creator est un agent IA open-source qui apporte la puissance de Gemini directement dans votre terminal, améliorant votre flux de travail Pr-creator ist ein Open-Source-AI-Agent, der die Leistung von Gemini direkt in Ihr Terminal bringt, Ihren Arbeitsablauf verbessert O pr-creator é um agente de IA de código aberto que integra o Gemini no seu terminal, permitindo uma experiência de desenvolvimento mais eficiente ИИ Агент pr-creator - это открытый агент, который интегрирует Gemini в ваш терминал, обеспечивая более эффективный опыт разработки أداة pr-creator هي أداة ذكاء اصطناعي مفتوحة المصدر تعمل على دمج Gemini في جهازك، مما يتيح لك تجربة تطوير أكثر كفاءة An open-source AI agent that brings the power of Gemini directly into your terminal. 如何使用pr-creator 什么是AI智能工具 pr-creator替代品 pr-creator vs 其他AI工具 pr-creator安装 pr-creator设置指南 AI智能工具开发 终端集成开发 An open-source AI agent that brings the power of Gemini directly into your terminal.');
