INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lobehub/lobehub/hotkey', 'hotkey', 'lobehub', 'lobehub', 'community', 'hotkey lobehub lobehub community Hotkey 是一个用于查找、构建和协作的 AI智能工具，支持多智能体协作和设计。它提供了一种新的工作和生活方式 Hotkeyは、AIエージェントの検索、構築、コラボレーションをサポートするプラットフォームです。新しいワークスタイルを提供します Hotkey는 검색, 구축 및 협력을 위한 AI 에이전트 플랫폼입니다. 새로운 작업 방식을 제공합니다 hotkey es el espacio perfecto para encontrar, construir y colaborar con agentes que crecen contigo, mejorando la colaboración y el diseño de equipos de agentes. hotkey est l''espace idéal pour trouver, construire et collaborer avec des agents qui grandissent avec vous, améliorant la collaboration et la conception d''équipes d''agents. hotkey ist der perfekte Raum, um Agenten zu finden, zu bauen und mit ihnen zusammenzuarbeiten, die mit Ihnen wachsen, und dabei die Zusammenarbeit und das Design von Agententeams zu verbessern. O hotkey é uma plataforma de colaboração de agentes de IA que permite encontrar, construir e trabalhar em equipe com agentes que crescem com você hotkey - это платформа для сотрудничества ИИ Агентов, которая позволяет найти, создать и работать в команде с агентами, которые растут с вами hotkey هو منصة للتعاون بين وكلاء الذكاء الاصطناعي التي تمكنك من العثور على وكلاء، بناءهم والعمل معهم كفريق The ultimate space for work and life — to find, build, and collaborate with agent teammates that grow with you. We are taking agent harness to the next level — enabling multi-agent collaboration, effortless agent team design, and introducing agents as the unit of work interaction. Hotkey是什么 AI智能工具 多智能体协作 智能体团队设计 Hotkey安装 Hotkey教程 AI工具比较 Hotkey vs 其他AI工具 The ultimate space for work and life — to find, build, and collaborate with agent teammates that grow with you. We are taking agent harness to the next level — enabling multi-agent collaboration, effortless agent team design, and introducing agents as the unit of work interaction.');
