INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('diegoknsk/video-processing-engine-auth-lambda/performance-optimization', 'performance-optimization', 'diegoknsk', 'video-processing-engine-auth-lambda', 'community', 'performance-optimization diegoknsk video-processing-engine-auth-lambda community 该AI智能工具利用AWS Lambda和Amazon Cognito实现性能优化和身份验证，为Hackathon FIAP Pós Tech提供安全的API访问控制 このAIエージェントは、AWS LambdaとAmazon Cognitoを使用してパフォーマンス最適化と認証を実現し、Hackathon FIAP Pós TechのAPIへの安全なアクセス制御を提供する 이 AI 에이전트는 AWS Lambda와 Amazon Cognito를 사용하여 성능 최적화와 인증을 구현하며, Hackathon FIAP Pós Tech의 API에 대한 안전한 액세스 제어를 제공합니다 Nuestra herramienta de optimización de rendimiento utiliza AWS Lambda para mejorar la eficiencia de las aplicaciones, integrada con Amazon Cognito para un control de acceso seguro Notre outil d''optimisation de performance utilise AWS Lambda pour améliorer l''efficacité des applications, intégré à Amazon Cognito pour un contrôle d''accès sécurisé Unsere Leistungsoptimierungsfunktion nutzt AWS Lambda, um die Effizienz von Anwendungen zu verbessern, integriert mit Amazon Cognito für einen sicheren Zugriff A ferramenta de performance-optimization é uma solução de otimização de desempenho para sistemas de processamento de vídeos, integrada ao Amazon Cognito e API Gateway. ИИ Агент performance-optimization - это решение для оптимизации производительности систем обработки видео, интегрированное с Amazon Cognito и API Gateway. أداة الإي الأجنت performance-optimization هي حل لتحسين الأداء لأنظمة معالجة الفيديو، متكاملة مع Amazon Cognito و API Gateway. AWS Lambda responsável pela autenticação do sistema de processamento de vídeos, integrada ao Amazon Cognito e utilizada pelo API Gateway para controle de acesso às APIs do Hackathon FIAP Pós Tech em Arquitetura de Software. AI智能工具 性能优化 AWS Lambda Amazon Cognito API Gateway 如何使用AI智能工具 什么是性能优化 AI智能工具的优点 AWS Lambda responsável pela autenticação do sistema de processamento de vídeos, integrada ao Amazon Cognito e utilizada pelo API Gateway para controle de acesso às APIs do Hackathon FIAP Pós Tech em Arquitetura de Software.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sendo-kakeru/family-photo/code-review', 'community', 'sendo-kakeru', 'family-photo', 'sendo-kakeru/family-photo', 'code-review', 0, 0, 36, '2026-03-06T12:59:22.171Z', '2026-03-06T13:23:58.014Z', 'ad6b0650b5b9c97d863104bc8190e14b6218c22d290fa42231be7e81c29f7055', '{"id":"sendo-kakeru/family-photo/code-review","name":"code-review","description":{"en":"The code-review skill automates the review process for local branches and GitHub PRs, detecting quality and consistency issues. It benefits developers by ensuring high-quality code.","zh":"代码审查工具帮助开发者审查代码，检测潜在问题，并确保代码的一致性","ja":"コードレビューツールは開発者がコードをレビューし、潜在的な問題を検出し、コードの一貫性を確保するのに役立ちます","ko":"코드 리뷰 도구는 개발자가 코드를 검토하고 잠재적인 문제를 감지하며 코드 일관성을 보장하는 데 도움이 됩니다","es":"La revisión de código es un proceso que ayuda a detectar problemas y mejorar la calidad del código. Utiliza herramientas como AskUserQuestion para revisar cambios en GitHub PR o ramas locales","fr":"La revue de code est un processus qui aide à détecter les problèmes et améliorer la qualité du code. Utilisez des outils comme AskUserQuestion pour réviser les modifications dans GitHub PR ou les branches locales","de":"Die Code-Überprüfung ist ein Prozess, der dabei hilft, Probleme zu erkennen und die Qualität des Codes zu verbessern. Verwenden Sie Tools wie AskUserQuestion, um Änderungen in GitHub PR oder lokalen Branches zu überprüfen","pt":"O code review é uma ferramenta que ajuda a melhorar a qualidade do código, detectando problemas potenciais e garantindo a consistência do código.","ru":"Код-ревью - это инструмент, который помогает улучшить качество кода, обнаруживая потенциальные проблемы и гарантируя согласованность кода.","ar":"المراجعة اللغوية هي أداة تساعد على تحسين جودة الكود، واكتشاف المشاكل المحتملة، وضمان الاتساق في الكود."},"seo":{"title":{"en":"Code-Review: Automated Review Setup Guide | AI Agent Skill","zh":"代码审查工具Setup Guide","ja":"コードレビューツールのベストプラクティス","ko":"코드 리뷰 도구 설정 가이드","es":"Guía de configuración de revisión de código para desarrol...","fr":"Guide de configuration de la revue de code pour les dével...","de":"Einrichtungsleitfaden für Code-Review für Entwickler","pt":"Guia de Configuração de Code Review para Desenvolvedores","ru":"Настройка код-ревью: ИИ Агенты для разработчиков","ar":"دليل thiết lập المراجعة اللغوية للبرمجة"},"description":{"en":"Streamline your code review process with this AI agent skill, featuring automated review setup and GitHub PR integration - learn how to get started today!","zh":"使用代码审查工具提高代码质量，检测潜在问题，并确保代码的一致性","ja":"コードレビューツールを使用してコードの品質を向上させ、潜在的な問題を検出し、コードの一貫性を確保する","ko":"코드 리뷰 도구를 사용하여 코드 품질을 향상시키고 잠재적인 문제를 감지하며 코드 일관성을 보장합니다","es":"Aprende a configurar y utilizar la herramienta de revisión de código para mejorar la calidad y consistencia de tu código","fr":"Découvrez comment configurer et utiliser l''outil de revue de code pour améliorer la qualité et la cohérence de votre code","de":"Erfahren Sie, wie Sie das Code-Review-Tool konfigurieren und verwenden, um die Qualität und Konsistenz Ihres Codes zu verbessern","pt":"Aprenda a configurar o code review para melhorar a qualidade do código e detectar problemas potenciais com nossa ferramenta de code review","ru":"Узнайте, как настроить код-ревью для улучшения качества кода и обнаружения потенциальных проблем с помощью ИИ Агентов","ar":"تعلم كيفية ضبط المراجعة اللغوية لتحسين جودة الكود واكتشاف المشاكل المحتملة مع أداة المراجعة اللغوية"},"definition":{"en":"Code-review is a systematic examination of code changes to detect quality, consistency, and potential issues, using tools like AskUserQuestion and GitHub PR integration.","zh":"代码审查工具是一种用于审查代码、检测潜在问题和确保代码一致性的AIエージェント","ja":"コードレビューツールは、コードをレビューし、潜在的な問題を検出し、コードの一貫性を確保するためのAIエージェントです","ko":"코드 리뷰 도구는 코드를 검토하고 잠재적인 문제를 감지하며 코드 일관성을 보장하는 인공지능 에이전트입니다","es":"La revisión de código es un proceso de verificación de la calidad y consistencia del código","fr":"La revue de code est un processus de vérification de la qualité et de la cohérence du code","de":"Die Code-Überprüfung ist ein Prozess der Überprüfung der Qualität und Konsistenz des Codes","pt":"Code review é o processo de revisar e avaliar o código para garantir a qualidade e a consistência.","ru":"Код-ревью - это процесс проверки и оценки кода для обеспечения качества и согласованности.","ar":"المراجعة اللغوية هي عملية مراجعة وتقييم الكود لضمان الجودة والاتساق."},"features":{"en":["Reviews local branches and GitHub PRs for quality and consistency issues","Utilizes AskUserQuestion tool for interview-style review condition setup","Supports review of local diffs, staged local diffs, and GitHub PR diffs","Executes reviews using appropriate sub-agents for efficient code analysis","Provides options for reviewing specific types of code changes, such as local branches and GitHub PRs"],"zh":["支持审查GitHub PR的差分","支持审查本地代码的差分","支持审查已暂存的本地代码的差分","使用AskUserQuestion工具进行审查条件的询问","支持多种审查选项，包括本地分支、GitHub PR和本地差分"],"ja":["GitHub PRの差分をレビューする機能","ローカルコードの差分をレビューする機能","ステージ済みのローカルコードの差分をレビューする機能","AskUserQuestionツールを使ったレビュー条件のインタビュー","複数のレビュー 옵션をサポートする機能"],"ko":["GitHub PR의 차이를 검토하는 기능","로컬 코드의 차이를 검토하는 기능","暂存된 로컬 코드의 차이를 검토하는 기능","AskUserQuestion 도구를 사용한 검토 조건 인터뷰","여러 가지 검토 옵션을 지원하는 기능"],"es":["Revisión de cambios en GitHub PR","Revisión de ramas locales","Uso de AskUserQuestion para revisar condiciones","Detección de problemas y mejora de la calidad del código","Soporte para revisar diferencias entre ramas"],"fr":["Révision des modifications dans GitHub PR","Révision des branches locales","Utilisation d''AskUserQuestion pour réviser les conditions","Détection des problèmes et amélioration de la qualité du code","Prise en charge de la révision des différences entre les branches"],"de":["Überprüfung von Änderungen in GitHub PR","Überprüfung von lokalen Branches","Verwendung von AskUserQuestion zur Überprüfung von Bedingungen","Erkennung von Problemen und Verbesserung der Code-Qualität","Unterstützung für die Überprüfung von Differenzen zwischen Branches"],"pt":["Revisão de código em branch local ou GitHub PR","Detecção de problemas potenciais e inconsistências","Uso da ferramenta AskUserQuestion para entrevista de condições de revisão","Execução de revisão com subagentes adequados","Suporte a diferentes tipos de revisão, incluindo revisão de branch e revisão de pull request"],"ru":["Проверка кода в локальной ветке или GitHub PR","Обнаружение потенциальных проблем и несоответствий","Использование инструмента AskUserQuestion для интервью условий проверки","Выполнение проверки с помощью подходящих субагентов","Поддержка различных типов проверки, включая проверку ветки и проверку pull request"],"ar":["مراجعة الكود في الفرع المحلي أو GitHub PR","اكتشاف المشاكل المحتملة والتناقضات","استخدام أداة AskUserQuestion لاستجواب شروط المراجعة","تنفيذ المراجعة باستخدام وكلاء منASsub","دعم أنواع مختلفة من المراجعة، بما في ذلك مراجعة الفرع ومراجعة الطلبات الجديدة"]},"keywords":{"en":["how to use code-review","code-review alternative","code-review setup guide","what is code-review","code-review vs git review","code-review install","automated code review tools","github pr code review","local branch code review"],"zh":["代码审查工具","代码审查AIエージェント","代码质量检测","代码一致性检查","GitHub PR审查","本地代码审查","AskUserQuestion工具"],"ja":["コードレビューツール","コードレビューAIエージェント","コード品質検査","コードの一貫性チェック","GitHub PRレビュー","ローカルコードレビュー","AskUserQuestionツール"],"ko":["코드 리뷰 도구","코드 리뷰 인공지능 에이전트","코드 품질 검사","코드 일관성 검사","GitHub PR 검토","로컬 코드 검토","AskUserQuestion 도구"],"es":["revisión de código","herramientas de revisión de código","AskUserQuestion","GitHub PR","ramas locales","calidad del código","desarrollo de software"],"fr":["revue de code","outils de revue de code","AskUserQuestion","GitHub PR","branches locales","qualité du code","développement de logiciels"],"de":["Code-Überprüfung","Code-Review-Tools","AskUserQuestion","GitHub PR","lokale Branches","Code-Qualität","Software-Entwicklung"],"pt":["code review","ferramenta de code review","melhorar a qualidade do código","detectar problemas potenciais","garantir a consistência do código","AskUserQuestion","subagentes","revisão de branch","revisão de pull request"],"ru":["код-ревью","инструмент код-ревью","улучшить качество кода","обнаружить потенциальные проблемы","гарантировать согласованность кода","AskUserQuestion","субагенты","проверка ветки","проверка pull request"],"ar":["المراجعة اللغوية","أداة المراجعة اللغوية","تحسين جودة الكود","اكتشاف المشاكل المحتملة","ضمان الاتساق في الكود","AskUserQuestion","وكلاء منASsub","مراجعة الفرع","مراجعة الطلبات الجديدة"]}},"owner":"sendo-kakeru","repo":"family-photo","repoPath":"sendo-kakeru/family-photo","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.171Z","topics":[],"category":"community","skillMd":{"name":"code-review","description":"現在のブランチをコードレビューする。「コードレビューして」「レビューして」「PRの前にチェック」「破壊的変更をチェック」といった依頼、またはマージ前の品質確認が必要な場合に使用する。","bodyPreview":"# コードレビュー\n\n## 概要\n\n**目的**: ローカルブランチまたは GitHub PR の変更内容をレビューし、品質・一貫性・潜在的な問題を検出する。\n\nAskUserQuestion ツールを使ってレビュー条件をインタビューし、適切なサブエージェントでレビューを実行する。\n\n---\n\n## フェーズ 1: レビュー対象の確認\n\nAskUserQuestion ツールを使って質問する。\n\n**質問内容:**\n- question: \"レビュー対象は？\"\n- header: \"対象\"\n- options:\n  - label: \"ローカルブランチ\", description: \"現在のブランチと main の差分をレビュー\"\n  - label: \"GitHub PR\", description: \"現在のブランチPRの差分をレビュー\"\n  - label: \"ローカル差分\", description: \"ローカルにある差分をレビュー\"\n  - label: \"ステージ済みのローカル差分\", description: \"ローカルにあるステージ済みの差分をレビュー\"\n\n---\n\n#","body":"# コードレビュー\n\n## 概要\n\n**目的**: ローカルブランチまたは GitHub PR の変更内容をレビューし、品質・一貫性・潜在的な問題を検出する。\n\nAskUserQuestion ツールを使ってレビュー条件をインタビューし、適切なサブエージェントでレビューを実行する。\n\n---\n\n## フェーズ 1: レビュー対象の確認\n\nAskUserQuestion ツールを使って質問する。\n\n**質問内容:**\n- question: \"レビュー対象は？\"\n- header: \"対象\"\n- options:\n  - label: \"ローカルブランチ\", description: \"現在のブランチと main の差分をレビュー\"\n  - label: \"GitHub PR\", description: \"現在のブランチPRの差分をレビュー\"\n  - label: \"ローカル差分\", description: \"ローカルにある差分をレビュー\"\n  - label: \"ステージ済みのローカル差分\", description: \"ローカルにあるステージ済みの差分をレビュー\"\n\n---\n\n## フェーズ 2: 破壊的変更チェックの確認\n\nAskUserQuestion ツールを使って質問する。\n\n**質問内容:**\n- question: \"破壊的変更チェックは？\"\n- header: \"破壊的変更\"\n- options:\n  - label: \"行う\", description: \"API/スキーマ変更確認\"\n  - label: \"行わない\", description: \"通常レビューのみ\"\n\n---\n\n## フェーズ 3: 変更内容の取得\n\nフェーズ 1 の回答に基づいて変更内容を取得する。\n\n**ローカルブランチの場合:**\n```bash\ngit diff main...HEAD\ngit diff --name-only main...HEAD\n```\n\n**GitHub PR の場合:**\n\nAskUserQuestion ツールを使って PR 番号を確認する。\n\n<rules>\n- **AskUserQuestion ツールを必ず使用** - 会話形式の質問は不可\n</rules>\n\nその後:\n```bash\ngh pr view <PR番号> --json title,body,files,additions,deletions\ngh pr diff <PR番号>\n```\n\n---\n\n## フェーズ 4: レビューの実行\n\n**全てのサブエージェントを並列で実行する。**\n\n### サブエージェント\n\n| サブエージェント | 専門領域 |\n|------------------|----------|\n| `review-quality` | コード品質（命名、SRP、複雑度、エラー処理） |\n| `review-performance` | パフォーマンス（計算効率、メモリ、レンダリング） |\n| `review-security` | セキュリティ（XSS、SQLi、入力検証） |\n| `review-guideline` | ガイドライン準拠（TypeScript/React/テストルール） |\n\n---\n\n## フェーズ 6: 破壊的変更のチェック\n\n**「行う」を選択した場合のみ実行する。**\n\n| カテゴリ | 例 |\n|----------|-----|\n| API 変更 | 関数の引数追加/削除、戻り値の型変更 |\n| スキーマ変更 | DB カラムの削除、型変更、NOT NULL 追加 |\n| 設定変更 | 環境変数の追加/削除、デフォルト値の変更 |\n| 依存関係 | メジャーバージョンアップ、パッケージの削除 |\n\n---\n\n## フェーズ 7: 結果の出力\n\n### レビュー観点（サブエージェント別）\n\n| サブエージェント | チェック内容 |\n|------------------|-------------|\n| review-quality | 命名規則、単一責任原則、関数複雑度、エラーハンドリング |\n| review-performance | 計算効率、メモリ管理、レンダリング最適化、N+1問題 |\n| review-security | XSS、SQLi、入力検証、認証・認可、OWASP Top 10 |\n| review-guideline | TypeScript/React/テストルール準拠、コードスタイル |\n\n### 出力形式\n\n```markdown\n## コードレビュー結果\n\n### サマリー\n- レビュー対象: ローカルブランチ / PR #XXX\n- 変更ファイル数: X\n- 追加行数: +XXX\n- 削除行数: -XXX\n\n### スコア一覧\n\n| 観点 | スコア |\n|------|--------|\n| 品質 | A/B/C/D |\n| パフォーマンス | A/B/C/D |\n| テスト | A/B/C/D |\n| ドキュメント | A/B/C/D |\n| セキュリティ | A/B/C/D |\n| ガイドライン | A/B/C/D |\n| Design Doc | A/B/C/D（設計書ありの場合） |\n\n### 破壊的変更\n🔴 あり / 🟢 なし\n\n### 発見事項\n\n#### 🔴 Critical（修正必須）\n- [ファイル名:行番号] 問題の説明\n\n#### 🟡 Warning（推奨）\n- [ファイル名:行番号] 改善提案\n\n#### 🟢 Good（良い点）\n- 良かった実装のポイント\n\n### 総評\n全体的な評価とコメント\n```\n\n---\n\n## 重要な注意事項\n\n- **AskUserQuestion ツールを必ず使用** - 会話形式の質問は不可\n- 各フェーズで必ず AskUserQuestion を呼び出してからユーザーの回答を待つ\n"},"lastSynced":"2026-03-06T13:23:58.014Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated code inspection and quality assurance.","zh":"适用于需要自动代码检查和质量保证的开发代理。","ja":"自動コード検査と品質保証を必要とする開発エージェントに最適です。","ko":"자동 코드 검사 및 품질 보증이 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren inspección de código automatizada y garantía de calidad.","fr":"Idéal pour les agents de développement nécessitant une inspection de code automatisée et une assurance de la qualité.","de":"Ideal für Entwicklungssagenten, die eine automatisierte Code-Inspektion und Qualitätsicherung benötigen.","pt":"Ideal para Agentes de Desenvolvimento que exigem inspeção de código automatizada e garantia de qualidade.","ru":"Идеально для агентов разработки, требующих автоматизированного осмотра кода и обеспечения качества.","ar":"مثالي لعميل التطوير الذي يتطلب فحص رمز آلي وتأكيد الجودة."},"recommendation":{"en":"Empowers agents to detect quality and consistency issues in local branches and GitHub PRs, ensuring high-quality code through automated review processes utilizing tools like AskUserQuestion for tailored review conditions.","zh":"赋予代理检测本地分支和 GitHub PR 中的质量和一致性问题的能力，通过使用 AskUserQuestion 等工具的自动审查流程，确保高质量的代码。","ja":"ローカルブランチと GitHub PR の品質と一貫性の問題を検出するエージェントを可能にし、AskUserQuestion などのツールを使用した自動レビュー処理を通じて、高品質のコードを確保します。","ko":"로컬 브랜치와 GitHub PR의 품질 및 일관성 문제를检测하는 에이전트를 가능하게 하며, AskUserQuestion 등의 도구를 사용한 자동 리뷰 처리를 통해 고품질의 코드를 보장합니다.","es":"Habilita a los agentes para detectar problemas de calidad y consistencia en ramas locales y solicitudes de extracción de GitHub, garantizando un código de alta calidad a través de procesos de revisión automatizados que utilizan herramientas como AskUserQuestion para condiciones de revisión personalizadas.","fr":"Permet aux agents de détecter les problèmes de qualité et de cohérence dans les branches locales et les demandes de tirage GitHub, garantissant un code de haute qualité grâce à des processus de révision automatisés utilisant des outils comme AskUserQuestion pour des conditions de révision personnalisées.","de":"Ermöglicht es Agenten, Qualität- und Konsistenzprobleme in lokalen Branches und GitHub-PRs zu erkennen, und stellt so durch automatisierte Überprüfungsprozesse mit Tools wie AskUserQuestion für maßgeschneiderte Überprüfungsbedingungen hochwertigen Code sicher.","pt":"Habilita os agentes a detectar problemas de qualidade e consistência em branches locais e PRs do GitHub, garantindo um código de alta qualidade por meio de processos de revisão automatizados que utilizam ferramentas como AskUserQuestion para condições de revisão personalizadas.","ru":"Наделяет агентов возможностью обнаруживать проблемы качества и согласованности в локальных ветках и запросах на включение в GitHub, обеспечивая код высокого качества за счет автоматизированных процессов проверки с использованием инструментов, таких как AskUserQuestion, для настраиваемых условий проверки.","ar":"يمنح الوكلاء القدرة على كشف مشاكل الجودة والموافقة في الفروع المحلية وطلبات GitHub، مما يضمن رمزًا عالي الجودة من خلال عمليات مراجعة آلية باستخدام أدوات مثل AskUserQuestion لشروط المراجعة المخصصة."},"useCases":{"en":["Automating code reviews for GitHub PRs","Detecting quality issues in local branches","Ensuring consistency across codebases"],"zh":["自动化 GitHub PR 的代码审查","检测本地分支中的质量问题","确保代码库的一致性"],"ja":["GitHub PR のコードレビューの自動化","ローカルブランチの品質問題の検出","コードベースの一貫性の確保"],"ko":["GitHub PR의 코드 리뷰 자동화","로컬 브랜치의 품질 문제 감지","코드베이스의 일관성 보장"],"es":["Automatización de revisiones de código para solicitudes de extracción de GitHub","Detección de problemas de calidad en ramas locales","Garantía de consistencia en todo el código"],"fr":["Automation des examens de code pour les demandes de tirage GitHub","Détection des problèmes de qualité dans les branches locales","Assurance de la cohérence à travers les bases de code"],"de":["Automatisierung von Code-Reviews für GitHub-PRs","Erkennung von Qualitätsproblemen in lokalen Branches","Sicherstellung der Konsistenz über Codebasen hinweg"],"pt":["Automatizar revisões de código para PRs do GitHub","Detectar problemas de qualidade em branches locais","Garantir consistência em todo o código"],"ru":["Автоматизировать проверку кода для запросов на включение в GitHub","Обнаруживать проблемы качества в локальных ветках","Обеспечивать согласованность во всех кодах"],"ar":["تأتمتية استعراض الرمز لطلبات GitHub","كشف مشاكل الجودة في الفروع المحلية","ضمان الاتساق عبر جميع قواعد البيانات"]},"limitations":{"en":["Requires access to GitHub API for PR reviews","Limited to reviewing code in local branches or GitHub PRs"],"zh":["需要访问 GitHub API 进行 PR 审查","仅限于审查本地分支或 GitHub PR 的代码"],"ja":["PR レビューのために GitHub API へのアクセスが必要","ローカルブランチまたは GitHub PR のコードのみをレビューすることができる"],"ko":["PR 리뷰를 위해 GitHub API에 접근할 수 있어야 함","로컬 브랜치 또는 GitHub PR의 코드만을 리뷰할 수 있음"],"es":["Requiere acceso a la API de GitHub para revisiones de PR","Limitado a la revisión de código en ramas locales o solicitudes de extracción de GitHub"],"fr":["Nécessite un accès à l''API GitHub pour les révisions de PR","Limité à la révision de code dans les branches locales ou les demandes de tirage GitHub"],"de":["Benötigt Zugriff auf die GitHub-API für PR-Überprüfungen","Begrenzt auf die Überprüfung von Code in lokalen Branches oder GitHub-PRs"],"pt":["Exige acesso à API do GitHub para revisões de PR","Limitado à revisão de código em branches locais ou PRs do GitHub"],"ru":["Требует доступа к API GitHub для проверок PR","Ограничен проверкой кода в локальных ветках или запросах на включение в GitHub"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات GitHub لاستعراض PR","محدود بالاستعراض الرمز في الفروع المحلية أو طلبات GitHub"]},"version":4},"contentHash":"ad6b0650b5b9c97d863104bc8190e14b6218c22d29