INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry-data/github-search', 'github-search', 'majiayu000', 'claude-skill-registry-data', 'community', 'github-search majiayu000 claude-skill-registry-data community The github-search skill enables developers to efficiently search GitHub repositories, code, issues, and PRs using specific commands. It benefits developers who need to find projects or code by specific criteria. GitHub 搜索是一个强大的工具，允许开发者快速搜索代码、仓库和问题，提高开发效率 GitHub 検索は、コード、リポジトリ、イシューを迅速に検索できる強力なツールです GitHub 검색은 코드, 저장소, 문제를 빠르게 검색할 수 있는 강력한 도구로 개발자에게 생산성을 높여줍니다 github-search es una herramienta para buscar repositorios, código, problemas y solicitudes de extracción en GitHub. Ofrece comandos rápidos y patrones de búsqueda para encontrar proyectos por criterios específicos github-search est un outil pour rechercher des référentiels, du code, des problèmes et des demandes de tirage sur GitHub. Il propose des commandes rapides et des modèles de recherche pour trouver des projets selon des critères spécifiques github-search ist ein Tool zum Suchen von Repositorys, Code, Problemen und Pull-Requests auf GitHub. Es bietet schnelle Befehle und Suchmuster, um Projekte nach bestimmten Kriterien zu finden O GitHub Search é uma ferramenta poderosa para encontrar repositórios, código, problemas e solicitações de pull no GitHub. Aprenda a usá-la com comandos rápidos e padrões Поиск на GitHub - это мощный инструмент для поиска репозиториев, кода, проблем и запросов на включение на GitHub. Узнайте, как им пользоваться с помощью быстрых команд и шаблонов بحث GitHub هو أداة قوية لإيجاد المستودعات و Код و مشاكل و طلبات السحب على GitHub. تعلم كيفية استخدامها بسرعة وأشكال how to use github-search github-search setup guide github-search alternative github-search vs git github-search install what is github-search github-search for developers github-search efficient code search github-search commands github-search skill GitHub 搜索 代码搜索 仓库搜索 问题搜索 PR 搜索 CLI 工具 开发者工具 AIエージェント Searches repositories using ''gh search repos'' command Finds code using ''gh search code'' command with limit options Supports searching issues with ''gh search issues'' command Allows searching PRs using ''gh search prs'' command Uses specific query formats for tailored search results Limits search results with ''--limit'' option for efficient browsing github-search is a skill that allows developers to search GitHub using commands like ''gh search repos'' and ''gh search code'' to find specific repositories, code, issues, and PRs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cute-baobao/pm/hotkey', 'community', 'cute-baobao', 'pm', 'cute-baobao/pm', 'hotkey', 0, 0, 36, '2026-03-06T12:59:22.217Z', '2026-03-06T14:00:58.573Z', '06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd', '{"id":"cute-baobao/pm/hotkey","name":"hotkey","description":{"en":"The hotkey skill enables developers to add custom keyboard shortcuts to their AI agents, streamlining conversation workflows. It benefits developers working with TypeScript and UI frameworks.","zh":"本文介绍了如何在AI工具中设置热键，包括更新热键常量和注册默认热键","ja":"AIエージェントでホットキーを設定する方法について説明します。ホットキー定数の更新とデフォルトホットキーの登録を含みます","ko":"AI 도구에서 핫키를 설정하는 방법을 설명합니다. 핫키 常量의 업데이트와 기본 핫키의 등록을 포함합니다","es":"Hotkey es una función que permite agregar atajos de teclado personalizados. Actualiza las constantes de hotkey en `src/types/hotkey.ts` y registra los atajos en `src/const/hotkeys.ts`","fr":"Hotkey est une fonctionnalité qui permet d''ajouter des raccourcis clavier personnalisés. Mettez à jour les constantes de hotkey dans `src/types/hotkey.ts` et enregistrez les raccourcis dans `src/const/hotkeys.ts`","de":"Hotkey ist eine Funktion, die benutzerdefinierte Tastenkombinationen ermöglicht. Aktualisieren Sie die Hotkey-Konstanten in `src/types/hotkey.ts` und registrieren Sie die Tastenkombinationen in `src/const/hotkeys.ts`","pt":"O hotkey permite adicionar atalhos de teclado personalizados às suas aplicações. Aprenda a configurar com TypeScript e UI","ru":"Горячие клавиши позволяют добавлять пользовательские клавиатурные сокращения к вашим приложениям. Узнайте, как настроить с помощью TypeScript и UI","ar":"الاختصارات الساخنة تسمح بإضافة اختصارات لوحة المفاتيح مخصصة إلى تطبيقاتك. تعلم كيفية設定 باستخدام TypeScript و UI"},"seo":{"title":{"en":"Hotkey: Setup Guide for AI Agents","zh":"热键设置指南 - AI工具热键配置","ja":"ホットキー設定ガイド - AIエージェントのショートカット登録","ko":"핫키 설정 가이드 - AI 도구의 단축키 등록","es":"Guía de configuración de hotkey para desarrolladores","fr":"Guide de configuration de raccourci clavier hotkey","de":"Hotkey Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração de Atalhos de Teclado para Ferrament...","ru":"Настройка Горячих Клавиш для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد اختصارات لوحة المفاتيح لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to register default hotkeys and update hotkey constants with our expert guide. Learn to integrate hotkeys into your AI agent workflow today!","zh":"了解如何在AI工具中设置热键，包括更新热键常量和注册默认热键","ja":"AIエージェントでホットキーを設定する方法を学びます。ホットキー定数の更新とデフォルトホットキーの登録について","ko":"AI 도구에서 핫키를 설정하는 방법을 알아보세요. 핫키 常量의 업데이트와 기본 핫키의 등록에 대해","es":"Aprende a agregar atajos de teclado personalizados con hotkey. Descubre cómo registrar y actualizar constantes de hotkey en tu proyecto","fr":"Découvrez comment ajouter des raccourcis clavier personnalisés avec hotkey. Apprenez à enregistrer et à mettre à jour les constantes de hotkey dans votre projet","de":"Erfahren Sie, wie Sie benutzerdefinierte Tastenkombinationen mit hotkey hinzufügen. Entdecken Sie, wie Sie Hotkey-Konstanten in Ihrem Projekt registrieren un...","pt":"Aprenda a adicionar atalhos de teclado personalizados às suas ferramentas de IA com este guia passo a passo","ru":"Узнайте, как добавить пользовательские горячие клавиши к вашим ИИ Агентам с помощью этого пошагового руководства","ar":"تعلم كيفية إضافة اختصارات لوحة المفاتيح مخصصة لأدوات الذكاء الاصطناعي الخاصة بك مع هذا الدليل خطوة بخطوة"},"definition":{"en":"Hotkey is a feature that allows developers to assign custom keyboard shortcuts to specific actions in their AI agents, using constants and registrations.","zh":"热键是AI工具中的一个功能，允许用户自定义快捷键","ja":"ホットキーは、AIエージェントでユーザーがショートカットキーをカスタマイズできる機能です","ko":"핫키는 AI 도구에서 사용자가 단축키를 사용자 정의할 수 있는 기능입니다","es":"Un hotkey es una tecla o combinación de teclas que activa una acción específica en una aplicación","fr":"Un raccourci clavier est une touche ou une combinaison de touches qui active une action spécifique dans une application","de":"Ein Hotkey ist eine Taste oder eine Kombination von Tasten, die eine bestimmte Aktion in einer Anwendung auslöst","pt":"O hotkey é uma funcionalidade que permite adicionar atalhos de teclado personalizados às aplicações","ru":"Горячая клавиша - это функция, которая позволяет добавлять пользовательские клавиатурные сокращения к приложениям","ar":"الاختصار الساخن هو ميزة تسمح بإضافة اختصارات لوحة المفاتيح مخصصة إلى التطبيقات"},"features":{"en":["Updates hotkey constants in src/types/hotkey.ts","Registers default hotkeys in src/const/hotkeys.ts","Utilizes KeyMapEnum and combineKeys from @lobehub/ui","Supports HotkeyEnum for clear chat actions","Enables customization of keyboard shortcuts for conversation workflows"],"zh":["更新热键常量","注册默认热键","使用TypeScript进行热键枚举","使用combineKeys函数注册热键","支持多种热键组","自定义热键ID"],"ja":["ホットキー定数の更新","デフォルトホットキーの登録","TypeScriptによるホットキー列挙","combineKeys関数によるホットキーの登録","複数のホットキー グループのサポート","ホットキーIDのカスタマイズ"],"ko":["핫키 常量의 업데이트","기본 핫키의 등록","TypeScript를 사용한 핫키 열거","combineKeys 함수를 사용한 핫키 등록","다중 핫키 그룹의 지원","핫키 ID의 사용자 정의"],"es":["Actualizar constantes de hotkey en `src/types/hotkey.ts`","Registrar atajos de teclado en `src/const/hotkeys.ts`","Utilizar la enumeración `HotkeyEnum` para definir atajos","Combinar teclas con `combineKeys` de `@lobehub/ui`","Agregar atajos de teclado personalizados para mejorar la experiencia del usuario","Integrar hotkey con otras funcionalidades de la aplicación"],"fr":["Mettre à jour les constantes de hotkey dans `src/types/hotkey.ts`","Enregistrer les raccourcis clavier dans `src/const/hotkeys.ts`","Utiliser l''énumération `HotkeyEnum` pour définir les raccourcis","Combiner les touches avec `combineKeys` de `@lobehub/ui`","Ajouter des raccourcis clavier personnalisés pour améliorer l''expérience utilisateur","Intégrer hotkey avec d''autres fonctionnalités de l''application"],"de":["Aktualisieren von Hotkey-Konstanten in `src/types/hotkey.ts`","Registrieren von Tastenkombinationen in `src/const/hotkeys.ts`","Verwenden der Aufzählung `HotkeyEnum` zur Definition von Tastenkombinationen","Kombinieren von Tasten mit `combineKeys` von `@lobehub/ui`","Hinzufügen benutzerdefinierter Tastenkombinationen zur Verbesserung der Benutzeroberfläche","Integrieren von hotkey mit anderen Funktionen der Anwendung"],"pt":["Adicionar atalhos de teclado personalizados com TypeScript","Registro de atalhos de teclado com UI","Utilização de enumerações para organizar atalhos","Combinação de teclas com a biblioteca @lobehub/ui","Definição de grupos de atalhos de teclado"],"ru":["Добавление пользовательских клавиатурных сокращений с помощью TypeScript","Регистрация горячих клавиш с помощью UI","Использование перечислений для организации горячих клавиш","Комбинация клавиш с помощью библиотеки @lobehub/ui","Определение групп горячих клавиш"],"ar":["إضافة اختصارات لوحة المفاتيح مخصصة باستخدام TypeScript","تسجيل اختصارات لوحة المفاتيح باستخدام UI","استخدام التعدادات لتنظيم الاختصارات","مجموعة مفاتيح مع مكتبة @lobehub/ui","تحديد مجموعات اختصارات لوحة المفاتيح"]},"keywords":{"en":["how to use hotkey","hotkey setup guide","hotkey alternative","hotkey vs keyboard shortcut","what is hotkey","hotkey install for AI agents","typescript hotkey integration","custom keyboard shortcuts for AI agents"],"zh":["AI工具热键设置","热键常量更新","注册默认热键","TypeScript热键枚举","combineKeys函数","热键组","自定义热键ID","AI工具开发","热键配置"],"ja":["AIエージェントのホットキー設定","ホットキー定数の更新","デフォルトホットキーの登録","TypeScriptによるホットキー列挙","combineKeys関数","ホットキー グループ","ホットキーIDのカスタマイズ","AIエージェントの開発","ホットキーの設定"],"ko":["AI 도구의 핫키 설정","핫키 常量의 업데이트","기본 핫키의 등록","TypeScript를 사용한 핫키 열거","combineKeys 함수","핫키 그룹","핫키 ID의 사용자 정의","AI 도구 개발","핫키 설정"],"es":["hotkey","atajos de teclado","personalizar atajos","configurar hotkey","desarrollo de aplicaciones","tecnologías de desarrollo"," Typescript","javascript"],"fr":["hotkey","raccourcis clavier","personnaliser les raccourcis","configurer hotkey","développement d''applications","technologies de développement","Typescript","javascript"],"de":["hotkey","Tastenkombinationen","benutzerdefinierte Tastenkombinationen","Hotkey-Konfiguration","Anwendungsentwicklung","Entwicklungstechnologien","Typescript","javascript"],"pt":["atalhos de teclado","ferramentas de IA","TypeScript","UI","enumerações","combinação de teclas","registro de atalhos","desenvolvimento de aplicações"],"ru":["горячие клавиши","ИИ Агенты","TypeScript","UI","перечисления","комбинация клавиш","регистрация горячих клавиш","разработка приложений"],"ar":["اختصارات لوحة المفاتيح","أدوات الذكاء الاصطناعي","TypeScript","UI","التعدادات","مجموعة مفاتيح","تسجيل اختصارات","تطوير التطبيقات"]}},"owner":"cute-baobao","repo":"pm","repoPath":"cute-baobao/pm","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.217Z","topics":[],"category":"community","skillMd":{"name":"hotkey","description":"Guide for adding keyboard shortcuts. Use when implementing new hotkeys, registering shortcuts, or working with keyboard interactions. Triggers on hotkey implementation or keyboard shortcut tasks.","bodyPreview":"# Adding Keyboard Shortcuts Guide\n\n## Steps to Add a New Hotkey\n\n### 1. Update Hotkey Constant\n\nIn `src/types/hotkey.ts`:\n\n```typescript\nexport const HotkeyEnum = {\n  // existing...\n  ClearChat: ''clearChat'', // Add new\n} as const;\n```\n\n### 2. Register Default Hotkey\n\nIn `src/const/hotkeys.ts`:\n\n```typescript\nimport { KeyMapEnum as Key, combineKeys } from ''@lobehub/ui'';\n\nexport const HOTKEYS_REGISTRATION: HotkeyRegistration = [\n  {\n    group: HotkeyGroupEnum.Conversation,\n    id: HotkeyEnum.Clear","body":"# Adding Keyboard Shortcuts Guide\n\n## Steps to Add a New Hotkey\n\n### 1. Update Hotkey Constant\n\nIn `src/types/hotkey.ts`:\n\n```typescript\nexport const HotkeyEnum = {\n  // existing...\n  ClearChat: ''clearChat'', // Add new\n} as const;\n```\n\n### 2. Register Default Hotkey\n\nIn `src/const/hotkeys.ts`:\n\n```typescript\nimport { KeyMapEnum as Key, combineKeys } from ''@lobehub/ui'';\n\nexport const HOTKEYS_REGISTRATION: HotkeyRegistration = [\n  {\n    group: HotkeyGroupEnum.Conversation,\n    id: HotkeyEnum.ClearChat,\n    keys: combineKeys([Key.Mod, Key.Shift, Key.Backspace]),\n    scopes: [HotkeyScopeEnum.Chat],\n  },\n];\n```\n\n### 3. Add i18n Translation\n\nIn `src/locales/default/hotkey.ts`:\n\n```typescript\nconst hotkey: HotkeyI18nTranslations = {\n  clearChat: {\n    desc: ''清空当前会话的所有消息记录'',\n    title: ''清空聊天记录'',\n  },\n};\n```\n\n### 4. Create and Register Hook\n\nIn `src/hooks/useHotkeys/chatScope.ts`:\n\n```typescript\nexport const useClearChatHotkey = () => {\n  const clearMessages = useChatStore((s) => s.clearMessages);\n  return useHotkeyById(HotkeyEnum.ClearChat, clearMessages);\n};\n\nexport const useRegisterChatHotkeys = () => {\n  useClearChatHotkey();\n  // ...other hotkeys\n};\n```\n\n### 5. Add Tooltip (Optional)\n\n```tsx\nconst clearChatHotkey = useUserStore(settingsSelectors.getHotkeyById(HotkeyEnum.ClearChat));\n\n<Tooltip hotkey={clearChatHotkey} title={t(''clearChat.title'', { ns: ''hotkey'' })}>\n  <Button icon={<DeleteOutlined />} onClick={clearMessages} />\n</Tooltip>;\n```\n\n## Best Practices\n\n1. **Scope**: Choose global or chat scope based on functionality\n2. **Grouping**: Place in appropriate group (System/Layout/Conversation)\n3. **Conflict check**: Ensure no conflict with system/browser shortcuts\n4. **Platform**: Use `Key.Mod` instead of hardcoded `Ctrl` or `Cmd`\n5. **Clear description**: Provide title and description for users\n\n## Troubleshooting\n\n- **Not working**: Check scope and RegisterHotkeys hook\n- **Not in settings**: Verify HOTKEYS_REGISTRATION config\n- **Conflict**: HotkeyInput component shows warnings\n- **Page-specific**: Ensure correct scope activation\n"},"lastSynced":"2026-03-06T14:00:58.573Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing customizable keyboard shortcuts for streamlined conversation workflows.","zh":"非常适合需要可自定义键盘快捷键以实现流畅对话工作流的 UI 聚焦代理。","ja":"UI フォーカス エージェントがカスタマイズ可能なキーボード ショートカットを使用して会話のワークフローをストリームライン化する必要がある場合に最適です。","ko":"사용자 인터페이스에 중점을 둔 에이전트가 대화 워크플로를 최적화하는 데 필요한 사용자 지정 키보드 단축키를 필요로 하는 경우에 적합합니다.","es":"Perfecto para Agentes centrados en la interfaz de usuario que necesitan atajos de teclado personalizables para flujos de trabajo de conversación optimizados.","fr":"Parfait pour les agents axés sur l''interface utilisateur nécessitant des raccourcis clavier personnalisables pour des flux de travail de conversation rationalisés.","de":"Perfekt für benutzeroberflächengesteuerte Agenten, die benutzerdefinierte Tastenkombinationen für optimierte Konversationsworkflows benötigen.","pt":"Perfeito para Agentes focados em UI que precisam de atalhos de teclado personalizáveis para fluxos de trabalho de conversa otimizados.","ru":"Идеально для агентов, ориентированных на UI, которым необходимы настраиваемые клавиатурные сокращения для оптимизированных рабочих процессов разговора.","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم وذين يحتاجون إلى اختصارات لوحة مفاتيح قابلة للتخصيص لتدفقات عمل محادثة مبسطة."},"recommendation":{"en":"Empowers agents to register custom hotkeys using TypeScript and UI frameworks like @lobehub/ui, enabling efficient conversation management via keyboard shortcuts such as ''ClearChat'' and combining keys with ''combineKeys'' from ''@lobehub/ui''.","zh":"通过使用 TypeScript 和 UI 框架（如 @lobehub/ui）使代理能够注册自定义热键，从而实现通过键盘快捷键（如 ''ClearChat''）和 ''@lobehub/ui'' 中的 ''combineKeys'' 进行高效的会话管理。","ja":"TypeScript と UI フレームワーク (@lobehub/ui など) を使用して、エージェントがカスタム ホットキーを登録できるようにし、キーボード ショートカット (''ClearChat'' など) と ''@lobehub/ui'' の ''combineKeys'' を使用して効率的な会話管理を可能にします。","ko":"TypeScript와 UI 프레임워크 (@lobehub/ui 등)를 사용하여 에이전트가 사용자 지정 핫키를 등록할 수 있도록 하여 ''ClearChat''와 같은 키보드 단축키 및 ''@lobehub/ui''의 ''combineKeys''를 사용하여 효율적인 대화 관리를 가능하게 합니다.","es":"Habilita a los agentes para registrar teclas rápidas personalizadas utilizando TypeScript y marcos de interfaz de usuario como @lobehub/ui, lo que permite una gestión de conversación eficiente a través de atajos de teclado como ''ClearChat'' y combinación de teclas con ''combineKeys'' de ''@lobehub/ui''.","fr":"Permet aux agents d''enregistrer des touches de raccourci personnalisées en utilisant TypeScript et des cadres d''interface utilisateur tels que @lobehub/ui, permettant ainsi une gestion de conversation efficace via des raccourcis clavier tels que ''ClearChat'' et la combinaison de touches avec ''combineKeys'' de ''@lobehub/ui''.","de":"Ermöglicht es den Agenten, benutzerdefinierte Hotkeys mit TypeScript und Benutzeroberflächenframeworks wie @lobehub/ui zu registrieren, wodurch eine effiziente Konversationsverwaltung über Tastenkombinationen wie ''ClearChat'' und Kombination von Tasten mit ''combineKeys'' von ''@lobehub/ui'' ermöglicht wird.","pt":"Habilita os agentes a registrar atalhos personalizados usando TypeScript e frameworks de UI como @lobehub/ui, permitindo um gerenciamento de conversa eficiente via atalhos de teclado, como ''ClearChat'' e combinando teclas com ''combineKeys'' de ''@lobehub/ui''.","ru":"Наделяет агентов возможностью регистрировать пользовательские хоткеи с помощью TypeScript и фреймворков UI, таких как @lobehub/ui, обеспечивая эффективное управление разговором с помощью клавиатурных сокращений, таких как ''ClearChat'' и комбинация клавиш с ''combineKeys'' из ''@lobehub/ui''.","ar":"تمكّن الوكلاء من تسجيل الاختصارات المخصصة باستخدام TypeScript وأطر واجهة المستخدم مثل @lobehub/ui، مما يتيح إدارة محادثة فعالة عبر اختصارات لوحة المفاتيح مثل ''ClearChat'' ودمج المفاتيح مع ''combineKeys'' من ''@lobehub/ui''."},"useCases":{"en":["Registering default hotkeys for common actions","Updating hotkey constants for new features","Streamlining conversation workflows with custom keyboard shortcuts"],"zh":["注册常见操作的默认热键","更新新功能的热键常量","使用自定义键盘快捷键优化会话工作流"],"ja":["一般的な操作のデフォルト ホットキーを登録する","新しい機能のホットキー定数を更新する","カスタム キーボード ショートカットを使用して会話のワークフローを最適化する"],"ko":["일반적인 작업을 위한 기본 핫키 등록","새로운 기능을 위한 핫키 상수 업데이트","사용자 지정 키보드 단축키를 통한 대화 워크플로 최적화"],"es":["Registro de atajos de teclado predeterminados para acciones comunes","Actualización de constantes de atajos de teclado para nuevas características","Optimización de flujos de trabajo de conversación con atajos de teclado personalizados"],"fr":["Enregistrement des touches de raccourci par défaut pour les actions courantes","Mise à jour des constantes de touches de raccourci pour les nouvelles fonctionnalités","Optimisation des flux de travail de conversation avec des touches de raccourci personnalisées"],"de":["Registrierung von Standard-Tastenkombinationen für allgemeine Aktionen","Aktualisierung von Hotkey-Konstanten für neue Funktionen","Optimierung von Konversationsworkflows mit benutzerdefinierten Tastenkombinationen"],"pt":["Registrar atalhos padrão para ações comuns","Atualizar constantes de atalho para recursos novos","Otimizar fluxos de trabalho de conversa com atalhos de teclado personalizados"],"ru":["Регистрация стандартных хоткеев для обычных действий","Обновление констант хоткеев для новых функций","Оптимизация рабочих процессов разговора с помощью пользовательских клавиатурных сокращений"],"ar":["تسجيل الاختصارات الافتراضية للإجراءات الشائعة","تحديث ثوابت الاختصار للميزات الجديدة","تبسيط تدفقات عمل المحادثة باستخدام اختصارات لوحة المفاتيح المخصصة"]},"limitations":{"en":["Requires TypeScript and UI framework compatibility","Needs access to ''src/types/hotkey.ts'' and ''src/const/hotkeys.ts'' files"],"zh":["需要 TypeScript 和 UI 框架兼容性","需要访问 ''src/types/hotkey.ts'' 和 ''src/const/hotkeys.ts'' 文件"],"ja":["TypeScript と UI フレームワークの互換性が必要","''src/types/hotkey.ts'' と ''src/const/hotkeys.ts'' ファイルへのアクセスが必要"],"ko":["TypeScript 및 UI 프레임워크 호환성이 필요함","''src/types/hotkey.ts'' 및 ''src/const/hotkeys.ts'' 파일에 대한 액세스가 필요"],"es":["Requiere compatibilidad con TypeScript y marco de interfaz de usuario","Necesita acceso a los archivos ''src/types/hotkey.ts'' y ''src/const/hotkeys.ts''"],"fr":["Nécessite la compatibilité avec TypeScript et le cadre d''interface utilisateur","Nécessite l''accès aux fichiers ''src/types/hotkey.ts'' et ''src/const/hotkeys.ts''"],"de":["Benötigt Kompatibilität mit TypeScript und Benutzeroberflächenframework","Benötigt Zugriff auf die Dateien ''src/types/hotkey.ts'' und ''src/const/hotkeys.ts''"],"pt":["Exige compatibilidade com TypeScript e framework de UI","Necessita acesso aos arquivos ''src/types/hotkey.ts'' e ''src/const/hotkeys.ts''"],"ru":["Требует совместимости с TypeScript и фреймворком UI","Требует доступа к файлам ''src/types/hotkey.ts'' и ''src/const/hotkeys.ts''"],"ar":["يتطلب توافقًا مع TypeScript وإطار واجهة المستخدم","يحتاج إلى الوصول إلى الملفات ''src/types/hotkey.ts'' و ''src/const/hotkeys.ts''"]},"version":4},"contentHash":"06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd","qualityScore":36}');
