INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cute-baobao/pm/hotkey', 'hotkey', 'cute-baobao', 'pm', 'community', 'hotkey cute-baobao pm community The hotkey skill enables developers to add custom keyboard shortcuts to their AI agents, streamlining conversation workflows. It benefits developers working with TypeScript and UI frameworks. 本文介绍了如何在AI工具中设置热键，包括更新热键常量和注册默认热键 AIエージェントでホットキーを設定する方法について説明します。ホットキー定数の更新とデフォルトホットキーの登録を含みます AI 도구에서 핫키를 설정하는 방법을 설명합니다. 핫키 常量의 업데이트와 기본 핫키의 등록을 포함합니다 Hotkey es una función que permite agregar atajos de teclado personalizados. Actualiza las constantes de hotkey en `src/types/hotkey.ts` y registra los atajos en `src/const/hotkeys.ts` Hotkey est une fonctionnalité qui permet d''ajouter des raccourcis clavier personnalisés. Mettez à jour les constantes de hotkey dans `src/types/hotkey.ts` et enregistrez les raccourcis dans `src/const/hotkeys.ts` Hotkey ist eine Funktion, die benutzerdefinierte Tastenkombinationen ermöglicht. Aktualisieren Sie die Hotkey-Konstanten in `src/types/hotkey.ts` und registrieren Sie die Tastenkombinationen in `src/const/hotkeys.ts` O hotkey permite adicionar atalhos de teclado personalizados às suas aplicações. Aprenda a configurar com TypeScript e UI Горячие клавиши позволяют добавлять пользовательские клавиатурные сокращения к вашим приложениям. Узнайте, как настроить с помощью TypeScript и UI الاختصارات الساخنة تسمح بإضافة اختصارات لوحة المفاتيح مخصصة إلى تطبيقاتك. تعلم كيفية設定 باستخدام TypeScript و UI how to use hotkey hotkey setup guide hotkey alternative hotkey vs keyboard shortcut what is hotkey hotkey install for AI agents typescript hotkey integration custom keyboard shortcuts for AI agents AI工具热键设置 热键常量更新 注册默认热键 TypeScript热键枚举 combineKeys函数 热键组 自定义热键ID AI工具开发 热键配置 Updates hotkey constants in src/types/hotkey.ts Registers default hotkeys in src/const/hotkeys.ts Utilizes KeyMapEnum and combineKeys from @lobehub/ui Supports HotkeyEnum for clear chat actions Enables customization of keyboard shortcuts for conversation workflows Hotkey is a feature that allows developers to assign custom keyboard shortcuts to specific actions in their AI agents, using constants and registrations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moorestech/moorestech/creating-server-protocol', 'community', 'moorestech', 'moorestech', 'moorestech/moorestech', 'creating-server-protocol', 63, 7, 35, '2026-02-25T16:33:34Z', '2026-03-06T06:34:19.529Z', '6918e4dabfeb6199c51a335f1603173c0c1f20505860b2a7eb955419911bb21f', '{"id":"moorestech/moorestech/creating-server-protocol","name":"creating-server-protocol","description":{"en":"The creating-server-protocol skill helps game developers create automated factory game servers using C#, .NET Core, and Unity. It supports Request-Response and Event-type protocols.","zh":"创建服务器协议是游戏开发中的关键步骤，本指南介绍了Request-Response型和Event型协议的选择和实现，使用C#和Unity3D。","ja":"サーバープロトコル作成はゲーム開発における重要なステップです。本ガイドでは、Request-Response型とEvent型のプロトコルの選択と実装方法を紹介します。C#とUnity3Dを使用。","ko":"서버 프로토콜 생성은 게임 개발의 중요한 단계입니다. 이 가이드에서는 Request-Response 및 Event 유형의 프로토콜 선택 및 구현 방법을介绍합니다. C# 및 Unity3D 사용","es":"El protocolo de servidor es fundamental para los juegos de mundo abierto automatizados. Aprende a crear uno con C# y Unity.","fr":"Le protocole de serveur est essentiel pour les jeux de monde ouvert automatisés. Découvrez comment en créer un avec C# et Unity.","de":"Das Server-Protokoll ist für automatisierte Open-World-Spiele unerlässlich. Erfahren Sie, wie Sie eines mit C# und Unity erstellen.","pt":"Crie um protocolo de servidor para jogos em tempo real com C# e .NET Core, incluindo Request-Response e Eventos","ru":"Создайте протокол сервера для игр в реальном времени с помощью C# и .NET Core, включая Request-Response и события","ar":"انشئ بروتوكول خادم للألعاب في الوقت الفعلي باستخدام C# و .NET Core، بما في ذلك الطلب والاستجابة والأحداث"},"seo":{"title":{"en":"Creating-Server-Protocol: Setup Guide for Unity Game Serv...","zh":"创建服务器协议 Setup Guide","ja":"サーバープロトコル作成ガイド - Request-Response型とEvent型","ko":"서버 프로토콜 생성하기: Request-Response 및 Event 유형","es":"Creación de Protocolo de Servidor: Guía de Configuración","fr":"Création de Protocole de Serveur: Meilleures Pratiques","de":"Erstellung von Server-Protokoll: Einrichtungsanleitung","pt":"Guia de Criação de Protocolo de Servidor para Jogos em Te...","ru":"Настройка протокола сервера для игр в реальном времени с ...","ar":"دليل إنشاء بروتوكول خادم للألعاب في الوقت الفعلي باستخدام..."},"description":{"en":"Learn how to create a server protocol for your Unity game with our expert guide. Get started with Request-Response and Event-type protocols today!","zh":"了解创建服务器协议的最佳实践，包括Request-Response型和Event型协议的选择和实现，使用C#和Unity3D","ja":"サーバープロトコル作成のためのガイド。Request-Response型とEvent型の選択と実装方法を紹介します。C#とUnity3Dを使用。","ko":"서버 프로토콜 생성을 위한 안내서입니다. Request-Response 및 Event 유형의 선택과 구현 방법을 알아보세요. C# 및 Unity3D 사용","es":"Aprende a crear un protocolo de servidor para juegos de mundo abierto automatizados con C# y Unity","fr":"Découvrez comment créer un protocole de serveur pour les jeux de monde ouvert automatisés avec C# et Unity","de":"Erfahren Sie, wie Sie ein Server-Protokoll für automatisierte Open-World-Spiele mit C# und Unity erstellen","pt":"Aprenda a criar um protocolo de servidor para jogos em tempo real com C#, .NET Core e Unity, incluindo padrões de protocolo e exemplos de código","ru":"Узнайте, как создать протокол сервера для игр в реальном времени с помощью C#, .NET Core и Unity, включая шаблоны протокола и примеры кода с помощью ИИ Агентов","ar":"تعرف على كيفية إنشاء بروتوكول خادم للألعاب في الوقت الفعلي باستخدام C# و .NET Core و Unity، بما في ذلك أنماط البروتوكول وأمثلة الكود مع أدوات الذكاء الاصطناعي"},"definition":{"en":"creating-server-protocol is a skill for creating server protocols for Unity game development, supporting Request-Response and Event-type protocols for real-time communication.","zh":"创建服务器协议是指设计和实现服务器与客户端之间的通信协议，用于游戏开发和实时服务器通信","ja":"サーバープロトコル作成とは、サーバーとクライアントの間の通信プロトコルを設計し、実装することを指します。ゲーム開発とリアルタイムサーバー通信に使用されます","ko":"서버 프로토콜 생성은 서버와 클라이언트 간의 통신 프로토콜을 설계 및 구현하는 것을 의미합니다. 게임 개발 및 실시간 서버 통신에 사용됩니다","es":"El protocolo de servidor es un conjunto de reglas que define la comunicación entre el servidor y el cliente en un juego","fr":"Le protocole de serveur est un ensemble de règles qui définit la communication entre le serveur et le client dans un jeu","de":"Das Server-Protokoll ist eine Sammlung von Regeln, die die Kommunikation zwischen Server und Client in einem Spiel definieren","pt":"O protocolo de servidor é um conjunto de regras para comunicação entre cliente e servidor em jogos em tempo real","ru":"Протокол сервера - это набор правил для обмена данными между клиентом и сервером в играх реального времени","ar":"بروتوكول الخادم هو مجموعة من القواعد للاتصال بين العميل والخادم في الألعاب في الوقت الفعلي"},"features":{"en":["Generates protocol classes using C# and .NET Core","Supports Request-Response and Event-type protocols for real-time communication","Uses MessagePack for efficient data serialization","Creates packet response files in the `moorestech_server/Assets/Scripts/Server.Protocol/PacketResponse/` directory","Follows protocol patterns and code examples from `references/protocol-patterns.md`"],"zh":["支持Request-Response型和Event型协议","使用C#和Unity3D进行实现","提供详细的协议选择和实现指南","适用于游戏开发和实时服务器通信","使用MessagePack进行数据序列化"],"ja":["Request-Response型とEvent型のプロトコルをサポート","C#とUnity3Dを使用した実装","詳細なプロトコルの選択と実装ガイドを提供","ゲーム開発とリアルタイムサーバー通信に適しています","MessagePackを使用したデータのシリアル化"],"ko":["Request-Response 및 Event 유형의 프로토콜 지원","C# 및 Unity3D를 사용한 구현","詳細한 프로토콜 선택 및 구현 가이드 제공","게임 개발 및 실시간 서버 통신에 적합","MessagePack를 사용한 데이터 시리얼화"],"es":["Soporte para Request-Response y Eventos","Creación de protocolos personalizados con C#","Integración con Unity para juegos de mundo abierto","Uso de MessagePack para la serialización de datos","Patrones de protocolo predefinidos para una implementación rápida"],"fr":["Prise en charge de Request-Response et d''Événements","Création de protocoles personnalisés avec C#","Intégration avec Unity pour les jeux de monde ouvert","Utilisation de MessagePack pour la sérialisation des données","Modèles de protocole prédéfinis pour une mise en œuvre rapide"],"de":["Unterstützung für Request-Response und Ereignisse","Erstellung von benutzerdefinierten Protokollen mit C#","Integration mit Unity für Open-World-Spiele","Verwendung von MessagePack für die Datenserialisierung","Vordefinierte Protokollmuster für eine schnelle Implementierung"],"pt":["Suporte a Request-Response e Eventos","Integração com C# e .NET Core","Exemplos de código para Unity","Padrões de protocolo personalizados","Comunicação em tempo real"],"ru":["Поддержка Request-Response и событий","Интеграция с C# и .NET Core","Примеры кода для Unity","Пользовательские шаблоны протокола","Обмен данными в реальном времени"],"ar":["دعم الطلب والاستجابة والأحداث","التكامل مع C# و .NET Core","أمثلة الكود ل Unity","أنماط بروتوكول مخصصة","التواصل في الوقت الفعلي"]},"keywords":{"en":["how to create a server protocol for Unity","creating-server-protocol setup guide","Request-Response protocol example","Event-type protocol tutorial","Unity game server development","C# and .NET Core for game development","creating-server-protocol vs other game server protocols"],"zh":["创建服务器协议","Request-Response型协议","Event型协议","C#游戏开发","Unity3D游戏开发","实时服务器通信","MessagePack数据序列化"],"ja":["サーバープロトコル作成","Request-Response型プロトコル","Event型プロトコル","C#ゲーム開発","Unity3Dゲーム開発","リアルタイムサーバー通信","MessagePackデータシリアル化"],"ko":["서버 프로토콜 생성","Request-Response 유형 프로토콜","Event 유형 프로토콜","C# 게임 개발","Unity3D 게임 개발","실시간 서버 통신","MessagePack 데이터 시리얼화"],"es":["creación de protocolo de servidor","juegos de mundo abierto","C#","Unity","MessagePack","Request-Response","Eventos","desarrollo de juegos","protocolo de servidor personalizado"],"fr":["création de protocole de serveur","jeux de monde ouvert","C#","Unity","MessagePack","Request-Response","Événements","développement de jeux","protocole de serveur personnalisé"],"de":["Erstellung von Server-Protokoll","Open-World-Spiele","C#","Unity","MessagePack","Request-Response","Ereignisse","Spieleentwicklung","benutzerdefiniertes Server-Protokoll"],"pt":["criar protocolo de servidor","jogos em tempo real","C#",".NET Core","Unity","Request-Response","Eventos","comunicação em tempo real"],"ru":["создать протокол сервера","игры в реальном времени","C#",".NET Core","Unity","Request-Response","события","обмен данными в реальном времени","ИИ Агенты"],"ar":["إنشاء بروتوكول خادم","الألعاب في الوقت الفعلي","C#",".NET Core","Unity","الطلب والاستجابة","الأحداث","التواصل في الوقت الفعلي","أدوات الذكاء الاصطناعي"]}},"owner":"moorestech","repo":"moorestech","repoPath":"moorestech/moorestech","stars":63,"forks":7,"updatedAt":"2026-02-25T16:33:34Z","topics":["csharp","dotnet","dotnet-core","dotnetcore","game","game-development","game-server","realtime-server","unity","unity3d","unity3d-game"],"category":"community","skillMd":{"name":"creating-server-protocol","description":"|","bodyPreview":"# サーバープロトコル作成ガイド\n\n## プロトコル選択\n\n| 条件 | 種類 |\n|------|------|\n| クライアントが明示的に情報を要求/操作を実行 | **Request-Response型** |\n| サーバー側の状態変化をクライアントに通知 | **Event型** |\n\n詳細パターンとコード例: [references/protocol-patterns.md](references/protocol-patterns.md) を参照。\n\n## Request-Response型の作成手順\n\n### Step 1: プロトコルクラスを作成\n\n`moorestech_server/Assets/Scripts/Server.Protocol/PacketResponse/` に新規ファイルを作成。\n\n```csharp\nusing System;\nusing System.Collections.Generic;\nusing MessagePack;\nusing Server.Protocol;\n\nnamespace Server.Protocol.PacketR","body":"# サーバープロトコル作成ガイド\n\n## プロトコル選択\n\n| 条件 | 種類 |\n|------|------|\n| クライアントが明示的に情報を要求/操作を実行 | **Request-Response型** |\n| サーバー側の状態変化をクライアントに通知 | **Event型** |\n\n詳細パターンとコード例: [references/protocol-patterns.md](references/protocol-patterns.md) を参照。\n\n## Request-Response型の作成手順\n\n### Step 1: プロトコルクラスを作成\n\n`moorestech_server/Assets/Scripts/Server.Protocol/PacketResponse/` に新規ファイルを作成。\n\n```csharp\nusing System;\nusing System.Collections.Generic;\nusing MessagePack;\nusing Server.Protocol;\n\nnamespace Server.Protocol.PacketResponse\n{\n    public class YourProtocol : IPacketResponse\n    {\n        public const string ProtocolTag = \"va:yourProtocol\";\n\n        private readonly ISomeDependency _dependency;\n\n        public YourProtocol(ServiceProvider serviceProvider)\n        {\n            _dependency = serviceProvider.GetService<ISomeDependency>();\n        }\n\n        public ProtocolMessagePackBase GetResponse(byte[] payload)\n        {\n            var data = MessagePackSerializer.Deserialize<YourRequestMessagePack>(payload);\n            // ビジネスロジック\n            return new YourResponseMessagePack(/* result */);\n        }\n\n        #region MessagePack\n\n        [MessagePackObject]\n        public class YourRequestMessagePack : ProtocolMessagePackBase\n        {\n            // Key(0)=Tag, Key(1)=SequenceId は基底クラスで予約済み\n            [Key(2)] public int SomeField { get; set; }\n\n            [Obsolete(\"デシリアライズ用のコンストラクタです。基本的に使用しないでください。\")]\n            public YourRequestMessagePack() { }\n\n            public YourRequestMessagePack(int someField)\n            {\n                Tag = ProtocolTag;\n                SomeField = someField;\n            }\n        }\n\n        [MessagePackObject]\n        public class YourResponseMessagePack : ProtocolMessagePackBase\n        {\n            [Key(2)] public string ResultData { get; set; }\n\n            [Obsolete(\"デシリアライズ用のコンストラクタです。基本的に使用しないでください。\")]\n            public YourResponseMessagePack() { }\n\n            public YourResponseMessagePack(string resultData)\n            {\n                Tag = ProtocolTag;\n                ResultData = resultData;\n            }\n        }\n\n        #endregion\n    }\n}\n```\n\n### Step 2: PacketResponseCreatorに登録\n\n`moorestech_server/Assets/Scripts/Server.Protocol/PacketResponseCreator.cs` のコンストラクタに追加:\n\n```csharp\n_packetResponseDictionary.Add(YourProtocol.ProtocolTag, new YourProtocol(serviceProvider));\n```\n\n### Step 3: テストを作成\n\n`/creating-server-tests` スキルを使用してテストを作成。配置先: `Tests/CombinedTest/Server/PacketTest/`\n\n### Step 4: コンパイル確認\n\nMCPツールまたは`unity-test.sh`でコンパイルを確認。\n\n---\n\n## Event型の作成手順\n\n### Step 1: イベントパケットクラスを作成\n\n`moorestech_server/Assets/Scripts/Server.Event/EventReceive/` に新規ファイルを作成。\n\n```csharp\nusing System;\nusing Game.Context;\nusing MessagePack;\nusing Server.Event;\n\nnamespace Server.Event.EventReceive\n{\n    public class YourEventPacket\n    {\n        public const string EventTag = \"va:event:yourEvent\";\n        private readonly EventProtocolProvider _eventProtocolProvider;\n\n        public YourEventPacket(EventProtocolProvider eventProtocolProvider)\n        {\n            _eventProtocolProvider = eventProtocolProvider;\n            // ゲームイベントを購読（UniRx .Subscribe）\n            ServerContext.SomeEvent.OnSomething.Subscribe(OnSomething);\n        }\n\n        private void OnSomething(SomeEventData eventData)\n        {\n            var messagePack = new YourEventMessagePack(eventData.Value);\n            var payload = MessagePackSerializer.Serialize(messagePack);\n\n            // 全プレイヤー: AddBroadcastEvent / 特定プレイヤー: AddEvent(playerId, ...)\n            _eventProtocolProvider.AddBroadcastEvent(EventTag, payload);\n        }\n\n        #region MessagePack\n\n        [MessagePackObject]\n        public class YourEventMessagePack\n        {\n            // EventのMessagePackはProtocolMessagePackBaseを継承しない。Key(0)から開始\n            [Key(0)] public string Value { get; set; }\n\n            [Obsolete(\"デシリアライズ用のコンストラクタです。基本的に使用しないでください。\")]\n            public YourEventMessagePack() { }\n\n            public YourEventMessagePack(string value)\n            {\n                Value = value;\n            }\n        }\n\n        #endregion\n    }\n}\n```\n\n### Step 2: イベントパケットを初期化\n\nイベントを発火する責任を持つシステムのコンストラクタでインスタンス化し、フィールドに保持する（GC防止）。\n\n例: ブロック配置イベント → `BlockUpdateSystem`で初期化、レールノード作成イベント → `RailGraphDatastore`関連で初期化。\n\n### Step 3: テストを作成\n\n`/creating-server-tests` スキルを使用。配置先: `Tests/CombinedTest/Server/PacketTest/Event/`\n\n### Step 4: コンパイル確認\n\nMCPツールまたは`unity-test.sh`でコンパイルを確認。\n\n---\n\n## 注意事項\n\n- タグの一意性を必ず確認する（既存タグと重複しないこと）\n- MessagePackのKey番号: Request/ResponseはKey(2)から、EventデータはKey(0)から\n- `[Obsolete]`付き引数なしコンストラクタは省略不可\n- イベント購読はUniRxの`.Subscribe()`を使用（`/csharp-event-pattern`参照）\n- コードのコメントは日本語・英語の2行セット\n\n"},"lastSynced":"2026-03-06T06:34:19.529Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing automated server protocol creation using C#, .NET Core, and Unity.","zh":"非常适合需要使用C#、.NET Core和Unity进行自动化服务器协议创建的游戏开发代理。","ja":"C#、.NET Core、Unityを使用して自動的にサーバー通信プロトコルを作成する必要があるゲーム開発エージェントに最適です。","ko":"C#、.NET Core 및 Unity를 사용하여 자동으로 서버 프로토콜을 생성해야 하는 게임 개발 에이전트에게完璧합니다.","es":"Perfecto para Agentes de Desarrollo de Juegos que necesitan la creación automática de protocolos de servidor utilizando C#, .NET Core y Unity.","fr":"Parfait pour les Agents de Développement de Jeux ayant besoin de la création automatisée de protocoles de serveur en utilisant C#, .NET Core et Unity.","de":"Perfekt für Game-Entwicklungsagenten, die die automatisierte Erstellung von Serverprotokollen mit C#, .NET Core und Unity benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Jogos que precisam de criação automática de protocolo de servidor usando C#, .NET Core e Unity.","ru":"Идеально подходит для агентов разработки игр, которым требуется автоматизированная создание серверного протокола с использованием C#, .NET Core и Unity.","ar":"مثالي لعميل تطوير الألعاب الذي يحتاج إلى إنشاء بروتوكول خادم تلقائي باستخدام C# و .NET Core و Unity."},"recommendation":{"en":"Empowers agents to create Request-Response and Event-type protocols for game servers, supporting efficient client-server communication using MessagePack and custom protocol classes.","zh":"赋予代理创建请求-响应和事件类型协议的能力，以支持客户端和服务器之间使用MessagePack和自定义协议类的高效通信。","ja":"エージェントが、MessagePackとカスタムプロトコルクラスを使用したクライアントとサーバーの効率的な通信をサポートする、リクエスト-レスポンス型とイベント型のプロトコルを作成できるようにします。","ko":"에이전트가 MessagePack와 사용자 정의 프로토콜 클래스를 사용하여 클라이언트와 서버 간의 효율적인 통신을 지원하는 요청-응답 및 이벤트 유형 프로토콜을 생성할 수 있도록 합니다.","es":"Habilita a los agentes a crear protocolos de tipo Request-Response y Event-type para servidores de juegos, lo que admite una comunicación eficiente entre cliente y servidor utilizando MessagePack y clases de protocolo personalizadas.","fr":"Permet aux agents de créer des protocoles de type Request-Response et Event-type pour les serveurs de jeux, ce qui prend en charge une communication efficace entre client et serveur en utilisant MessagePack et des classes de protocole personnalisées.","de":"Ermächtigt Agenten zur Erstellung von Request-Response- und Event-Typ-Protokollen für Gameserver, was eine effiziente Client-Server-Kommunikation mittels MessagePack und benutzerdefinierten Protokollklassen ermöglicht.","pt":"Concede poderes aos agentes para criar protocolos do tipo Solicitação-Resposta e Evento para servidores de jogos, suportando comunicação eficiente cliente-servidor usando MessagePack e classes de protocolo personalizadas.","ru":"Наделяет агентов возможностью создавать протоколы типа Запрос-Ответ и Событие для игровых серверов, поддерживая эффективную связь между клиентом и сервером с помощью MessagePack и пользовательских классов протокола.","ar":"يمنح الوكلاء القدرة على إنشاء بروتوكولات من نوع الطلب-الاستجابة والحدث للخادم اللعبة، ودعم الاتصالات الفعالة بين العميل والخادم باستخدام MessagePack وفئات بروتوكول مخصصة."},"useCases":{"en":["Implementing Request-Response protocols for client-initiated actions","Designing Event-type protocols for server-side state changes","Automating factory game server setup using Unity and .NET Core"],"zh":["为客户端发起的操作实现请求-响应协议","为服务器端状态更改设计事件类型协议","使用Unity和.NET Core自动化工厂游戏服务器设置"],"ja":["クライアントが開始したアクションのためのリクエスト-レスポンスプロトコルを実装する","サーバー側の状態変更のためのイベント型プロトコルを設計する","Unityと.NET Coreを使用してファクトリーゲームサーバーのセットアップを自動化する"],"ko":["클라이언트가 시작한 동작에 대한 요청-응답 프로토콜 구현","서버측 상태 변경을 위한 이벤트 유형 프로토콜 설계","Unity 및 .NET Core를 사용하여 공장 게임 서버 설정 자동화"],"es":["Implementar protocolos Request-Response para acciones iniciadas por el cliente","Diseñar protocolos de tipo Event-type para cambios de estado en el lado del servidor","Automatizar la configuración del servidor de juegos de fábrica utilizando Unity y .NET Core"],"fr":["Mettre en œuvre des protocoles Request-Response pour les actions initiées par le client","Concevoir des protocoles de type Event-type pour les changements d''état côté serveur","Automatiser la configuration du serveur de jeux d''usine en utilisant Unity et .NET Core"],"de":["Implementierung von Request-Response-Protokollen für clientinitiierte Aktionen","Entwurf von Event-Typ-Protokollen für serverseitige Statusänderungen","Automatisierung der Fabrik-Game-Server-Einrichtung mit Unity und .NET Core"],"pt":["Implementar protocolos de Solicitação-Resposta para ações iniciadas pelo cliente","Projetar protocolos de tipo Evento para alterações de estado do lado do servidor","Automatizar a configuração do servidor de jogo de fábrica usando Unity e .NET Core"],"ru":["Реализовать протоколы типа Запрос-Ответ для действий, инициированных клиентом","Разработать протоколы типа Событие для изменений состояния на стороне сервера","Автоматизировать настройку фабричного игрового сервера с помощью Unity и .NET Core"],"ar":["تنفيذ بروتوكولات الطلب-الاستجابة لأفعال مبادرة من العميل","تصميم بروتوكولات من نوع الحدث لتغييرات حالة côté الخادم","توفير إعداد تلقائي للخادم اللعبة المصنع باستخدام Unity و .NET Core"]},"limitations":{"en":["Requires C# and .NET Core expertise","Unity game engine dependency","Limited to Request-Response and Event-type protocols"],"zh":["需要C#和.NET Core的专业知识","依赖于Unity游戏引擎","仅限于请求-响应和事件类型协议"],"ja":["C#と.NET Coreの専門知識が必要","Unityゲームエンジンに依存している","リクエスト-レスポンス型とイベント型のプロトコルに限定されている"],"ko":["C# 및 .NET Core 전문 지식이 필요","Unity 게임 엔진 의존","요청-응답 및 이벤트 유형 프로토콜에만 제한"],"es":["Requiere experiencia en C# y .NET Core","Dependencia del motor de juego Unity","Limitado a protocolos de tipo Request-Response y Event-type"],"fr":["Nécessite une expertise en C# et .NET Core","Dépendance du moteur de jeu Unity","Limité aux protocoles de type Request-Response et Event-type"],"de":["Benötigt Erfahrung mit C# und .NET Core","Abhängigkeit von der Unity-Game-Engine","Begrenzt auf Request-Response- und Event-Typ-Protokolle"],"pt":["Requer conhecimento de C# e .NET Core","Dependência do mecanismo de jogo Unity","Limitado a protocolos do tipo Solicitação-Resposta e Evento"],"ru":["Требует знаний C# и .NET Core","Зависимость от игрового движка Unity","Ограничен протоколами типа Запрос-Ответ и Событие"],"ar":["يتطلب معرفة C# و .NET Core","اعتماد على محرك ألعاب Unity","محدود ببروتوكولات الطلب-الاستجابة والحدث"]},"version":4},"contentHash":"6918e4dabfeb6199c51a335f1603173c0c1f20505860b2a7eb955419911bb21f","qualityScore":35}');
