INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AuroraWebSoftware/AAuth/aauth', 'aauth', 'AuroraWebSoftware', 'AAuth', 'community', 'aauth AuroraWebSoftware AAuth community abac access-control access-management auth authentication authorization laravel laravel-framework laravel-package permissions php php8 aauth is a Laravel package that provides hierarchical role-permission based authentication with limitless organizational levels. It benefits developers building complex access control systems. AAuth是一个Laravel层次授权包，支持无限层级组织。它提供RBAC和参数权限，帮助开发者实现复杂的访问控制 AAuthは階層型ロールパーミッションを備えたLaravelパッケージで、無限の階層レベルを実現します。RBACとパラメータパーミッションを提供 AAuth는 계층적 역할 권한을 갖춘 Laravel 패키지로, 무한한 계층 수준을 지원합니다. RBAC 및 매개 변수 권한을 제공하여 개발자가 복잡한 액세스 제어를 구현하도록 도와줍니다 aauth es un paquete de autenticación jerárquica para Laravel que ofrece una estructura de organizaciones de nivel ilimitado y permisos paramétricos aauth est un package d''authentification hiérarchique pour Laravel qui propose une structure d''organisations de niveau illimité et des permissions paramétriques aauth ist ein Paket für hierarchische Authentifizierung für Laravel, das eine Struktur von Organisationen auf unbegrenztem Level und parametrierte Berechtigungen bietet O AAuth é um pacote de autenticação para Laravel que suporta hierarquia de organizações e permissões paramétricas. Ele é fácil de instalar e configurar. AAuth - это пакет аутентификации для Laravel, который поддерживает иерархию организаций и параметрические разрешения. Он легко устанавливается и настраивается. AAuth هو حزمة مصادقة للاستخدام مع Laravel، وهو يدعم هرمية المنظمات والصلاحيات المعلمة. إنه سهل التثبيت والتهيئة. how to use aauth aauth setup guide laravel rbac package hierarchical role-permission aauth vs laravel permission aauth install parametric permissions laravel access control aauth tutorial aauth documentation AAuth Laravel层次授权 RBAC 参数权限 无限层级组织 Laravel包 PHP8 访问控制 角色权限 Implements `AAuthUserContract` for custom User models Supports limitless hierarchical levels of organizations Provides parametric permissions for fine-grained access control Uses Composer for installation via `composer require aurora-web-software/aauth` Requires publishing config and migrations via `php artisan vendor:publish` Supports PHP 8 and Laravel framework aauth is a Laravel RBAC package that enables hierarchical role-permission based authentication with organization hierarchy and parametric permissions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ippei-shimizu/buzzbase/create-pr', 'community', 'ippei-shimizu', 'buzzbase', 'ippei-shimizu/buzzbase', 'create-pr', 25, 3, 35, '2026-02-26T03:09:46Z', '2026-03-06T06:40:13.015Z', 'd9581e2ed65928d4a2c956c0ca8c2bf6115074f34c1a2a88e755d5fb8bbef3d7', '{"id":"ippei-shimizu/buzzbase/create-pr","name":"create-pr","description":{"en":"The create-pr skill analyzes changes in the current branch and creates a PR for review. It supports Git commands and integrates with the ippei-shimizu/buzzbase repository.","zh":"create-pr技能用于自动化PR创建流程，通过分析当前分支的变化并创建PR","ja":"create-prスキルは、現在のブランチの変更内容を分析し、PRを作成することでPR作成を自動化する","ko":"create-pr 스킬은 현재 브랜치의 변경 사항을 분석하여 PR을 자동 생성합니다","es":"Create-pr es una herramienta de AI que analiza los cambios en la rama actual y crea solicitudes de extracción en el repositorio de GitHub","fr":"Create-pr est un outil d''IA qui analyse les modifications dans la branche actuelle et crée des demandes d''extraction dans le référentiel GitHub","de":"Create-pr ist ein AI-Tool, das die Änderungen im aktuellen Branch analysiert und Pull-Requests im GitHub-Repository erstellt","pt":"O Create-PR é uma ferramenta que analisa as alterações no branch atual e cria solicitações de pull personalizadas com o Git e CLI.","ru":"Create-PR - это инструмент, который анализирует изменения в текущей ветке и создает индивидуальные запросы на изменения с помощью Git и CLI.","ar":"Create-PR هو أداة تحليل التغييرات في الفرع الحالي وإنشاء طلبات سحب مخصصة باستخدام Git وواجهة سطر الأوامر"},"seo":{"title":{"en":"create-pr: Automated PR Creation Setup Guide | AI Agent S...","zh":"create-pr_SETUP GUIDE：自动化PR创建流程","ja":"create-prセットアップガイド：PR作成自動化","ko":"create-pr 셋アップ 가이드: PR 자동 생성","es":"Guía de configuración de create-pr para desarrolladores","fr":"Configurer create-pr : Meilleures pratiques pour les déve...","de":"Einrichten von create-pr: Leitfaden für Entwickler","pt":"Guia de Configuração do Create-PR: Criando Solicitações d...","ru":"Настройка Create-PR: Лучшие Практики для Создания Запросо...","ar":"دليل إعداد Create-PR: إنشاء طلبات السحب باستخدام واجهة سط..."},"description":{"en":"Streamline your development workflow with create-pr, an AI agent skill that automates PR creation. Learn how to set up and use create-pr to boost your produc...","zh":"了解create-pr技能的技术细节，自动化PR创建流程，提高开发效率","ja":"create-prスキルの技術的詳細を学び、PR作成を自動化して開発効率を向上させる","ko":"create-pr 기술의 세부사항을 익히고 PR 자동 생성을 통해 개발 효율성을 높여보세요","es":"Aprende a crear solicitudes de extracción con create-pr, una herramienta de AI para desarrolladores que automatiza el análisis de cambios y la creación de PR","fr":"Découvrez comment créer des demandes d''extraction avec create-pr, un outil d''IA pour les développeurs qui automatise l''analyse des modifications et la créati...","de":"Erfahren Sie, wie Sie Pull-Requests mit create-pr erstellen, einem AI-Tool für Entwickler, das die Analyse von Änderungen und die Erstellung von PR automatis...","pt":"Aprenda a configurar o Create-PR para criar solicitações de pull personalizadas com o Git e CLI, melhore sua produtividade com os agentes de IA","ru":"Узнайте, как настроить Create-PR для создания индивидуальных запросов на изменения с помощью Git и CLI, повышайте производительность с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Create-PR لإنشاء طلبات سحب مخصصة باستخدام Git وواجهة سطر الأوامر، ورفع الإنتاجية باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"create-pr is a skill that automates the creation of pull requests (PRs) for code changes, using Git commands and repository integrations.","zh":"create-pr是AIエージェント中的一个技能，用于自动创建PR","ja":"create-prはAIエージェントのスキルの一つで、PRを作成する","ko":"create-pr은 AI 에이전트의 스킬 중 하나로 PR을 자동 생성하는 기능입니다","es":"Create-pr es una herramienta de AI que automatiza la creación de solicitudes de extracción en GitHub","fr":"Create-pr est un outil d''IA qui automatise la création de demandes d''extraction sur GitHub","de":"Create-pr ist ein AI-Tool, das die Erstellung von Pull-Requests auf GitHub automatisiert","pt":"O Create-PR é uma ferramenta de linha de comando que cria solicitações de pull automatizadas com base nas alterações no branch atual","ru":"Create-PR - это команда CLI, которая создает автоматические запросы на изменения на основе изменений в текущей ветке","ar":"Create-PR هو أمر سطر أوامر يخلق طلبات سحب آليّة بناءً على التغييرات في الفرع الحالي"},"features":{"en":["Analyzes current branch changes using Git commands","Creates PRs in the ippei-shimizu/buzzbase repository","Supports custom base branches via $ARGUMENTS","Checks for uncommitted changes using git status --short","Pushes changes to remote repositories before creating PRs"],"zh":["自动分析当前分支的变化","创建PR到ippei-shimizu/buzzbase仓库","支持自定义基准分支","确保所有PR描述为日本语","在创建PR前获得用户确认","支持Git CLI命令"],"ja":["現在のブランチの変更内容を分析","PRをippei-shimizu/buzzbaseリポジトリに作成","ベースブランチのカスタマイズをサポート","すべてのPR記述を日本語で行う","PR作成前にユーザーの承認を得る","Git CLIコマンドをサポート"],"ko":["현재 브랜치의 변경 사항을 분석","PR을 ippei-shimizu/buzzbase 저장소에 생성","기반 브랜치의 커스터마이징을 지원","모든 PR 설명을 일본어로 작성","PR 생성 전에 사용자 승인 얻기","Git CLI 명령어 지원"],"es":["Análisis de cambios en la rama actual con git status y git log","Creación de solicitudes de extracción en el repositorio de GitHub","Soporte para especificar la rama base con $ARGUMENTS","Automatización de la creación de PR con git diff y git log","Compatibilidad con GitHub y CLI de Git","Soporte para múltiples ramas y repositorios"],"fr":["Analyse des modifications dans la branche actuelle avec git status et git log","Création de demandes d''extraction dans le référentiel GitHub","Prise en charge de la spécification de la branche de base avec $ARGUMENTS","Automatisation de la création de PR avec git diff et git log","Compatibilité avec GitHub et la CLI de Git","Prise en charge de plusieurs branches et référentiels"],"de":["Analyse von Änderungen im aktuellen Branch mit git status und git log","Erstellung von Pull-Requests im GitHub-Repository","Unterstützung für die Angabe der Basisbranche mit $ARGUMENTS","Automatisierung der Erstellung von PR mit git diff und git log","Kompatibilität mit GitHub und der Git-CLI","Unterstützung für mehrere Branches und Repositorys"],"pt":["Análise de alterações no branch atual com Git","Criação de solicitações de pull personalizadas com CLI","Integração com o repositório Git","Suporte a branchs personalizadas","Notificação de alterações não commitadas","Suporte a múltiplos commits"],"ru":["Анализ изменений в текущей ветке с помощью Git","Создание индивидуальных запросов на изменения с помощью CLI","Интеграция с репозиторием Git","Поддержка индивидуальных веток","Уведомление о не зафиксированных изменениях","Поддержка нескольких коммитов"],"ar":["تحليل التغييرات في الفرع الحالي باستخدام Git","إنشاء طلبات سحب مخصصة باستخدام واجهة سطر الأوامر","التكامل مع مستودع Git","دعم الفروع المخصصة","إشعار بالتغييرات غير الملتزمة","دعم متعدد Commits"]},"keywords":{"en":["how to use create-pr","create-pr setup guide","automated PR creation","create-pr vs GitHub Actions","create-pr install","what is create-pr","create-pr alternative","create-pr tutorial","Git PR automation"],"zh":["create-pr","AIエージェント","自动化PR创建","Git CLI","PR管理","开发效率","自动化流程"],"ja":["create-pr","AIエージェント","PR作成自動化","Git CLI","PR管理","開発効率","自動化プロセス"],"ko":["create-pr","AI 에이전트","PR 자동 생성","Git CLI","PR 관리","개발 효율성","자동화 프로세스"],"es":["create-pr","herramientas de AI para desarrolladores","automatización de solicitudes de extracción","GitHub","Git","CLI de Git","desarrollo de software","integración continua","automatización de flujos de trabajo"],"fr":["create-pr","outils d''IA pour les développeurs","automatisation des demandes d''extraction","GitHub","Git","CLI de Git","développement de logiciels","intégration continue","automatisation de flux de travail"],"de":["create-pr","AI-Tools für Entwickler","Automatisierung von Pull-Requests","GitHub","Git","Git-CLI","Software-Entwicklung","kontinuierliche Integration","Automatisierung von Workflows"],"pt":["Create-PR","Git","CLI","solicitação de pull","branch","repositório","agentes de IA","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Create-PR","Git","CLI","запрос на изменение","ветка","репозиторий","ИИ Агенты","разработка программного обеспечения","инструменты разработки"],"ar":["Create-PR","Git","واجهة سطر الأوامر","طلب سحب","فرع","مستودع","أدوات الذكاء الاصطناعي","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ippei-shimizu","repo":"buzzbase","repoPath":"ippei-shimizu/buzzbase","stars":25,"forks":3,"updatedAt":"2026-02-26T03:09:46Z","topics":[],"category":"community","skillMd":{"name":"create-pr","description":"現在のブランチからGitHub PRを作成する。差分・コミット履歴を分析し、テンプレートに沿ったタイトルとdescriptionを生成する。「PRを作成して」「プルリク作って」などのリクエストで起動する。作成前に必ずユーザーに確認を取る。","bodyPreview":"# PR作成スキル\n\n現在のブランチの変更内容を分析し、PRを作成する。\n\n## ルール\n\n- PRは `ippei-shimizu/buzzbase` リポジトリに作成する\n- ベースブランチはデフォルトで `stg`（`$ARGUMENTS` で指定があればそちらを使用）\n- すべて日本語で記述する\n- 作成前に必ずユーザーの承認を得る\n- リモートにプッシュされていない場合は先にプッシュする\n\n## ワークフロー\n\n### 1. 現在のブランチ状態を確認\n\n```bash\n# 現在のブランチ名\ngit branch --show-current\n\n# 未コミットの変更がないか確認\ngit status --short\n\n# リモートとの同期状態を確認\ngit log origin/$(git branch --show-current)..HEAD --oneline 2>/dev/null\n\n# ベースブランチからの全コミット\ngit log stg..HEAD --oneline\n\n# ベースブランチからの全差分\ngit diff stg...HEAD --stat\n```","body":"# PR作成スキル\n\n現在のブランチの変更内容を分析し、PRを作成する。\n\n## ルール\n\n- PRは `ippei-shimizu/buzzbase` リポジトリに作成する\n- ベースブランチはデフォルトで `stg`（`$ARGUMENTS` で指定があればそちらを使用）\n- すべて日本語で記述する\n- 作成前に必ずユーザーの承認を得る\n- リモートにプッシュされていない場合は先にプッシュする\n\n## ワークフロー\n\n### 1. 現在のブランチ状態を確認\n\n```bash\n# 現在のブランチ名\ngit branch --show-current\n\n# 未コミットの変更がないか確認\ngit status --short\n\n# リモートとの同期状態を確認\ngit log origin/$(git branch --show-current)..HEAD --oneline 2>/dev/null\n\n# ベースブランチからの全コミット\ngit log stg..HEAD --oneline\n\n# ベースブランチからの全差分\ngit diff stg...HEAD --stat\n```\n\n未コミットの変更がある場合はユーザーに通知し、先にコミットするか確認する。\n\n### 2. 差分の分析\n\nベースブランチからの全コミットと差分を分析する:\n\n```bash\n# コミットメッセージ一覧\ngit log stg..HEAD --format=\"%s\"\n\n# 変更ファイル一覧\ngit diff stg...HEAD --stat\n\n# 詳細な差分（大きい場合はサブエージェントで分析）\ngit diff stg...HEAD\n```\n\n以下を把握する:\n- 変更されたファイルとその種類（新規/変更/削除）\n- 実装の目的と内容\n- 影響範囲（front / back / 両方 / その他）\n- 関連するissue番号（ブランチ名やコミットメッセージから推測）\n\n### 3. PRタイトルの生成\n\n- コミット履歴と差分から変更の主目的を要約する\n- 70文字以内の簡潔な日本語タイトル\n- `$ARGUMENTS` にタイトルのヒントがあればそれを優先する\n\n### 4. PR descriptionの生成\n\n`/pr-description` スキルと同じテンプレートに沿って生成する:\n\n```markdown\n## issue\nclose #ISSUE_NUMBER\n\n## 実装概要\n<!-- 何をしたかを簡潔に（1-3行） -->\n\n## 背景\n<!-- なぜこの変更が必要だったか -->\n\n## やらなかったこと\n<!-- スコープ外にしたこと。なければ「特になし」 -->\n\n## 受入基準\n<!-- この PR がマージ可能と判断するための条件をチェックリストで -->\n- [ ] 基準1\n- [ ] 基準2\n\n## 実装詳細\n<!-- 技術的な実装内容。ファイル単位やモジュール単位で説明 -->\n\n## スクリーンショット\n<!-- UI変更がある場合のみ。なければ「なし」 -->\n\n## 確認手順\n<!-- レビュワーが動作確認するための具体的な手順 -->\n1. 手順1\n2. 手順2\n\n## 影響範囲\n<!-- この変更が影響する画面・機能・モジュール -->\n\n## コード上の懸念点\n<!-- レビュワーに特に見てほしい箇所や、判断に迷った実装 -->\n\n## その他\n<!-- 補足情報。なければ「特になし」 -->\n```\n\n### 5. ユーザーに確認\n\n作成内容を以下のフォーマットでプレビュー表示し、承認を待つ:\n\n```\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nPR プレビュー\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nブランチ: <head-branch> → <base-branch>\nタイトル: <タイトル>\n\n本文:\n<description プレビュー>\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n```\n\nユーザーの明示的な承認（「OK」「作成して」等）を待つ。承認前にPRを作成してはならない。\nフィードバックがあれば修正して再度プレビューを表示する。\n\n### 6. プッシュとPR作成\n\n承認後、以下の順序で実行する:\n\n```bash\n# リモートにプッシュされていない場合\ngit push -u origin $(git branch --show-current)\n\n# PR作成\ngh pr create \\\n  --repo ippei-shimizu/buzzbase \\\n  --base stg \\\n  --title \"<タイトル>\" \\\n  --body \"$(cat <<''EOF''\n<description内容>\nEOF\n)\"\n```\n\n### 7. 結果報告\n\n作成されたPRのURLを表示する。\n\n## 注意事項\n\n- ユーザーの承認なしにPRを作成しない\n- ユーザーの承認なしに `git push` しない\n- 差分から読み取れる事実に基づいて記述し、推測が入る箇所は明示する\n- issue番号がブランチ名やコミットから特定できない場合は `close #` の行は空欄にする（推測で番号を入れない）\n- `$ARGUMENTS` が指定された場合、それをPRの背景コンテキストとして活用する\n- 会話の文脈（直前の実装作業など）がある場合は、それを活用してdescriptionを充実させる\n"},"lastSynced":"2026-03-06T06:40:13.015Z","agentAnalysis":{"suitability":{"en":"Perfect for Git-based Agents needing automated pull request creation and review.","zh":"适合需要自动创建和审查拉取请求的 Git 基础 Agent。","ja":"Git ベースのエージェントが自動的にプルリクエストを作成およびレビューする必要がある場合に適しています。","ko":"자동으로 풀 리퀘스트를 생성하고 검토해야 하는 Git 기반 에이전트에게 적합합니다.","es":"Perfecto para agentes basados en Git que necesitan la creación y revisión automatizada de solicitudes de extracción.","fr":"Parfait pour les agents basés sur Git nécessitant la création et l''examen automatiques des demandes d''extraction.","de":"Perfekt für Git-basierte Agenten, die die automatisierte Erstellung und Überprüfung von Pull-Anfragen benötigen.","pt":"Perfeito para agentes baseados em Git que precisam de criação e revisão de pull requests automatizadas.","ru":"Идеально для агентов на основе Git, которым необходима автоматизированная создание и проверка запросов на слияние.","ar":"مثالي لعميل Git الذي يحتاج إلى إنشاء ومراجعة طلبات السحب التلقائي."},"recommendation":{"en":"Empowers agents to create PRs for review using Git commands and integrates with the ippei-shimizu/buzzbase repository, supporting features like branch analysis and commit validation using protocols like Git log and Git diff.","zh":"赋予代理创建 PR 以供审查的能力，使用 Git 命令，并与 ippei-shimizu/buzzbase 存储库集成，支持分支分析和提交验证等功能，使用 Git log 和 Git diff 等协议。","ja":"エージェントに PR をレビューのために作成する能力を与え、Git コマンドを使用し、ippei-shimizu/buzzbase リポジトリと統合し、ブランチ分析やコミットの検証などの機能をサポートし、Git log や Git diff などのプロトコルを使用します。","ko":"에이전트가 PR을 검토하기 위해 생성할 수 있는 능력을 부여하며, Git 명령을 사용하고, ippei-shimizu/buzzbase 저장소와 통합하여, 분기 분석 및 커밋 확인 等의 기능을 지원하며, Git log 및 Git diff 等의 프로토콜을 사용합니다.","es":"Habilita a los agentes a crear solicitudes de extracción para su revisión utilizando comandos Git e integra con el repositorio ippei-shimizu/buzzbase, que admite características como el análisis de ramas y la validación de confirmaciones utilizando protocolos como Git log y Git diff.","fr":"Permet aux agents de créer des demandes d''extraction pour examen à l''aide de commandes Git et s''intègre au référentiel ippei-shimizu/buzzbase, prenant en charge des fonctionnalités comme l''analyse de branches et la validation des validations à l''aide de protocoles tels que Git log et Git diff.","de":"Ermächtigt Agenten, Pull-Anfragen für die Überprüfung mithilfe von Git-Befehlen zu erstellen und integriert mit dem ippei-shimizu/buzzbase-Repository, das Funktionen wie Branchenanalyse und Commit-Validierung mithilfe von Protokollen wie Git-Log und Git-Diff unterstützt.","pt":"Habilita os agentes a criar PRs para revisão usando comandos Git e se integra com o repositório ippei-shimizu/buzzbase, suportando recursos como análise de branch e validação de commit usando protocolos como Git log e Git diff.","ru":"Наделяет агентов возможностью создавать запросы на слияние для проверки с помощью команд Git и интегрируется с репозиторием ippei-shimizu/buzzbase, поддерживая функции, такие как анализ веток и проверка коммитов с помощью протоколов, таких как Git log и Git diff.","ar":"يمنح الوكيل khảية إنشاء طلبات إدماج للrevision باستخدام أوامر Git ويتكامل مع مستودع ippei-shimizu/buzzbase، ودعم ميزات مثل تحليل الفروع والتحقق من_commit باستخدام بروتوكولات مثل Git log و Git diff."},"useCases":{"en":["Automating PR creation for code reviews","Analyzing branch changes before PR submission","Validating commit history for consistency"],"zh":["自动化代码审查的 PR 创建","提交 PR 前的分支更改分析","提交历史的一致性验证"],"ja":["コードレビューの PR 作成の自動化","PR 提出前のブランチ変更の分析","コミット履歴の一貫性の検証"],"ko":["코드 리뷰를 위한 PR 자동 생성","PR 제출 전의 브랜치 변경 분석","커밋 기록의 일관성 확인"],"es":["Automatización de la creación de solicitudes de extracción para revisiones de código","Análisis de los cambios de rama antes de la presentación de la solicitud de extracción","Validación del historial de confirmaciones para la coherencia"],"fr":["Automatisation de la création de demandes d''extraction pour les examens de code","Analyse des modifications de branche avant la soumission de la demande d''extraction","Validation de l''historique des validations pour la cohérence"],"de":["Automatisierung der Erstellung von Pull-Anfragen für Code-Überprüfungen","Analyse von Branchenänderungen vor der Einreichung der Pull-Anfrage","Validierung der Commit-Historie für Konsistenz"],"pt":["Automatizar a criação de PRs para revisões de código","Analisar alterações de branch antes da submissão de PRs","Validar o histórico de commit para consistência"],"ru":["Автоматизировать создание запросов на слияние для проверки кода","Анализировать изменения веток перед отправкой запросов на слияние","Проверять историю коммитов на последовательность"],"ar":["تحسين إنشاء طلبات الإدماج التلقائي لمراجعة الشفرة","تحليل تغييرات الفرع قبل إرسال طلبات الإدماج","التحقق من تاريخ_commit للاتساق"]},"limitations":{"en":["Requires Git installation and configuration","Limited to ippei-shimizu/buzzbase repository","Needs user authorization before PR creation"],"zh":["需要 Git 安装和配置","仅限于 ippei-shimizu/buzzbase 存储库","需要用户授权才可以创建 PR"],"ja":["Git のインストールと設定が必要","ippei-shimizu/buzzbase リポジトリに限定される","PR の作成にはユーザーの認可が必要"],"ko":["Git 설치 및 구성이 필요함","ippei-shimizu/buzzbase 저장소에만 국한됨","PR 생성 전 사용자 인증이 필요함"],"es":["Requiere la instalación y configuración de Git","Limitado al repositorio ippei-shimizu/buzzbase","Necesita autorización de usuario antes de la creación de la solicitud de extracción"],"fr":["Nécessite l''installation et la configuration de Git","Limité au référentiel ippei-shimizu/buzzbase","Nécessite l''autorisation de l''utilisateur avant la création de la demande d''extraction"],"de":["Benötigt die Installation und Konfiguration von Git","Begrenzt auf das ippei-shimizu/buzzbase-Repository","Benötigt Benutzerberechtigung vor der Erstellung der Pull-Anfrage"],"pt":["Requer instalação e configuração do Git","Limitado ao repositório ippei-shimizu/buzzbase","Necessita de autorização do usuário antes da criação de PRs"],"ru":["Требует установки и настройки Git","Ограничен репозиторием ippei-shimizu/buzzbase","Требует авторизации пользователя перед созданием запросов на слияние"],"ar":["يتطلب تثبيت وتهيئة Git","محدود بمستودع ippei-shimizu/buzzbase","يحتاج إلى تفويض المستخدم قبل إنشاء طلبات الإدماج"]},"version":4},"contentHash":"d9581e2ed65928d4a2c956c0ca8c2bf6115074f34c1a2a88e755d5fb8bbef3d7","qualityScore":35}');
