INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ippei-shimizu/buzzbase/create-pr', 'create-pr', 'ippei-shimizu', 'buzzbase', 'community', 'create-pr ippei-shimizu buzzbase community The create-pr skill analyzes changes in the current branch and creates a PR for review. It supports Git commands and integrates with the ippei-shimizu/buzzbase repository. create-pr技能用于自动化PR创建流程，通过分析当前分支的变化并创建PR create-prスキルは、現在のブランチの変更内容を分析し、PRを作成することでPR作成を自動化する create-pr 스킬은 현재 브랜치의 변경 사항을 분석하여 PR을 자동 생성합니다 Create-pr es una herramienta de AI que analiza los cambios en la rama actual y crea solicitudes de extracción en el repositorio de GitHub Create-pr est un outil d''IA qui analyse les modifications dans la branche actuelle et crée des demandes d''extraction dans le référentiel GitHub Create-pr ist ein AI-Tool, das die Änderungen im aktuellen Branch analysiert und Pull-Requests im GitHub-Repository erstellt O Create-PR é uma ferramenta que analisa as alterações no branch atual e cria solicitações de pull personalizadas com o Git e CLI. Create-PR - это инструмент, который анализирует изменения в текущей ветке и создает индивидуальные запросы на изменения с помощью Git и CLI. Create-PR هو أداة تحليل التغييرات في الفرع الحالي وإنشاء طلبات سحب مخصصة باستخدام Git وواجهة سطر الأوامر how to use create-pr create-pr setup guide automated PR creation create-pr vs GitHub Actions create-pr install what is create-pr create-pr alternative create-pr tutorial Git PR automation create-pr AIエージェント 自动化PR创建 Git CLI PR管理 开发效率 自动化流程 Analyzes current branch changes using Git commands Creates PRs in the ippei-shimizu/buzzbase repository Supports custom base branches via $ARGUMENTS Checks for uncommitted changes using git status --short Pushes changes to remote repositories before creating PRs create-pr is a skill that automates the creation of pull requests (PRs) for code changes, using Git commands and repository integrations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tanepiper/teskooano/particles-physics', 'community', 'tanepiper', 'teskooano', 'tanepiper/teskooano', 'particles-physics', 25, 2, 35, '2026-02-19T20:15:49Z', '2026-03-07T01:51:10.329Z', '2de0749455508e6bd2391d39bc4caa6fc78853c046a1d245028465b7f0960478', '{"id":"tanepiper/teskooano/particles-physics","name":"particles-physics","description":{"en":"particles-physics is a Multi-camera ThreeJS powered 3D N-body simulator, enabling developers to create dynamic particle motion by applying forces, fields, and constraints. It benefits developers working with 3D simulations and physics.","zh":"particles-physics Skill是一个基于ThreeJS的三维N体模拟器，用于创建动态粒子运动","ja":"particles-physics SkillはThreeJSを使用した3D N体シミュレーターで、ダイナミックな粒子運動を作成する","ko":"particles-physics Skill은 ThreeJS를 기반으로 하는 3D N體 시뮬레이터로서 동적 입자 운동을 생성","es":"El simulador de partículas físicas es una herramienta de simulación 3D que utiliza ThreeJS para aplicar fuerzas y campos a partículas en movimiento","fr":"Le simulateur de physique des particules est un outil de simulation 3D qui utilise ThreeJS pour appliquer des forces et des champs à des particules en mouvement","de":"Der Partikelphysik-Simulator ist ein 3D-Simulationswerkzeug, das ThreeJS verwendet, um Kräfte und Felder auf sich bewegende Partikel anzuwenden","pt":"O skill particles-physics é uma ferramenta de simulação de física de partículas em 3D, alimentada pelo ThreeJS.","ru":"Навык particles-physics - это инструмент для симуляции физики частиц в 3D, основанный на ThreeJS.","ar":"مهارة particles-physics هي أداة محاكاة فيزياء الجسيمات ثلاثية الأبعاد مدعومة من ThreeJS."},"seo":{"title":{"en":"particles-physics: 3D N-body Simulator Setup Guide | AI A...","zh":"particles-physics 三维模拟器设置指南","ja":"particles-physics 3Dシミュレーターのベストプラクティス","ko":"particles-physics 3D 시뮬레이터 구축 가이드","es":"Guía de configuración de partículas físicas con ThreeJS","fr":"Guide de démarrage rapide de la physique des particules a...","de":"Einrichtungsleitfaden für Partikelphysik mit ThreeJS","pt":"Guia de Configuração de Partículas Físicas com ThreeJS","ru":"ИИ Агенты: Настройка Физики Частиц с ThreeJS","ar":"دليل إعداد الجسيمات الفيزيائية مع ThreeJS"},"description":{"en":"Unlock dynamic particle motion with particles-physics! Learn how to apply forces, fields, and constraints using ThreeJS and discover the power of n-body simu...","zh":"使用particles-physics Skill创建三维N体模拟，实现动态粒子运动","ja":"particles-physics Skillを使用して3D N体シミュレーションを作成し、ダイナミックな粒子運動を実現","ko":"particles-physics Skill을 사용하여 3D N體 시뮬레이션을 생성하고 동적 입자 운동을 구현","es":"Simula el movimiento de partículas con fuerzas, campos y restricciones en 3D con ThreeJS","fr":"Simulez le mouvement de particules avec des forces, des champs et des contraintes en 3D avec ThreeJS","de":"Simulieren Sie die Bewegung von Partikeln mit Kräften, Feldern und Einschränkungen in 3D mit ThreeJS","pt":"Aprenda a criar simulações de física de partículas com o skill particles-physics e ThreeJS","ru":"Создавайте симуляции физики частиц с помощью навыка particles-physics и ThreeJS","ar":"تعلم كيفية إنشاء محاكاة الفيزياء الجزيئية مع مهارة particles-physics و ThreeJS"},"definition":{"en":"particles-physics is a 3D N-body simulator that applies forces, fields, and constraints to create dynamic particle motion using ThreeJS.","zh":"particles-physics Skill是一种创建三维N体模拟的技术，用于模拟粒子之间的相互作用","ja":"particles-physics Skillは3D N体シミュレーションを作成する技術で、粒子間の相互作用をシミュレート","ko":"particles-physics Skill은 3D N體 시뮬레이션을 생성하는 기술로서 입자 간 상호작용을 시뮬레이트","es":"Un simulador de partículas físicas es una herramienta que aplica fuerzas y campos a partículas en movimiento en un entorno 3D","fr":"Un simulateur de physique des particules est un outil qui applique des forces et des champs à des particules en mouvement dans un environnement 3D","de":"Ein Partikelphysik-Simulator ist ein Werkzeug, das Kräfte und Felder auf sich bewegende Partikel in einer 3D-Umgebung anwendet","pt":"O que é particles-physics? É uma simulação de física de partículas em 3D que aplica forças e campos.","ru":"Что такое particles-physics? Это симуляция физики частиц в 3D, которая применяет силы и поля.","ar":"ما هي particles-physics؟ إنه محاكاة فيزياء الجسيمات ثلاثية الأبعاد التي تطبيقات القوى والحقول."},"features":{"en":["Applies gravity and velocity using the `useFrame` function","Updates particle positions using `positions` and `velocities` arrays","Utilizes ThreeJS for 3D rendering and simulation","Supports multi-camera setup for enhanced visualization","Enables dynamic particle motion through forces, fields, and constraints"],"zh":["基于ThreeJS的三维渲染","支持N体模拟","实现动态粒子运动","使用useFrame函数更新粒子位置","支持多摄像头模拟"],"ja":["ThreeJSを使用した3Dレンダリング","N体シミュレーションのサポート","ダイナミックな粒子運動の実現","useFrame関数を使用した粒子位置の更新","マルチカメラシミュレーションのサポート"],"ko":["ThreeJS를 기반으로 하는 3D 렌더링","N體 시뮬레이션 지원","동적 입자 운동 구현","useFrame 함수를 사용한 입자 위치 업데이트","멀티 카메라 시뮬레이션 지원"],"es":["Simulación de movimiento de partículas en 3D","Aplicación de fuerzas y campos a partículas","Uso de ThreeJS para renderizar gráficos 3D","Actualización de posiciones y velocidades de partículas","Compatibilidad con múltiples cámaras"],"fr":["Simulation du mouvement de particules en 3D","Application de forces et de champs à des particules","Utilisation de ThreeJS pour rendre des graphiques 3D","Mise à jour des positions et des vitesses des particules","Compatibilité avec plusieurs caméras"],"de":["Simulierung der Bewegung von Partikeln in 3D","Anwendung von Kräften und Feldern auf Partikel","Verwendung von ThreeJS für die Darstellung von 3D-Grafiken","Aktualisierung der Positionen und Geschwindigkeiten von Partikeln","Kompatibilität mit mehreren Kameras"],"pt":["Simulação de física de partículas em 3D com ThreeJS","Aplicação de forças e campos para criar movimento dinâmico","Cálculo de posição e velocidade das partículas","Integração com geometria e atributos de posição","Suporte a múltiplas câmeras"],"ru":["Симуляция физики частиц в 3D с помощью ThreeJS","Применение сил и полей для создания динамического движения","Расчет позиции и скорости частиц","Интеграция с геометрией и атрибутами позиции","Поддержка нескольких камер"],"ar":["محاكاة فيزياء الجسيمات ثلاثية الأبعاد مع ThreeJS","تطبيق القوى والحقول لإنشاء حركة ديناميكية","حساب موقع وسرعة الجسيمات","التكامل مع الهندسة وسمات الموقع","دعم الكاميرات المتعددة"]},"keywords":{"en":["how to use particles-physics","particles-physics alternative","particles-physics setup guide","what is particles-physics","particles-physics vs ThreeJS","particles-physics install","n-body simulation with particles-physics","particles-physics documentation","particles-physics tutorial"],"zh":["particles-physics","ThreeJS","N体模拟","动态粒子运动","useFrame函数","三维渲染","AIエージェント","AI工具"],"ja":["particles-physics","ThreeJS","N体シミュレーション","ダイナミックな粒子運動","useFrame関数","3Dレンダリング","AIエージェント","AIツール"],"ko":["particles-physics","ThreeJS","N體 시뮬레이션","동적 입자 운동","useFrame 함수","3D 렌더링","AI 에이전트","AI 툴"],"es":["partículas físicas","simulación 3D","ThreeJS","fuerzas y campos","movimiento de partículas","simulador de partículas","herramientas de simulación","desarrollo de juegos","visualización de datos"],"fr":["physique des particules","simulation 3D","ThreeJS","forces et champs","mouvement de particules","simulateur de particules","outils de simulation","développement de jeux","visualisation de données"],"de":["Partikelphysik","3D-Simulation","ThreeJS","Kräfte und Felder","Bewegung von Partikeln","Partikel-Simulator","Simulationswerkzeuge","Spieleentwicklung","Datenvisualisierung"],"pt":["particles-physics","simulação de física de partículas","ThreeJS","física de partículas em 3D","aplicação de forças e campos","cálculo de posição e velocidade","geometria e atributos de posição"],"ru":["particles-physics","симуляция физики частиц","ThreeJS","физика частиц в 3D","применение сил и полей","расчет позиции и скорости","геометрия и атрибуты позиции"],"ar":["particles-physics","محاكاة فيزياء الجسيمات","ThreeJS","فيزياء الجسيمات ثلاثية الأبعاد","تطبيق القوى والحقول","حساب موقع وسرعة الجسيمات","الهندسة وسمات الموقع"]}},"owner":"tanepiper","repo":"teskooano","repoPath":"tanepiper/teskooano","stars":25,"forks":2,"updatedAt":"2026-02-19T20:15:49Z","topics":["nbody-simulation","physics-simulation","threejs"],"category":"community","skillMd":{"name":"particles-physics","description":"Physics simulation for particle systems—forces (gravity, wind, drag), attractors/repulsors, velocity fields, turbulence, and collision. Use when particles need realistic or artistic motion, swarm behavior, or field-based animation.","bodyPreview":"# Particle Physics\n\nApply forces, fields, and constraints to create dynamic particle motion.\n\n## Quick Start\n\n```tsx\n// Simple gravity + velocity\nuseFrame((_, delta) => {\n  for (let i = 0; i < count; i++) {\n    // Apply gravity\n    velocities[i * 3 + 1] -= 9.8 * delta;\n\n    // Update position\n    positions[i * 3] += velocities[i * 3] * delta;\n    positions[i * 3 + 1] += velocities[i * 3 + 1] * delta;\n    positions[i * 3 + 2] += velocities[i * 3 + 2] * delta;\n  }\n  geometry.attributes.position.ne","body":"# Particle Physics\n\nApply forces, fields, and constraints to create dynamic particle motion.\n\n## Quick Start\n\n```tsx\n// Simple gravity + velocity\nuseFrame((_, delta) => {\n  for (let i = 0; i < count; i++) {\n    // Apply gravity\n    velocities[i * 3 + 1] -= 9.8 * delta;\n\n    // Update position\n    positions[i * 3] += velocities[i * 3] * delta;\n    positions[i * 3 + 1] += velocities[i * 3 + 1] * delta;\n    positions[i * 3 + 2] += velocities[i * 3 + 2] * delta;\n  }\n  geometry.attributes.position.needsUpdate = true;\n});\n```\n\n## Force Types\n\n### Gravity (Constant Force)\n\n```tsx\nfunction applyGravity(\n  velocities: Float32Array,\n  count: number,\n  gravity: THREE.Vector3,\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    velocities[i * 3] += gravity.x * delta;\n    velocities[i * 3 + 1] += gravity.y * delta;\n    velocities[i * 3 + 2] += gravity.z * delta;\n  }\n}\n\n// Usage\nconst gravity = new THREE.Vector3(0, -9.8, 0);\napplyGravity(velocities, count, gravity, delta);\n```\n\n### Wind (Directional + Noise)\n\n```tsx\nfunction applyWind(\n  velocities: Float32Array,\n  positions: Float32Array,\n  count: number,\n  direction: THREE.Vector3,\n  strength: number,\n  turbulence: number,\n  time: number,\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const x = positions[i * 3];\n    const y = positions[i * 3 + 1];\n    const z = positions[i * 3 + 2];\n\n    // Base wind\n    let wx = direction.x * strength;\n    let wy = direction.y * strength;\n    let wz = direction.z * strength;\n\n    // Add turbulence (using simple noise approximation)\n    const noise = Math.sin(x * 0.5 + time) * Math.cos(z * 0.5 + time);\n    wx += noise * turbulence;\n    wy += Math.sin(y * 0.3 + time * 1.3) * turbulence * 0.5;\n    wz += Math.cos(x * 0.4 + time * 0.7) * turbulence;\n\n    velocities[i * 3] += wx * delta;\n    velocities[i * 3 + 1] += wy * delta;\n    velocities[i * 3 + 2] += wz * delta;\n  }\n}\n```\n\n### Drag (Velocity Damping)\n\n```tsx\nfunction applyDrag(\n  velocities: Float32Array,\n  count: number,\n  drag: number, // 0-1, higher = more drag\n  delta: number,\n) {\n  const factor = 1 - drag * delta;\n\n  for (let i = 0; i < count; i++) {\n    velocities[i * 3] *= factor;\n    velocities[i * 3 + 1] *= factor;\n    velocities[i * 3 + 2] *= factor;\n  }\n}\n\n// Quadratic drag (more realistic)\nfunction applyQuadraticDrag(\n  velocities: Float32Array,\n  count: number,\n  coefficient: number,\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const vx = velocities[i * 3];\n    const vy = velocities[i * 3 + 1];\n    const vz = velocities[i * 3 + 2];\n\n    const speed = Math.sqrt(vx * vx + vy * vy + vz * vz);\n    if (speed > 0) {\n      const dragForce = coefficient * speed * speed;\n      const factor = Math.max(0, 1 - (dragForce * delta) / speed);\n\n      velocities[i * 3] *= factor;\n      velocities[i * 3 + 1] *= factor;\n      velocities[i * 3 + 2] *= factor;\n    }\n  }\n}\n```\n\n## Attractors & Repulsors\n\n### Point Attractor\n\n```tsx\nfunction applyAttractor(\n  velocities: Float32Array,\n  positions: Float32Array,\n  count: number,\n  attractorPos: THREE.Vector3,\n  strength: number, // Positive = attract, negative = repel\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const dx = attractorPos.x - positions[i * 3];\n    const dy = attractorPos.y - positions[i * 3 + 1];\n    const dz = attractorPos.z - positions[i * 3 + 2];\n\n    const distSq = dx * dx + dy * dy + dz * dz;\n    const dist = Math.sqrt(distSq);\n\n    if (dist > 0.1) {\n      // Avoid division by zero\n      // Inverse square falloff\n      const force = strength / distSq;\n\n      velocities[i * 3] += (dx / dist) * force * delta;\n      velocities[i * 3 + 1] += (dy / dist) * force * delta;\n      velocities[i * 3 + 2] += (dz / dist) * force * delta;\n    }\n  }\n}\n```\n\n### Orbit Attractor\n\n```tsx\nfunction applyOrbitAttractor(\n  velocities: Float32Array,\n  positions: Float32Array,\n  count: number,\n  center: THREE.Vector3,\n  orbitStrength: number,\n  pullStrength: number,\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const dx = positions[i * 3] - center.x;\n    const dy = positions[i * 3 + 1] - center.y;\n    const dz = positions[i * 3 + 2] - center.z;\n\n    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);\n\n    if (dist > 0.1) {\n      // Tangential force (orbit)\n      const tx = -dz / dist;\n      const tz = dx / dist;\n\n      velocities[i * 3] += tx * orbitStrength * delta;\n      velocities[i * 3 + 2] += tz * orbitStrength * delta;\n\n      // Radial force (pull toward center)\n      velocities[i * 3] -= (dx / dist) * pullStrength * delta;\n      velocities[i * 3 + 1] -= (dy / dist) * pullStrength * delta;\n      velocities[i * 3 + 2] -= (dz / dist) * pullStrength * delta;\n    }\n  }\n}\n```\n\n### Multiple Attractors\n\n```tsx\ninterface Attractor {\n  position: THREE.Vector3;\n  strength: number;\n  radius: number; // Influence radius\n}\n\nfunction applyAttractors(\n  velocities: Float32Array,\n  positions: Float32Array,\n  count: number,\n  attractors: Attractor[],\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const px = positions[i * 3];\n    const py = positions[i * 3 + 1];\n    const pz = positions[i * 3 + 2];\n\n    for (const attractor of attractors) {\n      const dx = attractor.position.x - px;\n      const dy = attractor.position.y - py;\n      const dz = attractor.position.z - pz;\n\n      const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);\n\n      if (dist > 0.1 && dist < attractor.radius) {\n        // Smooth falloff within radius\n        const falloff = 1 - dist / attractor.radius;\n        const force = attractor.strength * falloff * falloff;\n\n        velocities[i * 3] += (dx / dist) * force * delta;\n        velocities[i * 3 + 1] += (dy / dist) * force * delta;\n        velocities[i * 3 + 2] += (dz / dist) * force * delta;\n      }\n    }\n  }\n}\n```\n\n## Velocity Fields\n\n### Curl Noise Field\n\n```tsx\n// In shader (GPU)\nvec3 curlNoise(vec3 p) {\n  const float e = 0.1;\n\n  vec3 dx = vec3(e, 0.0, 0.0);\n  vec3 dy = vec3(0.0, e, 0.0);\n  vec3 dz = vec3(0.0, 0.0, e);\n\n  float n1 = snoise(p + dy) - snoise(p - dy);\n  float n2 = snoise(p + dz) - snoise(p - dz);\n  float n3 = snoise(p + dx) - snoise(p - dx);\n  float n4 = snoise(p + dz) - snoise(p - dz);\n  float n5 = snoise(p + dx) - snoise(p - dx);\n  float n6 = snoise(p + dy) - snoise(p - dy);\n\n  return normalize(vec3(n1 - n2, n3 - n4, n5 - n6));\n}\n\n// Usage in vertex shader\nvec3 velocity = curlNoise(position * 0.5 + uTime * 0.1);\nposition += velocity * delta;\n```\n\n### Flow Field (2D/3D Grid)\n\n```tsx\nclass FlowField {\n  private field: THREE.Vector3[];\n  private resolution: number;\n  private size: number;\n\n  constructor(resolution: number, size: number) {\n    this.resolution = resolution;\n    this.size = size;\n    this.field = [];\n\n    for (let i = 0; i < resolution ** 3; i++) {\n      this.field.push(new THREE.Vector3());\n    }\n  }\n\n  // Generate field from noise\n  generate(time: number, scale: number) {\n    for (let x = 0; x < this.resolution; x++) {\n      for (let y = 0; y < this.resolution; y++) {\n        for (let z = 0; z < this.resolution; z++) {\n          const index =\n            x + y * this.resolution + z * this.resolution * this.resolution;\n\n          // Use noise to generate flow direction\n          const wx = (x / this.resolution) * scale;\n          const wy = (y / this.resolution) * scale;\n          const wz = (z / this.resolution) * scale;\n\n          const angle1 = noise3D(wx, wy, wz + time) * Math.PI * 2;\n          const angle2 = noise3D(wx + 100, wy, wz + time) * Math.PI * 2;\n\n          this.field[index].set(\n            Math.cos(angle1) * Math.cos(angle2),\n            Math.sin(angle2),\n            Math.sin(angle1) * Math.cos(angle2),\n          );\n        }\n      }\n    }\n  }\n\n  // Sample field at position\n  sample(position: THREE.Vector3): THREE.Vector3 {\n    const halfSize = this.size / 2;\n\n    const x = Math.floor(\n      ((position.x + halfSize) / this.size) * this.resolution,\n    );\n    const y = Math.floor(\n      ((position.y + halfSize) / this.size) * this.resolution,\n    );\n    const z = Math.floor(\n      ((position.z + halfSize) / this.size) * this.resolution,\n    );\n\n    const cx = Math.max(0, Math.min(this.resolution - 1, x));\n    const cy = Math.max(0, Math.min(this.resolution - 1, y));\n    const cz = Math.max(0, Math.min(this.resolution - 1, z));\n\n    const index =\n      cx + cy * this.resolution + cz * this.resolution * this.resolution;\n    return this.field[index];\n  }\n}\n```\n\n### Vortex Field\n\n```tsx\nfunction applyVortex(\n  velocities: Float32Array,\n  positions: Float32Array,\n  count: number,\n  center: THREE.Vector3,\n  axis: THREE.Vector3, // Normalized\n  strength: number,\n  falloff: number,\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const dx = positions[i * 3] - center.x;\n    const dy = positions[i * 3 + 1] - center.y;\n    const dz = positions[i * 3 + 2] - center.z;\n\n    // Project onto plane perpendicular to axis\n    const dot = dx * axis.x + dy * axis.y + dz * axis.z;\n    const px = dx - dot * axis.x;\n    const py = dy - dot * axis.y;\n    const pz = dz - dot * axis.z;\n\n    const dist = Math.sqrt(px * px + py * py + pz * pz);\n\n    if (dist > 0.1) {\n      // Tangent direction (cross product with axis)\n      const tx = axis.y * pz - axis.z * py;\n      const ty = axis.z * px - axis.x * pz;\n      const tz = axis.x * py - axis.y * px;\n\n      const tLen = Math.sqrt(tx * tx + ty * ty + tz * tz);\n      const force = strength * Math.exp(-dist * falloff);\n\n      velocities[i * 3] += (tx / tLen) * force * delta;\n      velocities[i * 3 + 1] += (ty / tLen) * force * delta;\n      velocities[i * 3 + 2] += (tz / tLen) * force * delta;\n    }\n  }\n}\n```\n\n## Turbulence\n\n### Simplex-Based Turbulence\n\n```glsl\n// GPU turbulence in vertex shader\nvec3 turbulence(vec3 p, float time, float scale, int octaves) {\n  vec3 result = vec3(0.0);\n  float amplitude = 1.0;\n  float frequency = scale;\n\n  for (int i = 0; i < octaves; i++) {\n    vec3 samplePos = p * frequency + time;\n    result.x += snoise(samplePos) * amplitude;\n    result.y += snoise(samplePos + vec3(100.0)) * amplitude;\n    result.z += snoise(samplePos + vec3(200.0)) * amplitude;\n\n    frequency *= 2.0;\n    amplitude *= 0.5;\n  }\n\n  return result;\n}\n```\n\n### CPU Turbulence\n\n```tsx\nfunction applyTurbulence(\n  velocities: Float32Array,\n  positions: Float32Array,\n  count: number,\n  strength: number,\n  scale: number,\n  time: number,\n  delta: number,\n) {\n  for (let i = 0; i < count; i++) {\n    const x = positions[i * 3] * scale;\n    const y = positions[i * 3 + 1] * scale;\n    const z = positions[i * 3 + 2] * scale;\n\n    // Simple noise approximation\n    const nx = Math.sin(x + time) * Math.cos(z + time * 0.7);\n    const ny = Math.sin(y + time * 1.3) * Math.cos(x + time * 0.5);\n    const nz = Math.sin(z + time * 0.9) * Math.cos(y + time * 1.1);\n\n    velocities[i * 3] += nx * strength * delta;\n    velocities[i * 3 + 1] += ny * strength * delta;\n    velocities[i * 3 + 2] += nz * strength * delta;\n  }\n}\n```\n\n## Collision\n\n### Plane Collision\n\n```tsx\nfunction collidePlane(\n  positions: Float32Array,\n  velocities: Float32Array,\n  count: number,\n  planeY: number,\n  bounce: number, // 0-1\n) {\n  for (let i = 0; i < count; i++) {\n    if (positions[i * 3 + 1] < planeY) {\n      positions[i * 3 + 1] = planeY;\n      velocities[i * 3 + 1] *= -bounce;\n    }\n  }\n}\n```\n\n### Sphere Collision\n\n```tsx\nfunction collideSphere(\n  positions: Float32Array,\n  velocities: Float32Array,\n  count: number,\n  center: THREE.Vector3,\n  radius: number,\n  bounce: number,\n  inside: boolean, // true = contain inside, false = repel from outside\n) {\n  for (let i = 0; i < count; i++) {\n    const dx = positions[i * 3] - center.x;\n    const dy = positions[i * 3 + 1] - center.y;\n    const dz = positions[i * 3 + 2] - center.z;\n\n    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);\n\n    const collision = inside ? dist > radius : dist < radius;\n\n    if (collision && dist > 0) {\n      const nx = dx / dist;\n      const ny = dy / dist;\n      const nz = dz / dist;\n\n      // Move to surface\n      const targetDist = inside ? radius : radius;\n      positions[i * 3] = center.x + nx * targetDist;\n      positions[i * 3 + 1] = center.y + ny * targetDist;\n      positions[i * 3 + 2] = center.z + nz * targetDist;\n\n      // Reflect velocity\n      const dot =\n        velocities[i * 3] * nx +\n        velocities[i * 3 + 1] * ny +\n        velocities[i * 3 + 2] * nz;\n      velocities[i * 3] = (velocities[i * 3] - 2 * dot * nx) * bounce;\n      velocities[i * 3 + 1] = (velocities[i * 3 + 1] - 2 * dot * ny) * bounce;\n      velocities[i * 3 + 2] = (velocities[i * 3 + 2] - 2 * dot * nz) * bounce;\n    }\n  }\n}\n```\n\n## Integration Methods\n\n### Euler (Simple)\n\n```tsx\n// Fastest, least accurate\nposition += velocity * delta;\nvelocity += acceleration * delta;\n```\n\n### Verlet (Better for constraints)\n\n```tsx\n// Store previous position\nconst newPos = position * 2 - prevPosition + acceleration * delta * delta;\nprevPosition = position;\nposition = newPos;\n```\n\n### RK4 (Most accurate)\n\n```tsx\n// Runge-Kutta 4th order (for high precision)\nfunction rk4(\n  position: number,\n  velocity: number,\n  acceleration: (p: number, v: number) => number,\n  dt: number,\n) {\n  const k1v = acceleration(position, velocity);\n  const k1x = velocity;\n\n  const k2v = acceleration(\n    position + (k1x * dt) / 2,\n    velocity + (k1v * dt) / 2,\n  );\n  const k2x = velocity + (k1v * dt) / 2;\n\n  const k3v = acceleration(\n    position + (k2x * dt) / 2,\n    velocity + (k2v * dt) / 2,\n  );\n  const k3x = velocity + (k2v * dt) / 2;\n\n  const k4v = acceleration(position + k3x * dt, velocity + k3v * dt);\n  const k4x = velocity + k3v * dt;\n\n  return {\n    position: position + ((k1x + 2 * k2x + 2 * k3x + k4x) * dt) / 6,\n    velocity: velocity + ((k1v + 2 * k2v + 2 * k3v + k4v) * dt) / 6,\n  };\n}\n```\n\n## File Structure\n\n```\nparticles-physics/\n├── SKILL.md\n├── references/\n│   ├── forces.md             # All force types\n│   └── integration.md        # Integration methods comparison\n└── scripts/\n    ├── forces/\n    │   ├── gravity.ts        # Gravity implementations\n    │   ├── attractors.ts     # Point/orbit attractors\n    │   └── fields.ts         # Flow/velocity fields\n    └── collision/\n        ├── planes.ts         # Plane collision\n        └── shapes.ts         # Sphere, box collision\n```\n\n## Reference\n\n- `references/forces.md` — Complete force implementations\n- `references/integration.md` — When to use which integration method\n"},"lastSynced":"2026-03-07T01:51:10.329Z","agentAnalysis":{"suitability":{"en":"Perfect for Simulation Agents needing advanced 3D particle physics capabilities with ThreeJS","zh":"适合需要高级 3D 粒子物理功能的模拟代理，搭配 ThreeJS","ja":"ThreeJS を使用して高度な 3D 粒子物理シミュレーションが必要なシミュレーション エージェントに適しています","ko":"ThreeJS와 함께 고급 3D 입자 물리 기능이 필요한 시뮬레이션 에이전트에 적합합니다","es":"Perfecto para agentes de simulación que necesitan capacidades de física de partículas 3D avanzadas con ThreeJS","fr":"Parfait pour les agents de simulation nécessitant des capacités de physique de particules 3D avancées avec ThreeJS","de":"Perfekt für Simulationsagenten, die erweiterte 3D-Partikel-Physik-Funktionen mit ThreeJS benötigen","pt":"Perfeito para Agentes de Simulação que necessitam de capacidades avançadas de física de partículas 3D com ThreeJS","ru":"Идеально подходит для агентов симуляции, которым необходимы продвинутые возможности физики частиц 3D с ThreeJS","ar":"مثالي لعمليات المحاكاة التي تحتاج إلى قدرات فيزياء الجسيمات ثلاثية الأبعاد متقدمة مع ThreeJS"},"recommendation":{"en":"Empowers agents to create dynamic particle motion by applying forces, fields, and constraints using ThreeJS, enabling realistic 3D simulations and physics-based interactions","zh":"赋予代理创建动态粒子运动的能力，通过 ThreeJS 应用力、场和约束，实现真实的 3D 模拟和基于物理的交互","ja":"ThreeJS を使用して力、場、制約を適用して、ダイナミックな粒子運動を作成することで、リアルな 3D シミュレーションと物理ベースのインタラクションを可能にします","ko":"ThreeJS를 사용하여 힘, 필드, 제약 조건을 적용하여 동적 입자 운동을 생성하여 실제적인 3D 시뮬레이션과 물리 기반 상호 작용을 가능하게 합니다","es":"Habilita a los agentes a crear un movimiento de partículas dinámico aplicando fuerzas, campos y restricciones utilizando ThreeJS, lo que permite simulaciones 3D realistas y interacciones basadas en la física","fr":"Permet aux agents de créer un mouvement de particules dynamique en appliquant des forces, des champs et des contraintes à l''aide de T