INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tanepiper/teskooano/particles-physics', 'particles-physics', 'tanepiper', 'teskooano', 'community', 'particles-physics tanepiper teskooano community nbody-simulation physics-simulation threejs particles-physics is a Multi-camera ThreeJS powered 3D N-body simulator, enabling developers to create dynamic particle motion by applying forces, fields, and constraints. It benefits developers working with 3D simulations and physics. particles-physics Skill是一个基于ThreeJS的三维N体模拟器，用于创建动态粒子运动 particles-physics SkillはThreeJSを使用した3D N体シミュレーターで、ダイナミックな粒子運動を作成する particles-physics Skill은 ThreeJS를 기반으로 하는 3D N體 시뮬레이터로서 동적 입자 운동을 생성 El simulador de partículas físicas es una herramienta de simulación 3D que utiliza ThreeJS para aplicar fuerzas y campos a partículas en movimiento Le simulateur de physique des particules est un outil de simulation 3D qui utilise ThreeJS pour appliquer des forces et des champs à des particules en mouvement Der Partikelphysik-Simulator ist ein 3D-Simulationswerkzeug, das ThreeJS verwendet, um Kräfte und Felder auf sich bewegende Partikel anzuwenden O skill particles-physics é uma ferramenta de simulação de física de partículas em 3D, alimentada pelo ThreeJS. Навык particles-physics - это инструмент для симуляции физики частиц в 3D, основанный на ThreeJS. مهارة particles-physics هي أداة محاكاة فيزياء الجسيمات ثلاثية الأبعاد مدعومة من ThreeJS. how to use particles-physics particles-physics alternative particles-physics setup guide what is particles-physics particles-physics vs ThreeJS particles-physics install n-body simulation with particles-physics particles-physics documentation particles-physics tutorial particles-physics ThreeJS N体模拟 动态粒子运动 useFrame函数 三维渲染 AIエージェント AI工具 Applies gravity and velocity using the `useFrame` function Updates particle positions using `positions` and `velocities` arrays Utilizes ThreeJS for 3D rendering and simulation Supports multi-camera setup for enhanced visualization Enables dynamic particle motion through forces, fields, and constraints particles-physics is a 3D N-body simulator that applies forces, fields, and constraints to create dynamic particle motion using ThreeJS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OpenDCAI/leonai/oiloil-ui-ux-guide', 'community', 'OpenDCAI', 'leonai', 'OpenDCAI/leonai', 'oiloil-ui-ux-guide', 20, 1, 35, '2026-02-23T11:28:25Z', '2026-03-06T06:41:30.203Z', 'f7056af0569cb3d9a559b6e438b5b187cb038dd8ed19324cffa82e5628ff3503', '{"id":"OpenDCAI/leonai/oiloil-ui-ux-guide","name":"oiloil-ui-ux-guide","description":{"en":"The oiloil-ui-ux-guide skill provides compact principles and concrete do/don''t rules for modern clean UI/UX, benefiting developers and designers. It offers two modes: guide and review.","zh":"OilOil UI/UX 指南提供现代极简设计的原则和最佳实践，帮助开发者优化用户界面设计","ja":"OilOil UI/UX ガイドは、モダン・マイナム デザインの原則とベストプラクティスを提供し、開発者がユーザー インターフェイス設計を最適化するのに役立ちます","ko":"OilOil UI/UX 가이드는 현대적 최소한의 디자인 원칙과 모범 사례를 제공하여 개발자가 사용자 인터페이스 디자인을 최적화하는 데 도움이 됩니다","es":"La guía oiloil-ui-ux-guide te ayuda a crear interfaces de usuario modernas y minimalistas. Ofrece principios compactos y reglas concretas para mejorar la experiencia del usuario.","fr":"Le guide oiloil-ui-ux-guide vous aide à créer des interfaces utilisateur modernes et minimalistes. Il propose des principes compacts et des règles concrètes pour améliorer l''expérience utilisateur.","de":"Die Anleitung oiloil-ui-ux-guide hilft Ihnen bei der Erstellung moderner und minimalistischer Benutzeroberflächen. Sie bietet kompakte Prinzipien und konkrete Regeln für die Verbesserung der Benutzererfahrung.","pt":"O oiloil-ui-ux-guide é uma ferramenta para criar interfaces de usuário modernas e minimalistas. Fornece diretrizes e regras concretas para melhorar a UI/UX","ru":"ИИ Агент oiloil-ui-ux-guide предназначен для создания современных и минималистских интерфейсов пользователя. Он предоставляет руководство и конкретные правила для улучшения вашей UI/UX","ar":"دليل تصميم واجهة المستخدم وتجربة المستخدم oiloil-ui-ux-guide هو أداة لإنشاء واجهات مستخدم حديثة وتصميمات بسيطة. يقدم إرشادات وقواعد محددة لتحسين تجربة المستخدم"},"seo":{"title":{"en":"oiloil-ui-ux-guide: Modern Minimal UI/UX Setup Guide | AI...","zh":"OilOil UI/UX 指南：现代极简设计最佳实践","ja":"OilOil UI/UX ガイド：モダン・マイナム デザインのためのベストプラクティス","ko":"OilOil UI/UX 가이드: 현대적 최소한의 디자인 설정","es":"Guía de UI/UX Moderna Minimalista: Configuración y Mejore...","fr":"Guide UI/UX Moderne Minimaliste: Mise en Place et Bonnes ...","de":"Moderne Minimalistische UI/UX-Anleitung: Einrichtung und ...","pt":"Guia de UI/UX Moderna Minimalista com oiloil-ui-ux-guide","ru":"ИИ Агент для Современного Минимализма: oiloil-ui-ux-guide...","ar":"دليل تصميم واجهة المستخدم وتجربة المستخدم الحديثة مع oilo..."},"description":{"en":"Unlock concise UI/UX principles and actionable fixes with oiloil-ui-ux-guide. Discover how to optimize your workflow and improve design quality - get started...","zh":"使用 OilOil UI/UX 指南，学习现代极简设计的原则和最佳实践，优化您的用户界面设计","ja":"OilOil UI/UX ガイドを使用して、モダン・マイナム デザインの原則とベストプラクティスを学び、ユーザー インターフェイス設計を最適化する","ko":"OilOil UI/UX 가이드를 사용하여 현대적 최소한의 디자인 원칙과 모범 사례를 배우고 사용자 인터페이스 디자인을 최적화합니다","es":"Aprende a crear interfaces de usuario modernas y minimalistas con oiloil-ui-ux-guide. Descubre cómo mejorar la experiencia del usuario con nuestros consejos ...","fr":"Découvrez comment créer des interfaces utilisateur modernes et minimalistes avec oiloil-ui-ux-guide. Améliorez l''expérience utilisateur avec nos conseils et ...","de":"Erfahren Sie, wie Sie moderne und minimalistische Benutzeroberflächen mit oiloil-ui-ux-guide erstellen. Verbessern Sie die Benutzererfahrung mit unseren Tipp...","pt":"Aprenda a criar interfaces de usuário modernas e minimalistas com o oiloil-ui-ux-guide. Obtenha dicas e regras concretas para melhorar sua UI/UX","ru":"Узнайте, как создавать современные и минималистские интерфейсы пользователя с помощью oiloil-ui-ux-guide. Получите советы и конкретные правила для улучшения ...","ar":"تعلم كيفية تصميم واجهات مستخدم حديثة وتصميمات بسيطة مع oiloil-ui-ux-guide. احصل على نصائح وقواعد محددة لتحسين تجربة المستخدم"},"definition":{"en":"oiloil-ui-ux-guide is a skill that provides guidance on modern minimal UI/UX design, offering principles and rules for clean design and reviewing existing UI for prioritized fixes.","zh":"OilOil UI/UX 指南是一种 AI 工具，提供现代极简设计的原则和最佳实践","ja":"OilOil UI/UX ガイドは、モダン・マイナム デザインの原則とベストプラクティスを提供する AI エージェントです","ko":"OilOil UI/UX 가이드는 현대적 최소한의 디자인 원칙과 모범 사례를 제공하는 AI 에이전트입니다","es":"oiloil-ui-ux-guide es una herramienta de diseño de interfaces de usuario que proporciona principios y reglas para crear experiencias de usuario modernas y minimalistas.","fr":"oiloil-ui-ux-guide est un outil de conception d''interfaces utilisateur qui propose des principes et des règles pour créer des expériences utilisateur modernes et minimalistes.","de":"oiloil-ui-ux-guide ist ein Werkzeug für die Gestaltung von Benutzeroberflächen, das Prinzipien und Regeln für die Erstellung moderner und minimalistischer Benutzererfahrungen bereitstellt.","pt":"O oiloil-ui-ux-guide é uma ferramenta de design de UI/UX que fornece diretrizes e regras para criar interfaces de usuário modernas e minimalistas","ru":"ИИ Агент oiloil-ui-ux-guide - это инструмент для создания современных и минималистских интерфейсов пользователя, который предоставляет руководство и конкретные правила","ar":"دليل تصميم واجهة المستخدم وتجربة المستخدم oiloil-ui-ux-guide هو أداة لإنشاء واجهات مستخدم حديثة وتصميمات بسيطة، يقدم إرشادات وقواعد محددة"},"features":{"en":["Provides compact UI/UX principles in guide mode","Reviews existing UI and outputs prioritized, actionable fixes in review mode","Supports various workflows, including marketing pages and dashboards","Outputs concise results, preferring bullets over long paragraphs","Identifies primary surfaces, such as creation flows and forms"],"zh":["提供现代极简设计的原则和最佳实践","支持两种模式：guide 和 review","输出紧凑的原则和具体的做/不做规则","支持各种界面类型，包括市场页面、仪表板、设置、创建流程、列表-详细信息和表单","可以对现有的 UI 进行审查和输出优先的、可执行的修复"],"ja":["モダン・マイナム デザインの原則とベストプラクティスを提供","2 つのモードをサポート：guide と review","コンパクトな原則と具体的な做/不做ルールを出力","さまざまなインターフェイス タイプをサポート，包括マーケティング ページ、ダッシュボード、設定、作成フロー、リスト-詳細、フォーム","既存の UI をレビューして優先度の高い、実行可能な修正を出力"],"ko":["현대적 최소한의 디자인 원칙과 모범 사례 제공","두 가지 모드 지원: 가이드와 리뷰","紧凑한 원칙과 구체적인 수행/수행하지 않음 규칙 출력","다양한 인터페이스 유형 지원, 포함된 시장 페이지, 대시보드, 설정, 생성 흐름, 목록-세부 정보, 양식","기존 UI를 검토하고 우선순위가 높은 실행 가능한 수정을 출력"],"es":["Dos modos de funcionamiento: guía y revisión","Proporciona principios compactos y reglas concretas para UI/UX moderna","Revisa interfaces de usuario existentes y proporciona soluciones prioritarias","Salidas concisas en forma de viñetas","Identifica la superficie de la interfaz de usuario: página de marketing, panel de control, configuración, flujo de creación, lista-detalle, formulario"],"fr":["Deux modes de fonctionnement : guide et révision","Fournit des principes compacts et des règles concrètes pour une UI/UX moderne","Examine les interfaces utilisateur existantes et propose des solutions prioritaires","Sorties concises sous forme de puces","Identifie la surface de l''interface utilisateur : page de marketing, tableau de bord, configuration, flux de création, liste-détail, formulaire"],"de":["Zwei Betriebsmodi: Anleitung und Überprüfung","Bietet kompakte Prinzipien und konkrete Regeln für eine moderne Benutzeroberfläche","Überprüft bestehende Benutzeroberflächen und liefert priorisierte Lösungen","Kompakte Ausgaben in Form von Aufzählungspunkten","Identifiziert die Oberfläche der Benutzeroberfläche: Marketing-Seite, Dashboard, Einstellungen, Erstellungsfunktion, Liste-Details, Formular"],"pt":["Dois modos de operação: guide e review","Fornece diretrizes e regras concretas para UI/UX moderna","Análise de interfaces de usuário existentes","Saídas concisas em formato de bullets","Identificação de superfícies de design, como páginas de marketing e dashboards"],"ru":["Два режима работы: guide и review","Предоставляет руководство и конкретные правила для современной UI/UX","Анализ существующих интерфейсов пользователя","Консисе вывод в формате bullets","Идентификация поверхностей дизайна, таких как страницы маркетинга и панели управления"],"ar":["وضعان للتشغيل: دليل ومراجعة","يقدم إرشادات وقواعد محددة لتصميم واجهة المستخدم وتجربة المستخدم الحديثة","تحليل واجهات المستخدم الحالية","مخرجات مختصرة في شكل نقاط","تحديد سطح التصميم، مثل صفحات التسويق واللوحات"]},"keywords":{"en":["how to use oiloil-ui-ux-guide","oiloil-ui-ux-guide setup guide","modern minimal UI/UX design","UI/UX review tool","oiloil-ui-ux-guide alternative","oiloil-ui-ux-guide vs competing tools","install oiloil-ui-ux-guide","oiloil-ui-ux-guide workflow optimization"],"zh":["OilOil UI/UX 指南","现代极简设计","用户界面设计","AI 工具","UI/UX 设计原则","最佳实践","界面设计","用户体验设计"],"ja":["OilOil UI/UX ガイド","モダン・マイナム デザイン","ユーザー インターフェイス設計","AI エージェント","UI/UX 設計原則","ベストプラクティス","インターフェイス設計","ユーザー エクスペリエンス設計"],"ko":["OilOil UI/UX 가이드","현대적 최소한의 디자인","사용자 인터페이스 디자인","AI 에이전트","UI/UX 디자인 원칙","모범 사례","인터페이스 디자인","사용자 경험 디자인"],"es":["diseño de interfaces de usuario","experiencia del usuario","UI/UX moderna","herramientas de diseño","principios de diseño","reglas de diseño","revisión de interfaces de usuario","soluciones de diseño","oiloil-ui-ux-guide","agentes de inteligencia artificial"],"fr":["conception d''interfaces utilisateur","expérience utilisateur","UI/UX moderne","outils de conception","principes de conception","règles de conception","examen d''interfaces utilisateur","solutions de conception","oiloil-ui-ux-guide","outils d''intelligence artificielle"],"de":["Gestaltung von Benutzeroberflächen","Benutzererfahrung","moderne Benutzeroberfläche","Gestaltungstools","Gestaltungsprinzipien","Gestaltungsregeln","Überprüfung von Benutzeroberflächen","Gestaltungslösungen","oiloil-ui-ux-guide","Künstliche Intelligenz-Tools"],"pt":["oiloil-ui-ux-guide","ui/ux moderna","design de interface de usuário","guias de design","regras de ui/ux","análise de interface de usuário","desenvolvimento de software","ferramentas de design"],"ru":["ИИ Агент oiloil-ui-ux-guide","современная ui/ux","дизайн интерфейса пользователя","руководство по дизайну","правила ui/ux","анализ интерфейса пользователя","разработка программного обеспечения","инструменты дизайна"],"ar":["دليل تصميم واجهة المستخدم وتجربة المستخدم oiloil-ui-ux-guide","تصميم واجهة المستخدم وتجربة المستخدم الحديثة","تصميم واجهة المستخدم","دليل التصميم","قواعد تصميم واجهة المستخدم وتجربة المستخدم","تحليل واجهة المستخدم","تطوير البرمجيات","أدوات التصميم"]}},"owner":"OpenDCAI","repo":"leonai","repoPath":"OpenDCAI/leonai","stars":20,"forks":1,"updatedAt":"2026-02-23T11:28:25Z","topics":[],"category":"community","skillMd":{"name":"oiloil-ui-ux-guide","description":"Modern, clean UI/UX guidance + review skill. Use when you need actionable UX/UI recommendations, design principles, or a design review checklist for new features or existing systems (web/app). Focus on CRAP (Contrast/Repetition/Alignment/Proximity) plus task-first UX, information architecture, feedback & system status, consistency, affordances, error prevention/recovery, and cognitive load. Enforce a modern minimal style (clean, spacious, typography-led), reduce unnecessary copy, forbid emoji as icons, and recommend intuitive refined icons from a consistent icon set.","bodyPreview":"# OilOil UI/UX Guide (Modern Minimal)\n\nUse this skill in two modes:\n\n- `guide`: Provide compact principles and concrete do/don''t rules for modern clean UI/UX.\n- `review`: Review an existing UI (screenshot / mock / HTML / PR) and output prioritized, actionable fixes.\n\nKeep outputs concise. Prefer bullets, not long paragraphs.\n\n## Workflow (pick one)\n\n### 1) `guide` workflow\n1. Identify the surface: marketing page / dashboard / settings / creation flow / list-detail / form.\n2. Identify the primary","body":"# OilOil UI/UX Guide (Modern Minimal)\n\nUse this skill in two modes:\n\n- `guide`: Provide compact principles and concrete do/don''t rules for modern clean UI/UX.\n- `review`: Review an existing UI (screenshot / mock / HTML / PR) and output prioritized, actionable fixes.\n\nKeep outputs concise. Prefer bullets, not long paragraphs.\n\n## Workflow (pick one)\n\n### 1) `guide` workflow\n1. Identify the surface: marketing page / dashboard / settings / creation flow / list-detail / form.\n2. Identify the primary user task and primary CTA.\n3. Apply the system-level guiding principles first (mental model and interaction logic).\n4. Then apply the core principles below (start from UX, then refine with CRAP).\n5. If icons are involved: apply `references/icons.md`.\n\n### 2) `review` workflow\n1. State assumptions (platform, target user, primary task).\n2. List findings as `P0/P1/P2` (blocker / important / polish) with short evidence.\n3. For each major issue, label the diagnosis: execution vs evaluation gulf; slip vs mistake (see `references/design-psych.md`).\n4. Propose fixes that are implementable (layout, hierarchy, components, copy, states).\n5. End with a short checklist to verify changes.\n\nUse `references/review-template.md` when you need a stable output format.\n\n## Non-negotiables (hard rules)\n- No emoji used as icons (or as UI decoration). If an emoji appears, replace it with a proper icon.\n- Icons must be intuitive and refined. Use a single consistent icon set for the product (avoid mixing styles).\n- Minimize copy by default. Add explanatory text only when it prevents errors, reduces ambiguity, or improves trust.\n\n## System-Level Guiding Principles (cross-system, high-level)\n\nUse these as first-order constraints before choosing specific components or page patterns.\n\n- Concept constancy:\n  - Definition: The same business concept keeps the same name, meaning, and interaction semantics across the system.\n  - Review question: If a user learns this concept in one place, can they transfer that understanding everywhere else?\n- Primary task focus:\n  - Definition: Each screen has one dominant objective with the highest visual and interaction priority.\n  - Review question: Can users identify the most important action within 3 seconds?\n- UI copy source discipline (for product development):\n  - Definition: visible UI copy should come from business content, not from implementation constraints or generation instructions.\n  - Preferred copy sources:\n    - User task: what the user is trying to do.\n    - System state: what is happening now (loading, empty, error, success, permission).\n    - Result + next step: what changed and what users can do next.\n    - Risk/trust context: only when it prevents mistakes or improves confidence.\n  - Internal-only sources (do not render directly in product UI by default):\n    - Visual/style constraints (e.g., \"minimal\", \"black-and-white\", \"modern\").\n    - Technical constraints and implementation notes.\n    - Prompt instructions, review rubrics, and generation meta text.\n  - User-facing copy framing heuristic (general, not title-specific):\n    - Applies to any prominent UI copy: titles, section headers, callouts, badges, CTA labels, and empty states.\n    - Prefer user-outcome framing: describe the user''s goal and the result they get.\n    - Avoid self-referential/process framing for end-user product UI (e.g., \"to showcase\", \"this page demonstrates\", \"showing the skill''s value\").\n    - Exception: if the surface is explicitly a demo/tutorial/spec page for builders, self-referential/process copy can be acceptable when it improves understanding.\n  - State perceptibility (high-level, cross-system):\n    - Problem: users make errors when an important internal state is not perceivable (mode, scope, selection, unsaved changes, environment, permission).\n    - Principle: make state visible using the lowest-noise signal that reliably changes behavior.\n    - Preferred signals (in order):\n      - Structural change: the layout/components clearly switch (read -> edit; list -> selection; view -> compare).\n      - Control state: the control that changes behavior shows its state (tabs, toggles, segmented controls).\n      - Inline signifiers: local cues near the affected area (selection count, scope chip, disabled reason).\n      - Post-action feedback: clear results + next step (reduces evaluation gulf).\n      - Only if needed: persistent banners/labels for high-risk, sticky modes.\n    - Avoid: redundant \"status labels\" that restate what the structure already makes obvious (they add noise but not clarity).\n  - Practical workflow:\n    - First build a content model (task/state/result/risk).\n    - Then apply visual constraints through layout, hierarchy, and component styling.\n    - Run a final copy pass: if a sentence does not help task completion, state understanding, or trust, move it to internal notes.\n  - Review question: is each visible sentence useful for end users, or only useful for builders/reviewers?\n- Help text layering (avoid \"hint sprawl\"):\n  - Problem this prevents: dumping all tips onto the UI feels \"safe\", but it destroys hierarchy and increases scanning cost.\n  - Placement heuristic:\n    - L0 (Always visible): only information needed to complete the task correctly.\n    - L1 (Nearby): short guidance for high-risk / high-ambiguity inputs.\n    - L2 (On demand): examples, advanced details, \"learn more\".\n    - L3 (After action): result, error, recovery, and next step.\n  - Copy budget heuristic:\n    - Prefer one clear helper line over multiple repetitive hints.\n    - If a page needs many persistent hints, improve IA or defaults first.\n- Feedback loop closure:\n  - Definition: Every user action must complete a full loop: received, in progress, result, and clear next step.\n  - Review question: At any moment, can users tell what the system is doing and what they should do next?\n- Prevention first + recoverability:\n  - Definition: Reduce error probability before submission, and provide recovery paths for high-risk outcomes.\n  - Review question: Is the path designed to be easy to do right and safe to recover when wrong?\n- Progressive complexity:\n  - Definition: Show minimum-required controls by default; reveal advanced capability only when context requires it.\n  - Review question: Can novices complete the core task quickly without limiting expert throughput?\n- Action perceptibility (affordance + signifiers):\n  - Definition: Interactive targets and likely outcomes are perceivable from structure and visual cues, without guesswork.\n  - Review question: Without reading help text, can users predict what is actionable and what will happen?\n- Cognitive load budget:\n  - Definition: Limit new rules, terms, and interaction modes per screen; prioritize reuse over novelty.\n  - Review question: As information grows, does comprehension cost stay stable?\n- Evolution with semantic continuity:\n  - Definition: Introduce new components/patterns only when existing ones cannot solve the problem, and keep semantic compatibility.\n  - Review question: Is this necessary innovation or avoidable interaction drift?\n\n## Core Principles (minimal set)\n\n### A) Task-first UX\n- Make the primary task obvious in <3 seconds.\n- Allow exactly one primary CTA per screen/section.\n- Optimize the happy path; hide advanced controls behind progressive disclosure.\n\n### B) Information architecture (grouping & findability)\n- Group by user mental model (goal/object/time/status), not by backend fields.\n- Use clear section titles; keep navigation patterns stable across similar screens.\n- When item count grows: add search/filter/sort early, not late.\n\n### C) Feedback & system status\n- Always show: loading, empty, error, success, and permission states.\n- After any action, answer: \"did it work?\" + \"what changed?\" + \"what can I do next?\"\n- Prefer inline, contextual feedback over global toasts (except for cross-page actions).\n\n### D) Consistency & predictability\n- Same interaction = same component + same wording + same placement.\n- Use a small, stable set of component variants; avoid one-off styles.\n\n### E) Affordance / 示能性 + Signifiers / 指示符 (make actions obvious)\n- People should see **what can be done** and **how to do it** without guessing.\n- Clickable things must look clickable (button/link styling + hover/focus + cursor); avoid “mystery meat” UI.\n  - Web: if you implement clickability on non-native elements (e.g. `div` with `onClick`), ensure `cursor: pointer` and proper focus styles.\n- Do not hide primary actions behind unlabeled icons. If an icon can be misunderstood, add a short label.\n- Prefer **natural mapping**: control placement mirrors the thing it controls (layout, direction, grouping).\n- Forms: show constraints before submit (format, units, examples, required), not only after errors.\n\n### F) Error prevention & recovery\n- Prevent errors with constraints, defaults, and inline validation.\n- Make destructive actions reversible when possible; otherwise require deliberate confirmation.\n- Error messages must be actionable (what happened + how to fix).\n\n### G) Cognitive load control\n- Reduce choices: sensible defaults, presets, and progressive disclosure.\n- Break long tasks into steps only when it reduces thinking (not just to look \"enterprise\").\n- Keep visual noise low: fewer borders, fewer colors, fewer competing highlights.\n\n### H) CRAP (visual hierarchy & layout)\n- Contrast: emphasize the few things that matter (CTA, current state, key numbers).\n- Repetition: tokens/components/spacing follow a scale; avoid “almost the same” styles.\n- Alignment: align to a clear grid; fix 2px drift; align baselines where text matters.\n- Proximity: tight within a group, loose between groups; spacing is the primary grouping tool.\n\n## Spacing & layout discipline (compact rule set)\n\nUse this when implementing or reviewing layouts. Keep it short, but enforce it strictly.\n\n- Rule 1 - One spacing scale:\n  - Base unit: 4px.\n  - Allowed spacing set (recommended): 4 / 8 / 12 / 16 / 24 / 32 / 40 / 48.\n  - New gaps/padding should use this set; off-scale values need a clear reason.\n- Rule 2 - Repetition first:\n  - Same component type keeps the same internal spacing (cards, list rows, form groups, section blocks).\n  - Components with the same visual role should not have different spacing patterns.\n- Rule 3 - Alignment + grouping:\n  - Align to one grid and fix 1-2px drift.\n  - Tight spacing within a group, looser spacing between groups.\n- Rule 4 - No decorative nesting:\n  - Extra wrappers must add real function (grouping, state, scroll, affordance).\n  - If a wrapper only adds border/background, remove it and group with spacing instead.\n- Quick review pass:\n  - Any off-scale spacing values?\n  - Any baseline/edge misalignment?\n  - Any wrapper layer removable without losing meaning?\n\n## Modern minimal style guidance (taste with rules)\n- Use whitespace + typography to create hierarchy; avoid decoration-first design.\n- Prefer subtle surfaces (light elevation, low-contrast borders). Avoid heavy shadows.\n- Keep color palette small; use one accent color for primary actions and key states.\n- Copy: short, direct labels; add helper text only when it reduces mistakes or increases trust.\n\n## Motion (animation) guidance (content/creator-friendly, not flashy)\n- Motion explains **hierarchy** (what is a layer/panel) and **state change** (what just happened). Avoid motion as decoration.\n- Default motion vocabulary: fade; then small translate+fade; allow tiny scale+fade for overlays. Avoid big bouncy motion.\n- Keep the canvas/content area stable. Panels/overlays can move; the work surface should not “float.”\n- Prefer consistency over variety: same component type uses the same motion pattern.\n- Avoid layout jumps. Use placeholders/skeletons to keep layout stable while loading.\n\n## References\n- Icon rules and “intuitive refined” guidance: `references/icons.md`\n- Review output template and scoring: `references/review-template.md`\n- Expanded checklists (use when needed): `references/checklists.md`\n- Design Psychology (示能性、指示符、映射、约束、错误类型、概念模型): `references/design-psych.md`\n"},"lastSynced":"2026-03-06T06:41:30.203Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX-focused Agents needing compact principles and concrete do/don''t rules for modern clean UI/UX design.","zh":"非常适合需要紧凑原则和具体的UI/UX设计规范的UI/UX专注的Agent。","ja":"UI/UXに焦点を当てたエージェントがコンパクトな原則とモダンなクリーンUI/UXデザインの具体的なルールを必要とする場合に最適です。","ko":"コンパクトな原則とモダン한 클린 UI/UX 디자인의 구체적인 규칙이 필요한 UI/UX 중심 에이전트에게 적합합니다.","es":"Perfecto para agentes centrados en UI/UX que necesitan principios compactos y reglas concretas de hacer/no hacer para un diseño UI/UX moderno y limpio.","fr":"Parfait pour les agents axés sur l''UI/UX nécessitant des principes compacts et des règles concrètes de faire/ne pas faire pour une conception UI/UX moderne et propre.","de":"Perfekt für UI/UX-fokussierte Agenten, die compacte Prinzipien und konkrete Regeln für modernes, sauberes UI/UX-Design benötigen.","pt":"Perfeito para Agentes focados em UI/UX que necessitam de princípios compactos e regras concretas de fazer/não fazer para design de UI/UX moderno e limpo.","ru":"Идеально подходит для агентов, ориентированных на UI/UX, которым необходимы компактные принципы и конкретные правила делать/не делать для современного чистого дизайна UI/UX.","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم / تجربة المستخدم الذين يحتاجون إلى مبادئ مدمجة وقواعد ملموسة للفعل / عدم الفعل لتصميم واجهة المستخدم / تجربة المستخدم الحديثة والنظيفة."},"recommendation":{"en":"Empowers agents to provide prioritized, actionable fixes for existing UI designs and offer guide principles for marketing pages, dashboards, settings, creation flows, list-detail, and forms using HTML and screenshot reviews.","zh":"赋予代理提供针对现有UI设计的优先、可执行的修复，并为营销页面、仪表板、设置、创建流程、列表-详细信息和使用HTML和截图审查的表单提供指导原则。","ja":"エージェントが既存のUIデザインに対する優先順位付けされた可実行な修正を提供し、HTMLおよびスクリーンショットレビューを使用してマーケティングページ、ダッシュボード、設定、作成フロー、リスト-詳細、フォームに対するガイド原則を提供できるようにします。","ko":"에이전트가 기존 UI 설계에 대한 우선 순위가 지정된 실행 가능한 수정을 제공하고 HTML 및 스크린샷 검토를 사용하여 마케팅 페이지, 대시보드, 설정, 생성 흐름, 목록-세부 정보 및 양식을 위한 가이드 원칙을 제공할 수 있도록 합니다.","es":"Empodera a los agentes para proporcionar soluciones prioritarias y acciones concretas para los diseños UI existentes y ofrecer principios guía para páginas de marketing, paneles de control, configuraciones, flujos de creación, listas-detalle y formularios utilizando revisiones de HTML y capturas de pantalla.","fr":"Autonomise les agents pour fournir des solutions prioritaires et des mesures concrètes pour les conceptions UI existantes et offrir des principes directeurs pour les pages de marketing, les tableaux de bord, les paramètres, les flux de création, les listes-détails et les formulaires en utilisant des examens de HTML et des captures d''écran.","de":"Ermächtigt Agenten, priorisierte, umsetzbare Korrekturen für bestehende UI-Designs bereitzustellen und Leitprinzipien für Marketingseiten, Dashboards, Einstellungen, Erstellungsflüsse, Listen-Detail und Formulare unter Verwendung von HTML- und Screenshot-Reviews anzubieten.","pt":"Habilita os agentes a fornecer soluções prioritárias e ações concretas para projetos de UI existentes e oferecer princípios direcionais para páginas de marketing, dashboards, configurações, fluxos de criação, listas-detalhes e formulários usando revisões de HTML e capturas de tela.","ru":"Наделяет агентов возможностью предоставлять приоритезированные, действенные исправления для существующих проектов UI и предлагать руководящие принципы для страниц маркетинга, панелей управления, настроек, потоков создания, списков-деталей и форм, используя обзоры HTML и скриншоты.","ar":"تمكّن الوكلاء من تقديم إصلاحات ذات أولوية وقابلة للتنفيذ للمشاريع الحالية لواجهة المستخدم وتقديم مبادئ توجيهية للصفحات التسويقية ولوحات القيادة والإعدادات وعمليات إنشاء القوائم-التفاصيل والاستمارات باستخدام مراجعات HTML وصور الشاشة."},"useCases":{"en":["Reviewing UI designs for marketing pages","Generating prioritized fixes for dashboard layouts","Providing compact UI/UX principles for creation flows"],"zh":["审查营销页面的UI设计","为仪表板布局生成优先修复","为创建流程提供紧凑的UI/UX原则"],"ja":["マーケティングページのUIデザインをレビューする","ダッシュボードレイアウトの優先修正を生成する","作成フローにコンパクトなUI/UX原則を提供する"],"ko":["마케팅 페이지의 UI 설계를 검토하는 것","대시보드 레이아웃에 대한 우선 순위 수정을 생성하는 것","생성 흐름에 대한 컴팩트한 UI/UX 원칙을 제공하는 것"],"es":["Revisar diseños UI para páginas de marketing","Generar soluciones prioritarias para diseños de paneles de control","Proporcionar principios UI/UX compactos para flujos de creación"],"fr":["Réviser les conceptions UI pour les pages de marketing","Générer des solutions prioritaires pour les dispositions de tableaux de bord","Fournir des principes UI/UX compacts pour les flux de création"],"de":["UI-Designs für Marketingseiten überprüfen","Priorisierte Korrekturen für Dashboards-Layouts generieren","Kompakte UI/UX-Prinzipien für Erstellungsflüsse bereitstellen"],"pt":["Revisar projetos de UI para páginas de marketing","Gerar soluções prioritárias para layouts de dashboards","Fornecer princípios UI/UX compactos para fluxos de criação"],"ru":["Просмотр проектов UI для страниц маркетинга","Генерация приоритезированных исправлений для макетов панелей управления","Предоставление компактных принципов UI/UX для потоков создания"],"ar":["استعراض مشاريع واجهة المستخدم للصفحات التسويقية","توليد إصلاحات ذات أولوية لتنسيقات لوحات القيادة","تقديم مبادئ واجهة المستخدم / تجربة المستخدم المدمجة لعمليات إنشاء"]},"limitations":{"en":["Requires input in the form of screenshots, mocks, HTML, or PRs","Output is limited to concise bullet points"],"zh":["需要以截图、模拟、HTML或PR的形式输入","输出仅限于简洁的项目符号"],"ja":["入力はスクリーンショット、モック、HTML、またはPRの形式でなければならない","出力は簡潔な項目符号に限定される"],"ko":["입력이 스크린샷, 모의, HTML 또는 PR 형식으로 필요","출력은 간결한 항목 기호로 제한"],"es":["Requiere entrada en forma de capturas de pantalla, mocks, HTML o PRs","La salida se limita a puntos concisos"],"fr":["Nécessite une entrée sous forme de captures d''écran, de mocks, de HTML ou de PR","La sortie est limitée à des points concis"],"de":["Benötigt Eingaben in Form von Screenshots, Mocks, HTML oder PRs","Die Ausgabe ist auf knappe Punkte beschränkt"],"pt":["Exige entrada na forma de capturas de tela, mocks, HTML ou PRs","Saída limitada a pontos concisos"],"ru":["Требует ввода в виде скриншотов, макетов, HTML или PR","Выход ограничен краткими пунктами"],"ar":["يتطلب إدخالًا على شكل صور شاشة أو نماذج أو HTML أو PRs","الإخراج محدود بنقاط متوافقة"]},"version":4},"contentHash":"f7056af0569cb3d9a559b6e438b5b187cb038dd8ed19324cffa82e5628ff3503","qualityScore":35}');
