INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('carlheath/ogmios/PAI', 'PAI', 'carlheath', 'ogmios', 'community', 'PAI carlheath ogmios community PAI is a Personal AI Environment that provides an extended context for user interactions. It benefits developers and users by offering a customizable infrastructure for AI agents. PAI是一种个人AI环境，提供扩展的联系人列表、安全和响应格式等功能 PAIは、拡張コンテキスト機能を備えたパーソナルAI環境です PAI는 개인 AI 환경으로 확장된 연락처 목록, 보안 및 응답 형식을 제공합니다 PAI es un entorno de AI personalizado que permite a los desarrolladores configurar un sistema de IA con contactos y preferencias personalizados PAI est un environnement d''IA personnalisé qui permet aux développeurs de configurer un système d''IA avec des contacts et des préférences personnalisés PAI ist eine persönliche KI-Umgebung, die es Entwicklern ermöglicht, ein AI-System mit individuellen Kontakten und Präferenzen zu konfigurieren O PAI é um ambiente de inteligência artificial pessoal que permite gerenciar contatos e preferências de forma avançada. Ele inclui funcionalidades como lista de contatos estendida e gerenciamento de preferências. PAI — это личная инфраструктура искусственного интеллекта, которая позволяет управлять контактами и предпочтениями в расширенном режиме. Она включает функции, такие как расширенный список контактов и управление предпочтениями. بيئة الذكاء الاصطناعي الشخصي PAI هي منصة لادارة الاتصالات والتفضيلات بطريقة متقدمة. تشمل ميزاتها قائمة اتصالات موسعة وإدارة التفضيلات. how to use PAI what is PAI PAI alternative PAI vs other AI environments PAI install guide PAI setup tutorial PAI configuration options Personal AI Environment benefits customizable AI infrastructure PAI extended contact list PAI个人AI环境 AI环境设置 扩展联系人列表 身份和密钥联系人管理 栈首选项和安全配置 响应格式自定义 系统提示集成 Supports extended contact lists with customizable relationships and email addresses Utilizes system prompts for core essentials, including identity and security Allows for configuration of stack preferences and response formats Includes a customizable list of key contacts with corresponding email addresses Enables users to define relationships and contact information for up to four contacts Provides a flexible infrastructure for AI agents using a Personal AI Environment PAI is a Personal AI Environment that enables users to create a customized infrastructure for AI agents, including extended contact lists and system prompts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zachsnoek/zachsnoek.com/commit', 'community', 'zachsnoek', 'zachsnoek.com', 'zachsnoek/zachsnoek.com', 'commit', 2, 1, 35, '2026-02-26T02:53:45Z', '2026-03-07T12:49:30.125Z', '6df1038ac01af846188fd6771754c03ecc8225e69fa11f1267e2969bdb4b62cb', '{"id":"zachsnoek/zachsnoek.com/commit","name":"commit","description":{"en":"The commit skill generates descriptive commit messages by analyzing Git diffs and follows the conventional-commits format. It benefits developers using Next.js, TypeScript, and MDX.","zh":"Commit AI Agent是用于生成描述性提交消息的工具，支持Next.js、TypeScript和MDX","ja":"Commit AIエージェントは、Next.js、TypeScript、MDXをサポートする、描述的な提交メッセージを生成するツールです","ko":"Commit AI 에이전트는 Next.js, TypeScript, MDX를 지원하는 의미있는 커밋 메시지를 생성하는 도구입니다","es":"La herramienta de commit genera mensajes de commit descriptivos analizando diffs de Git y sigue el formato de conventional-commits.","fr":"L''outil de commit génère des messages de commit descriptifs en analysant les diffs Git et suit le format de conventional-commits.","de":"Das Commit-Tool generiert beschreibende Commit-Mitteilungen, indem es Git-Diffs analysiert und dem conventional-commits-Format folgt.","pt":"O commit é uma ferramenta que gera mensagens descritivas analisando git diffs e segue as convenções de commit. Use para melhorar a qualidade das suas mensagens de commit","ru":"ИИ Агент Commit - это инструмент, который генерирует описательные сообщения, анализируя git diffs и следуя конвенциям. Используйте его для улучшения качества ваших сообщений о.commit","ar":"أداة Commit هي أداة تنتج رسائل وصفية من خلال تحليل git diffs و اتباع الاتفاقيات. استخدمها لتحسين جودة رسائل الالتزام الخاصة بك"},"seo":{"title":{"en":"commit: Automated Commit Message Generation for AI Agents...","zh":"Commit Setup Guide: 生成描述性提交消息","ja":"Commit ベストプラクティス: AIエージェントによる提交メッセージ生成","ko":"Commit 사용법: 의미있는 커밋 메시지 생성하기","es":"Guía de configuración de commit: Mejores prácticas para m...","fr":"Guide de configuration de commit: Bonnes pratiques pour l...","de":"Commit-Setup-Leitfaden: Best Practices für Commit-Mitteil...","pt":"Guia de Configuração do Commit: Melhores Práticas para Me...","ru":"ИИ Агент Commit: Руководство по Настройке и Лучшим Практикам","ar":"إعداد أداة Commit: دليل أفضل الممارسات لرسائل الالتزام ال..."},"description":{"en":"Discover how commit simplifies Git workflows with automated commit messages. Learn how to use commit with Next.js, TypeScript, and MDX for streamlined develo...","zh":"使用Commit AI Agent自动生成描述性提交消息，遵循Conventional Commits格式，提升代码管理效率","ja":"Commit AIエージェントを使用して、Conventional Commits形式の描述的な提交メッセージを自動生成します","ko":"Commit AI 에이전트를 사용하여 의미있는 커밋 메시지를 자동 생성하고 코드 관리 효율성을 높여보세요","es":"Aprende a generar mensajes de commit descriptivos con la herramienta de commit. Mejora tus habilidades de desarrollo con nuestras mejores prácticas.","fr":"Découvrez comment générer des messages de commit descriptifs avec l''outil de commit. Améliorez vos compétences de développement avec nos meilleures pratiques.","de":"Erfahren Sie, wie Sie beschreibende Commit-Mitteilungen mit dem Commit-Tool erstellen. Verbessern Sie Ihre Entwicklungsfähigkeiten mit unseren Best Practices.","pt":"Aprenda a usar o commit para gerar mensagens descritivas analisando git diffs e siga as convenções de commit","ru":"Узнайте, как использовать ИИ Агент Commit для генерации описательных сообщений, анализируя git diffs и следуя конвенциям","ar":"تعرف على كيفية استخدام أداة Commit لإنشاء رسائل وصفية من خلال تحليل git diffs و اتباع الاتفاقيات"},"definition":{"en":"commit is a skill that automates the generation of descriptive commit messages for Git repositories, following the conventional-commits format.","zh":"Commit AI Agent是一种用于生成描述性提交消息的AI工具","ja":"Commit AIエージェントは、描述的な提交メッセージを生成するAIエージェントの一種です","ko":"Commit AI 에이전트는 의미있는 커밋 메시지를 생성하는 AI 에이전트입니다","es":"Un agente de commit es una herramienta de desarrollo que genera mensajes de commit descriptivos y sigue el formato de conventional-commits.","fr":"Un agent de commit est un outil de développement qui génère des messages de commit descriptifs et suit le format de conventional-commits.","de":"Ein Commit-Agent ist ein Entwicklungstool, das beschreibende Commit-Mitteilungen generiert und dem conventional-commits-Format folgt.","pt":"O commit é uma ferramenta de linha de comando que gera mensagens descritivas para commits de código","ru":"ИИ Агент Commit - это команда, генерирующая описательные сообщения для коммитов кода","ar":"أداة Commit هي أداة سطر الأوامر التي تنتج رسائل وصفية لالتمامات البرمجية"},"features":{"en":["Generates descriptive commit messages by analyzing Git diffs","Follows the conventional-commits format for consistent messaging","Supports integration with Next.js, TypeScript, and MDX for streamlined development","Automates commit message generation to avoid vague descriptions","Pushes branches to keep the upstream repository in sync"],"zh":["生成描述性提交消息","支持Conventional Commits格式","自动推送分支","集成Next.js、TypeScript和MDX","避免模糊的提交消息","支持GoatCounter、Mailchimp和Reach UI"],"ja":["描述的な提交メッセージを生成","Conventional Commits形式をサポート","自動的にブランチをプッシュ","Next.js、TypeScript、MDXをサポート","曖昧な提交メッセージを避ける","GoatCounter、Mailchimp、Reach UIをサポート"],"ko":["의미있는 커밋 메시지를 생성","Conventional Commits 형식을 지원","자동으로 브랜치를 푸시","Next.js, TypeScript, MDX를 지원","모호한 커밋 메시지를 피함","GoatCounter, Mailchimp, Reach UI를 지원"],"es":["Genera mensajes de commit descriptivos analizando diffs de Git","Sigue el formato de conventional-commits","Evita descripciones vagas como ''ayuda con documentos'' o ''procesa datos''","Soporta tecnologías como Next.js, TypeScript y MDX","Integra con herramientas como GoatCounter, Mailchimp y Netlify"],"fr":["Génère des messages de commit descriptifs en analysant les diffs Git","Suit le format de conventional-commits","Évite les descriptions vagues comme ''aide avec les documents'' ou ''traite les données''","Prend en charge des technologies comme Next.js, TypeScript et MDX","Intègre avec des outils comme GoatCounter, Mailchimp et Netlify"],"de":["Generiert beschreibende Commit-Mitteilungen, indem es Git-Diffs analysiert","Folgt dem conventional-commits-Format","Vermeidet vage Beschreibungen wie ''hilft bei Dokumenten'' oder ''bearbeitet Daten''","Unterstützt Technologien wie Next.js, TypeScript und MDX","Integriert mit Tools wie GoatCounter, Mailchimp und Netlify"],"pt":["Geração de mensagens descritivas analisando git diffs","Suporte às convenções de commit","Integração com React e Next.js","Uso de TypeScript para tipagem estática","Compatibilidade com MDX para documentação"],"ru":["Генерация описательных сообщений, анализируя git diffs","Поддержка конвенций коммитов","Интеграция с React и Next.js","Использование TypeScript для статической типизации","Совместимость с MDX для документации"],"ar":["إنشاء رسائل وصفية من خلال تحليل git diffs","دعم الاتفاقيات الالتزام","التكامل مع React و Next.js","استخدام TypeScript للتحقق الإ靜","التوافق مع MDX للتوثيق"]},"keywords":{"en":["how to use commit","commit setup guide","commit vs conventional-commits","automated commit message generation","commit with Next.js and TypeScript","Git workflow optimization with commit","commit alternative for AI agents","commit install for developers"],"zh":["Commit AI Agent","提交消息生成","Conventional Commits","Next.js","TypeScript","MDX","GoatCounter","Mailchimp","Reach UI","AI工具"],"ja":["Commit AIエージェント","提交メッセージ生成","Conventional Commits","Next.js","TypeScript","MDX","GoatCounter","Mailchimp","Reach UI","AIエージェント"],"ko":["Commit AI 에이전트","커밋 메시지 생성","Conventional Commits","Next.js","TypeScript","MDX","GoatCounter","Mailchimp","Reach UI","AI 에이전트"],"es":["agente de commit","herramienta de commit","mensajes de commit descriptivos","conventional-commits","Next.js","TypeScript","MDX","GoatCounter","Mailchimp","Netlify"],"fr":["agent de commit","outil de commit","messages de commit descriptifs","conventional-commits","Next.js","TypeScript","MDX","GoatCounter","Mailchimp","Netlify"],"de":["Commit-Agent","Commit-Tool","beschreibende Commit-Mitteilungen","conventional-commits","Next.js","TypeScript","MDX","GoatCounter","Mailchimp","Netlify"],"pt":["commit","git diffs","convenções de commit","React","Next.js","TypeScript","MDX","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["ИИ Агент Commit","git diffs","конвенции коммитов","React","Next.js","TypeScript","MDX","инструменты разработки","разработка программного обеспечения"],"ar":["أداة Commit","git diffs","اتفاقيات الالتزام","React","Next.js","TypeScript","MDX","أدوات التطوير","تطوير البرمجيات"]}},"owner":"zachsnoek","repo":"zachsnoek.com","repoPath":"zachsnoek/zachsnoek.com","stars":2,"forks":1,"updatedAt":"2026-02-26T02:53:45Z","topics":["blog","goatcounter","mailchimp","mdx","netlify","nextjs","reach-ui","react","typescript"],"category":"community","skillMd":{"name":"commit","description":"Generate descriptive commit messages by analyzing git diffs.","bodyPreview":"## What I do\n\n- Generate descriptive commit messages by analyzing git diffs.\n- Avoid vague descriptions like \"helps with documents\", \"processes data\", or \"does stuff with files\".\n- Follow the conventional-commits format described in `AGENTS.md` for every message.\n- After committing, push the branch so the upstream stays in sync.\n\n## When to use\n\nUse when the user asks for help writing commit messages or reviewing staged changes.","body":"## What I do\n\n- Generate descriptive commit messages by analyzing git diffs.\n- Avoid vague descriptions like \"helps with documents\", \"processes data\", or \"does stuff with files\".\n- Follow the conventional-commits format described in `AGENTS.md` for every message.\n- After committing, push the branch so the upstream stays in sync.\n\n## When to use\n\nUse when the user asks for help writing commit messages or reviewing staged changes.\n"},"lastSynced":"2026-03-07T12:49:30.125Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Management Agents requiring standardized commit message generation and Git workflow automation.","zh":"适用于需要标准化提交消息生成和 Git 工作流自动化的代码管理代理。","ja":"コード管理エージェントが標準化されたコミットメッセージ生成とGitワークフローの自動化を必要とする場合に最適です。","ko":"표준화된 커밋 메시지 생성과 Git 워크플로 자동화가 필요한 코드 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de código que requieren generación de mensajes de confirmación estandarizados y automatización de flujo de trabajo de Git.","fr":"Idéal pour les agents de gestion de code nécessitant une génération de messages de commit standardisés et une automation du workflow Git.","de":"Ideal für Code-Management-Agents, die eine standardisierte Commit-Nachrichtengenerierung und eine Git-Workflow-Automatisierung erfordern.","pt":"Ideal para Agentes de Gerenciamento de Código que exigem geração de mensagens de commit padronizadas e automação de fluxo de trabalho do Git.","ru":"Идеально подходит для агентов управления кодом, требующих стандартизированной генерации сообщений о коммитах и автоматизации рабочего процесса Git.","ar":"مثالي للموكلين لإدارة الشفرة الذين يتطلبون توليد رسائل الالتزام المعيارية وتأتمة تدفق العمل في Git."},"recommendation":{"en":"Empowers agents to generate descriptive commit messages following the conventional-commits format, utilizing Git diffs analysis and supporting Next.js, TypeScript, and MDX projects, while ensuring upstream sync through automatic branch pushing.","zh":"赋予代理生成遵循 conventional-commits 格式的描述性提交消息的能力，利用 Git 差异分析，并支持 Next.js、TypeScript 和 MDX 项目，同时通过自动分支推送确保上游同步。","ja":"conventional-commits形式に従った記述的なコミットメッセージを生成する機能をエージェントに付与し、Gitの差分分析を利用し、Next.js、TypeScript、MDXプロジェクトをサポートし、自動ブランチプッシュを通じてアップストリーム同期を確保します。","ko":"에이전트가 conventional-commits 형식의 설명적인 커밋 메시지를 생성할 수 있는 기능을 제공하며, Git 차이 분석을 사용하고 Next.js, TypeScript, MDX 프로젝트를 지원하며 자동 브랜치 푸시를 통해 업스트림 동기화를 보장합니다.","es":"Habilita a los agentes a generar mensajes de commit descriptivos siguiendo el formato conventional-commits, utilizando el análisis de Git diffs y compatibilidad con proyectos Next.js, TypeScript y MDX, mientras garantiza la sincronización upstream a través de la automatic branch pushing.","fr":"Permet aux agents de générer des messages de commit descriptifs suivant le format conventional-commits, en utilisant l''analyse de Git diffs et en prenant en charge les projets Next.js, TypeScript et MDX, tout en assurant la synchronisation en amont via le pushing automatique de branches.","de":"Ermächtigt Agenten, beschreibende Commit-Nachrichten im conventional-commits-Format zu generieren, indem Git-Diffs-Analysen verwendet und die Unterstützung von Next.js-, TypeScript- und MDX-Projekten gewährleistet wird, während die Upstream-Synchronisierung durch automatisches Branch-Pushing sichergestellt wird.","pt":"Habilita os agentes a gerar mensagens de commit descritivas seguindo o formato conventional-commits, utilizando análise de diferenças do Git e suportando projetos Next.js, TypeScript e MDX, garantindo a sincronização upstream por meio do envio automático de branches.","ru":"Наделяет агентов возможностью генерировать описательные сообщения о коммитах в формате conventional-commits, используя анализ差ов Git и поддерживая проекты Next.js, TypeScript и MDX, обеспечивая синхронизацию upstream посредством автоматического pushes веток.","ar":"تمكّن الوكلاء من توليد رسائل الالتزام الوصفية اتباعًا لتنسيق conventional-commits، مستخدمين تحليل الفروقات في Git وداعمين مشاريع Next.js وTypeScript وMDX، مع ضمان التزامن المتدفق من خلال دفع الفروع تلقائيًا."},"useCases":{"en":["Automating commit message generation","Reviewing staged changes for accuracy","Standardizing commit messages across teams"],"zh":["自动化提交消息生成","检查暂存更改的准确性","在团队中标准化提交消息"],"ja":["コミットメッセージ生成の自動化","ステージングされた変更の精度の確認","チーム間でのコミットメッセージの標準化"],"ko":["커밋 메시지 생성 자동화","暂存된 변경의 정확성 검토","팀 간 커밋 메시지 표준화"],"es":["Automatización de la generación de mensajes de commit","Revisión de los cambios en espera para garantizar la precisión","Estandarización de los mensajes de commit en todos los equipos"],"fr":["Automation de la génération de messages de commit","Révision des changements en attente pour garantir l''exactitude","Standardisation des messages de commit dans tous les équipes"],"de":["Automatisierung der Commit-Nachrichtengenerierung","Überprüfung der gestarteten Änderungen auf Genauigkeit","Standardisierung der Commit-Nachrichten in allen Teams"],"pt":["Automatizar a geração de mensagens de commit","Revisar alterações em estágio para precisão","Padronizar mensagens de commit em equipes"],"ru":["Автоматизировать генерацию сообщений о коммитах","Проверять изменения в стадии на точность","Стандартизировать сообщения о коммитах в командах"],"ar":["تأتمة توليد رسائل الالتزام","مراجعة التغييرات المتراكمة لالدقة","تعیین معايير رسائل الالتزام عبر الفرق"]},"limitations":{"en":["Requires Git repository access","Limited to conventional-commits format"],"zh":["需要 Git 仓库访问","仅限 conventional-commits 格式"],"ja":["Gitリポジトリへのアクセスが必要","conventional-commits形式のみ"],"ko":["Git 저장소 액세스가 필요","conventional-commits 형식만 해당"],"es":["Requiere acceso al repositorio Git","Limitado al formato conventional-commits"],"fr":["Nécessite un accès au référentiel Git","Limité au format conventional-commits"],"de":["Erfordert Zugriff auf das Git-Repository","Begrenzt auf das conventional-commits-Format"],"pt":["Exige acesso ao repositório Git","Limitado ao formato conventional-commits"],"ru":["Требует доступа к репозиторию Git","Ограничен форматом conventional-commits"],"ar":["يتطلب الوصول إلى مستودع Git","محدود بتنسيق conventional-commits"]},"version":4},"contentHash":"6df1038ac01af846188fd6771754c03ecc8225e69fa11f1267e2969bdb4b62cb","qualityScore":35}');
