INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zachsnoek/zachsnoek.com/commit', 'commit', 'zachsnoek', 'zachsnoek.com', 'community', 'commit zachsnoek zachsnoek.com community blog goatcounter mailchimp mdx netlify nextjs reach-ui react typescript The commit skill generates descriptive commit messages by analyzing Git diffs and follows the conventional-commits format. It benefits developers using Next.js, TypeScript, and MDX. Commit AI Agent是用于生成描述性提交消息的工具，支持Next.js、TypeScript和MDX Commit AIエージェントは、Next.js、TypeScript、MDXをサポートする、描述的な提交メッセージを生成するツールです Commit AI 에이전트는 Next.js, TypeScript, MDX를 지원하는 의미있는 커밋 메시지를 생성하는 도구입니다 La herramienta de commit genera mensajes de commit descriptivos analizando diffs de Git y sigue el formato de conventional-commits. L''outil de commit génère des messages de commit descriptifs en analysant les diffs Git et suit le format de conventional-commits. Das Commit-Tool generiert beschreibende Commit-Mitteilungen, indem es Git-Diffs analysiert und dem conventional-commits-Format folgt. O commit é uma ferramenta que gera mensagens descritivas analisando git diffs e segue as convenções de commit. Use para melhorar a qualidade das suas mensagens de commit ИИ Агент Commit - это инструмент, который генерирует описательные сообщения, анализируя git diffs и следуя конвенциям. Используйте его для улучшения качества ваших сообщений о.commit أداة Commit هي أداة تنتج رسائل وصفية من خلال تحليل git diffs و اتباع الاتفاقيات. استخدمها لتحسين جودة رسائل الالتزام الخاصة بك how to use commit commit setup guide commit vs conventional-commits automated commit message generation commit with Next.js and TypeScript Git workflow optimization with commit commit alternative for AI agents commit install for developers Commit AI Agent 提交消息生成 Conventional Commits Next.js TypeScript MDX GoatCounter Mailchimp Reach UI AI工具 Generates descriptive commit messages by analyzing Git diffs Follows the conventional-commits format for consistent messaging Supports integration with Next.js, TypeScript, and MDX for streamlined development Automates commit message generation to avoid vague descriptions Pushes branches to keep the upstream repository in sync commit is a skill that automates the generation of descriptive commit messages for Git repositories, following the conventional-commits format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('opensrcdevelop/auth/git-worktree', 'community', 'opensrcdevelop', 'auth', 'opensrcdevelop/auth', 'git-worktree', 1, 0, 35, '2026-03-04T13:46:29Z', '2026-03-06T07:19:33.278Z', '31867f73aef17038ec8cce65f254e0bce5f4493b66c3069cf781492ec80159c4', '{"id":"opensrcdevelop/auth/git-worktree","name":"git-worktree","description":{"en":"The git-worktree skill enables developers to manage Git worktrees efficiently, supporting creation, listing, and deletion operations. It benefits developers working on multiple projects or branches.","zh":"Git Worktree 管理命令提供创建、列表查看和删除工作树的功能，支持 iTerm2 集成","ja":"Git Worktree 管理コマンドは、作成、リスト表示、削除などのワークツリー操作をサポートし、iTerm2 との統合も可能","ko":"Git Worktree 관리 명령어는 작업 트리를 생성, 목록 보기, 삭제하는 기능을 제공하며 iTerm2와의 통합을 지원합니다","es":"Git-worktree es una herramienta para gestionar proyectos de Git. Permite crear, listar y eliminar worktrees de manera sencilla.","fr":"Git-worktree est un outil pour gérer les projets Git. Il permet de créer, de lister et de supprimer des worktrees de manière simple.","de":"Git-worktree ist ein Tool zur Verwaltung von Git-Projekten. Es ermöglicht die einfache Erstellung, Auflistung und Löschung von Worktrees.","pt":"O git-worktree é uma ferramenta para gerenciar worktrees em projetos Git. Ele permite criar, listar e remover worktrees de forma eficiente.","ru":"Git Worktree - это инструмент для управления worktrees в проектах Git. Он позволяет создавать, просматривать и удалять worktrees эффективно с ИИ Агентами.","ar":"Git Worktree هو أداة لإدارة worktrees في مشاريع Git. يسمح بإنشاء وفرز وإزالة worktrees بفعالية مع الأدوات الذكية."},"seo":{"title":{"en":"git-worktree: Setup Guide for AI Agents","zh":"Git Worktree 管理命令 Setup Guide","ja":"Git Worktree 管理コマンドのベストプラクティス","ko":"Git Worktree 관리 명령어 설정 가이드","es":"Guía de configuración de git-worktree para desarrolladores","fr":"Guide de mise en œuvre de git-worktree pour les développeurs","de":"Einrichtungsleitfaden für git-worktree-Entwickler","pt":"Guia de Configuração do Git Worktree para Desenvolvedores","ru":"Настройка Git Worktree: Руководство для Разработчиков с И...","ar":"دليل إعداد Git Worktree للأدوات الذكية"},"description":{"en":"Unlock efficient Git worktree management with our AI agent skill, featuring init, list, and remove commands - learn how to get started today!","zh":"了解 Git Worktree 的管理命令，包括创建、列表查看和删除操作，使用 AIエージェント 优化您的开发流程","ja":"Git Worktree の管理コマンドを学び、AIエージェント を使用して開発プロセスを最適化する","ko":"Git Worktree 관리 명령어를 사용하여 개발 프로세스를 최적화하고 AI Tools 를 활용하여 작업을 자동화하세요","es":"Aprende a utilizar git-worktree para gestionar proyectos de Git de manera efectiva. Descubre cómo crear, listar y eliminar worktrees con facilidad.","fr":"Découvrez comment utiliser git-worktree pour gérer vos projets Git de manière efficace. Créez, listez et supprimez des worktrees avec facilité.","de":"Erfahren Sie, wie Sie git-worktree verwenden, um Git-Projekte effektiv zu verwalten. Erstellen, listen und löschen Sie Worktrees mit Leichtigkeit.","pt":"Aprenda a usar o git-worktree para gerenciar projetos Git com eficiência. Crie, liste e remova worktrees com facilidade.","ru":"Узнайте, как использовать git-worktree для эффективного управления проектами Git. Создавайте, просматривайте и удаляйте worktrees легко с ИИ Агентами.","ar":"تعرف على كيفية استخدام Git Worktree لإدارة مشاريع Git بفعالية. أنشئ وقم بفرز وإزالة worktrees بسهولة مع الأدوات الذكية."},"definition":{"en":"git-worktree is a Git management command that allows users to create, list, and remove worktrees, streamlining project development and branch management.","zh":"Git Worktree 是一种 Git 的管理命令，用于创建、管理和删除工作树","ja":"Git Worktree は、Git の管理コマンドで、ワークツリーの作成、管理、削除を行う","ko":"Git Worktree 는 Git 의 관리 명령어로 작업 트리를 생성, 관리, 삭제하는 데 사용됩니다","es":"Git-worktree es una herramienta de línea de comandos para gestionar worktrees en proyectos de Git.","fr":"Git-worktree est un outil en ligne de commande pour gérer les worktrees dans les projets Git.","de":"Git-worktree ist ein Kommandozeilen-Tool zur Verwaltung von Worktrees in Git-Projekten.","pt":"O que é git-worktree? É uma ferramenta para gerenciar worktrees em projetos Git.","ru":"Что такое Git Worktree? Это инструмент для управления worktrees в проектах Git с ИИ Агентами.","ar":"ما هو Git Worktree? هو أداة لإدارة worktrees في مشاريع Git مع الأدوات الذكية."},"features":{"en":["Creates new worktrees using the `/git-worktree init` command","Lists all existing worktrees with the `/git-worktree list` command","Removes worktrees using the `/git-worktree remove` command","Automatically infers branch type based on user task description","Supports integration with iTerm2 for seamless workflow"],"zh":["创建新的工作树","列表查看所有工作树","删除工作树","支持 iTerm2 集成","使用 AIエージェント 优化开发流程"],"ja":["新しいワークツリーの作成","すべてのワークツリーのリスト表示","ワークツリーの削除","iTerm2 との統合","AIエージェント を使用した開発プロセスの最適化"],"ko":["새로운 작업 트리 생성","모든 작업 트리 목록 보기","작업 트리 삭제","iTerm2와의 통합","AI Tools 를 사용한 개발 프로세스 최적화"],"es":["Crear worktrees nuevos con el comando `/git-worktree init`","Listar todos los worktrees existentes con el comando `/git-worktree list`","Eliminar worktrees con el comando `/git-worktree remove`","Integración con iTerm2 para abrir nuevos worktrees en una pestaña nueva","Compatibilidad con la herramienta de línea de comandos de Git"],"fr":["Créer de nouveaux worktrees avec la commande `/git-worktree init`","Lister tous les worktrees existants avec la commande `/git-worktree list`","Supprimer des worktrees avec la commande `/git-worktree remove`","Intégration avec iTerm2 pour ouvrir de nouveaux worktrees dans un nouvel onglet","Compatibilité avec l''outil en ligne de commande de Git"],"de":["Erstellen von neuen Worktrees mit dem Befehl `/git-worktree init`","Auflisten aller existierenden Worktrees mit dem Befehl `/git-worktree list`","Löschen von Worktrees mit dem Befehl `/git-worktree remove`","Integration mit iTerm2 zum Öffnen neuer Worktrees in einem neuen Tab","Kompatibilität mit dem Git-Kommandozeilentool"],"pt":["Criação de worktrees com base em descrições de tarefas","Listagem de todos os worktrees existentes","Remoção de worktrees desnecessários","Integração com iTerm2 para abrir novas abas","Suporte à criação de worktrees com descrições de tarefas"],"ru":["Создание worktrees на основе описаний задач","Просмотр всех существующих worktrees","Удаление ненужных worktrees","Интеграция с iTerm2 для открытия новых вкладок","Поддержка создания worktrees с описаниями задач с ИИ Агентами"],"ar":["إنشاء worktrees على أساس وصفات المهام","عرض جميع worktrees الحالية","إزالة worktrees غير ضرورية","التكامل مع iTerm2 لفتح علامات تبويب جديدة","دعم إنشاء worktrees مع وصفات المهام مع الأدوات الذكية"]},"keywords":{"en":["how to use git-worktree","git-worktree setup guide","git-worktree vs git submodule","git-worktree install","what is git-worktree","git-worktree alternative","git-worktree tutorial","git-worktree best practices"],"zh":["Git Worktree","AIエージェント","Git 管理命令","工作树管理","iTerm2 集成","开发流程优化"],"ja":["Git Worktree","AIエージェント","Git 管理コマンド","ワークツリー管理","iTerm2 統合","開発プロセス最適化"],"ko":["Git Worktree","AI Tools","Git 관리 명령어","작업 트리 관리","iTerm2 통합","개발 프로세스 최적화"],"es":["git-worktree","gestión de proyectos de Git","creación de worktrees","lista de worktrees","eliminación de worktrees","herramientas de línea de comandos de Git","desarrollo de software","control de versiones"],"fr":["git-worktree","gestion de projets Git","création de worktrees","liste de worktrees","suppression de worktrees","outils en ligne de commande de Git","développement de logiciels","contrôle de versions"],"de":["git-worktree","Verwaltung von Git-Projekten","Erstellung von Worktrees","Auflistung von Worktrees","Löschung von Worktrees","Git-Kommandozeilentools","Software-Entwicklung","Versionskontrolle"],"pt":["git worktree","gerenciamento de worktrees","desenvolvimento de software","ferramentas de git","iTerm2","criação de worktrees","listagem de worktrees","remoção de worktrees"],"ru":["git worktree","управление worktrees","разработка программного обеспечения","инструменты git","iTerm2","создание worktrees","просмотр worktrees","удаление worktrees","ИИ Агенты"],"ar":["git worktree","إدارة worktrees","تطوير البرمجيات","أدوات git","iTerm2","إنشاء worktrees","عرض worktrees","إزالة worktrees","الأدوات الذكية"]}},"owner":"opensrcdevelop","repo":"auth","repoPath":"opensrcdevelop/auth","stars":1,"forks":0,"updatedAt":"2026-03-04T13:46:29Z","topics":[],"category":"community","skillMd":{"name":"git-worktree","description":"Git Worktree 管理命令。提供 init、list、remove 三个子命令来管理项目 worktree。","version":"1.0.0","bodyPreview":"# Git Worktree 管理命令 (v1.0.0)\n\n管理项目中的 Git worktree，支持创建、列表查看和删除操作。\n\n## 调用方式\n\n```\n/git-worktree init \"任务描述\"   # 创建 worktree\n/git-worktree list             # 列出所有 worktree\n/git-worktree remove           # 删除 worktree\n```\n\n## 命令详解\n\n### init - 创建新的 Worktree\n\n根据用户描述的任务，自动推断分支类型并创建 worktree。创建完成后询问用户是否要在 iTerm2 中打开新 tab 并启动 Claude。\n\n**调用方式：**\n```\n/git-worktree init \"任务描述\"\n```\n\n**参数说明：**\n- `任务描述` - 任务的简短描述（必需）\n\n**交互流程：**\n1. 执行脚本创建 worktree\n2. 脚本输出 `[ASK_USER_OPEN_ITERM]` 标记和信息\n3. AI 检测到标记后，使用 AskUserQue","body":"# Git Worktree 管理命令 (v1.0.0)\n\n管理项目中的 Git worktree，支持创建、列表查看和删除操作。\n\n## 调用方式\n\n```\n/git-worktree init \"任务描述\"   # 创建 worktree\n/git-worktree list             # 列出所有 worktree\n/git-worktree remove           # 删除 worktree\n```\n\n## 命令详解\n\n### init - 创建新的 Worktree\n\n根据用户描述的任务，自动推断分支类型并创建 worktree。创建完成后询问用户是否要在 iTerm2 中打开新 tab 并启动 Claude。\n\n**调用方式：**\n```\n/git-worktree init \"任务描述\"\n```\n\n**参数说明：**\n- `任务描述` - 任务的简短描述（必需）\n\n**交互流程：**\n1. 执行脚本创建 worktree\n2. 脚本输出 `[ASK_USER_OPEN_ITERM]` 标记和信息\n3. AI 检测到标记后，使用 AskUserQuestion 询问用户是否打开 iTerm2\n4. 用户同意后，执行以下命令打开 iTerm2：\n\n```bash\ncd /Users/lee0407/dev/projs/auth && python3 .claude/skills/git-worktree/scripts/open_iterm.py \"<worktree_path>\" \"<branch_name>\" \"<description>\"\n```\n\n**自动推断的分支类型：**\n\n| 关键词 | 分支类型 |\n|--------|----------|\n| feat, 功能, 添加, 新增, 实现 | feature |\n| fix, 修复, bug, 错误, 问题 | bugfix |\n| refactor, 重构, 优化, 重写 | refactor |\n| docs, 文档, 说明, readme | docs |\n| test, 测试, 单元 | test |\n| chore, 配置, 构建, 依赖 | chore |\n\n**执行流程：**\n1. 切换到 develop 分支并拉取最新代码\n2. 根据描述推断分支类型并生成分支名\n3. 创建新分支\n4. 在 `worktrees/` 目录下创建 worktree\n5. 切换回 develop 分支\n6. 输出 `[ASK_USER_OPEN_ITERM]` 标记，等待 AI 询问用户\n\n**使用示例：**\n```\n/git-worktree init \"添加用户 Excel 导入导出功能\"\n# 结果：创建 feature/excel-import-export 分支和 worktree\n#       AI 检测到 [ASK_USER_OPEN_ITERM] 标记\n#       AI 使用 AskUserQuestion 询问用户\n#       用户同意后执行 open_iterm.py 打开 iTerm2 并启动 Claude\n```\n\n## AI 响应规则\n\n当执行 `/git-worktree init` 后，脚本会输出 `[ASK_USER_OPEN_ITERM]` 标记。AI 应：\n\n1. **检测到 `[ASK_USER_OPEN_ITERM]` 标记**\n2. **解析标记后的信息**（格式：`path|branch|description`）\n3. **使用 AskUserQuestion 询问用户**：\n```json\n{\n  \"questions\": [\n    {\n      \"question\": \"是否要在 iTerm2 中打开新 tab 并启动 Claude？\",\n      \"header\": \"iTerm2\",\n      \"options\": [\n        {\"label\": \"是，打开 iTerm2\", \"description\": \"在 iTerm2 新 tab 中启动 Claude\"},\n        {\"label\": \"否，稍后手动打开\", \"description\": \"不打开，稍后自行执行\"}\n      ],\n      \"multiSelect\": false\n    }\n  ]\n}\n```\n4. **用户选择\"是\"后**，执行：\n```bash\ncd /Users/lee0407/dev/projs/auth && python3 .claude/skills/git-worktree/scripts/open_iterm.py \"<worktree_path>\" \"<branch_name>\" \"<description>\"\n```\n\n## 脚本说明\n\n### worktree_manager.py\n主脚本，处理 worktree 的创建、列表和删除操作。\n\n### open_iterm.py\n辅助脚本，用于在 iTerm2 中打开新 tab 并启动 Claude。\n\n## 命令详解\n\n### list - 列出所有 Worktree\n\n显示当前仓库中所有 worktree 的列表。\n\n**调用方式：**\n```\n/git-worktree list\n```\n\n**输出格式：**\n```\nGit Worktree 列表\n============================================================\n主 /Users/lee0407/dev/projs/auth                    [develop] ✓\n└─ worktrees/feature-excel-import              [feature/excel-import] ✓\n└─ worktrees/bugfix-login-issue                [bugfix/login-issue] ✗\n============================================================\n✓ = 干净工作区 | ✗ = 有未提交更改\n```\n\n**使用示例：**\n```\n/git-worktree list\n```\n\n### remove - 删除 Worktree\n\n交互式删除指定的 worktree。\n\n**调用方式：**\n```\n/git-worktree remove           # 交互式选择\n/git-worktree remove 1         # 按索引删除\n/git-worktree remove feature-xxx  # 按路径删除\n```\n\n**注意事项：**\n- 不会删除主目录的 worktree\n- 不会删除有未提交更改的 worktree（除非强制）\n\n**使用示例：**\n```\n/git-worktree remove\n# 显示可删除的 worktree 列表，供用户选择\n```\n\n## 工作原理\n\nGit Worktree 允许在同一个仓库中同时在多个分支上工作：\n\n```\nauth/\n├── .git/\n├── worktrees/\n│   ├── feature-excel-import/     # 功能开发 worktree\n│   └── bugfix-login-issue/       # Bug 修复 worktree\n├── auth-biz/\n├── auth-server/\n└── ...\n```\n\n## 最佳实践\n\n1. **每个任务一个 worktree** - 保持工作区干净\n2. **及时清理** - 任务完成后删除不需要的 worktree\n3. **描述清晰** - 使用有意义的任务描述便于识别\n4. **先更新 develop** - 创建前确保 develop 是最新的\n\n## 注意事项\n\n1. 所有 worktree 必须创建在 `worktrees/` 目录下\n2. 创建前会自动检查 develop 分支是否为最新\n3. 删除前会询问用户确认\n4. 不会删除主目录的 worktree\n"},"lastSynced":"2026-03-06T07:19:33.278Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient Git worktree management and automation.","zh":"非常适合需要高效的Git工作树管理和自动化的开发代理。","ja":"開発エージェントが効率的なGitのワークツリーマネージメントと自動化を必要とする場合に最適です。","ko":"개발 에이전트가 효율적인 Git 작업 트리 관리 및 자동화를 필요로 하는 경우에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión y automatización eficiente de Git worktree.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion et d''automatisation efficaces de Git worktree.","de":"Perfekt für Entwicklungssagenten, die eine effiziente Git-Arbeitsbereichsverwaltung und -automatisierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento eficiente de worktree do Git e automação.","ru":"Идеально подходит для агентов разработки, которым необходим эффективный менеджмент Git worktree и автоматизация.","ar":"مثالي لعمليات وكيل التطوير التي تحتاج إلى إدارة شجرة العمل في Git وفعالية التشغيل التلقائي."},"recommendation":{"en":"Empowers agents to manage Git worktrees efficiently, supporting creation, listing, and deletion operations using Git commands, and integrates with iTerm2 for seamless workflow automation, utilizing protocols like command-line interfaces.","zh":"赋予代理高效管理Git工作树的能力，支持使用Git命令创建、列出和删除操作，并与iTerm2集成以实现无缝的工作流自动化，利用像命令行接口这样的协议。","ja":"エージェントがGitのワークツリを効率的に管理できるようにし、Gitコマンドを使用した作成、リスト、削除操作をサポートし、iTerm2と統合してワークフローの自動化をシームレスに行うことができ、コマンドラインインターフェースなどのプロトコルを利用します。","ko":"에이전트가 Git 작업 트리를 효율적으로 관리할 수 있도록 해주며, Git 명령어를 사용한 생성, 목록, 삭제 연산을 지원하며, iTerm2와 통합하여 작업 흐름 자동화를 무중단으로 수행할 수 있으며, 명령줄 인터페이스와 같은 프로토콜을 활용합니다.","es":"Habilita a los agentes a gestionar los worktrees de Git de forma eficiente, admitiendo operaciones de creación, lista y eliminación mediante comandos Git, e integra con iTerm2 para una automatización de flujo de trabajo sin problemas, utilizando protocolos como interfaces de línea de comandos.","fr":"Permet aux agents de gérer les worktrees Git de manière efficace, en prenant en charge la création, la liste et la suppression à l''aide de commandes Git, et s''intègre à iTerm2 pour une automation de workflow transparente, en utilisant des protocoles tels que des interfaces de ligne de commande.","de":"Ermächtigt Agenten, Git-Arbeitsbereiche effizient zu verwalten, indem es die Erstellung, Auflistung und Löschung mithilfe von Git-Befehlen unterstützt und sich in iTerm2 integriert, um eine nahtlose Workflow-Automatisierung zu ermöglichen, indem Protokolle wie Kommandozeilenoberflächen verwendet werden.","pt":"Habilita os agentes a gerenciar worktrees do Git de forma eficiente, suportando a criação, listagem e operações de exclusão usando comandos Git e se integra com o iTerm2 para automação de fluxo de trabalho contínuo, utilizando protocolos como interfaces de linha de comando.","ru":"Позволяет агентам эффективно управлять Git worktree, поддерживая создание, перечисление и операции удаления с помощью команд Git, и интегрируется с iTerm2 для бесшовной автоматизации рабочего процесса, используя протоколы, такие как интерфейсы командной строки.","ar":"يمكن للوكلاء إدارة شجرة العمل في Git بشكل فعال ، ودعم إنشاء قائمة وحذف عمليات باستخدام أوامر Git ، ودمجها مع iTerm2 لتحقيق автомazione سلسة للتدفق ، باستخدام بروتوكولات مثل واجهات سطر الأوامر."},"useCases":{"en":["Automating worktree creation for new projects","Listing and managing existing worktrees for multiple branches","Deleting unused worktrees to maintain repository organization"],"zh":["为新项目自动创建工作树","列出和管理多个分支的现有工作树","删除未使用的工作树以维护存储库组织"],"ja":["新規プロジェクトのためのワークツリーの自動作成","複数のブランチの既存のワークツリーのリストと管理","未使用のワークツリーの削除によるリポジトリの整理"],"ko":["새 프로젝트를 위한 작업 트리의 자동 생성","여러 분기의 기존 작업 트리의 목록 및 관리","사용되지 않는 작업 트리의 삭제를 통한 저장소 조직 유지"],"es":["Automatización de la creación de worktrees para nuevos proyectos","Lista y gestión de worktrees existentes para varias ramas","Eliminación de worktrees no utilizados para mantener la organización del repositorio"],"fr":["Automatisation de la création de worktrees pour de nouveaux projets","Liste et gestion de worktrees existants pour plusieurs branches","Suppression de worktrees inutilisés pour maintenir l''organisation du référentiel"],"de":["Automatisierung der Erstellung von Arbeitsbereichen für neue Projekte","Auflistung und Verwaltung von vorhandenen Arbeitsbereichen für mehrere Branches","Löschung nicht verwendeter Arbeitsbereiche, um die Organisation des Repositorys aufrechtzuerhalten"],"pt":["Automatizar a criação de worktree para novos projetos","Listar e gerenciar worktrees existentes para várias branches","Excluir worktrees não utilizados para manter a organização do repositório"],"ru":["Автоматизировать создание worktree для новых проектов","Перечислять и управлять существующими worktree для нескольких веток","Удалять неиспользуемые worktree для поддержания организации репозитория"],"ar":["تحقيق تلقائي لإنشاء شجرة العمل للمشاريع الجديدة","إدراج و إدارة شجرة العمل الحالية للفروع المتعددة","حذف شجرة العمل غير المستخدمة للحفاظ على تنظيم المستودع"]},"limitations":{"en":["Requires Git installation and configuration","Limited to Git worktree management, not comprehensive Git repository management"],"zh":["需要Git的安装和配置","仅限Git工作树管理，不是全面的Git存储库管理"],"ja":["Gitのインストールと設定が必要","Gitのワークツリーマネージメントのみで、包括的なGitリポジトリマネージメントではありません"],"ko":["Git의 설치 및 구성이 필요함","Git 작업 트리 관리에만 제한되어 있으며, 포괄적인 Git 저장소 관리는 아님"],"es":["Requiere la instalación y configuración de Git","Limitado a la gestión de worktrees de Git, no a la gestión integral del repositorio de Git"],"fr":["Nécessite l''installation et la configuration de Git","Limité à la gestion des worktrees Git, et non à la gestion complète du référentiel Git"],"de":["Erfordert die Installation und Konfiguration von Git","Begrenzt auf die Verwaltung von Git-Arbeitsbereichen, nicht auf die umfassende Verwaltung des Git-Repositorys"],"pt":["Requer instalação e configuração do Git","Limitado ao gerenciamento de worktree do Git, não ao gerenciamento abrangente do repositório Git"],"ru":["Требует установки и конфигурации Git","Ограничен менеджментом Git worktree, а не комплексным менеджментом репозитория Git"],"ar":["يتطلب تثبيت وتكوين Git","محدود بإدارة شجرة العمل في Git ، وليس بإدارة مستودع Git الشاملة"]},"version":4},"contentHash":"31867f73aef17038ec8cce65f254e0bce5f4493b66c3069cf781492ec80159c4","qualityScore":35}');
